	endc


;---------------------------------------------------------------------------
; AmigaDOS hunk header, left in place.
; The bootblock loads this file raw to $80 and jumps to $A0 (first code byte),
; so the header and the HUNK_END at the end are never processed by DOS.
; The executable is pre-relocated for $80; there is no reloc hunk.
; [1MB] AmigaDOS hunk header, left in place. The bootblock loads this file raw to the
; [1MB] address in $4.w and jumps to load+$20.
;---------------------------------------------------------------------------
HunkHeader:
	dc.b	$00,$00,$03,$F3,$00,$00,$00,$00,$00,$00,$00,$01,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$62,$23,$00,$00,$03,$E9,$00,$00,$62,$23

;---------------------------------------------------------------------------
; Program entry point (bootblock does JMP $20(a0) with a0=$80).
; [1MB] Program entry point (load address + $20).
;---------------------------------------------------------------------------
ProgramEntry:
        bra.w   Start                           ; 000A0/     
	ifd	RELOC_PAD	; relocation test (enhanced/tools/reloc_test.py): every address
	dcb.b	RELOC_PAD,0	; after this point moves by RELOC_PAD bytes
	endc

;---------------------------------------------------------------------------
; === DATA: level map and tile tables ===
; Two separate tile systems share the map (WorldMap, one byte per 256 x 256-px cell):
;  graphics:  cell -> CellTiles: 16 x 16 tiles of 16 x 16 px, drawn from the level file
;  collision: cell -> BlockTiles: 8 x 8 tiles of 32 x 32 px -> TileAttr record (bank
;             from MapBlockIndex), which gives a profile for each 16 x 16 quadrant ->
;             FloorProfile / WallProfileR / WallProfileL (see MapTileAt).
; MapBlockIndex: per cell type, TileAttr bank x 8 (the value << 8 is the byte offset
; of the bank: 4 banks of 256 tiles x 8 bytes).
;---------------------------------------------------------------------------
MapBlockIndex:
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$08	; cells $00-$0F
	dc.b	$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$18,$18,$08,$10	; cells $10-$1F
	dc.b	$10,$10,$10,$00,$00,$00,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10	; cells $20-$2F
	dc.b	$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10	; cells $30-$3F
	dc.b	$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$18,$18,$18,$18,$18,$18	; cells $40-$4F
	dc.b	$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18	; cells $50-$5F
	dc.b	$18,$18,$18,$18,$10,$00,$10,$00,$00,$00,$00,$00,$00,$00,$00,$00	; cells $60-$6F

;---------------------------------------------------------------------------
; BlockTiles - per cell type ($00-$67), 64 collision-tile numbers: 8 columns of 8,
; each column listed from the bottom of the cell up (index = column*8 + row)
;---------------------------------------------------------------------------
; (BlockTiles: in the per-level table files now - LEVEL_BLOCKS, LoadLevelTables)

;---------------------------------------------------------------------------
; TileAttr - 4 banks of 256 collision tiles, 8 bytes each:
;   profile for the quadrants left-bottom, left-top, right-bottom, right-top, then the
;   four flag bytes in the same order. The game only tests flag bits 6-7: either set =
;   the quadrant is ignored (background - no floor, wall or ladder).
; The comment shows each quadrant's floor height (FloorProfile, 1-16 px from the bottom
; of the quadrant), L for a ladder profile ($40-$7D), - for none; 'bg' if any quadrant
; is flagged as background, '(unused)' past the highest tile any cell of that bank uses.
;---------------------------------------------------------------------------
TileAttr:
; bank 0 (tiles used up to $FD)
	dc.b	$00,$B0,$00,$B0, $00,$07,$00,$07	; $00  floor  -  -  -  -
	dc.b	$06,$AB,$06,$AA, $09,$17,$09,$17	; $01  floor 14  - 14  -
	dc.b	$A9,$A8,$A8,$A7, $17,$17,$17,$17	; $02  floor  -  -  -  -
	dc.b	$00,$00,$00,$00, $00,$00,$00,$00	; $03  floor  -  -  -  -
	dc.b	$AF,$00,$A5,$00, $07,$00,$17,$00	; $04  floor  -  -  -  -
	dc.b	$06,$A9,$06,$A6, $09,$17,$09,$17	; $05  floor 14  - 14  -
	dc.b	$A7,$A3,$A4,$00, $17,$17,$17,$00	; $06  floor  -  -  -  -
	dc.b	$06,$A3,$06,$41, $09,$17,$09,$C2	; $07  floor 14  - 14  L  bg
	dc.b	$06,$47,$06,$41, $09,$C2,$09,$C2	; $08  floor 14  L 14  L  bg
	dc.b	$46,$00,$00,$00, $C2,$00,$00,$00	; $09  floor  L  -  -  -  bg
	dc.b	$06,$44,$06,$41, $09,$C2,$09,$C2	; $0A  floor 14  L 14  L  bg
	dc.b	$06,$49,$06,$48, $09,$C4,$09,$D2	; $0B  floor 14  L 14  L  bg
	dc.b	$4D,$4C,$4B,$00, $C4,$D4,$D4,$00	; $0C  floor  L  L  L  -  bg
	dc.b	$06,$41,$06,$42, $09,$C2,$09,$C2	; $0D  floor 14  L 14  L  bg
	dc.b	$00,$00,$00,$F4, $00,$00,$00,$02	; $0E  floor  -  -  -  -
	dc.b	$00,$F5,$00,$F6, $00,$02,$00,$02	; $0F  floor  -  -  -  -
	dc.b	$F2,$F0,$F3,$F1, $02,$02,$02,$02	; $10  floor  -  -  -  -
	dc.b	$00,$F7,$00,$F8, $00,$02,$00,$02	; $11  floor  -  -  -  -
	dc.b	$00,$F9,$00,$F6, $00,$02,$00,$02	; $12  floor  -  -  -  -
	dc.b	$F2,$F0,$FC,$FB, $02,$02,$02,$02	; $13  floor  -  -  -  -
	dc.b	$00,$FA,$00,$00, $00,$02,$00,$00	; $14  floor  -  -  -  -
	dc.b	$FD,$00,$00,$00, $02,$00,$00,$00	; $15  floor  -  -  -  -
	dc.b	$00,$F9,$00,$F6, $00,$02,$00,$02	; $16  floor  -  -  -  -
	dc.b	$3B,$00,$3C,$00, $04,$00,$04,$00	; $17  floor 15  - 15  -
	dc.b	$06,$A5,$06,$A5, $09,$40,$09,$40	; $18  floor 14  - 14  -  bg
	dc.b	$06,$B8,$06,$B7, $09,$40,$09,$40	; $19  floor 14  - 14  -  bg
	dc.b	$B5,$B5,$B9,$B9, $40,$40,$40,$40	; $1A  floor  -  -  -  -  bg
	dc.b	$B5,$B6,$B4,$B9, $40,$40,$40,$40	; $1B  floor  -  -  -  -  bg
	dc.b	$AA,$A6,$AC,$A6, $40,$40,$40,$40	; $1C  floor  -  -  -  -  bg
	dc.b	$B3,$B2,$B3,$B2, $01,$01,$11,$11	; $1D  floor  -  -  -  -
	dc.b	$25,$00,$26,$00, $02,$00,$02,$00	; $1E  floor 15  - 15  -
	dc.b	$27,$00,$1D,$28, $02,$00,$02,$02	; $1F  floor 15  - 15 15
	dc.b	$00,$00,$29,$00, $00,$00,$02,$00	; $20  floor  -  - 14  -
	dc.b	$1D,$1D,$28,$29, $12,$02,$12,$12	; $21  floor 15 15 15 14
	dc.b	$2B,$00,$00,$00, $02,$00,$00,$00	; $22  floor 14  -  -  -
	dc.b	$00,$2F,$00,$00, $00,$12,$00,$00	; $23  floor  - 15  -  -
	dc.b	$00,$14,$00,$15, $00,$05,$00,$05	; $24  floor  - 14  - 14
	dc.b	$10,$00,$11,$00, $05,$00,$05,$00	; $25  floor 14  - 14  -
	dc.b	$06,$4F,$06,$4A, $09,$C2,$09,$C4	; $26  floor 14  L 14  L  bg
	dc.b	$06,$43,$06,$43, $09,$C2,$09,$C2	; $27  floor 14  L 14  L  bg
	dc.b	$06,$4A,$06,$42, $09,$C4,$09,$D2	; $28  floor 14  L 14  L  bg
	dc.b	$06,$45,$06,$4E, $09,$C2,$09,$C2	; $29  floor 14  L 14  L  bg
	dc.b	$06,$41,$06,$40, $09,$C2,$09,$D2	; $2A  floor 14  L 14  L  bg
	dc.b	$06,$41,$06,$47, $09,$C2,$09,$C2	; $2B  floor 14  L 14  L  bg
	dc.b	$00,$00,$46,$00, $00,$00,$C2,$00	; $2C  floor  -  -  L  -  bg
	dc.b	$06,$48,$06,$49, $09,$C2,$09,$C4	; $2D  floor 14  L 14  L  bg
	dc.b	$4B,$4B,$4D,$4C, $C4,$C4,$D4,$C4	; $2E  floor  L  L  L  L  bg
	dc.b	$06,$41,$06,$A0, $09,$C2,$09,$07	; $2F  floor 14  L 14  -  bg
	dc.b	$06,$A1,$06,$A2, $09,$07,$09,$07	; $30  floor 14  - 14  -
	dc.b	$00,$D0,$D3,$D4, $00,$06,$06,$16	; $31  floor  -  -  -  -
	dc.b	$A3,$00,$A6,$A4, $07,$00,$07,$07	; $32  floor  -  -  -  -
	dc.b	$00,$00,$CF,$CE, $00,$00,$06,$06	; $33  floor  -  -  -  -
	dc.b	$CB,$00,$CC,$D5, $06,$00,$06,$06	; $34  floor  -  -  -  -
	dc.b	$00,$00,$D6,$D3, $00,$00,$06,$06	; $35  floor  -  -  -  -
	dc.b	$CB,$D0,$D3,$D4, $16,$16,$06,$06	; $36  floor  -  -  -  -
	dc.b	$D0,$00,$D4,$D5, $16,$00,$06,$06	; $37  floor  -  -  -  -
	dc.b	$D1,$00,$D0,$D1, $16,$00,$16,$06	; $38  floor  -  -  -  -
	dc.b	$CF,$CE,$CF,$CE, $06,$06,$06,$06	; $39  floor  -  -  -  -
	dc.b	$CE,$D1,$CE,$CE, $06,$16,$06,$06	; $3A  floor  -  -  -  -
	dc.b	$D6,$D3,$CF,$CE, $06,$06,$06,$06	; $3B  floor  -  -  -  -
	dc.b	$D3,$D3,$CC,$D8, $06,$06,$06,$06	; $3C  floor  -  -  -  -
	dc.b	$D4,$D4,$D1,$D0, $06,$16,$16,$06	; $3D  floor  -  -  -  -
	dc.b	$D5,$00,$00,$00, $16,$00,$00,$00	; $3E  floor  -  -  -  -
	dc.b	$D4,$D4,$D1,$66, $06,$16,$16,$D6	; $3F  floor  -  -  -  L  bg
	dc.b	$D7,$72,$72,$72, $16,$C6,$C6,$C6	; $40  floor  -  L  L  L  bg
	dc.b	$72,$79,$7D,$63, $C6,$C6,$C6,$C6	; $41  floor  L  L  L  L  bg
	dc.b	$69,$72,$D7,$72, $C6,$C6,$16,$C6	; $42  floor  L  L  -  L  bg
	dc.b	$72,$79,$6D,$79, $C6,$C6,$D6,$C6	; $43  floor  L  L  L  L  bg
	dc.b	$63,$63,$63,$63, $C6,$C6,$C6,$C6	; $44  floor  L  L  L  L  bg
	dc.b	$7C,$62,$7A,$60, $C6,$C6,$C6,$C6	; $45  floor  L  L  L  L  bg
	dc.b	$62,$61,$60,$60, $C6,$C6,$C6,$C6	; $46  floor  L  L  L  L  bg
	dc.b	$6F,$6E,$60,$60, $D6,$D6,$C6,$C6	; $47  floor  L  L  L  L  bg
	dc.b	$65,$6E,$60,$78, $D6,$D6,$C6,$C6	; $48  floor  L  L  L  L  bg
