;---------------------------------------------------------------------------
; Graphics-set sizes (width, height in pixels) for the 1MB build's BuildMaskedGfx, which
; pre-builds masks for the graphics it keeps in memory. The 512K build has the same tables
; (here and after FloorProfile) but never reads them.
; [1MB] BuildMaskedGfx size tables (width px, height) for each cached file
;---------------------------------------------------------------------------
CacheSizesSmallBobs:
	dc.w	$0010,$000D	; set 0: 16 x 13 px
	dc.w	$0010,$000F	; set 1: 16 x 15 px
	dc.w	$0020,$0010	; set 2: 32 x 16 px
	dc.w	$0020,$0010	; set 3: 32 x 16 px
	dc.w	$0020,$0014	; set 4: 32 x 20 px
	dc.w	$0020,$0014	; set 5: 32 x 20 px
	dc.w	$0020,$0014	; set 6: 32 x 20 px
	dc.w	$0020,$0015	; set 7: 32 x 21 px
	dc.w	$0030,$000E	; set 8: 48 x 14 px
	dc.w	$0040,$000A	; set 9: 64 x 10 px

;---------------------------------------------------------------------------
; Profile tables, 256 bytes each. MapTileAt's profile byte is SIGN-EXTENDED before
; indexing, so each label is in the middle: profiles $80-$FF are the 128 bytes before it.
;  WallProfileR / WallProfileL - how far a wall pushes Arthur back when walking right / left
;  FloorProfile - floor surface height (1-16) within the 16 x 16 quadrant, 0 = no floor
;---------------------------------------------------------------------------
	dc.b	$00,$00,$05,$04,$04,$04,$00,$00,$00,$00,$00,$00,$10,$08,$00,$08	; WallProfileR profiles $80-$8F
	dc.b	$10,$00,$00,$00,$02,$08,$00,$00,$01,$0F,$08,$0F,$00,$08,$08,$08	; WallProfileR profiles $90-$9F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $A0-$AF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $B0-$BF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $C0-$CF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $D0-$DF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $E0-$EF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $F0-$FF

;---------------------------------------------------------------------------
; WallProfileR - wall offset when walking right (sign-extended profile index)
;---------------------------------------------------------------------------
WallProfileR:
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $00-$0F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $10-$1F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$08,$00	; WallProfileR profiles $20-$2F
	dc.b	$08,$00,$08,$00,$00,$00,$00,$00,$00,$00,$08,$00,$00,$00,$00,$00	; WallProfileR profiles $30-$3F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $40-$4F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $50-$5F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $60-$6F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileR profiles $70-$7F
	dc.b	$00,$00,$0F,$0E,$0E,$0E,$00,$00,$00,$00,$00,$00,$10,$08,$00,$08	; WallProfileL profiles $80-$8F
	dc.b	$10,$00,$00,$00,$02,$08,$00,$00,$0F,$0F,$08,$0F,$00,$08,$08,$08	; WallProfileL profiles $90-$9F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $A0-$AF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $B0-$BF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $C0-$CF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $D0-$DF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $E0-$EF
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $F0-$FF

;---------------------------------------------------------------------------
