	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$08,$00	; WallProfileL profiles $20-$2F
	dc.b	$08,$00,$08,$00,$00,$00,$00,$00,$00,$00,$08,$00,$00,$00,$00,$00	; WallProfileL profiles $30-$3F
