	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $60-$6F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; WallProfileL profiles $70-$7F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; FloorProfile profiles $80-$8F
	dc.b	$00,$00,$00,$00,$00,$0F,$0F,$00,$00,$00,$0F,$00,$00,$00,$00,$00	; FloorProfile profiles $90-$9F
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00	; FloorProfile profiles $A0-$AF
