;---------------------------------------------------------------------------
; MapTileAt - collision lookup for a world position
; In:  d6 = X, d7 = Y (level-relative pixels, Y increasing upwards)
; cell  = WorldMap byte at g_MapPtr + (X>>8) + (Y>>8)*32
; tile  = BlockTiles[cell*64 + ((X>>5)&7)*8 + ((Y>>5)&7)]   (8x8 grid of 32px tiles,
;         column-major, rows counted from the bottom of the cell)
; rec   = TileAttr + (MapBlockIndex[cell]<<8) + tile*8
; Out: a1 = rec + (X bit4 ? 2 : 0) + (Y bit4 ? 1 : 0)   (the 16x16 quadrant)
;      (a1)  = profile (SIGN-EXTENDED when indexing the tables below)
;              FloorProfile[p] = floor height 1-16 within the quadrant (0 = none)
;              WallProfileR/L[p] = wall offsets; p = $40-$7D = ladder
;      4(a1) = flags: bits 6-7 set = background / not solid (decorations, water)
;---------------------------------------------------------------------------
MapCellEmpty:
	dc.b	$67			; a cell type with nothing in it (MapTileAt)
	even
MapTileAt:
        movea.l g_MapPtr(a6),a1                 ; 05A7C/059FC
        move.w  d6,d0                           ; 05A80/05A00
        lsr.w   #$8,d0                          ; 05A82/05A02
        adda.w  d0,a1                           ; 05A84/05A04
        move.w  d7,d0                           ; 05A86/05A06
        clr.b   d0                              ; 05A88/05A08
        lsr.w   #$3,d0                          ; 05A8A/05A0A
        adda.w  d0,a1                           ; 05A8C/05A0C
        cmpa.l  #FrameOffsets1,a1               ; past the map and the tables after it (the
        bcs.b   mt_inside                       ; original read code there as map cells):
        lea.l   MapCellEmpty(pc),a1             ; an empty cell
mt_inside:
        move.b  (a1),d0                         ; 05A8E/05A0E
        ext.w   d0                              ; 05A90/05A10
        lea.l   MapBlockIndex(pc),a1            ; 05A92/05A12
        adda.w  d0,a1                           ; 05A96/05A16
        swap    d0                              ; 05A98/05A18
        move.b  (a1),d0                         ; 05A9A/05A1A
        lsl.w   #$8,d0                          ; 05A9C/05A1C
        lea.l   TileAttr(pc),a1                 ; 05A9E/05A1E
        pea.l   (a1,d0.w)                       ; 05AA2/05A22
        swap    d0                              ; 05AA6/05A26
        andi.w  #$FF,d0                         ; the cell's slot in this level's tables
        lea.l   (LEVEL_SLOTS).l,a1
        move.b  (a1,d0.w),d0
        lsl.w   #$6,d0                          ; 05AA8/05A28
        lea.l   (LEVEL_BLOCKS).l,a1             ; its BlockTiles
        adda.w  d0,a1                           ; 05AAE/05A2E
        move.w  d6,d0                           ; 05AB0/05A30
        lsr.w   #$5,d0                          ; 05AB2/05A32
        andi.w  #$7,d0                          ; 05AB4/05A34
        lsl.w   #$3,d0                          ; 05AB8/05A38
        adda.w  d0,a1                           ; 05ABA/05A3A
        move.w  d7,d0                           ; 05ABC/05A3C
        lsr.w   #$5,d0                          ; 05ABE/05A3E
        andi.w  #$7,d0                          ; 05AC0/05A40
        adda.w  d0,a1                           ; 05AC4/05A44
        clr.w   d0                              ; 05AC6/05A46
        move.b  (a1),d0                         ; 05AC8/05A48
        lsl.w   #$3,d0                          ; 05ACA/05A4A
        movea.l (a7)+,a1                        ; 05ACC/05A4C
        adda.w  d0,a1                           ; 05ACE/05A4E
        btst    #$4,d6                          ; 05AD0/05A50
        beq.b   l_05AD8                         ; 05AD4/05A54
        addq.l  #$2,a1                          ; 05AD6/05A56
l_05AD8:
        btst    #$4,d7                          ; 05AD8/05A58
        beq.b   l_05AE0                         ; 05ADC/05A5C
        addq.l  #$1,a1                          ; 05ADE/05A5E
l_05AE0:
        rts                                     ; 05AE0/05A60

;---------------------------------------------------------------------------
; CrashReset - target of every CPU exception vector ($8-$2C, $3C).
; Writes RESET / JMP $0.L ($4E70 $4EF9 0000) to address 0 and jumps there:
; any bus error, illegal instruction, trace etc. reboots the machine.
; This doubles as an anti-tamper / anti-debug measure.
;---------------------------------------------------------------------------
CrashReset:
        move.l  #$4e704ef9,(RESET_STUB).w       ; 05AE2/05A62
        jmp     (RESET_STUB).w                  ; 05AEA/05A6A

;---------------------------------------------------------------------------
; ==================================================================
; Start - one-time initialisation
;  - point all exception vectors at CrashReset, autovectors at it too
;  - a6 = GLOBALS, USP = GLOBALS (user mode stack lives below it)
;  - load file $7F9C (tracks 33-36): Arthur sprite graphics, interleave
;    and convert into the 8 sprite planes at $1DE34-$26E34
;  - build HUD sprite data, load the remaining common files
;  - initialise hi-score table, copper lists, screen buffers
;  - install interrupts (InitHardware), show the FAST copyright
;    warning screen for 10 s, then drop
;    to user mode and spin: the whole game runs in interrupts.
; ==================================================================
;---------------------------------------------------------------------------
Start:
        jsr     EnhRelocate                     ; with an expansion and under 1MB of chip RAM: the program moves there
        lea.l   $8.w,a1                         ; 05AEE/05A80  CPU exceptions $08-$24 (bus error ... trace) -> CrashReset
        lea.l   CrashReset(pc),a0               ; 05AF2/05A84
        move.l  a0,(a1)+                        ; 05AF6/05A88
        move.l  a0,(a1)+                        ; 05AF8/05A8A
        move.l  a0,(a1)+                        ; 05AFA/05A8C
        move.l  a0,(a1)+                        ; 05AFC/05A8E
        move.l  a0,(a1)+                        ; 05AFE/05A90
        move.l  a0,(a1)+                        ; 05B00/05A92
        move.l  a0,(a1)+                        ; 05B02/05A94
        move.l  a0,(a1)+                        ; 05B04/05A96
        move.l  a0,(VEC_UNINIT).w               ; 05B06/05A98  Line-A/Line-F slots ($28/$2C) left free: the loader uses them as variables
        move.l  a0,d0                           ; 05B0A/05A9C
        move.l  a0,d1                           ; 05B0C/05A9E
        move.l  a0,d2                           ; 05B0E/05AA0
        move.l  (VEC_LEVEL3).w,d3               ; 05B10/05AA2  autovectors $60-$7C -> CrashReset, except level 3 (kept for now)
        move.l  a0,d4                           ; 05B14/05AA6
        move.l  a0,d5                           ; 05B16/05AA8
        move.l  a0,d6                           ; 05B18/05AAA
        move.l  a0,d7                           ; 05B1A/05AAC
        lea.l   (VEC_SPURIOUS).w,a0             ; 05B1C/05AAE
        movem.l d0-d7,(a0)                      ; 05B20/05AB2
        lea.l   (GLOBALS).l,a6                  ; 05B24/     
        move    a6,usp                          ; 05B2A/       USP = globals block (user-mode stack grows down from here)
        bsr.w   ReadProfile                     ; what machine this is (Profile)
        bsr.w   LoadSound                       ; the sound package first (the 512K effects at MAP_LOW, the music
                                                ; where the program was)
        lea.l   FileTable(pc),a1                ; 05B2C/05AB6
        bsr.w   LoadFile                        ; 05B30/05ABA  load Arthur sprite file (tracks 33-36) to $37468

;---------------------------------------------------------------------------
; Arthur's sprite graphics (file tracks 33-36, 42 frames of 32x32, 4 planes).
; Source rows are 8 words: [L-p0 R-p0 L-p1 R-p1 L-p2 R-p2 L-p3 R-p3].
; They are split into four sprite banks $2900 apart: sprites 0+1 = left 16
; pixels (attached pair, 16 colours from COLOR16), sprites 2+3 = right half.
; Frames: 0-14 armoured poses, 15 frog, 16-31 the same poses without armour (+$10),
; 32-36 skeleton (death), 37-39 frog, 40 sitting in his underwear (opening scene),
; 41 arms raised (end of level, ending). The second loop builds mirrored copies
; (bit-reversed, halves swapped) of frames 0-39 only - 40 and 41 always face right.
;---------------------------------------------------------------------------
        lea.l   FileTable(pc),a5                ; 05B34/05ABE
        movea.l (a5),a5                         ; 05B38/05AC2
        lea.l   (ARTHUR_SPR_GFX).l,a1           ; 05B3A/05AC8
        lea.l   (SPR_GFX_A1).l,a2               ; 05B40/05ACE
        lea.l   (SPR_GFX_A2).l,a3               ; 05B46/05AD4
        lea.l   (SPR_GFX_A3).l,a4               ; 05B4C/05ADA
        moveq   #$29,d7                         ; 05B52/05AE8
l_05B54:
        moveq   #$1f,d6                         ; 05B54/05AEA
l_05B56:
        move.w  (a5)+,(a1)+                     ; 05B56/05AEC
        move.w  (a5)+,(a3)+                     ; 05B58/05AEE
        move.w  (a5)+,(a1)+                     ; 05B5A/05AF0
        move.w  (a5)+,(a3)+                     ; 05B5C/05AF2
        move.w  (a5)+,(a2)+                     ; 05B5E/05AF4
        move.w  (a5)+,(a4)+                     ; 05B60/05AF6
        move.w  (a5)+,(a2)+                     ; 05B62/05AF8
        move.w  (a5)+,(a4)+                     ; 05B64/05AFA
        dbra    d6,l_05B56                      ; 05B66/05AFC
        dbra    d7,l_05B54                      ; 05B6A/05B00
        lea.l   FileTable(pc),a5                ; 05B6E/05B04  second pass: build the mirrored frames
        movea.l (a5),a5                         ; 05B72/05B08
        lea.l   (SPR_GFX_B0).l,a3               ; 05B74/05B0A
        lea.l   (SPR_GFX_B1).l,a4               ; 05B7A/05B10
        lea.l   (SPR_GFX_B2).l,a1               ; 05B80/05B16
        lea.l   (SPR_GFX_B3).l,a2               ; 05B86/05B1C
        lea.l   BitReverseTable(pc),a0          ; 05B8C/05B2A
        clr.w   d0                              ; 05B90/05B2E
        moveq   #$27,d7                         ; 05B92/05B30  40 frames (0-39) are mirrored
