        clr.w   -(a1)                           ; 05D8A/05DE8
        move.l  a1,g_RestoreListA(a6)           ; 05D8C/05DEA
        lea.l   g_SpawnQuota(a6),a1             ; 05D90/05DEE
        clr.w   -(a1)                           ; 05D94/05DF2
        move.l  a1,g_RestoreListB(a6)           ; 05D96/05DF4
        lea.l   WorldMap(pc),a1                 ; 05D9A/05DF8
