IdleLoop:
        bra.b   IdleLoop                        ; 05EAA/05F00  ... and idle forever; everything else is interrupt driven

;---------------------------------------------------------------------------
; RedrawEntry - the VBL handler patches the return PC to here when a
; full redraw is pending (g_RedrawPending). Runs in user mode, outside the interrupt:
;   bsr.w RedrawScreen / clr.b g_SkipLogic(a6) (lets the logic run again) / bra *
; (kept as bytes: the code is only reached through the patched return address)
;---------------------------------------------------------------------------
RedrawEntry:
        jsr     EnhRedrawBackground             ; nothing to redraw: the scroller keeps the buffers current
        clr.b   g_SkipLogic(a6)                 ; 05EB0/05F06  let the logic run again
        bra.b   *                               ; 05EB4/05F0A  idle until the next interrupt

;---------------------------------------------------------------------------
; ==================================================================
; Level1Logic - LEVEL 1 (SOFTINT) handler = the game's main loop
; The VBL handler raises SOFTINT each frame unless the previous frame's
; logic is still running, so this runs at most once per frame at IPL 1,
; letting the VBL/keyboard interrupts pre-empt it.
; Dispatches on g_GameState:
;    0 -> InGame        1 -> AttractTitle      2 -> AttractHiScores
; ==================================================================
;---------------------------------------------------------------------------
Level1Logic:
	ifd	RASTER_BUILD
        jsr     EnhLogicStart                   ; timing build: (does the INTREQ write) grey
	else
        move.w  #INTF_SOFTINT,CUSTOM+INTREQ     ; 05EB6/05F0C
	endc
        movem.l d0-d7/a0-a5,-(a7)               ; 05EBE/05F14
        move.b  g_GameState(a6),d0              ; 05EC2/05F18
        ext.w   d0                              ; 05EC6/05F1C
        add.w   d0,d0                           ; 05EC8/05F1E
        add.w   d0,d0                           ; 05ECA/05F20
        jmp     GameStateTable(pc,d0.w)         ; 05ECC/05F22
GameStateTable:
        bra.w   InGame                          ; 05ED0/05F26
        bra.w   AttractTitle                    ; 05ED4/05F2A
        bra.w   AttractHiScores                 ; 05ED8/05F2E

;---------------------------------------------------------------------------
; Attract state 1: credits/title text, 400 frames
;---------------------------------------------------------------------------
AttractTitle:
        tst.b   g_SubState(a6)                  ; 05EDC/05F32
        bne.b   l_05F16                         ; 05EE0/05F36
        tst.b   g_RedrawDone(a6)                ; 05EE2/05F38
        beq.b   l_05F2C                         ; 05EE6/05F3C
        clr.w   g_RawKey(a6)                    ; 05EE8/05F3E
        bsr.w   SwapScreens                     ; 05EEC/05F42
        bsr.w   DrawCreditsScreen               ; 05EF0/05F46
        clr.b   g_ArthurVisible(a6)             ; 05EF4/05F4A
        clr.b   g_Spr47Visible(a6)              ; 05EF8/05F4E
        bsr.w   ArthurSpritePos                 ; 05EFC/05F52
        bsr.w   SetBitplanePtrs                 ; 05F00/05F56
        bsr.w   ShowBackBuffer                  ; 05F04/05F5A
        st.b    g_RedrawPending(a6)             ; 05F08/05F5E
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05F0C/05F62
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05F12/05F68
l_05F16:
        move.w  g_VblCount(a6),d0               ; 05F16/05F6C
        sub.w   g_FrameStamp(a6),d0             ; 05F1A/05F70
        cmp.w   #$190,d0                        ; 05F1E/05F74
        bcs.b   l_05F2C                         ; 05F22/05F78
        tst.b   (MenuPage).l                    ; the test page: no time-out
        bne.b   l_05F2C                         
        addq.b  #GS_TITLE,g_GameState(a6)       ; 05F24/05F7A
        clr.b   g_SubState(a6)                  ; 05F28/05F7E
l_05F2C:
        bra.b   CheckGameStart                  ; 05F2C/05F82

;---------------------------------------------------------------------------
; Attract state 2: high-score table, 200 frames
;---------------------------------------------------------------------------
AttractHiScores:
        tst.b   g_SubState(a6)                  ; 05F2E/05F84
        bne.b   l_05F5C                         ; 05F32/05F88
        tst.b   g_RedrawDone(a6)                ; 05F34/05F8A
        beq.b   CheckGameStart                  ; 05F38/05F8E
        bsr.w   SwapScreens                     ; 05F3A/05F90
