        bsr.w   ShowBackBuffer                  ; 05F4A/05FA0
        st.b    g_RedrawPending(a6)             ; 05F4E/05FA4
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05F52/05FA8
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05F58/05FAE
l_05F5C:
        move.w  g_VblCount(a6),d0               ; 05F5C/05FB2
        sub.w   g_FrameStamp(a6),d0             ; 05F60/05FB6
        cmp.w   #$c8,d0                         ; 05F64/05FBA
        bcs.b   CheckGameStart                  ; 05F68/05FBE
        move.b  #GS_TITLE,g_GameState(a6)       ; 05F6A/05FC0
        clr.b   g_SubState(a6)                  ; 05F70/05FC6

