;---------------------------------------------------------------------------
; ==================================================================
; InGame - dispatch on g_SubState:
;   0 LoadLevel     load the level's files            -> 1
;   1 PlayLevel     g_SubState2: 0 progress map, 1 SetupLevel, 2 start music -> 2
;   2 InPlay        PlayFrame every frame; after a death or a finished level decides
;                   what comes next
;   3 GameOver      'GAME OVER', high-score insertion and name entry
;   4 LevelComplete walk off, bonus                   -> 2 (g_LevelDone) -> 0
;   5 IntroCutscene once per game, before the first level
;   6 Ending        after Astaroth
;   7 WeaponUseless Astaroth's guard beaten without the cross
; ==================================================================
;---------------------------------------------------------------------------
InGame:
        move.b  g_SubState(a6),d0               ; 0645E/064BC
        add.w   d0,d0                           ; 06462/064C0
        add.w   d0,d0                           ; 06464/064C2
        jmp     InGameStateTable(pc,d0.w)       ; 06466/064C4
InGameStateTable:
        bra.w   LoadLevel                       ; 0646A/064C8
        bra.w   PlayLevel                       ; 0646E/064CC
        bra.w   InPlay                          ; 06472/064D0
        bra.w   GameOver                        ; 06476/064D4
        bra.w   LevelComplete                   ; 0647A/064D8
        bra.w   IntroCutscene                   ; 0647E/064DC
        bra.w   Ending                          ; 06482/064E0
        bra.w   WeaponUseless                   ; 06486/064E4

;---------------------------------------------------------------------------
; LevelComplete - sub state 4 (after taking the key). Steps (g_SubState2):
;  0 Arthur stands just past the right edge facing right
;  1 walks right for 32 frames,
;  2 raises his arms (frame 41) for 64 frames while 'BONUS' and the amount are shown
;    (5000 for levels 0-1, 10000 for 2-3, 15000 for 4-5); then the bonus is added and
;    his armour is restored
;  3 walks on for 70 frames; then g_Level + 1 (wrapping after 6), g_LevelDone, and
;    sub state 2 -> InPlay loads the next level.
;---------------------------------------------------------------------------
LevelComplete:
        move.b  g_SubState2(a6),d0              ; 0648A/064E8
        ext.w   d0                              ; 0648E/064EC
        add.w   d0,d0                           ; 06490/064EE
        add.w   d0,d0                           ; 06492/064F0
        jmp     LevelComplete_Jumps(pc,d0.w)    ; 06494/064F2
LevelComplete_Jumps:
        bra.w   Bonus_Setup                     ; 06498/064F6
        bra.w   Bonus_Walk                      ; 0649C/064FA
        bra.w   Bonus_Show                      ; 064A0/064FE
        bra.w   Bonus_WalkOff                   ; 064A4/06502
Bonus_Setup:
        clr.b   g_Jumping(a6)                   ; 064A8/06506
        clr.b   g_Crouching(a6)                 ; 064AC/0650A
        clr.b   g_ArthurState(a6)               ; 064B0/0650E
        move.b  #$1,g_ArthurFacing(a6)          ; 064B4/06512
        move.b  #$1,g_ArthurDir(a6)             ; 064BA/06518
        moveq   #$25,d0                         ; 064C0/0651E  37 px past the right edge
        add.w   g_LevelWidth(a6),d0             ; 064C2/06520
        move.w  d0,g_ArthurX(a6)                ; 064C6/06524
        lea.l   ArthurAnims(pc),a1              ; 064CA/06528
        bsr.w   ArthurSetAnim                   ; 064CE/0652C
        move.b  #$20,g_StateTimer(a6)           ; 064D2/06530
        addq.b  #$1,g_SubState2(a6)             ; 064D8/06536
        bra.w   l_06DA0                         ; 064DC/0653A
Bonus_Walk:
        subq.b  #$1,g_StateTimer(a6)            ; 064E0/0653E
        beq.b   l_064F6                         ; 064E4/06542
        addi.l  #$12000,g_ArthurX(a6)           ; 064E6/06544
        bsr.w   ArthurAnimate                   ; 064EE/0654C
        bra.w   l_06DA0                         ; 064F2/06550
l_064F6:
        move.b  #$29,g_ArthurFrame(a6)          ; 064F6/06554  arms raised
        clr.b   g_ArthurAnimTimer(a6)           ; 064FC/0655A
        move.b  #150,g_StateTimer(a6)           ; 'BONUS' and the amount: 3 s (the original: 64 frames)
snd71_go:
