        beq.b   l_06558                         ; 06512/06572
        move.b  #$1f,g_TextShadow(a6)           ; 06514/06574
        move.b  #$1b,g_TextInk(a6)              ; 0651A/0657A
        move.b  #$5,g_TextPaper(a6)             ; 06520/06580
        lea.l   TxtBonus(pc),a3                 ; 06526/06586
