        move.w  g_Level(a6),d0                  ; 06540/065A0
        mulu.w  #$6,d0                          ; 06544/065A4
        lea.l   TxtBonusAmounts(pc,d0.w),a3     ; 06548/065A8
        moveq   #$18,d1                         ; 0654C/065AC
        addq.w  #$8,d2                          ; 0654E/065AE
        bsr.w   PrintString                     ; 06550/065B0
