;---------------------------------------------------------------------------
; Sub state 2 - the normal 'playing' state. Each frame:
;   no death and no finished level -> PlayFrame
;   level finished (g_LevelDone)   -> sub state 0, load the next level
;   Arthur died (g_PlayerDied):
;     two players and the other one still has lives -> SwapPlayers; reload the level
;       if the other player is on a different one, else straight to sub state 1
;     else lives left -> sub state 1 (progress map, set-up) on the same level
;     else -> attract mode (g_GameState 1)
;---------------------------------------------------------------------------
InPlay:
        tst.b   g_PlayerDied(a6)                ; 0674C/067B0
        beq.b   l_067B0                         ; 06750/067B4
        tst.b   g_TwoPlayer(a6)                 ; 06752/067B6  2 players: does the other player have lives left?
        beq.b   l_06764                         ; 06756/067BA
        lea.l   (GLOBALS_P2).l,a0               ; 06758/067BC
        tst.b   $a6(a0)                         ; 0675E/     
        bne.b   l_06784                         ; 06762/067CA
l_06764:
        tst.b   g_Lives(a6)                     ; 06764/067CC  no lives: back to the attract screens
        bne.b   l_0679E                         ; 06768/067D0
        move.b  #GS_TITLE,g_GameState(a6)       ; 0676A/067D2
        clr.b   g_SubState(a6)                  ; 06770/067D8
        clr.b   g_SubState2(a6)                 ; 06774/067DC
        clr.b   g_SubState3(a6)                 ; 06778/067E0
        st.b    g_RedrawPending(a6)             ; 0677C/067E4
        bra.w   LogicExit                       ; 06780/067E8
l_06784:
        bsr.w   SwapPlayers                     ; 06784/067EC  switch to the other player
        clr.b   g_SubState(a6)                  ; 06788/067F0
        lea.l   (GLOBALS_P2).l,a0               ; 0678C/067F4
        move.w  $9a(a0),d0                      ; 06792/       same level as before? (then no need to reload)
        cmp.w   g_Level(a6),d0                  ; 06796/06802
        bne.w   LogicExit                       ; 0679A/06806
l_0679E:
        move.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 0679E/0680A  progress map and level set-up
        clr.b   g_SubState2(a6)                 ; 067A4/06810
        clr.b   g_SubState3(a6)                 ; 067A8/06814
        bra.w   LogicExit                       ; 067AC/06818
l_067B0:
        tst.b   g_LevelDone(a6)                 ; 067B0/0681C  normal frame: no level change pending
        beq.w   PlayFrame                       ; 067B4/06820
        clr.b   g_LevelDone(a6)                 ; 067B8/06824  level finished: load the next one (g_Level already advanced)
        clr.b   g_SubState(a6)                  ; 067BC/06828
        bra.w   LogicExit                       ; 067C0/0682C

;---------------------------------------------------------------------------
; 21 words: byte size of each BOB graphics set (see BobSetOffsets)
;---------------------------------------------------------------------------
BobSetSizes:
	dc.b	$10,$E0,$08,$98,$11,$80,$04,$60,$10,$D6,$3F,$C0,$2F,$3A,$0B,$E0
	dc.b	$3B,$88,$06,$D6,$20,$58,$15,$2C,$13,$92,$50,$00,$08,$52,$07,$94
	dc.b	$00,$00,$0B,$68,$0D,$C0,$08,$20,$08,$98
SmallBobSetSizes:
	dc.b	$00,$82,$00,$96,$01,$40,$01,$40,$01,$90,$01,$90,$01,$90,$01,$A4
	dc.b	$01,$A4,$01,$90

;---------------------------------------------------------------------------
; Per-level long bitmask of the BOB sets LoadLevel copies out of the big
; graphics file (only the enemies used on that level are kept in memory).
;---------------------------------------------------------------------------
LevelBobSetMask:
	dc.b	$00,$02,$89,$EB,$00,$12,$05,$36,$00,$0C,$18,$B1,$00,$00,$50,$24
	dc.b	$00,$08,$06,$65,$00,$00,$17,$61,$00,$00,$A0,$00
LevelSmallBobMask:
	dc.b	$00,$EB,$02,$07,$00,$13,$01,$03,$01,$01,$00,$02,$00,$01

;---------------------------------------------------------------------------
; Sub state 0: load the level.
;  - file $7FA6 (track 37)      -> BOB_GFX_A ($311E8)
;  - file $7FB0 (tracks 38-56)  -> SCREEN_0 area (enemy graphics)
;  - level file via index $7F8E -> LEVEL_FILE ($65548)
; then builds frame pointer tables with BuildFrameTable.
; [1MB] Sub state 0: load the level (1MB build).
; [1MB] Only the per-level file is loaded (tracks 84-109): the enemy graphics are already cached,
; [1MB] so BuildFrameTable points the frame tables into the cache (BobSetOffsetsCached) instead.
;---------------------------------------------------------------------------
LoadLevel:
        btst    #PF_CACHE,(Profile).l           ; cache: the graphics are already in memory
        bne.b   ll_cached                       
        move.w  #DMAF_RASTER,(CUSTOM+$96).l     ; bitplane DMA off while loading (first now: the small
        lea.l   FileSmallBobs(pc),a1            ; BOBs load into the screens too)
        bsr.w   LoadFile                        ; 06830/     
        lea.l   FileEnemyBobs(pc),a1            ; 0683A/     
        bsr.w   LoadFile                        ; 0683E/     
ll_cached:
        move.w  g_Level(a6),d0                  ; the level's map tables (LoadLevelTables), then its
        jsr     LoadLevelTables                 ; tile file
        lea.l   LevelFileIndex(pc),a1           ; 06842/06898
        move.w  g_Level(a6),d0                  ; 06846/0689C
        add.w   d0,d0                           ; 0684A/068A0
        adda.w  d0,a1                           ; 0684C/068A2
        adda.w  (a1),a1                         ; 0684E/068A4
        bsr.w   LoadFile                        ; 06850/068A6  load per-level file (tracks 84-109)
        move.l  a5,g_LevelFileEnd(a6)           ; 06854/068AA
        move.w  g_Level(a6),d0                  ; 06858/068AE
        lsl.w   #$2,d0                          ; 0685C/068B2
        move.l  LevelBobSetMask(pc,d0.w),d0     ; 0685E/068B4
        lea.l   g_BobSets(a6),a0                ; 06862/068B8
        movea.l g_LevelFileEnd(a6),a2           ; 06866/068BC
        lea.l   BobSetSizes(pc),a3              ; 0686A/068C0
        lea.l   BobSetOffsets(pc),a4            ; 0686E/     
        lea.l   (SCREEN_0).l,a5                 ; 06872/     
        btst    #PF_CACHE,(Profile).l           
        beq.b   ll_sets                         
        lea.l   (ENEMY_GFX_CACHE).l,a5          ; the masked enemy sets
ll_sets:
        moveq   #$14,d7                         ; 06878/068D2
        bsr.w   BuildFrameTable                 ; 0687A/068D4
        move.w  g_Level(a6),d0                  ; 0687E/068D8
        add.w   d0,d0                           ; 06882/068DC
        lea.l   LevelSmallBobMask(pc),a4        ; (out of reach of an indexed pc read now)
        move.w  (a4,d0.w),d0                    ; 06884/068DE
        lea.l   g_SmallBobSets(a6),a0           ; 06888/068E2
        lea.l   SmallBobSetSizes(pc),a3         ; 0688C/068E6
        lea.l   SmallBobSetOffsets(pc),a4       ; 06890/068EA
        lea.l   (SMALLBOB_LOAD).l,a5            ; 06894/068EE
        btst    #PF_CACHE,(Profile).l           
        beq.b   ll_small                        
        lea.l   (SMALLBOB_CACHE).l,a5           ; the masked small sets
ll_small:
        moveq   #$9,d7                          ; 0689A/068F8
        bsr.w   BuildFrameTable                 ; 0689C/068FA
        jsr     BuildLevelMasks                 ; 512K: the one-plane masks of the level's images
        clr.b   g_LevelDone(a6)                 ; 068A0/068FE
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 068A4/06902
        clr.b   g_SubState2(a6)                 ; 068A8/06906
        clr.b   g_SubState3(a6)                 ; 068AC/0690A
        tst.b   g_ShowIntro(a6)                 ; 068B0/0690E  first level of a game: skip the progress map (the opening scene comes instead)
        beq.w   LogicExit                       ; 068B4/06912
        addq.b  #$1,g_SubState2(a6)             ; 068B8/06916
        bra.w   LogicExit                       ; 068BC/0691A

;---------------------------------------------------------------------------
; Sub state 1: in-level play. $2B: 0 = progress map, 1 = set up level, 2 = play
;---------------------------------------------------------------------------
PlayLevel:
        tst.b   g_RedrawDone(a6)                ; 068C0/0691E  wait for any redraw in progress
        beq.w   LogicExit                       ; 068C4/06922
        clr.b   g_PlayerDied(a6)                ; 068C8/06926
        cmpi.b  #$1,g_SubState2(a6)             ; 068CC/0692A
        bcs.w   ProgressMap                     ; 068D2/06930
        bhi.w   l_06C0E                         ; 068D6/06934

;---------------------------------------------------------------------------
; SetupLevel - PlayLevel step 1: start (or restart) the level.
;  - map pointer, boss countdown, bonus-carrier and weapon-drop state
;  - start or checkpoint position and time (LevelStartPos / LevelCheckpointPos,
;    LevelTimeStart / LevelTimeCheckpoint); at the checkpoint the screen starts
;    LevelCheckpointX further right
;  - level bounds from LevelBounds (4 bytes, each x 256: origin X, end X, height,
;    origin Y); scroll limits reset
;  - every Arthur variable cleared: armour on, no frog, no key
;  - spawn quotas, then all shot / special / enemy-shot / spawner / item / enemy slots freed
;  - first game frame: go to the opening scene instead (sub state 5), which comes back here
;  - fill g_Items from LevelItemLists (type, param, x, y; shootable scenery gets 15 hits)
;    and g_Enemies from LevelEnemyLists (the placed enemies: type, param, x, y)
;  - draw both screen buffers, the HUD (lives, timer, weapon), show Arthur -> step 2
;---------------------------------------------------------------------------
SetupLevel:
        lea.l   LevelMapTable(pc),a1            ; 068DA/06938
        lea.l   LevelBossCountdown(pc),a2       ; 068DE/0693C
        move.w  g_Level(a6),d0                  ; 068E2/06940
        adda.w  d0,a2                           ; 068E6/06944
        add.w   d0,d0                           ; 068E8/06946
        adda.w  (a1,d0.w),a1                    ; 068EA/06948
        move.l  a1,g_MapPtr(a6)                 ; 068EE/0694C  level map
        move.b  (a2),g_BossCountdown(a6)        ; 068F2/06950  boss hits before the key / ending (BossKilled)
        clr.b   g_BigEnemyCount(a6)             ; 068F6/06954
        move.b  #$6,g_BonusEvery(a6)            ; 068FA/06958  every 6th spawn carries a bonus prize
        clr.b   g_BonusCycle(a6)                ; 06900/0695E
        clr.b   g_BonusRoll(a6)                 ; 06904/06962
        clr.b   g_WeaponOdds(a6)                ; 06908/06966
        clr.b   g_WeaponOdds+1(a6)              ; 0690C/0696A
        clr.b   g_WeaponOdds+2(a6)              ; 06910/0696E
        clr.b   g_WeaponOdds+3(a6)              ; 06914/06972
        clr.b   g_WeaponOdds+4(a6)              ; 06918/06976
        lea.l   LevelStartPos(pc),a1            ; 0691C/0697A  start of the level ...
        lea.l   LevelTimeStart(pc),a2           ; 06920/0697E
        tst.b   g_Checkpoint(a6)                ; 06924/06982
        beq.b   l_06932                         ; 06928/06986
        lea.l   LevelCheckpointPos(pc),a1       ; 0692A/06988  ... or the checkpoint
        lea.l   LevelTimeCheckpoint(pc),a2      ; 0692E/0698C
l_06932:
        move.w  g_Level(a6),d0                  ; 06932/06990
        add.w   d0,d0                           ; 06936/06994
        adda.w  d0,a1                           ; 06938/06996
        adda.w  d0,a2                           ; 0693A/06998
        move.w  (a2),g_TimeLeft(a6)             ; 0693C/0699A
        clr.w   d0                              ; 06940/0699E
        move.b  (a1)+,d0                        ; 06942/069A0
        move.w  d0,g_ArthurX(a6)                ; 06944/069A2
        move.b  (a1)+,d0                        ; 06948/069A6
        move.w  d0,g_ArthurY(a6)                ; 0694A/069A8
        lea.l   LevelBounds(pc),a1              ; 0694E/069AC  level bounds, in units of 256 px
        move.w  g_Level(a6),d0                  ; 06952/069B0
        lsl.w   #$2,d0                          ; 06956/069B4
        adda.w  d0,a1                           ; 06958/069B6
        move.b  (a1)+,d0                        ; 0695A/069B8
        lsl.w   #$8,d0                          ; 0695C/069BA
        move.w  d0,g_LevelOriginX(a6)           ; 0695E/069BC
        move.b  (a1)+,d0                        ; 06962/069C0
        lsl.w   #$8,d0                          ; 06964/069C2
        sub.w   g_LevelOriginX(a6),d0           ; 06966/069C4
        move.w  d0,g_LevelWidth(a6)             ; 0696A/069C8
        move.b  (a1)+,d0                        ; 0696E/069CC
        lsl.w   #$8,d0                          ; 06970/069CE
        move.w  d0,g_LevelHeight(a6)            ; 06972/069D0
        move.b  (a1)+,d0                        ; 06976/069D4
        lsl.w   #$8,d0                          ; 06978/069D6
        move.w  d0,g_LevelOriginY(a6)           ; 0697A/069D8
        sub.w   d0,g_LevelHeight(a6)            ; 0697E/069DC
        clr.w   g_ScrollTileX(a6)               ; 06982/069E0
        clr.w   g_ScrollTileY(a6)               ; 06986/069E4
        tst.b   g_Checkpoint(a6)                ; 0698A/069E8  checkpoint: start that far into the level
        beq.b   l_069A8                         ; 0698E/069EC
        lea.l   LevelCheckpointX(pc),a0         ; 06990/069EE
        move.w  g_Level(a6),d0                  ; 06994/069F2
        add.w   d0,d0                           ; 06998/069F6
        adda.w  d0,a0                           ; 0699A/069F8
        move.w  (a0),d0                         ; 0699C/069FA
        add.w   d0,g_ArthurX(a6)                ; 0699E/069FC
        lsr.w   #$4,d0                          ; 069A2/06A00
        move.w  d0,g_ScrollTileX(a6)            ; 069A4/06A02
l_069A8:
        clr.w   g_CamMinX(a6)                   ; 069A8/06A06
        clr.w   g_CamMinY(a6)                   ; 069AC/06A0A
        clr.w   g_CameraX(a6)                   ; 069B0/06A0E
        clr.w   g_CameraY(a6)                   ; 069B4/06A12
        clr.w   g_ScrollFineX(a6)               ; 069B8/06A16
        clr.w   g_ScrollFineY(a6)               ; 069BC/06A1A
        move.w  g_ScrollTileX(a6),g_NewTileX(a6); 069C0/06A1E
        move.w  g_ScrollTileY(a6),g_NewTileY(a6); 069C6/06A24
        st.b    g_MaxMapZone(a6)                ; 069CC/06A2A  force UpdateMapZone to start the first zone
        st.b    g_MapZone(a6)                   ; 069D0/06A2E
        clr.b   g_ArthurState(a6)               ; 069D4/06A32
        clr.b   g_NoArmour(a6)                  ; 069D8/06A36
        clr.b   g_ArthurFlash(a6)               ; 069DC/06A3A
        clr.b   g_FrogTimer(a6)                 ; 069E0/06A3E
        clr.b   g_KeyState(a6)                  ; 069E4/06A42
        clr.l   g_ArthurAnim(a6)                ; 069E8/06A46
        clr.b   g_ArthurAnimTimer(a6)           ; 069EC/06A4A
        clr.b   g_ArthurDir(a6)                 ; 069F0/06A4E
