;---------------------------------------------------------------------------
; Common exit: restore registers and RTE
;---------------------------------------------------------------------------
LogicExit:
	ifd	RASTER_BUILD
        jmp     EnhLogicEnd                     ; timing build: black, then this
	endc
        movem.l (a7)+,d0-d7/a0-a5               ; 06BF2/06C50
        jmp     IrqExit1                        ; 06BF6/06C54  (rte, with the interrupted a6)

;---------------------------------------------------------------------------
; world X of the half-way checkpoint per level
;---------------------------------------------------------------------------
LevelCheckpointX:
	dc.w	$0700,$0400,$0400,$0500,$1A00,$1D00,$1F00	; levels 0-6

;---------------------------------------------------------------------------
; LevelMusic - tune number per level. Only the 1MB build uses it: there it is
; passed to PlayMusic (player command 1). In this 512K build the lookup
; is still done but the call was removed, so there is no in-game music.
;---------------------------------------------------------------------------
LevelMusic:
	dc.b	2,2,13,13,13,12,12,0	; levels 0-6 (1MB tune numbers), pad
l_06C0E:
        moveq   #$0,d0                          ; 06C0E/06C6C  PlayLevel step 2: the level tune (1MB build only), then play (sub state 2)
        move.w  g_Level(a6),d0                  ; 06C10/06C6E
        move.b  LevelMusic(pc,d0.w),d0          ; 06C14/06C72
snd79_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd79_512                       
        move    (a7)+,ccr                       
        bsr.w   PlayMusic                       ;      /06C76
        bra.w   snd79_end                       
snd79_512:
