        move.b  #GS_TITLE,g_GameState(a6)       ; 06C2E/06C94  back to the attract screens, redrawing at the current camera position
        clr.b   g_SubState(a6)                  ; 06C34/06C9A
        clr.b   g_SubState2(a6)                 ; 06C38/06C9E
        clr.b   g_SubState3(a6)                 ; 06C3C/06CA2
        move.w  g_ScrollFineX(a6),d0            ; 06C40/06CA6
