;---------------------------------------------------------------------------
; ==================================================================
; Ending - sub state 6, entered when Astaroth is beaten with the cross (BossKilled).
; Steps (g_SubState2):
;  0 Arthur (armour on) faces right at Y $4E; the princess (type 15, g_Enemy1) starts at
;    X $F3. They meet a third of the way from Arthur: g_ArthurAux = his stop X, the
;    princess stops 16 px to its right.
;  1 both walk towards each other at 1.125 px/frame; Arthur raises his arms (frame 41)
;    when he arrives.
;  2 the princess takes frame 5 (size 3); hold for 550 frames.
;  3 'CONGRATULATIONS !' / 'THIS STORY HAS A HAPPY ENDING.'; when the timer runs out,
;    award 50000 (AddScore 21), print the score, and end the game: no lives left,
;    sub state 3 (game over and high-score entry).
; ===================================================================
;---------------------------------------------------------------------------
Ending:
        lea.l   g_Enemy1(a6),a5                 ; 071EC/07254
        move.b  g_SubState2(a6),d0              ; 071F0/07258
        ext.w   d0                              ; 071F4/0725C
        add.w   d0,d0                           ; 071F6/0725E
        add.w   d0,d0                           ; 071F8/07260
        jmp     Ending_Jumps(pc,d0.w)           ; 071FA/07262
Ending_Jumps:
        bra.w   Ending_Setup                    ; 071FE/07266
        bra.w   Ending_Walk                     ; 07202/0726A
        bra.w   Ending_Embrace                  ; 07206/0726E
        bra.w   Ending_Message                  ; 0720A/07272
Ending_Setup:
        move.w  #$f3,d0                         ; 0720E/07276  meet a third of the way from Arthur to the princess
        sub.w   g_ArthurX(a6),d0                ; 07212/0727A
        ext.l   d0                              ; 07216/0727E
        divs.w  #$3,d0                          ; 07218/07280
        add.w   g_ArthurX(a6),d0                ; 0721C/07284
        move.w  d0,g_ArthurAux(a6)              ; 07220/07288
        addi.w  #$10,d0                         ; 07224/0728C  the princess stops 16 px to Arthur's right
        move.w  d0,Scn_Target(a5)               ; 07228/07290
        move.w  #$4e,g_ArthurY(a6)              ; 0722C/07294
        move.b  #$1,g_ArthurDir(a6)             ; 07232/0729A
        move.b  #$1,g_ArthurFacing(a6)          ; 07238/072A0
        clr.b   g_NoArmour(a6)                  ; 0723E/072A6  armour on
        lea.l   ArthurAnims(pc),a1              ; 07242/072AA
        bsr.w   ArthurSetAnim                   ; 07246/072AE
        move.b  #$1,(a5)                        ; 0724A/072B2  princess: active, at ($F3,$4E), type 15, size 1
        move.w  #$f3,O_X(a5)                    ; 0724E/072B6
        move.w  #$4e,O_Y(a5)                    ; 07254/072BC
        move.b  #E_PRINCESS,O_Type(a5)          ; 0725A/072C2
        move.b  #$1,O_Size(a5)                  ; 07260/072C8
        lea.l   Princess_AnimWalk(pc),a0        ; 07266/072CE
        bsr.w   SetAnim                         ; 0726A/072D2
        addq.b  #$1,g_SubState2(a6)             ; 0726E/072D6
        bra.w   Ending_Draw                     ; 07272/072DA
Ending_Walk:
        move.w  g_ArthurX(a6),d0                ; 07276/072DE
        cmp.w   g_ArthurAux(a6),d0              ; 0727A/072E2
        bcc.b   l_0728E                         ; 0727E/072E6
        addi.l  #$12000,g_ArthurX(a6)           ; 07280/072E8  Arthur walks right 1.125 px/frame
        bsr.w   ArthurAnimate                   ; 07288/072F0
        bra.b   l_07294                         ; 0728C/072F4
l_0728E:
        move.b  #$29,g_ArthurFrame(a6)          ; 0728E/072F6  arrived: arms raised (frame 41)
l_07294:
        move.w  Scn_Target(a5),d0               ; 07294/072FC
        cmp.w   O_X(a5),d0                      ; 07298/07300
        bcc.b   l_072AE                         ; 0729C/07304
        subi.l  #$12000,O_X(a5)                 ; 0729E/07306  princess walks left 1.125 px/frame
        bsr.w   Animate                         ; 072A6/0730E
        bra.w   Ending_Draw                     ; 072AA/07312
l_072AE:
        addq.b  #$1,g_SubState2(a6)             ; 072AE/07316
        bra.b   Ending_Draw                     ; 072B2/0731A
Ending_Embrace:
        move.b  #$5,O_Frame(a5)                 ; 072B4/0731C  princess frame 5, size 3 - together
        move.b  #$3,O_Size(a5)                  ; 072BA/07322
        move.w  #$226,Scn_Target(a5)            ; 072C0/07328  550 frames (about 11 seconds)
        addq.b  #$1,g_SubState2(a6)             ; 072C6/0732E
        bra.b   Ending_Draw                     ; 072CA/07332
Ending_Message:
        move.b  #$1,g_TextInk(a6)               ; 072CC/07334  white on the background colour
        move.b  #$18,g_TextPaper(a6)            ; 072D2/0733A
        lea.l   TxtCongratulations(pc),a3       ; 072D8/07340
        moveq   #$7,d1                          ; 072DC/07344
        move.w  #$70,d2                         ; 072DE/07346
        bsr.w   PrintString                     ; 072E2/0734A
        lea.l   TxtHappyEnding(pc),a3           ; 072E6/0734E
        moveq   #$1,d1                          ; 072EA/07352
        move.w  #$a0,d2                         ; 072EC/07354
        bsr.w   PrintString                     ; 072F0/07358
        subq.w  #$1,Scn_Target(a5)              ; 072F4/0735C
        bne.b   Ending_Draw                     ; 072F8/07360
        moveq   #PTS_50000,d0                   ; 072FA/07362
        bsr.w   AddScore                        ; 072FC/07364
        moveq   #$1,d1                          ; 07300/07368  print the score in the player's HUD position
        tst.b   g_CurPlayer(a6)                 ; 07302/0736A
        beq.b   l_0730A                         ; 07306/0736E
        moveq   #$16,d1                         ; 07308/07370
l_0730A:
        moveq   #$8,d2                          ; 0730A/07372
        move.l  g_Score(a6),d6                  ; 0730C/07374
        bsr.w   PrintBCD                        ; 07310/07378
        st.b    g_PlayerDied(a6)                ; 07314/0737C  game over: lives gone, sub state 3 (high-score table / name entry)
        clr.b   g_Lives(a6)                     ; 07318/07380
        move.b  #SS_GAMEOVER,g_SubState(a6)     ; 0731C/07384
        clr.b   g_SubState2(a6)                 ; 07322/0738A
        clr.b   g_SubState3(a6)                 ; 07326/0738E
        bra.w   LogicExit                       ; 0732A/07392

;---------------------------------------------------------------------------
; Queue the princess, then the shared scene exit (redraw and show the screen)
;---------------------------------------------------------------------------
Ending_Draw:
        lea.l   g_SaveBufA(a6),a0               ; 0732E/07396
        move.l  a0,g_BlitListPtr(a6)            ; 07332/0739A
        bsr.w   QueueEnemyDraw                  ; 07336/0739E
        bra.w   l_06DA0                         ; 0733A/073A2

