Princess_AnimWalk:
	AF	$03,2
	AL	$04,2,Princess_AnimWalk
TxtCongratulations:
	dc.b	'CONGRATULATIONS !'
	dc.b	$00
TxtHappyEnding:
	dc.b	'THIS STORY HAS A HAPPY ENDING.'
	dc.b	$00
