WeaponUseless:
        lea.l   g_SaveBufA(a6),a0               ; 073AC/07414
        move.l  a0,g_BlitListPtr(a6)            ; 073B0/07418
        move.b  #$d,g_TextInk(a6)               ; 073B4/0741C  ink 13 on paper 6
        move.b  #$6,g_TextPaper(a6)             ; 073BA/07422
