        moveq   #$3,d1                          ; 073C4/0742C
        move.w  #$58,d2                         ; 073C6/0742E
        bsr.w   PrintString                     ; 073CA/07432
        move.b  #$1,g_TextInk(a6)               ; 073CE/07436
        move.b  #$18,g_TextPaper(a6)            ; 073D4/0743C
        lea.l   TxtGetCrucifix(pc),a3           ; 073DA/07442
        moveq   #$1,d1                          ; 073DE/07446
        move.w  #$68,d2                         ; 073E0/07448
        bsr.w   PrintString                     ; 073E4/0744C
        subq.b  #$1,g_StateTimer(a6)            ; 073E8/07450  g_StateTimer set by BossKilled
        bne.w   l_07132                         ; 073EC/07454
        move.w  #$4,g_Level(a6)                 ; 073F0/07458  back to level index 4 (the start of the last two levels)
        clr.b   g_SubState(a6)                  ; 073F6/0745E
        clr.b   g_SubState2(a6)                 ; 073FA/07462
        clr.b   g_SubState3(a6)                 ; 073FE/07466

;---------------------------------------------------------------------------
; ==================================================================
; IntroCutscene - sub state 5, the opening scene (shown once per game: g_ShowIntro).
; Objects: the princess in g_Enemy1 (type 15), the demon in g_Enemies slot 0 (type 6, the
; Satan graphics and animations), and Arthur's armour on the ground in special object 0.
; Steps (g_SubState3):
;   0 Arthur sits with the princess in his underwear (frame 40) at X $60; his armour
;     lies at X $50. Draw both screens; wait 60 frames. (1MB build: tune 14.)
;   1 the demon appears top right ($C5,$A0), the princess changes to frame 0; wait 20 frames.
;   2 the demon flaps for 64 frames,
;   3 then turns to dive (the 1MB build stops the music: tune 0).
;   4 it dives down-left at (-0.33, -6) px/frame until it reaches the floor; it grabs the
;     princess and Arthur is hit (ArthurState 1, pushed left).
;   5 Arthur is knocked back by the normal ArthurUpdate (g_NoArmour is clear, so it takes
;     the 'armour flies off' path; the pieces are never drawn here) while the demon carries the princess up and
;     right at (+1.125, +4.19) until Y $A0, where the princess is removed.
;   6-7 32 frames, then the demon is removed.
;   8 Arthur walks to his armour at X $50 and puts it on (g_NoArmour cleared),
;   9 walks on to X $60, stands (frame 4) for 30 frames,
;  10 and the game starts: sub state 1, progress map skipped (g_SubState2 = 1).
; ===================================================================
;---------------------------------------------------------------------------
IntroCutscene:
        lea.l   g_Enemies(a6),a5                ; 07402/0746A
        move.b  g_SubState3(a6),d0              ; 07406/0746E
        ext.w   d0                              ; 0740A/07472
        add.w   d0,d0                           ; 0740C/07474
        add.w   d0,d0                           ; 0740E/07476
        jmp     IntroCutscene_Jumps(pc,d0.w)    ; 07410/07478
IntroCutscene_Jumps:
        bra.w   Intro_Setup                     ; 07414/0747C
        bra.w   Intro_DemonAppears              ; 07418/07480
        bra.w   Intro_DemonWait                 ; 0741C/07484
        bra.w   Intro_DemonHover                ; 07420/07488
        bra.w   Intro_DemonSwoop                ; 07424/0748C
        bra.w   Intro_Abduction                 ; 07428/07490
        bra.w   Intro_Pause                     ; 0742C/07494
        bra.w   Intro_DemonGone                 ; 07430/07498
        bra.w   Intro_WalkToArmour              ; 07434/0749C
        bra.w   Intro_WalkOn                    ; 07438/074A0
        bra.w   Intro_Finish                    ; 0743C/074A4
Intro_Setup:
        moveq   #TUNE_INTRO,d0                  ; 07440/074A8
snd88_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd88_512                       
        move    (a7)+,ccr                       
        bsr.w   PlayMusic                       ;      /074AA
        bra.w   snd88_end                       
snd88_512:
        move    (a7)+,ccr                       
snd88_end:
        clr.b   g_NoArmour(a6)                  ; 07442/074AE  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]
        move.w  #$60,g_ArthurX(a6)              ; 07446/074B2  Arthur at ($60,$40), sitting (frame 40), facing right
        move.w  #$40,g_ArthurY(a6)              ; 0744C/074B8
        move.b  #$28,g_ArthurFrame(a6)          ; 07452/074BE
        move.b  #$1,g_ArthurDir(a6)             ; 07458/074C4
        move.b  #$1,g_ArthurFacing(a6)          ; 0745E/074CA
        clr.b   g_OnLadder(a6)                  ; 07464/074D0
        clr.b   g_OnPlatform(a6)                ; 07468/074D4
        st.b    g_ArthurVisible(a6)             ; 0746C/074D8
        clr.b   g_Spr47Visible(a6)              ; 07470/074DC
        move.b  #$3c,g_StateTimer(a6)           ; 07474/074E0  60 frames
        clr.b   (a5)                            ; 0747A/074E6  demon slot free for now
        lea.l   $3c(a5),a5                      ; 0747C/074E8
        move.b  #$1,(a5)                        ; 07480/074EC  g_Enemy1 = princess: active, on screen, state 1, size 1, type 15, at ($70,$40)
        move.b  #$1,O_OnScreen(a5)              ; 07484/074F0
        move.b  #ST_ACTIVE,O_State(a5)          ; 0748A/074F6
