;---------------------------------------------------------------------------
; ==================================================================
; ProgressMap - sub state 1 / g_SubState2 0, before each level (and after a life lost).
;  0 load FileProgressMap and unpack it into the spare screen: 80 lines x 5 planes,
;    each plane line RLE-packed to $2C bytes (n >= 0: copy n+1 bytes; n < 0: repeat the
;    next byte -n+1 times; -128: nothing), with blank borders. Point the map copper list
;    ($1A250) at it, and place a flashing Arthur marker from ProgressMapMarkers.
;  1 scroll the map 144 px to the left, one pixel a frame; the marker stops flashing.
;  2 hold for 100 frames, then on to level set-up (g_SubState2 = 1).
; The 1MB build stops the music and unpacks the copy kept at PROGRESS_MAP_CACHE instead
; of loading the file.
; ===================================================================
;---------------------------------------------------------------------------
ProgressMap:
        cmpi.b  #$1,g_SubState3(a6)             ; 07736/0779E
        beq.w   ProgressMap_Scroll              ; 0773C/077A4
        bhi.w   ProgressMap_Wait                ; 07740/077A8
        btst    #PF_CACHE,(Profile).l           
        beq.b   pm_load                         
        lea.l   (PROGRESS_MAP_CACHE).l,a0       ; 1MB: the map from the cache
        bra.b   pm_have                         
pm_load:
        move.l  #PM_MFM,(MfmBuf).l              ; (the level area is in use now: MFM buffer in the first screen)
        lea.l   FileProgressMap(pc),a1          ; 07744/       load the packed map picture
        bsr.w   LoadFile                        ; 07748/     
        move.l  #MFM_BUFFER,(MfmBuf).l
        moveq   #$0,d0                          ; 0774C/     
        lea.l   FileProgressMap(pc),a0          ; 0774E/     
        movea.l (a0),a0                         ; 07752/     
pm_have:
        movea.l g_ScreenSpare1(a6),a1           ; 07754/077BC  unpack into the lower of the two spare screens
        movea.l g_ScreenSpare2(a6),a2           ; 07758/077C0
        cmpa.l  a1,a2                           ; 0775C/077C4
        bhi.b   l_07762                         ; 0775E/077C6
        movea.l a2,a1                           ; 07760/077C8
l_07762:
        move.l  a1,g_ArthurAnim(a6)             ; 07762/077CA
        move.w  #$1f3f,d7                       ; 07766/077CE  clear $7D00 bytes
l_0776A:
        clr.l   (a1)+                           ; 0776A/077D2
        dbra    d7,l_0776A                      ; 0776C/077D4
        moveq   #$2c,d5                         ; 07770/077D8  $2C bytes per plane line; 80 lines
        moveq   #$4f,d7                         ; 07772/077DA
l_07774:
        moveq   #$4,d6                          ; 07774/077DC  5 planes
l_07776:
        clr.w   d4                              ; 07776/077DE
        clr.l   (a1)+                           ; 07778/077E0  4 blank bytes at the left
l_0777A:
        clr.w   d0                              ; 0777A/077E2
        move.b  (a0)+,d0                        ; 0777C/077E4
        bmi.b   l_0778A                         ; 0777E/077E6  n < 0: run
l_07780:
        move.b  (a0)+,(a1)+                     ; 07780/077E8  n >= 0: n+1 literal bytes
        addq.w  #$1,d4                          ; 07782/077EA
        dbra    d0,l_07780                      ; 07784/077EC
        bra.b   l_07798                         ; 07788/077F0
l_0778A:
        neg.b   d0                              ; 0778A/077F2  -n+1 copies of the next byte (-128: none)
        bvs.b   l_07798                         ; 0778C/077F4
        move.b  (a0)+,d1                        ; 0778E/077F6
l_07790:
        move.b  d1,(a1)+                        ; 07790/077F8
        addq.w  #$1,d4                          ; 07792/077FA
        dbra    d0,l_07790                      ; 07794/077FC
l_07798:
        cmp.w   d5,d4                           ; 07798/07800
        bcs.b   l_0777A                         ; 0779A/07802
        clr.w   (a1)+                           ; 0779C/07804  2 blank bytes at the right (line = $32 bytes)
        dbra    d6,l_07776                      ; 0779E/07806
        dbra    d7,l_07774                      ; 077A2/0780A
        move.w  #$3e7,d7                        ; 077A6/0780E  blank area below the picture
l_077AA:
        clr.l   (a1)+                           ; 077AA/07812
        dbra    d7,l_077AA                      ; 077AC/07814
        bsr.w   SetMapBitplanePtrs              ; 077B0/07818
        lea.l   CUSTOM,a0                       ; 077B4/0781C
        move.l  #COPPER_MAP,COP2LCH(a0)         ; 077BA/07822  map copper list
        bsr.w   SwapScreens                     ; 077C2/0782A
        move.w  g_Level(a6),d0                  ; 077C6/0782E  marker = ProgressMapMarkers[level][checkpoint]
        lsl.w   #$3,d0                          ; 077CA/07832
        tst.b   g_Checkpoint(a6)                ; 077CC/07834
        beq.b   l_077D4                         ; 077D0/07838
        addq.w  #$4,d0                          ; 077D2/0783A
l_077D4:
        lea.l   ProgressMapMarkers(pc,d0.w),a1  ; 077D4/0783C
        move.w  (a1)+,g_ArthurX(a6)             ; 077D8/07840
        move.w  (a1)+,g_ArthurY(a6)             ; 077DC/07844
        addq.w  #$8,g_ArthurX(a6)               ; 077E0/07848
        subq.w  #$8,g_ArthurY(a6)               ; 077E4/0784C
        st.b    g_ArthurVisible(a6)             ; 077E8/07850
        clr.b   g_Spr47Visible(a6)              ; 077EC/07854
        clr.b   g_ArthurFrame(a6)               ; 077F0/07858
        clr.w   g_ScrollFineX(a6)               ; 077F4/0785C
        clr.w   g_ScrollFineY(a6)               ; 077F8/07860
        clr.w   g_ScrollTileX(a6)               ; 077FC/07864
        clr.w   g_ScrollTileY(a6)               ; 07800/07868
        st.b    g_ArthurFlash(a6)               ; 07804/0786C  marker flashes while the map scrolls
        btst    #PF_MUSIC,(Profile).l           ; with music: the start tune, as the map appears
        beq.b   pm_nomus                        
        moveq   #TUNE_START,d0                  
        bsr.w   PlayMusic                       
pm_nomus:
        addq.b  #$1,g_SubState3(a6)             ; 07808/07870
        bra.w   LogicExit                       ; 0780C/07874

;---------------------------------------------------------------------------
; ProgressMapMarkers - per level, two (x.w, y.w) points on the map: level start and
; checkpoint (used when g_Checkpoint is set). The marker is drawn 8 px right and 8 px
; higher. Levels 4-6 use the same point for both.
;---------------------------------------------------------------------------
ProgressMapMarkers:
	dc.b	$00,$18,$00,$40,$00,$45,$00,$40,$00,$56,$00,$40,$00,$6E,$00,$40
	dc.b	$00,$9F,$00,$40,$00,$B5,$00,$40,$00,$D1,$00,$40,$00,$EC,$00,$40
	dc.b	$01,$19,$00,$40,$01,$19,$00,$40,$01,$35,$00,$50,$01,$35,$00,$50
	dc.b	$01,$35,$00,$63,$01,$35,$00,$63
ProgressMap_Scroll:
        bsr.w   SetMapBitplanePtrs              ; 07848/078B0
        bsr.w   ArthurSpritePos                 ; 0784C/078B4
        move.w  #DMAF_SETCLR|DMAF_RASTER,CUSTOM+DMACON; 07850/     
        addq.w  #$1,g_GameFrame(a6)             ; 07858/078B8  drives the marker flash
        addq.w  #$1,g_ScrollFineX(a6)           ; 0785C/078BC  scroll 1 px a frame up to 144 px
        cmpi.w  #$90,g_ScrollFineX(a6)          ; 07860/078C0
        bne.w   LogicExit                       ; 07866/078C6
        clr.b   g_ArthurFlash(a6)               ; 0786A/078CA
        bsr.w   SetMapBitplanePtrs              ; 0786E/078CE
        bsr.w   ArthurSpritePos                 ; 07872/078D2
        move.b  #$64,g_StateTimer(a6)           ; 07876/078D6  then hold for 100 frames
        addq.b  #$1,g_SubState3(a6)             ; 0787C/078DC
ProgressMap_Wait:
        subq.b  #$1,g_StateTimer(a6)            ; 07880/078E0
        bne.w   LogicExit                       ; 07884/078E4
        clr.w   g_ScrollFineX(a6)               ; 07888/078E8
        clr.b   g_SubState3(a6)                 ; 0788C/078EC
        move.b  #$1,g_SubState2(a6)             ; 07890/078F0
        bra.w   LogicExit                       ; 07896/078F6

;---------------------------------------------------------------------------
; Write bitplane pointers + BPLCON1 fine scroll into the back copper list
;---------------------------------------------------------------------------
SetBitplanePtrs:
        jmp     EnhSetBitplanePtrs              ; the scroller
; (SetBitplanePtrs: the rest of the original routine removed - the scroller does it)


;---------------------------------------------------------------------------
; Same for the progress-map copper list
;---------------------------------------------------------------------------
SetMapBitplanePtrs:
        move.l  g_ArthurAnim(a6),d2             ; 07920/07980  the unpacked map picture (address kept in g_ArthurAnim)
        move.w  g_ScrollFineX(a6),d0            ; 07924/07984  + the scroll in words
        subq.w  #$1,d0                          ; 07928/07988
        asr.w   #$4,d0                          ; 0792A/0798A
        add.w   d0,d0                           ; 0792C/0798C
        ext.l   d0                              ; 0792E/0798E
        add.l   d0,d2                           ; 07930/07990
        lea.l   (COPPER_MAP).l,a1               ; 07932/07992
        moveq   #$32,d0                         ; 07938/07998  5 planes, $32 bytes apart (one map line is $32 x 5 bytes)
        addq.l  #$2,a1                          ; 0793A/0799A
        swap    d2                              ; 0793C/0799C
        move.w  d2,(a1)+                        ; 0793E/0799E
        addq.l  #$2,a1                          ; 07940/079A0
        swap    d2                              ; 07942/079A2
        move.w  d2,(a1)+                        ; 07944/079A4
        add.l   d0,d2                           ; 07946/079A6
        addq.l  #$2,a1                          ; 07948/079A8
        swap    d2                              ; 0794A/079AA
        move.w  d2,(a1)+                        ; 0794C/079AC
        addq.l  #$2,a1                          ; 0794E/079AE
        swap    d2                              ; 07950/079B0
        move.w  d2,(a1)+                        ; 07952/079B2
        add.l   d0,d2                           ; 07954/079B4
        addq.l  #$2,a1                          ; 07956/079B6
        swap    d2                              ; 07958/079B8
        move.w  d2,(a1)+                        ; 0795A/079BA
        addq.l  #$2,a1                          ; 0795C/079BC
        swap    d2                              ; 0795E/079BE
        move.w  d2,(a1)+                        ; 07960/079C0
        add.l   d0,d2                           ; 07962/079C2
        addq.l  #$2,a1                          ; 07964/079C4
        swap    d2                              ; 07966/079C6
        move.w  d2,(a1)+                        ; 07968/079C8
        addq.l  #$2,a1                          ; 0796A/079CA
        swap    d2                              ; 0796C/079CC
        move.w  d2,(a1)+                        ; 0796E/079CE
        add.l   d0,d2                           ; 07970/079D0
        addq.l  #$2,a1                          ; 07972/079D2
        swap    d2                              ; 07974/079D4
        move.w  d2,(a1)+                        ; 07976/079D6
        addq.l  #$2,a1                          ; 07978/079D8
        swap    d2                              ; 0797A/079DA
        move.w  d2,(a1)+                        ; 0797C/079DC
        moveq   #$f,d1                          ; 0797E/079DE
        and.w   g_ScrollFineX(a6),d1            ; 07980/079E0
        beq.b   l_07992                         ; 07984/079E4
        moveq   #$10,d0                         ; 07986/079E6
        sub.w   d1,d0                           ; 07988/079E8
        move.w  d0,d1                           ; 0798A/079EA
        lsl.w   #$4,d1                          ; 0798C/079EC
        or.w    d1,d0                           ; 0798E/079EE
        bra.b   l_07994                         ; 07990/079F0
l_07992:
        clr.w   d0                              ; 07992/079F2
l_07994:
        addq.l  #$2,a1                          ; 07994/079F4
        move.w  d0,(a1)+                        ; 07996/079F6
        rts                                     ; 07998/079F8
TxtTakeKey:
	dc.b	'TAKE A KEY FOR COMING IN !'
	dc.b	$00,$00

;---------------------------------------------------------------------------
; The key that drops when the boss is beaten (after 'TAKE A KEY FOR COMING IN !').
; Runs instead of the enemies and shots, so everything else on screen freezes. Steps
; (g_SubState2, the key is special object 0):
;  0 wait until Arthur reaches the end of the level (levels 0-3: within 48 px of the
;    right edge; 4-6: above the top), then place the key 37 px past the right edge at
;    KeyDropY[level]; the 1MB build plays tune 5
;  1 30 frames spinning in the air
;  2 fall at 1.24 px/frame until it reaches the floor
;  3 when Arthur is within 8 px: sound 28, 1000 points, sub state 4 (LevelComplete)
;---------------------------------------------------------------------------
EndOfLevelKey:
        lea.l   g_SpecialObjs(a6),a5            ; 079B6/07A16
        move.b  g_SubState2(a6),d0              ; 079BA/07A1A
        ext.w   d0                              ; 079BE/07A1E
        add.w   d0,d0                           ; 079C0/07A20
        add.w   d0,d0                           ; 079C2/07A22
        jsr     EndOfLevelKey_Jumps(pc,d0.w)    ; 079C4/07A24
        tst.b   O_OnScreen(a5)                  ; 079C8/07A28
        bne.w   QueueObjectDraw                 ; 079CC/07A2C
        rts                                     ; 079D0/07A30
EndOfLevelKey_Jumps:
        bra.w   Key_Wait                        ; 079D2/07A32
        bra.w   Key_Spin                        ; 079D6/07A36
        bra.w   Key_Fall                        ; 079DA/07A3A
        bra.w   Key_Take                        ; 079DE/07A3E
Key_Wait:
snd93_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd93_512                       
        move    (a7)+,ccr                       
        moveq   #TUNE_BOSS_BEATEN,d0            ;      /07A42
        bsr.w   PlayMusic                       ;      /07A44
        bra.w   snd93_end                       
snd93_512:
        move    (a7)+,ccr                       
        moveq   #$5,d0                          ; 079E2/     
snd93_end:
        move.b  #$1,(a5)                        ; 079E4/07A48  active, not yet on screen
        clr.b   O_OnScreen(a5)                  ; 079E8/07A4C
        clr.b   O_State(a5)                     ; 079EC/07A50
        clr.b   O_Step(a5)                      ; 079F0/07A54
        clr.b   O_Size(a5)                      ; 079F4/07A58
        move.b  #$1e,Key_Timer(a5)              ; 079F8/07A5C  spin for 30 frames
        cmpi.w  #$4,g_Level(a6)                 ; 079FE/07A62  levels 4-6 end at the top
        bcc.b   l_07A40                         ; 07A04/07A68
        moveq   #-48,d0                         ; 07A06/07A6A  within 48 px of the right edge?
        add.w   g_LevelWidth(a6),d0             ; 07A08/07A6C
        cmp.w   g_ArthurX(a6),d0                ; 07A0C/07A70
        bhi.b   l_07A3E                         ; 07A10/07A74
l_07A12:
        moveq   #$25,d0                         ; 07A12/07A76  key: 37 px right of the edge, at KeyDropY
        add.w   g_LevelWidth(a6),d0             ; 07A14/07A78
        move.w  d0,O_X(a5)                      ; 07A18/07A7C
        move.w  g_Level(a6),d0                  ; 07A1C/07A80
        add.w   d0,d0                           ; 07A20/07A84
        move.w  KeyDropY(pc,d0.w),d0            ; 07A22/07A86
        sub.w   g_LevelOriginY(a6),d0           ; 07A26/07A8A
        move.w  d0,O_Y(a5)                      ; 07A2A/07A8E
        lea.l   Key_AnimSpin(pc),a0             ; 07A2E/07A92
        bsr.w   SetAnim                         ; 07A32/07A96
        bsr.w   CheckOnScreen                   ; 07A36/07A9A
snd94_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd94_512                       
        move    (a7)+,ccr                       
        moveq   #$3e,d0                         ;      /07A9E
        bra.w   snd94_end                       
snd94_512:
        move    (a7)+,ccr                       
snd94_end:
        addq.b  #$1,g_SubState2(a6)             ; 07A3A/07AA0
l_07A3E:
        rts                                     ; 07A3E/07AA4
l_07A40:
        moveq   #$20,d0                         ; 07A40/07AA6  above the top?
        add.w   g_LevelHeight(a6),d0            ; 07A42/07AA8
        cmp.w   g_ArthurY(a6),d0                ; 07A46/07AAC
        bhi.b   l_07A3E                         ; 07A4A/07AB0
        bra.b   l_07A12                         ; 07A4C/07AB2

;---------------------------------------------------------------------------
; Per level (0-5): height the key appears at (level coordinates, before g_LevelOriginY)
;---------------------------------------------------------------------------
KeyDropY:
	dc.b	$00,$B0,$00,$B0,$02,$B0,$02,$B0,$06,$90,$0A,$A0
Key_Spin:
        subq.b  #$1,Key_Timer(a5)               ; 07A5A/07AC0
        beq.b   l_07A68                         ; 07A5E/07AC4
        bsr.w   Animate                         ; 07A60/07AC6
        bra.w   CheckOnScreen                   ; 07A64/07ACA
l_07A68:
        lea.l   Key_AnimFall(pc),a0             ; 07A68/07ACE
        bsr.w   SetAnim                         ; 07A6C/07AD2
        bsr.w   CheckOnScreen                   ; 07A70/07AD6
        addq.b  #$1,g_SubState2(a6)             ; 07A74/07ADA
        rts                                     ; 07A78/07ADE
Key_Fall:
        addi.l  #$fffec300,O_Y(a5)              ; 07A7A/07AE0  fall 1.24 px/frame
        bsr.w   Animate                         ; 07A82/07AE8
        bsr.w   ObjectMapCollide                ; 07A86/07AEC  Z set = landed
        bne.b   l_07A90                         ; 07A8A/07AF0
        addq.b  #$1,g_SubState2(a6)             ; 07A8C/07AF2
l_07A90:
        bra.w   CheckOnScreen                   ; 07A90/07AF6
Key_Take:
        move.w  g_ArthurX(a6),d0                ; 07A94/07AFA  Arthur within 8 px?
        sub.w   O_X(a5),d0                      ; 07A98/07AFE
        addq.w  #$8,d0                          ; 07A9C/07B02
        cmp.w   #$10,d0                         ; 07A9E/07B04
        bhi.b   l_07AD8                         ; 07AA2/07B08
        move.w  g_ArthurY(a6),d0                ; 07AA4/07B0A
        sub.w   O_Y(a5),d0                      ; 07AA8/07B0E
        addq.w  #$8,d0                          ; 07AAC/07B12
        cmp.w   #$10,d0                         ; 07AAE/07B14
        bhi.b   l_07AD8                         ; 07AB2/07B18
        clr.b   (a5)                            ; 07AB4/07B1A
        clr.b   O_OnScreen(a5)                  ; 07AB6/07B1C
        btst    #PF_MUSIC,(Profile).l           ; with music the 1MB game plays the boss tune instead (Key_Wait)
        bne.b   kt_nosfx                        
        moveq   #SFX_PICKUP,d0                  ; 07ABA/     
        bsr.w   PlaySfx                         ; 07ABC/     
kt_nosfx:
        moveq   #PTS_1000,d0                    ; 07AC0/07B20
        bsr.w   AddScore                        ; 07AC2/07B22
        move.b  #SS_LEVELCOMPLETE,g_SubState(a6); 07AC6/07B26  -> LevelComplete
        clr.b   g_SubState2(a6)                 ; 07ACC/07B2C
        clr.b   g_SubState3(a6)                 ; 07AD0/07B30
        clr.b   g_KeyState(a6)                  ; 07AD4/07B34
l_07AD8:
        rts                                     ; 07AD8/07B38

;---------------------------------------------------------------------------
; Key spinning: frames 16, 17, 18, 17
;---------------------------------------------------------------------------
Key_AnimSpin:
	AF	$10,3
	AF	$11,3
	AF	$12,3
	AL	$11,3,Key_AnimSpin

;---------------------------------------------------------------------------
; Key falling: frame 19
;---------------------------------------------------------------------------
Key_AnimFall:
	AF	$13,1
	AF	$13,1
	AL	$13,1,Key_AnimFall

;---------------------------------------------------------------------------
; Look up the map zone of the cell under the camera (g_ScrollTileX/Y >> 4, in MapZoneTable). On a change, stop the spawners
; (except those flagged to keep running) and start the zone's list from ZoneSpawners:
; count.b, then per spawner two bytes: hi nibble of byte 1 = enemy type (= spawner slot),
; lo nibble of byte 1 / lo nibble of byte 2 = script number, hi nibble of byte 2 = flags
; (bit 0 world coordinates, bit 1 run once). Types with ZoneFlags = 0 only spawn in a zone
; further on than any reached before (no respawns when walking back).
;---------------------------------------------------------------------------
UpdateMapZone:
        move.w  g_ScrollTileX(a6),d0            ; 07AEC/07B4C  map cell under the camera: column ...
        asr.w   #$4,d0                          ; 07AF0/07B50
        bpl.b   l_07AF6                         ; 07AF2/07B52
        clr.w   d0                              ; 07AF4/07B54
l_07AF6:
        move.w  g_ScrollTileY(a6),d1            ; 07AF6/07B56  ... and row (32 cells a row)
        asr.w   #$4,d1                          ; 07AFA/07B5A
        asl.w   #$5,d1                          ; 07AFC/07B5C
        bpl.b   l_07B02                         ; 07AFE/07B5E
        clr.w   d1                              ; 07B00/07B60
l_07B02:
        add.w   d0,d1                           ; 07B02/07B62  -> offset into WorldMap -> zone from MapZoneTable
        add.l   g_MapPtr(a6),d1                 ; 07B04/07B64
        lea.l   WorldMap(pc),a1                 ; 07B08/07B68
        sub.l   a1,d1                           ; 07B0C/07B6C
        lea.l   MapZoneTable(pc),a1             ; 07B0E/07B6E
        move.b  (a1,d1.w),d0                    ; 07B12/07B72
        cmp.b   g_MapZone(a6),d0                ; 07B16/07B76  same zone as last frame: nothing to do
        beq.w   l_07BC6                         ; 07B1A/07B7A
        move.b  d0,g_MapZone(a6)                ; 07B1E/07B7E
        lea.l   g_Spawners(a6),a5               ; 07B22/07B82  zone changed: stop every spawner not flagged to keep running
        moveq   #$f,d7                          ; 07B26/07B86
l_07B28:
        btst    #$2,Spn_Flags(a5)               ; 07B28/07B88
        bne.b   l_07B32                         ; 07B2E/07B8E
        clr.b   (a5)                            ; 07B30/07B90
l_07B32:
        lea.l   $c(a5),a5                       ; 07B32/07B92
        dbra    d7,l_07B28                      ; 07B36/07B96
        lea.l   ZoneSpawners(pc),a2             ; 07B3A/07B9A  the zone's spawner list (ZoneSpawners: byte offset to count + entries)
        ext.w   d0                              ; 07B3E/07B9E
        adda.w  d0,a2                           ; 07B40/07BA0
        move.b  (a2),d0                         ; 07B42/07BA2
        adda.w  d0,a2                           ; 07B44/07BA4
        move.b  (a2)+,d7                        ; 07B46/07BA6
        ext.w   d7                              ; 07B48/07BA8
        subq.w  #$1,d7                          ; 07B4A/07BAA
        bmi.b   l_07BB8                         ; 07B4C/07BAC
l_07B4E:
        clr.w   d1                              ; 07B4E/07BAE  entry: type (high nibble of byte 1), script number, flags (high nibble of byte 2)
        move.b  (a2)+,d1                        ; 07B50/07BB0
        move.b  (a2)+,d2                        ; 07B52/07BB2
        move.w  d1,d0                           ; 07B54/07BB4
        lsr.w   #$4,d0                          ; 07B56/07BB6
        lsl.b   #$4,d1                          ; 07B58/07BB8
        moveq   #$f,d3                          ; 07B5A/07BBA
        and.b   d2,d3                           ; 07B5C/07BBC
        or.b    d3,d1                           ; 07B5E/07BBE
        lea.l   SpawnScripts(pc),a1             ; 07B60/07BC0  SpawnScripts: per type a byte offset to a word-offset table of scripts
        adda.w  d0,a1                           ; 07B64/07BC4
        move.b  (a1),d3                         ; 07B66/07BC6
        adda.w  d3,a1                           ; 07B68/07BC8
        add.w   d1,d1                           ; 07B6A/07BCA
        adda.w  d1,a1                           ; 07B6C/07BCC
        adda.w  (a1),a1                         ; 07B6E/07BCE
        move.w  (a1),d6                         ; 07B70/07BD0  empty script: skip
        beq.b   l_07BB4                         ; 07B72/07BD2
        move.w  d0,d1                           ; 07B74/07BD4  start the spawner of this type: active, first spawn in 10 frames,
        mulu.w  #$c,d1                          ; 07B76/07BD6
        lea.l   g_Spawners(a6),a0               ; 07B7A/07BDA
        adda.w  d1,a0                           ; 07B7E/07BDE
        st.b    (a0)                            ; 07B80/07BE0
        move.b  #$a,$a(a0)                      ; 07B82/07BE2
        move.l  a1,$6(a0)                       ; 07B88/07BE8  script start and position, entries left, flags
        addq.l  #$2,a1                          ; 07B8C/07BEC
        move.l  a1,$2(a0)                       ; 07B8E/07BEE
        move.b  d6,$1(a0)                       ; 07B92/07BF2
        lsr.b   #$4,d2                          ; 07B96/07BF6
        move.b  d2,$b(a0)                       ; 07B98/07BF8
        lea.l   ZoneFlags(pc,d0.w),a1           ; 07B9C/07BFC  types with ZoneFlags = 0 (bosses, Red Arremer, Big Man) keep running and only
        tst.b   (a1)                            ; 07BA0/07C00
        bne.b   l_07BB4                         ; 07BA2/07C02
        bset    #$2,$b(a0)                      ; 07BA4/07C04  start in a zone beyond any reached before
        move.b  g_MapZone(a6),d0                ; 07BAA/07C0A
        cmp.b   g_MaxMapZone(a6),d0             ; 07BAE/07C0E
        sgt.b   (a0)                            ; 07BB2/07C12
l_07BB4:
        dbra    d7,l_07B4E                      ; 07BB4/07C14
l_07BB8:
        move.b  g_MapZone(a6),d0                ; 07BB8/07C18
        cmp.b   g_MaxMapZone(a6),d0             ; 07BBC/07C1C
        ble.b   l_07BC6                         ; 07BC0/07C20
        move.b  d0,g_MaxMapZone(a6)             ; 07BC2/07C22
l_07BC6:
        rts                                     ; 07BC6/07C26
ZoneFlags:
	dc.b	$01,$01,$01,$01,$01,$00,$00,$01,$00,$01,$00,$01,$00,$00,$01,$01

;---------------------------------------------------------------------------
; 256-byte bit-reversal table used to build Arthur's mirrored sprite frames
;---------------------------------------------------------------------------
BitReverseTable:
	dc.b	$00,$80,$40,$C0,$20,$A0,$60,$E0,$10,$90,$50,$D0,$30,$B0,$70,$F0
	dc.b	$08,$88,$48,$C8,$28,$A8,$68,$E8,$18,$98,$58,$D8,$38,$B8,$78,$F8
	dc.b	$04,$84,$44,$C4,$24,$A4,$64,$E4,$14,$94,$54,$D4,$34,$B4,$74,$F4
	dc.b	$0C,$8C,$4C,$CC,$2C,$AC,$6C,$EC,$1C,$9C,$5C,$DC,$3C,$BC,$7C,$FC
	dc.b	$02,$82,$42,$C2,$22,$A2,$62,$E2,$12,$92,$52,$D2,$32,$B2,$72,$F2
	dc.b	$0A,$8A,$4A,$CA,$2A,$AA,$6A,$EA,$1A,$9A,$5A,$DA,$3A,$BA,$7A,$FA
	dc.b	$06,$86,$46,$C6,$26,$A6,$66,$E6,$16,$96,$56,$D6,$36,$B6,$76,$F6
	dc.b	$0E,$8E,$4E,$CE,$2E,$AE,$6E,$EE,$1E,$9E,$5E,$DE,$3E,$BE,$7E,$FE
	dc.b	$01,$81,$41,$C1,$21,$A1,$61,$E1,$11,$91,$51,$D1,$31,$B1,$71,$F1
	dc.b	$09,$89,$49,$C9,$29,$A9,$69,$E9,$19,$99,$59,$D9,$39,$B9,$79,$F9
	dc.b	$05,$85,$45,$C5,$25,$A5,$65,$E5,$15,$95,$55,$D5,$35,$B5,$75,$F5
	dc.b	$0D,$8D,$4D,$CD,$2D,$AD,$6D,$ED,$1D,$9D,$5D,$DD,$3D,$BD,$7D,$FD
	dc.b	$03,$83,$43,$C3,$23,$A3,$63,$E3,$13,$93,$53,$D3,$33,$B3,$73,$F3
	dc.b	$0B,$8B,$4B,$CB,$2B,$AB,$6B,$EB,$1B,$9B,$5B,$DB,$3B,$BB,$7B,$FB
	dc.b	$07,$87,$47,$C7,$27,$A7,$67,$E7,$17,$97,$57,$D7,$37,$B7,$77,$F7
	dc.b	$0F,$8F,$4F,$CF,$2F,$AF,$6F,$EF,$1F,$9F,$5F,$DF,$3F,$BF,$7F,$FF
;---------------------------------------------------------------------------
; ClearHudArea - clear the HUD's 16 lines of 5 planes (CLEAR_AREA, $B40 bytes)
;---------------------------------------------------------------------------
ClearHudArea:
        lea.l   (CLEAR_AREA).l,a0               ; 07CD8/07D38
        move.w  #$2cf,d7                        ; 07CDE/07D3E
l_07CE2:
        clr.l   (a0)+                           ; 07CE2/07D42
        dbra    d7,l_07CE2                      ; 07CE4/07D44
        rts                                     ; 07CE8/07D48

;---------------------------------------------------------------------------
; Display, audio and interrupt set-up:
;  BPLCON0 $5200 (5 planes), DDF $40-$C0, DIW $34A1-$24A1, modulos $92
;  all audio channels silent, vector $60 = MUSIC_PLAYER
;  CIA-A: serial (keyboard) interrupt only
;  vectors: $64 L1 = Level1Logic, $68 L2 = KeyboardIRQ, $6C L3 = VblIRQ
;  INTENA = SOFTINT|PORTS|VERTB, waits for line $12C before returning
;---------------------------------------------------------------------------
InitHardware:
        lea.l   CUSTOM,a0                       ; 07CEA/07D4A
        move.w  #DMAF_MASTER,DMACON(a0)         ; 07CF0/07D50  bitplane DMA off while setting up
        move.w  #$5200,BPLCON0(a0)              ; 07CF6/07D56  5 bitplanes, lores
        move.w  #$0,BPLCON1(a0)                 ; 07CFC/07D5C
        move.w  #$24,BPLCON2(a0)                ; 07D02/07D62
        move.w  #$92,BPL1MOD(a0)                ; 07D08/07D68  modulo 146: 180-byte interleaved lines, 34 bytes fetched
        move.w  #$92,BPL2MOD(a0)                ; 07D0E/07D6E
        move.w  #$40,DDFSTRT(a0)                ; 07D14/07D74  fetch 17 words (272 px: one more than shown, for the scroll)
        move.w  #$c0,DDFSTOP(a0)                ; 07D1A/07D7A
        move.w  #$34a1,DIWSTRT(a0)              ; 07D20/07D80  display window: 240 lines from line 52, 256 px wide
        move.w  #$24a1,DIWSTOP(a0)              ; 07D26/07D86
        moveq   #$7f,d0                         ; 07D2C/07D8C  audio: silent, period 1
        move.w  d0,AUD0LEN(a0)                  ; 07D2E/07D8E
        move.w  d0,AUD1LEN(a0)                  ; 07D32/07D92
        move.w  d0,AUD2LEN(a0)                  ; 07D36/07D96
        move.w  d0,AUD3LEN(a0)                  ; 07D3A/07D9A
        moveq   #$1,d0                          ; 07D3E/07D9E
        move.w  d0,AUD0PER(a0)                  ; 07D40/07DA0
        move.w  d0,AUD1PER(a0)                  ; 07D44/07DA4
        move.w  d0,AUD2PER(a0)                  ; 07D48/07DA8
        move.w  d0,AUD3PER(a0)                  ; 07D4C/07DAC
        moveq   #$0,d0                          ; 07D50/07DB0
        move.w  d0,AUD0VOL(a0)                  ; 07D52/07DB2
        move.w  d0,AUD1VOL(a0)                  ; 07D56/07DB6
        move.w  d0,AUD2VOL(a0)                  ; 07D5A/07DBA
        move.w  d0,AUD3VOL(a0)                  ; 07D5E/07DBE
        movea.l (MusicPlayerPtr).l,a1           
        move.l  a1,(VEC_SPURIOUS).w             ; vector $60 = the sound driver loaded (LoadSound)
        move.w  #$ff,ADKCON(a0)                 ; 07D6C/07DC2
        move.w  #DMAF_SETCLR|DMAF_AUD3|DMAF_AUD2|DMAF_AUD1|DMAF_AUD0,DMACON(a0); 07D72/07DC8
        lea.l   $bfe001.l,a1                    ; 07D78/07DCE
        move.b  #$7f,$d00(a1)                   ; 07D7E/07DD4  CIA-A: all interrupts off, then the keyboard (SP) on
        move.b  #$88,$d00(a1)                   ; 07D84/07DDA
        andi.b  #$80,$e00(a1)                   ; 07D8A/07DE0  CIA-A CRA: keep only bit 7
        move.w  #$aaaa,g_RandSeed(a6)           ; 07D90/07DE6
        clr.w   g_FrameStamp(a6)                ; 07D96/07DEC
        clr.w   g_VblCount(a6)                  ; 07D9A/07DF0
        clr.w   g_GameFrame(a6)                 ; 07D9E/07DF4
        clr.b   g_ArthurVisible(a6)             ; 07DA2/07DF8
        clr.b   g_Spr47Visible(a6)              ; 07DA6/07DFC
        clr.b   g_RedrawPending(a6)             ; 07DAA/07E00
        st.b    g_SkipLogic(a6)                 ; 07DAE/07E04
        move.l  g_CopperFront(a6),COP2LCH(a0)   ; 07DB2/07E08  copper: COP1 = the init list at COPPER_INIT, COP2 = the front list
        move.l  #COPPER_INIT,COP1LCH(a0)        ; 07DB8/07E0E
        move.w  COPJMP1(a0),d0                  ; 07DC0/07E16
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTENA(a0); 07DC4/07E1A  all interrupts off before installing the vectors
        lea.l   (IrqLevel1).l,a1                ; 07DCA/07E20  level 1 autovector (a6 for the handler)
        move.l  a1,(VEC_LEVEL1).w               ; 07DCE/07E24
        lea.l   KeyboardIRQ(pc),a1              ; 07DD2/07E28  level 2 autovector
        move.l  a1,(VEC_LEVEL2).w               ; 07DD6/07E2C
        lea.l   (IrqLevel3).l,a1                ; 07DDA/07E30  level 3 autovector (a6 for the handler)
        move.l  a1,(VEC_LEVEL3).w               ; 07DDE/07E34
        clr.l   (COPPER_INIT-4).l               ; 07DE2/07E38  clear the long before COPPER_INIT
        move.w  #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_RASTER|DMAF_COPPER|DMAF_BLITTER|DMAF_SPRITE|DMAF_DISK,DMACON(a0); 07DE8/07E3E  DMA on: blitter priority, master, bitplanes, copper, blitter, sprites, disk
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTREQ(a0); 07DEE/07E44
        move.w  #INTF_SETCLR|INTF_INTEN|INTF_VERTB|INTF_PORTS|INTF_SOFTINT,INTENA(a0); 07DF4/07E4A  INTENA = SET|INTEN|VERTB|PORTS|SOFTINT
l_07DFA:
        move.l  VPOSR(a0),d0                    ; 07DFA/07E50  wait for raster line 300
        andi.l  #$1ffff,d0                      ; 07DFE/07E54
        cmp.l   #$12c00,d0                      ; 07E04/07E5A
        bcs.b   l_07DFA                         ; 07E0A/07E60
        rts                                     ; 07E0C/07E62

;---------------------------------------------------------------------------
; CopperTemplate - $180 bytes copied to COPPER_INIT at start-up. First the COP1 list: the
; 16 lines above line $44 from $64468, the eight sprite pointers, then at line $44 the copper
; interrupt and a jump to COP2. Then the four playfield lists that COP2 rotates through
; (g_CopperFront / g_CopperBack / spares; their plane pointers are rewritten for the scroll) and
; the progress-map list. Bitplanes are line-interleaved: 5 planes of 36 bytes per 180-byte line.
;---------------------------------------------------------------------------
; COPPER_INIT (COP1): before line $44 the 16-line strip at $64468, all eight sprites,
; then the copper interrupt and a jump to COP2 (the front list)
CopperTemplate:
	dc.w	BPLCON1,$0000	; no fine scroll
	COPPTR	BPL1,CLEAR_AREA	; $64468
	COPPTR	BPL2,CLEAR_AREA+$24	; $6448C
	COPPTR	BPL3,CLEAR_AREA+$48	; $644B0
	COPPTR	BPL4,CLEAR_AREA+$6C	; $644D4
	COPPTR	BPL5,CLEAR_AREA+$90	; $644F8
	COPPTR	SPR0,SPRITE4B_DATA	; $30EB8
	COPPTR	SPR1,SPRITE5B_DATA	; $30F84
	COPPTR	SPR2,SPRITE6B_DATA	; $31050
	COPPTR	SPR3,SPRITE7B_DATA	; $3111C
	COPPTR	SPR4,SPRITE0_DATA	; $30BB8
	COPPTR	SPR5,SPRITE1_DATA	; $30C78
	COPPTR	SPR6,SPRITE2_DATA	; $30D38
	COPPTR	SPR7,SPRITE3_DATA	; $30DF8
	dc.w	$4401,$FF00	; WAIT line $44
	dc.w	INTREQ,$8010	; set COPER: the copper interrupt (level 3)
	dc.w	COPJMP2,$0000	; jump to COP2LC (the front list)
; COPPER_A1: playfield planes in SCREEN_0 (one of the four lists COP2 points at)
	COPPTR	BPL1,SCREEN_0+$2	; $3746A
	COPPTR	BPL2,SCREEN_0+$26	; $3748E
	COPPTR	BPL3,SCREEN_0+$4A	; $374B2
	COPPTR	BPL4,SCREEN_0+$6E	; $374D6
	COPPTR	BPL5,SCREEN_0+$92	; $374FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_A2: SCREEN_1
	COPPTR	BPL1,SCREEN_1+$2	; $4286A
	COPPTR	BPL2,SCREEN_1+$26	; $4288E
	COPPTR	BPL3,SCREEN_1+$4A	; $428B2
	COPPTR	BPL4,SCREEN_1+$6E	; $428D6
	COPPTR	BPL5,SCREEN_1+$92	; $428FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B1: SCREEN_2
	COPPTR	BPL1,SCREEN_2+$2	; $4DC6A
	COPPTR	BPL2,SCREEN_2+$26	; $4DC8E
	COPPTR	BPL3,SCREEN_2+$4A	; $4DCB2
	COPPTR	BPL4,SCREEN_2+$6E	; $4DCD6
	COPPTR	BPL5,SCREEN_2+$92	; $4DCFA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B2: SCREEN_3
	COPPTR	BPL1,SCREEN_3+$2	; $5906A
	COPPTR	BPL2,SCREEN_3+$26	; $5908E
	COPPTR	BPL3,SCREEN_3+$4A	; $590B2
	COPPTR	BPL4,SCREEN_3+$6E	; $590D6
	COPPTR	BPL5,SCREEN_3+$92	; $590FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_MAP: the between-level progress map (50-byte lines, modulo $D8 then $92)
	COPPTR	BPL1,SCREEN_2+$2	; $4DC6A
	COPPTR	BPL2,SCREEN_2+$34	; $4DC9C
	COPPTR	BPL3,SCREEN_2+$66	; $4DCCE
	COPPTR	BPL4,SCREEN_2+$98	; $4DD00
	COPPTR	BPL5,SCREEN_2+$CA	; $4DD32
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	BPL1MOD,$00D8
	dc.w	BPL2MOD,$00D8
	dc.w	$FFE1,$FFFE	; WAIT line $FF, x $E0 (the PAL wrap: later waits are lines $100+)
	dc.w	$2401,$FF00	; WAIT line $24 ($124 after the wrap)
	dc.w	BPL1MOD,$0092
	dc.w	BPL2MOD,$0092
	dc.w	$FFFF,$FFFE	; end of list

;---------------------------------------------------------------------------
; LevelFileIndex - per level a word offset, from the entry, to its tile file in FileTable
; (LoadLevel).
;---------------------------------------------------------------------------
LevelFileIndex:
	dc.w	FileLevel0-*	; level 0
	dc.w	FileLevel1-*	; level 1
	dc.w	FileLevel2-*	; level 2
	dc.w	FileLevel3-*	; level 3
	dc.w	FileLevel4-*	; level 4
	dc.w	FileLevel5-*	; level 5
	dc.w	FileLevel6-*	; level 6

;---------------------------------------------------------------------------
; FileTable - every file the program loads (FENTRY: load address, length in bytes, first
; track; a1 points at an entry for LoadFile, which reads length / 6,312 tracks, rounded up).
; The bootblock loads the rest: the loading screen and the main program. tools/disk/mkdisk.py
; reads this table (from the assembled binaries of both builds) to lay out the disk.
;---------------------------------------------------------------------------
FileTable:
	FENTRY	SCREEN_0,$05400,FID_ARTHUR             ; Arthur's sprite frames
FileSmallBobs:
	FENTRY	SMALLBOB_LOAD,$00D20,FID_SMALLBOBS     ; small item / scenery BOBs (into the screens, after the enemy sets)
FileEnemyBobs:
	FENTRY	SCREEN_0,$1D042,FID_ENEMYBOBS          ; enemy BOB sets
FileItemGfx2:
	FENTRY	ITEM_GFX2_BUF,$00EA6,FID_ITEMS2        ; weapon / effect BOBs, tail
FileEnemyShotGfx:
	FENTRY	ESHOT_GFX_BUF,$01234,FID_ESHOTS        ; enemy shot BOBs
FileItemGfx:
	FENTRY	ITEM_GFX_BUF,$01AC2,FID_ITEMS          ; weapon / pickup / effect BOBs
FileFont:
	FENTRY	SCREEN_0,$01840,FID_FONT               ; font
FileProgressMap:
	FENTRY	PM_LOAD,$01D5C,FID_PROGMAP             ; progress map (RLE; into the first screen)
FileMusic:
	FENTRY	MUSIC_FILE,$07D64,FID_SFX              ; sound driver and effects (512K)
FileCopyrightScreen:
	FENTRY	SCREEN_2,$025FE,FID_COPYRIGHT          ; copyright warning screen (RLE)
FileLevel0:
	FENTRY	LEVEL_FILE,$07440,FID_LEVEL0           ; level 0 tiles
FileLevel1:
	FENTRY	LEVEL_FILE,$0C120,FID_LEVEL0+1         ; level 1 tiles
FileLevel2:
	FENTRY	LEVEL_FILE,$05460,FID_LEVEL0+2         ; level 2 tiles
FileLevel3:
	FENTRY	LEVEL_FILE,$04880,FID_LEVEL0+3         ; level 3 tiles
FileLevel4:
	FENTRY	LEVEL_FILE,$02760,FID_LEVEL0+4         ; level 4 tiles
FileLevel5:
	FENTRY	LEVEL_FILE,$029E0,FID_LEVEL0+5         ; level 5 tiles
FileLevel6:
	FENTRY	LEVEL_FILE,$019A0,FID_LEVEL0+6         ; level 6 tiles
FileMusic1M:
	FENTRY	MUSIC1M_FILE,$1B394,FID_MUSIC1M        ; the 1MB music package (PF_MUSIC), for upper chip RAM
FileRelocs:
	FENTRY	0,RELOC_LEN,FID_RELOCS                 ; the relocation tables (EnhRelocate; build_game.py)

;---------------------------------------------------------------------------
; ==================================================================
; One program for every machine (enhanced branch)
; ==================================================================
; make_game.py appends this file to gng_game.s: the enhanced game's start-up and loading
; code that has no place in the original's routines (enhanced/docs/FEATURES.md, MEMORY.md):
;   ReadProfile       the machine (Profile) from the bootblock's description
;   LoadSound         the sound package for the machine
;   LoadLevelTables   a level's map tables file
;   LoadFile          a file by its id, with the 4489_byteloader (FileDir: the disk's file table)
;   IrqLevel1 / 3     the interrupt entries that give the handlers their a6
;   EnhRelocate       the program's move to expansion memory (ApplyRelocs)
;   CacheGraphics     with 1MB of chip RAM: every graphic cached with masks (BuildMaskedGfx)
; ==================================================================
; ReadProfile - Start, first thing: Profile from the bootblock's machine description
; (MACHINE_INFO). With 1MB or more of chip RAM (any chip RAM above $80000: Kickstart 1.3 keeps the
; top of a 1MB machine's chip RAM for itself and lists it as ending at $FE800): PF_CACHE, PF_MUSIC - the 1MB program's
; features (PF_EVERY, drawing every frame, is set for every machine). With less chip RAM:
; PF_MUSIC as well (the 1MB package where the program was, if it moved to an expansion; else
; the 512K music package, LoadSound). Without a description (the original bootblock): the
; 512K program, effects only. Also the two texts the 1MB program has its own way: the credit line
; ('MUSIC' for 'SOUND') and the initials stored for a blank name ('501' for '504').
;---------------------------------------------------------------------------
ReadProfile:
        lea.l   (MACHINE_INFO).l,a0
        cmpi.l  #'GNGM',MI_MAGIC(a0)
        bne.b   rp_done
        cmpi.l  #$80000,MI_CHIP_UPPER(a0)       ; more than 512K of chip RAM: 1MB or more (exec
        bls.b   rp_small                        ; may keep the top for itself: 1.3 lists $FE800)
        move.b  #(1<<PF_CACHE)|(1<<PF_MUSIC)|(1<<PF_EVERY),(Profile).l
rp_texts:
        lea.l   (TxtCreditSound).l,a0           ; 'SOUND' -> 'MUSIC'
        lea.l   TxtMusic(pc),a1
        moveq   #4,d0
rp_text:
        move.b  (a1)+,(a0)+
        dbra    d0,rp_text
        move.b  #'1',(NameBlank+2).l            ; '504' -> '501'
rp_done:
        rts
rp_small:
        move.b  #(1<<PF_MUSIC)|(1<<PF_EVERY),(Profile).l   ; music on every machine
        bra.b   rp_texts
TxtMusic:
        dc.b    'MUSIC'
Profile:
        dc.b    1<<PF_EVERY                     ; PF_ bits: every machine draws every frame now (the
                                                ; scroller has no redraw to wait for)
        even
MusicPlayerPtr:
        dc.l    MUSIC_PLAYER                    ; the sound driver's entry (LoadSound)
ItemGfxPtr:
        dc.l    ITEM_GFX_BUF                    ; item / explosion graphics (CacheGraphics: masked)
EShotGfxPtr:
        dc.l    ESHOT_GFX_BUF                   ; enemy shot graphics

;---------------------------------------------------------------------------
; LoadSound - the sound package: with 1MB of chip RAM (PF_CACHE) the 1MB one (music and
; effects, for MUSIC1M_FILE in upper chip RAM); with the program moved to an expansion the 1MB
; one where the program was (MUSICB_FILE); otherwise, with PF_MUSIC, the 512K music package
; (the 512K effects and the tunes) and without it the 512K effects package, at MUSIC_FILE.
;---------------------------------------------------------------------------
LoadSound:
        lea.l   (FileMusic).l,a1
        btst    #PF_MUSIC,(Profile).l
        beq.w   LoadFile
        btst    #PF_CACHE,(Profile).l
        bne.b   ls_music
        tst.b   (RelocDone).l
        bne.b   ls_music
        lea.l   (FileMusic512).l,a1             ; 512K: the music package at MUSIC_FILE
        bra.w   LoadFile
ls_music:
        lea.l   (FileMusic1M).l,a1
        tst.b   (RelocDone).l                   ; the program moved out of chip RAM: the package
        bne.b   ls_low                          ; goes where it was
        bsr.w   LoadFile
        move.l  #MUSIC1M_PLAYER,(MusicPlayerPtr).l
        rts
ls_low:
        move.l  #MUSICB_FILE,(a1)
        bsr.w   LoadFile
        movea.l (MusicRelocs).l,a3              ; its relocations (EnhRelocate loaded them)
        lea.l   (MUSICB_FILE).l,a2
        move.l  #MUSICB_FILE-MUSIC1M_FILE,d5
        bsr.w   ApplyRelocs
        move.l  #MUSICB_FILE+$20,(MusicPlayerPtr).l
        rts

;---------------------------------------------------------------------------
; LoadLevelTables - d0 = level: its map tables (per-level files build_game.py makes from the
; original program's BlockTiles and CellTiles, which are no longer in the program), to
; LEVEL_TABLES: the cells' slots (LEVEL_SLOTS: 256 bytes, cell -> slot; a cell the level
; never reads -> slot 0, cell $67's: empty), their BlockTiles (LEVEL_BLOCKS, 64 bytes a slot)
; and their CellTiles (LEVEL_CELLS, 256 bytes a slot). All registers kept.
;---------------------------------------------------------------------------
LoadLevelTables:
        movem.l d0-d7/a0-a6,-(a7)
        lea.l   (FileTables).l,a1
        mulu.w  #10,d0
        adda.w  d0,a1
        jsr     (LoadFile).l
        movem.l (a7)+,d0-d7/a0-a6
        rts
FileMusic512:
	FENTRY	MUSIC_FILE,MUSIC512_LEN,FID_MUSIC512    ; the music for 512K (sound/gng_music_512k.s)
MfmBuf:
        dc.l    MFM_BUFFER                      ; LoadFile's MFM buffer (the progress map sets PM_MFM)

;---------------------------------------------------------------------------
; LoadFile - a1 -> file record (FENTRY: dest.l, length.l, file id.w) -> a5 = the end of the
; loaded data, a0 = CUSTOM (as the original's track loader left them); other registers kept.
; The disk is an ordinary AmigaDOS-format disk (11 sectors a track) with a file table at
; FT_OFFSET (boot_4489.s; build_game.py writes it): read once into FileDir, then each file is
; loaded from its offset by the 4489_byteloader (ByteLoader), the exact number of bytes. A
; failed load is tried again until it works (after 8 failures COLOR00 shows red).
; The byteloader uses a6, so the interrupt handlers load a6 themselves (IrqLevel1/3).
;---------------------------------------------------------------------------
LoadFile:
        movem.l d0-d7/a1-a4/a6,-(a7)
        movea.l (a1),a5                         ; destination
        move.l  4(a1),d5                        ; length
        moveq   #0,d4
        move.w  8(a1),d4                        ; file id
        lea.l   (FileDir).l,a2
        cmpi.l  #'GNGF',(a2)                    ; the file table, the first time
        beq.b   lf_dir
        movem.l d4-d5/a5,-(a7)
        moveq   #0,d0
        move.w  #FT_OFFSET,d0
        move.l  #FT_SIZE,d1
        movea.l a2,a0
        bsr.b   lf_load
        movem.l (a7)+,d4-d5/a5
lf_dir:
        lea.l   (FileDir).l,a2                  ; (the byteloader keeps no registers)
        lsl.w   #$3,d4
        move.l  FT_ENTRY(a2,d4.w),d0            ; the file's offset on the disk
        move.l  d5,d1
        movea.l a5,a0
        movem.l d5/a5,-(a7)
        bsr.b   lf_load
        movem.l (a7)+,d5/a5
        adda.l  d5,a5
        lea.l   CUSTOM,a0
        movem.l (a7)+,d0-d7/a1-a4/a6
        rts
lf_load:                                        ; d0 = offset, d1 = length, a0 = destination
        moveq   #0,d6
lf_try:
        movem.l d0-d1/d6/a0/a5,-(a7)
        moveq   #0,d2                           ; DF0
        movea.l (MfmBuf).l,a1
        bsr.w   ByteLoader
        move.l  d0,d7
        movem.l (a7)+,d0-d1/d6/a0/a5
        tst.l   d7
        beq.b   lf_ok
        addq.w  #$1,d6
        cmp.w   #$8,d6
        bcs.b   lf_try
        move.w  #$f00,CUSTOM+COLOR00            ; a disk error: red, and on trying
        bra.b   lf_try
lf_ok:
        rts
FileDir:
        dcb.b   FT_SIZE,0                       ; the disk's file table (LoadFile)
ByteLoader:
	include	"byteloader.i"
        even

;---------------------------------------------------------------------------
; IrqLevel1 / IrqLevel3 - the level 1 and level 3 autovectors: a6 = GLOBALS for the handlers
; (Level1Logic, VblIRQ), which take it as given; the interrupted a6 back on the way out
; (IrqExit1 / IrqExit3, where the handlers return). The byteloader uses a6 while a file
; loads with the interrupts running.
;---------------------------------------------------------------------------
IrqLevel1:
        move.l  a6,(IrqA6L1).l
        lea.l   (GLOBALS).l,a6
        jmp     Level1Logic
IrqExit1:
        movea.l (IrqA6L1).l,a6
        rte
IrqLevel3:
        move.l  a6,(IrqA6L3).l
        lea.l   (GLOBALS).l,a6
        jmp     VblIRQ
IrqExit3:
        movea.l (IrqA6L3).l,a6
        rte
IrqA6L1:
        dc.l    0                               ; the a6 the level 1 handler interrupted
IrqA6L3:
        dc.l    0                               ; ... and the level 3 handler
FileTables:                                     ; the levels' map table files (LoadLevelTables)
	FENTRY	LEVEL_TABLES,TBLLEN0,FID_TABLES0+0
	FENTRY	LEVEL_TABLES,TBLLEN1,FID_TABLES0+1
	FENTRY	LEVEL_TABLES,TBLLEN2,FID_TABLES0+2
	FENTRY	LEVEL_TABLES,TBLLEN3,FID_TABLES0+3
	FENTRY	LEVEL_TABLES,TBLLEN4,FID_TABLES0+4
	FENTRY	LEVEL_TABLES,TBLLEN5,FID_TABLES0+5
	FENTRY	LEVEL_TABLES,TBLLEN6,FID_TABLES0+6

;---------------------------------------------------------------------------
; EnhRelocate - Start, first thing, still at $80: with less than 1MB of chip RAM and an
; expansion (fast RAM, else slow RAM: MACHINE_INFO) with room, the program moves there -
; everything from $80 to the memory map (MAP_LOW: the code, the tables, the globals; the
; memory map stays where it is, in chip RAM). It is copied, the relocation file (tables of
; the program's and the 1MB music package's absolute addresses, made by build_game.py by
; assembling each at two origins) is loaded after it, the program's addresses are moved,
; and Start runs again there (RelocDone: once). The chip RAM from $80 is then free for the
; 1MB music package (ReadProfile: PF_MUSIC; LoadSound). The CPU alone reads the program: the
; blitter, copper, sprites and Paula read only the memory map.
;---------------------------------------------------------------------------
IMAGE_BASE      equ     $80                     ; where the bootblock loads the program
IMAGE_SIZE      equ     (MAP_LOW-IMAGE_BASE+3)&-4
RELOC_ROOM      equ     IMAGE_SIZE+RELOC_LEN    ; (LoadFile loads exactly the file's bytes)
EnhRelocate:
        tst.b   (RelocDone).l
        bne.w   er_out
        tst.l   (FileRelocs+4).l                ; (a build without the relocation file)
        beq.w   er_out
        lea.l   (MACHINE_INFO).l,a0
        cmpi.l  #'GNGM',MI_MAGIC(a0)
        bne.w   er_out
        cmpi.l  #$80000,MI_CHIP_UPPER(a0)       ; 1MB of chip RAM (more than 512K): the program
        bhi.w   er_out                          ; stays
        movem.l 24(a0),d0-d1                    ; fast RAM: lower, upper
        bsr.w   er_fit
        beq.b   er_go
        lea.l   (MACHINE_INFO).l,a0
        movem.l 16(a0),d0-d1                    ; slow RAM
        bsr.w   er_fit
        bne.w   er_out
er_go:  move.l  d0,d6                           ; d6 = where it goes
        lea.l   (IMAGE_BASE).w,a1
        movea.l d0,a2
        move.w  #IMAGE_SIZE/4-1,d7
er_copy:
        move.l  (a1)+,(a2)+
        dbra    d7,er_copy
        move.l  a2,-(a7)                        ; the relocation file after it
        lea.l   (FileRelocs).l,a1
        move.l  a2,(a1)
        move.l  d6,-(a7)
        jsr     (LoadFile).l
        move.l  (a7)+,d6
        movea.l (a7)+,a3
        movea.l d6,a2                           ; the program's addresses: + (d6 - $80)
        move.l  d6,d5
        sub.l   #IMAGE_BASE,d5
        bsr.w   ApplyRelocs                     ; (a3 = the music package's table after it)
        move.l  d6,d0                           ; in the copy: the music table, done, and on
        add.l   #MusicRelocs-IMAGE_BASE,d0
        movea.l d0,a0
        move.l  a3,(a0)
        move.l  d6,d0
        add.l   #RelocDone-IMAGE_BASE,d0
        movea.l d0,a0
        st.b    (a0)
        addq.l  #4,a7                           ; (Start called this)
        add.l   #Start-IMAGE_BASE,d6
        movea.l d6,a0
        jmp     (a0)
er_out:
        rts
; d0 = lower, d1 = upper end of a region -> d0 = where the program would go (on 256 bytes);
; Z set if it fits
er_fit:
        tst.l   d1
        beq.b   er_no
        add.l   #$FF,d0
        and.l   #$FFFFFF00,d0
        move.l  d1,d2
        sub.l   d0,d2
        bls.b   er_no
        cmp.l   #RELOC_ROOM,d2
        bcs.b   er_no
        moveq   #0,d2
        rts
er_no:  moveq   #1,d2
        rts

; ApplyRelocs - a3 = a table (count.l, then word gaps between the offsets of the longs to
; move), a2 = the image's base, d5 = how far it moved -> a3 = after the table
ApplyRelocs:
        move.l  (a3)+,d7
        beq.b   ar_done
ar_next:
        moveq   #0,d0
        move.w  (a3)+,d0
        adda.l  d0,a2
        add.l   d5,(a2)
        subq.l  #1,d7
        bne.b   ar_next
ar_done:
        rts

RelocDone:
        dc.b    0                               ; this is the copy (EnhRelocate)
        even
MusicRelocs:
        dc.l    0                               ; the music package's relocation table

;---------------------------------------------------------------------------
; CacheGraphics - with PF_CACHE, as the 1MB program's Start: every BOB graphics file is
; loaded once and converted by BuildMaskedGfx into a buffer in upper chip RAM with a mask
; line after every plane line (the item, shot and font files are already loaded to their
; 512K places); the packed progress map is kept; the frame offsets are doubled to match.
;---------------------------------------------------------------------------
CacheGraphics:
        btst    #PF_CACHE,(Profile).l
        beq.w   cg_done
        lea.l   (FileSmallBobs).l,a1
        bsr.w   LoadFile
        lea.l   (FileSmallBobs).l,a1
        movea.l (a1),a1
        lea.l   (SMALLBOB_CACHE).l,a2
        lea.l   (CacheSizesSmallBobs).l,a3
        moveq   #$9,d7
        bsr.w   BuildMaskedGfx
        lea.l   (FileEnemyBobs).l,a1
        bsr.w   LoadFile
        lea.l   (FileEnemyBobs).l,a1
        movea.l (a1),a1
        lea.l   (ENEMY_GFX_CACHE).l,a2
        lea.l   (CacheSizesEnemyGfx).l,a3
        moveq   #$26,d7
        bsr.w   BuildMaskedGfx
        lea.l   (FileItemGfx2).l,a1
        movea.l (a1),a1
        lea.l   (MITEM_GFX2_BUF).l,a2
        lea.l   (CacheSizesItemGfx2).l,a3
        moveq   #$2,d7
        bsr.w   BuildMaskedGfx
        lea.l   (FileEnemyShotGfx).l,a1
        movea.l (a1),a1
        lea.l   (MESHOT_GFX_BUF).l,a2
        lea.l   (CacheSizesEnemyShots).l,a3
        moveq   #$2,d7
        bsr.w   BuildMaskedGfx
        lea.l   (FileItemGfx).l,a1
        movea.l (a1),a1
        lea.l   (MITEM_GFX_BUF).l,a2
        lea.l   (CacheSizesItems).l,a3
        moveq   #$3,d7
        bsr.w   BuildMaskedGfx
        move.l  #MITEM_GFX_BUF,(ItemGfxPtr).l
        move.l  #MESHOT_GFX_BUF,(EShotGfxPtr).l
        lea.l   (FileProgressMap).l,a1          ; keep the packed progress map
        bsr.w   LoadFile
        lea.l   (FileProgressMap).l,a2
        movea.l (a2)+,a1
        move.l  (a2)+,d7
        lsr.l   #$2,d7
        subq.l  #$1,d7
        lea.l   (PROGRESS_MAP_CACHE).l,a2
cg_map:
        move.l  (a1)+,(a2)+
        dbra    d7,cg_map
        lea.l   (FrameOffsets1).l,a0            ; the BOB frame tables (FRAME): offsets x 2
        move.w  #(FrameOffsets1End-FrameOffsets1)/4-1,d0
        bsr.b   cg_frames
        lea.l   (FrameOffsets2).l,a0
        move.w  #(FrameOffsets2End-FrameOffsets2)/4-1,d0
        bsr.b   cg_frames
        lea.l   (BobSetOffsets).l,a0            ; set offsets (longs) x 2
        moveq   #21-1,d0
        bsr.b   cg_longs
        lea.l   (SmallBobSetOffsets).l,a0
        moveq   #10-1,d0
        bsr.b   cg_longs
cg_done:
        rts
cg_frames:
        move.w  (a0),d1
        add.w   d1,d1
        move.w  d1,(a0)
        addq.l  #4,a0
        dbra    d0,cg_frames
        rts
cg_longs:
        move.l  (a0),d1
        add.l   d1,d1
        move.l  d1,(a0)+
        dbra    d0,cg_longs
        rts

	include	"scroller.s"


;---------------------------------------------------------------------------
; Switch to the screen RedrawScreen has just drawn at g_NewTileX/Y: the pending
; offsets become the current ones (fine scroll clamped to -16..15), then the buffers
; are rotated (falls into SwapScreens)
;---------------------------------------------------------------------------
CameraJump:
        jmp     EnhCameraJump                   ; the scroller: the same fine-scroll rules, no buffers to rotate
; (CameraJump: the rest of the original routine removed - the scroller does it)


;---------------------------------------------------------------------------
; SwapScreens - adopt the new tile origin (g_NewTileX/Y) and rotate the four screen
; buffers and copper lists: the two just redrawn become the working pair, the old pair
; the spares for the next redraw. Both restore lists are emptied.
;---------------------------------------------------------------------------
SwapScreens:
        jmp     EnhSwapScreens                  ; the scroller
; (SwapScreens: the rest of the original routine removed - the scroller does it)


;---------------------------------------------------------------------------
; ShowBackBuffer - wait for the copper interrupt (INTREQ bit 4, raised by the copper
; list), point COP2LC at the copper list just built, then swap front and back screens,
; save areas, restore lists and save pointers for the next frame
;---------------------------------------------------------------------------
ShowBackBuffer:
        jmp     EnhShowBackBuffer               ; the scroller
; (ShowBackBuffer: the rest of the original routine removed - the scroller does it)


;---------------------------------------------------------------------------
; Compute SPRxPOS/CTL for Arthur's two attached sprite pairs (hidden while flashing)
;---------------------------------------------------------------------------
ArthurSpritePos:
        moveq   #$0,d0                          ; 0813C/08192
        moveq   #$20,d1                         ; 0813E/08194
        move.w  g_ScrollTileY(a6),d0            ; 08140/08196
        lsl.w   #$4,d0                          ; 08144/0819A
        add.w   g_ScrollFineY(a6),d0            ; 08146/0819C
        sub.w   g_ArthurY(a6),d0                ; 0814A/081A0
        moveq   #-16,d2                         ; 0814E/081A4
        cmp.w   d2,d0                           ; 08150/081A6
        ble.b   l_08156                         ; 08152/081A8
        move.l  d2,d0                           ; 08154/081AA
l_08156:
        addi.w  #$124,d0                        ; 08156/081AC
        add.w   d0,d1                           ; 0815A/081B0
        moveq   #$0,d2                          ; 0815C/081B2
        sub.w   g_ScrollTileX(a6),d2            ; 0815E/081B4
        asl.w   #$4,d2                          ; 08162/081B8
        sub.w   g_ScrollFineX(a6),d2            ; 08164/081BA
        addi.w  #$90,d2                         ; 08168/081BE
        add.w   g_ArthurX(a6),d2                ; 0816C/081C2
        tst.b   g_ArthurFlash(a6)               ; 08170/081C6
        beq.b   l_08182                         ; 08174/081CA
        btst    #$2,g_VblCount+1(a6)            ; 08176/081CC
        beq.b   l_08182                         ; 0817C/081D2
        move.w  #$1a1,d2                        ; 0817E/081D4
l_08182:
        swap    d0                              ; 08182/081D8
        rol.l   #$8,d0                          ; 08184/081DA
        lsl.w   #$2,d0                          ; 08186/081DC
        lsr.w   #$1,d2                          ; 08188/081DE
        swap    d2                              ; 0818A/081E0
        roxl.w  #$1,d2                          ; 0818C/081E2
        rol.w   #$8,d1                          ; 0818E/081E4
        lsl.b   #$1,d1                          ; 08190/081E6
        or.l    d1,d0                           ; 08192/081E8
        or.l    d2,d0                           ; 08194/081EA
        move.l  d0,d1                           ; 08196/081EC
        bset    #$7,d1                          ; 08198/081EE
        move.l  #$80000,d2                      ; 0819C/081F2
        move.l  d0,g_ArthurSprCtl(a6)           ; 081A2/081F8
        move.l  d1,g_ArthurSprCtl+4(a6)         ; 081A6/081FC
        add.l   d2,d0                           ; 081AA/08200
        add.l   d2,d1                           ; 081AC/08202
        move.l  d0,g_ArthurSprCtl+8(a6)         ; 081AE/08204
        move.l  d1,g_ArthurSprCtl+12(a6)        ; 081B2/08208
        rts                                     ; 081B6/0820C

;---------------------------------------------------------------------------
; Exchange the two 16-byte per-player blocks and toggle g_CurPlayer
;---------------------------------------------------------------------------
SwapPlayers:
        lea.l   g_OtherPlayer(a6),a1            ; 081B8/0820E
        moveq   #$7,d7                          ; 081BC/08212
        lea.l   g_Level(a6),a0                  ; 081BE/08214
l_081C2:
        move.w  (a1),d0                         ; 081C2/08218
        move.w  (a0),(a1)+                      ; 081C4/0821A
        move.w  d0,(a0)+                        ; 081C6/0821C
        dbra    d7,l_081C2                      ; 081C8/0821E
        not.b   g_CurPlayer(a6)                 ; 081CC/08222
        rts                                     ; 081D0/08226

;---------------------------------------------------------------------------
; Probe the map under Arthur's feet; snaps Y to the floor. Out: N set = in the air
;---------------------------------------------------------------------------
ArthurFloorCheck:
        moveq   #-8,d6                          ; 081D2/08228  probe 8 px left of centre, 16 px below
        add.w   g_ArthurX(a6),d6                ; 081D4/0822A
        moveq   #-16,d7                         ; 081D8/0822E
        add.w   g_ArthurY(a6),d7                ; 081DA/08230
        bsr.w   MapTileAt                       ; 081DE/08234
        move.b  $4(a1),d0                       ; 081E2/08238
        andi.b  #$c0,d0                         ; 081E6/0823C
        bne.b   l_08202                         ; 081EA/08240
        move.b  (a1),d0                         ; 081EC/08242
        ext.w   d0                              ; 081EE/08244
        lea.l   (FloorProfile).l,a1           ; 081F0/08246
        adda.w  d0,a1                           ; 081F4/0824A
        move.b  (a1),d1                         ; 081F6/0824C
        beq.b   l_08202                         ; 081F8/0824E
        moveq   #$f,d0                          ; 081FA/08250
        and.b   d7,d0                           ; 081FC/08252
        sub.b   d0,d1                           ; 081FE/08254
        bcc.b   l_08236                         ; 08200/08256
l_08202:
        moveq   #$8,d6                          ; 08202/08258  then 8 px right
        add.w   g_ArthurX(a6),d6                ; 08204/0825A
        moveq   #-16,d7                         ; 08208/0825E
        add.w   g_ArthurY(a6),d7                ; 0820A/08260
        bsr.w   MapTileAt                       ; 0820E/08264
        move.b  $4(a1),d0                       ; 08212/08268
        andi.b  #$c0,d0                         ; 08216/0826C
        bne.b   l_08232                         ; 0821A/08270
        move.b  (a1),d0                         ; 0821C/08272
        ext.w   d0                              ; 0821E/08274
        lea.l   (FloorProfile).l,a1           ; 08220/08276
        adda.w  d0,a1                           ; 08224/0827A
        move.b  (a1),d1                         ; 08226/0827C
        beq.b   l_08232                         ; 08228/0827E
        moveq   #$f,d0                          ; 0822A/08280
        and.w   d7,d0                           ; 0822C/08282
        sub.b   d0,d1                           ; 0822E/08284
        bcc.b   l_08236                         ; 08230/08286
l_08232:
        moveq   #-1,d0                          ; 08232/08288
        rts                                     ; 08234/0828A
l_08236:
        ext.w   d1                              ; 08236/0828C
        add.w   d1,g_ArthurY(a6)                ; 08238/0828E
        moveq   #$0,d0                          ; 0823C/08292
        rts                                     ; 0823E/08294

;---------------------------------------------------------------------------
; Per item type 1-5 (shootable scenery, then the platforms): width Arthur can stand on
;---------------------------------------------------------------------------
PlatformSizes:
	dc.b	$18,$1E,$3E,$20,$34

;---------------------------------------------------------------------------
; Per item type 1-5: height (Arthur stands on the top). Item type 1 - gravestones and
; other shootable scenery - is solid too; only types 2-5 carry him (Itm_Rider).
;---------------------------------------------------------------------------
PlatformHeights:
	dc.b	$26,$30,$30,$2E,$2A

;---------------------------------------------------------------------------
; d3,d4 = probe point. Out: Z clear if standing on a moving platform/item
;---------------------------------------------------------------------------
ArthurOnPlatform:
        lea.l   g_Items(a6),a5                  ; 0824A/082A0
        moveq   #$1d,d7                         ; 0824E/082A4
l_08250:
        tst.b   O_OnScreen(a5)                  ; 08250/082A6  each on-screen item of type 1-5
        beq.w   l_082E2                         ; 08254/082AA
        clr.w   d0                              ; 08258/082AE
        move.b  O_Type(a5),d0                   ; 0825A/082B0
        beq.w   l_082E2                         ; 0825E/082B4
        subq.w  #$1,d0                          ; 08262/082B8  width and height of this item type
        lea.l   PlatformSizes(pc,d0.w),a1       ; 08264/082BA
        lea.l   PlatformHeights(pc,d0.w),a2     ; 08268/082BE
        clr.w   d1                              ; 0826C/082C2
        move.b  (a1),d1                         ; 0826E/082C4
        move.w  d1,d2                           ; 08270/082C6  probe X within the width?
        lsr.w   #$1,d2                          ; 08272/082C8
        add.w   d3,d2                           ; 08274/082CA
        sub.w   O_X(a5),d2                      ; 08276/082CC
        cmp.w   d1,d2                           ; 0827A/082D0
        bhi.b   l_082E2                         ; 0827C/082D2
        clr.w   d1                              ; 0827E/082D4
        move.b  (a2),d1                         ; 08280/082D6
        move.w  d1,d2                           ; 08282/082D8  probe Y within the height?
        lsr.w   #$1,d2                          ; 08284/082DA
        add.w   d4,d2                           ; 08286/082DC
        sub.w   O_Y(a5),d2                      ; 08288/082DE
        cmp.w   d1,d2                           ; 0828C/082E2
        bhi.b   l_082E2                         ; 0828E/082E4
        tst.b   g_Falling(a6)                   ; 08290/082E6  falling: only when he is above its middle
        beq.b   l_082A0                         ; 08294/082EA
        move.w  g_ArthurY(a6),d1                ; 08296/082EC
        sub.w   O_Y(a5),d1                      ; 0829A/082F0
        bmi.b   l_082E2                         ; 0829E/082F4
l_082A0:
        move.w  g_ArthurY(a6),d2                ; 082A0/082F6  within 3 px of the top: snap onto it
        sub.w   O_Y(a5),d2                      ; 082A4/082FA
        addq.w  #$3,d2                          ; 082A8/082FE
        cmp.w   #$6,d2                          ; 082AA/08300
        bcs.b   l_082BE                         ; 082AE/08304
        clr.w   d1                              ; 082B0/08306
        move.b  (a2),d1                         ; 082B2/08308
        lsr.w   #$1,d1                          ; 082B4/0830A
        add.w   O_Y(a5),d1                      ; 082B6/0830C
        move.w  d1,g_ArthurY(a6)                ; 082BA/08310
l_082BE:
        cmpi.b  #$2,O_Type(a5)                  ; 082BE/08314  type 2-5 (moving): it carries him - mark it as his platform
        bcs.b   l_082DE                         ; 082C4/0831A
        move.l  g_ArthurPlatform(a6),d0         ; 082C6/0831C
        beq.b   l_082D2                         ; 082CA/08320
        movea.l d0,a0                           ; 082CC/08322
        clr.b   $18(a0)                         ; 082CE/08324
l_082D2:
        move.l  a5,g_ArthurPlatform(a6)         ; 082D2/08328
        st.b    Itm_Rider(a5)                   ; 082D6/0832C
        st.b    g_OnPlatform(a6)                ; 082DA/08330
l_082DE:
        moveq   #-1,d0                          ; 082DE/08334
        rts                                     ; 082E0/08336
l_082E2:
        lea.l   $1c(a5),a5                      ; 082E2/08338
        dbra    d7,l_08250                      ; 082E6/0833C
        moveq   #$0,d0                          ; 082EA/08340
        rts                                     ; 082EC/08342

;---------------------------------------------------------------------------
; a1 = animation table (two variants selected by facing)
;---------------------------------------------------------------------------
ArthurSetAnim:
        tst.b   g_ArthurFacing(a6)              ; 082EE/08344
        bpl.b   l_082F6                         ; 082F2/08348
        addq.l  #$2,a1                          ; 082F4/0834A
l_082F6:
        adda.w  (a1),a1                         ; 082F6/0834C

;---------------------------------------------------------------------------
; Start Arthur's animation script a1 as it is (no facing table) and show its first frame
;---------------------------------------------------------------------------
ArthurSetScript:
        move.l  a1,g_ArthurAnim(a6)             ; 082F8/0834E
        clr.b   g_ArthurAnimTimer(a6)           ; 082FC/08352
        bra.b   l_08308                         ; 08300/08356

;---------------------------------------------------------------------------
; Step Arthur's animation script; armour-less frames are +$10
;---------------------------------------------------------------------------
ArthurAnimate:
        subq.b  #$1,g_ArthurAnimTimer(a6)       ; 08302/08358
        bne.b   l_08346                         ; 08306/0835C
l_08308:
        movea.l g_ArthurAnim(a6),a1             ; 08308/0835E
        move.b  (a1)+,g_ArthurFrame(a6)         ; 0830C/08362
        move.b  (a1)+,d0                        ; 08310/08366
        bpl.b   l_08318                         ; 08312/08368
        neg.b   d0                              ; 08314/0836A
        adda.w  (a1),a1                         ; 08316/0836C
l_08318:
        move.b  d0,g_ArthurAnimTimer(a6)        ; 08318/0836E
        move.l  a1,g_ArthurAnim(a6)             ; 0831C/08372
        tst.b   g_ArthurState(a6)               ; 08320/08376
        bne.b   l_08346                         ; 08324/0837A
        tst.b   g_FrogTimer(a6)                 ; 08326/0837C
        bne.b   l_08346                         ; 0832A/08380
        tst.b   g_NoArmour(a6)                  ; 0832C/08382
        beq.b   l_08346                         ; 08330/08386
        tst.b   g_ArthurFrame(a6)               ; 08332/08388
        bmi.b   l_08340                         ; 08336/0838C
        addi.b  #$10,g_ArthurFrame(a6)          ; 08338/0838E
        rts                                     ; 0833E/08394
l_08340:
        subi.b  #$10,g_ArthurFrame(a6)          ; 08340/08396
l_08346:
        rts                                     ; 08346/0839C
ArmourDebris:
	dc.b	$01,$08,$08,$02,$08,$F8,$03,$F8,$F8,$04,$F8,$08

;---------------------------------------------------------------------------
; State 1. With armour: it flies off as 4 pieces (shot type 5, sound 1) and he is knocked
; back. Without: he dies (the 1MB build plays tune 8, or 7 on the last life).
;---------------------------------------------------------------------------
ArthurHit:
        clr.b   g_FrogTimer(a6)                 ; 08354/083AA  no longer a frog
        tst.b   g_NoArmour(a6)                  ; 08358/083AE
        bne.b   l_083AE                         ; 0835C/083B2
        lea.l   ArmourDebris(pc),a1             ; 0835E/083B4
        lea.l   g_Shots(a6),a5                  ; 08362/083B8
        moveq   #$3,d7                          ; 08366/083BC
l_08368:
        clr.b   O_State(a5)                     ; 08368/083BE
        clr.b   O_Step(a5)                      ; 0836C/083C2
        clr.b   O_Step2(a5)                     ; 08370/083C6
        move.b  #$2,(a5)                        ; 08374/083CA
        clr.b   O_OnScreen(a5)                  ; 08378/083CE
        move.b  (a1)+,O_Dir(a5)                 ; 0837C/083D2
        move.b  (a1)+,d0                        ; 08380/083D6
        ext.w   d0                              ; 08382/083D8
        add.w   g_ArthurX(a6),d0                ; 08384/083DA
        move.w  d0,O_X(a5)                      ; 08388/083DE
        move.b  (a1)+,d0                        ; 0838C/083E2
        ext.w   d0                              ; 0838E/083E4
        add.w   g_ArthurY(a6),d0                ; 08390/083E6
        move.w  d0,O_Y(a5)                      ; 08394/083EA
        move.b  #$5,O_Type(a5)                  ; 08398/083EE  shot type 5: a piece of armour
        lea.l   $26(a5),a5                      ; 0839E/083F4
        dbra    d7,l_08368                      ; 083A2/083F8
        moveq   #SFX_ARTHUR_HIT,d0              ; 083A6/083FC
        bsr.w   PlaySfx                         ; 083A8/083FE
        bra.b   l_083BA                         ; 083AC/08402
l_083AE:
        moveq   #$8,d0                          ; 083AE/08404  no armour: dying. d0 = tune for the 1MB build: 8, or 7 (game over) on the last life
        cmpi.b  #$1,g_Lives(a6)                 ; 083B0/08406
snd106_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd106_512                      
        move    (a7)+,ccr                       
        bne.b   l1m_08410                       ;      /0840C
        bra.w   snd106_end                      
snd106_512:
        move    (a7)+,ccr                       
        bne.b   l_083BA                         ; 083B6/     
snd106_end:
        moveq   #TUNE_GAME_OVER,d0              ; 083B8/0840E
snd107_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd107_512                      
        move    (a7)+,ccr                       
l1m_08410:
        bsr.w   PlayMusic                       ;      /08410
        bra.w   snd107_end                      
snd107_512:
        move    (a7)+,ccr                       
snd107_end:
l_083BA:
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 083BA/08414  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]
        rts                                     ; 083BE/08418

;---------------------------------------------------------------------------
; State 2: thrown up and away from the enemy (the same launch as a jump: 4.25 up,
; 0.5 across), facing it
;---------------------------------------------------------------------------
ArthurKnockback:
        move.b  g_ArthurDir(a6),g_ArthurFacing(a6); 083C0/0841A  face the enemy (the opposite of the way he is pushed)
        neg.b   g_ArthurFacing(a6)              ; 083C6/08420
        st.b    g_Jumping(a6)                   ; 083CA/08424
        move.w  g_ArthurY(a6),g_ArthurAux(a6)   ; 083CE/08428
        clr.b   g_Falling(a6)                   ; 083D4/0842E
        clr.b   g_FireCooldown(a6)              ; 083D8/08432
        clr.b   g_LadderDir(a6)                 ; 083DC/08436
        move.l  #$8000,g_ArthurVelX(a6)         ; 083E0/0843A  0.5 px/frame away
        move.l  #$44000,g_ArthurVelY(a6)        ; 083E8/08442  4.25 px/frame up
        lea.l   ArthurAnimKnockback(pc),a1      ; 083F0/0844A
        tst.b   g_NoArmour(a6)                  ; 083F4/0844E
        beq.b   l_083FE                         ; 083F8/08452
        lea.l   ArthurAnimKnockbackBare(pc),a1  ; 083FA/08454
l_083FE:
        bsr.w   ArthurSetAnim                   ; 083FE/08458
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08402/0845C
        rts                                     ; 08406/08460

;---------------------------------------------------------------------------
; State 3: fly until he lands
;---------------------------------------------------------------------------
ArthurKnockFly:
        bsr.w   ArthurJump                      ; 08408/08462
        tst.b   g_Jumping(a6)                   ; 0840C/08466
        bne.b   l_08416                         ; 08410/0846A
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08412/0846C
l_08416:
        rts                                     ; 08416/08470

;---------------------------------------------------------------------------
; State 4: landed. Armour lost now: flash (invulnerable) for 120 frames and carry on in
; his underwear; already without armour: start dying (20 + 40 + 225 frames)
;---------------------------------------------------------------------------
ArthurLand:
        bsr.w   ArthurFall                      ; 08418/08472
        tst.b   g_Falling(a6)                   ; 0841C/08476
        bne.b   l_08450                         ; 08420/0847A
        tst.b   g_NoArmour(a6)                  ; 08422/0847C
        beq.b   l_08452                         ; 08426/08480
        tst.b   g_OnPlatform(a6)                ; 08428/08482
        beq.b   l_0843E                         ; 0842C/08486
        move.l  g_ArthurPlatform(a6),d0         ; 0842E/08488
        beq.b   l_0843E                         ; 08432/0848C
        movea.l d0,a0                           ; 08434/0848E
        clr.b   $18(a0)                         ; 08436/08490
        clr.b   g_OnPlatform(a6)                ; 0843A/08494
l_0843E:
        lea.l   ArthurAnimDie1(pc),a1           ; 0843E/08498
        bsr.w   ArthurSetAnim                   ; 08442/0849C
        move.b  #$14,g_StateTimer(a6)           ; 08446/084A0
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 0844C/084A6
l_08450:
        rts                                     ; 08450/084AA
l_08452:
        move.b  #$78,g_ArthurFlash(a6)          ; 08452/084AC  flash for 120 frames: enemies cannot hurt him
        neg.b   g_ArthurFacing(a6)              ; 08458/084B2
        st.b    g_NoArmour(a6)                  ; 0845C/084B6  armour gone
        lea.l   ArthurAnims(pc),a1              ; 08460/084BA
        bsr.w   ArthurSetAnim                   ; 08464/084BE
        clr.b   g_ArthurDir(a6)                 ; 08468/084C2
        clr.b   g_ArthurState(a6)               ; 0846C/084C6
        clr.b   g_Jumping(a6)                   ; 08470/084CA
        clr.b   g_Falling(a6)                   ; 08474/084CE
        clr.b   g_OnLadder(a6)                  ; 08478/084D2
        rts                                     ; 0847C/084D6
ArthurDie1:
        subq.b  #$1,g_StateTimer(a6)            ; 0847E/084D8
        bne.w   ArthurAnimate                   ; 08482/084DC
        clr.b   g_FrogTimer(a6)                 ; 08486/084E0
        move.b  #$28,g_StateTimer(a6)           ; 0848A/084E4
        lea.l   ArthurAnimDie2(pc),a1           ; 08490/084EA
        bsr.w   ArthurSetAnim                   ; 08494/084EE
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08498/084F2
        rts                                     ; 0849C/084F6
ArthurDie2:
        subq.b  #$1,g_StateTimer(a6)            ; 0849E/084F8
        bne.w   ArthurAnimate                   ; 084A2/084FC
        move.b  #$e1,g_StateTimer(a6)           ; 084A6/08500  225 frames
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 084AC/08506
        rts                                     ; 084B0/0850A

;---------------------------------------------------------------------------
; Sets g_PlayerDied when the death animation finishes
;---------------------------------------------------------------------------
ArthurDie3:
        subq.b  #$1,g_StateTimer(a6)            ; 084B2/0850C
        bne.b   l_084C0                         ; 084B6/08510
        clr.b   g_ArthurState(a6)               ; 084B8/08512
        st.b    g_PlayerDied(a6)                ; 084BC/08516  tell the game loop
l_084C0:
        rts                                     ; 084C0/0851A

;---------------------------------------------------------------------------
; ==================================================================
; ArthurUpdate - Arthur's state machine (g_ArthurState):
;  0 normal (walk / jump / fall / crouch / ladder / frog)   1 hit
;  2 knockback start   3 knockback flight   4 landed after the knockback
;  5-7 death animation
; Positions and speeds are 16.16 fixed point, Y increasing upwards.
;   walk     1.125 px/frame (ArthurWalk)
;   jump     up 4.25 px/frame, gravity 0.24 px/frame^2 (falls at up to 5 px/frame):
;            rises for 17 frames, about 39 px high; forward jumps start at 0.5 px/frame and
;            speed up by 0.06 px/frame while rising - about 44 px over a 35-frame jump.
;            Direction is fixed for the whole jump.
;   ladder   1.375 px/frame up or down
;   frog     g_FrogTimer x 64 frames (8 = 512 frames); can walk and jump, not climb or fire
; ===================================================================
;---------------------------------------------------------------------------
ArthurUpdate:
        clr.w   d0                              ; 084C2/0851C
        move.b  g_ArthurState(a6),d0            ; 084C4/0851E
        add.w   d0,d0                           ; 084C8/08522
        add.w   d0,d0                           ; 084CA/08524
        jmp     ArthurUpdate_Jumps(pc,d0.w)     ; 084CC/08526
ArthurUpdate_Jumps:
        bra.w   ArthurNormal                    ; 084D0/0852A
        bra.w   ArthurHit                       ; 084D4/0852E
        bra.w   ArthurKnockback                 ; 084D8/08532
        bra.w   ArthurKnockFly                  ; 084DC/08536
        bra.w   ArthurLand                      ; 084E0/0853A
        bra.w   ArthurDie1                      ; 084E4/0853E
        bra.w   ArthurDie2                      ; 084E8/08542
        bra.w   ArthurDie3                      ; 084EC/08546

;---------------------------------------------------------------------------
; State 0: frog / jumping / falling / crouching / ladder / walking. Order: up or down
; (ladder, jump, crouch), climb, fire, left / right, then the floor test (walking off an
; edge starts a fall) and the platform test.
;---------------------------------------------------------------------------
ArthurNormal:
        tst.b   g_FrogTimer(a6)                 ; 084F0/0854A
        bne.w   ArthurFrog                      ; 084F4/0854E
        tst.b   g_ArthurFlash(a6)               ; 084F8/08552
        beq.b   l_08502                         ; 084FC/08556
        subq.b  #$1,g_ArthurFlash(a6)           ; 084FE/08558  invulnerable flash counting down
l_08502:
        tst.b   g_Jumping(a6)                   ; 08502/0855C
        bne.w   ArthurJump                      ; 08506/08560
        tst.b   g_Falling(a6)                   ; 0850A/08564
        bne.w   ArthurFall                      ; 0850E/08568
        tst.b   g_Crouching(a6)                 ; 08512/0856C
        bne.w   ArthurCrouch                    ; 08516/08570
        bsr.w   ArthurReadUpDown                ; 0851A/08574
        tst.b   d0                              ; 0851E/08578
        beq.b   l_08528                         ; 08520/0857A
        tst.b   g_OnLadder(a6)                  ; 08522/0857C
        bne.b   l_08576                         ; 08526/08580
l_08528:
        tst.b   g_OnLadder(a6)                  ; 08528/08582
        bne.w   ArthurClimb                     ; 0852C/08586
        bsr.w   ArthurFire                      ; 08530/0858A  fire (ArthurFire) before moving
        tst.b   g_Jumping(a6)                   ; 08534/0858E
        bne.b   l_08576                         ; 08538/08592
        bsr.w   ArthurReadLeftRight             ; 0853A/08594
        tst.b   g_ArthurDir(a6)                 ; 0853E/08598
        beq.b   l_08548                         ; 08542/0859C
        bsr.w   ArthurWalk                      ; 08544/0859E
l_08548:
        tst.b   g_OnPlatform(a6)                ; 08548/085A2
        beq.b   l_0855A                         ; 0854C/085A6
        movea.l g_ArthurPlatform(a6),a0         ; 0854E/085A8
        clr.b   $18(a0)                         ; 08552/085AC
        clr.b   g_OnPlatform(a6)                ; 08556/085B0
l_0855A:
        bsr.w   ArthurFloorCheck                ; 0855A/085B4  floor under his feet? no: start falling
        smi.b   g_Falling(a6)                   ; 0855E/085B8
        move.w  g_ArthurX(a6),d3                ; 08562/085BC
        move.w  g_ArthurY(a6),d4                ; 08566/085C0
        subq.w  #$1,d4                          ; 0856A/085C4
        bsr.w   ArthurOnPlatform                ; 0856C/085C6
        beq.b   l_08576                         ; 08570/085CA
        clr.b   g_Falling(a6)                   ; 08572/085CC
l_08576:
        tst.b   g_Falling(a6)                   ; 08576/085D0
        bpl.b   l_08580                         ; 0857A/085D4
        clr.b   g_ArthurDir(a6)                 ; 0857C/085D6
l_08580:
        rts                                     ; 08580/085DA

;---------------------------------------------------------------------------
; Normal state while transformed into a frog (g_FrogTimer)
;---------------------------------------------------------------------------
ArthurFrog:
        tst.b   g_ArthurFlash(a6)               ; 08582/085DC
        beq.b   l_0858C                         ; 08586/085E0
        subq.b  #$1,g_ArthurFlash(a6)           ; 08588/085E2
l_0858C:
        moveq   #$3f,d0                         ; 0858C/085E6
        and.w   g_GameFrame(a6),d0              ; 0858E/085E8
        bne.b   l_085A2                         ; 08592/085EC
        subq.b  #$1,g_FrogTimer(a6)             ; 08594/085EE  every 64 frames
        bne.b   l_085A2                         ; 08598/085F2
        lea.l   ArthurAnims(pc),a1              ; 0859A/085F4  back to normal
        bra.w   ArthurSetAnim                   ; 0859E/085F8
l_085A2:
        tst.b   g_Jumping(a6)                   ; 085A2/085FC
        bne.b   l_0860A                         ; 085A6/08600
        tst.b   g_Falling(a6)                   ; 085A8/08602
        bne.w   l_086AC                         ; 085AC/08606
        bsr.w   ArthurReadUpDown                ; 085B0/0860A
        bne.w   ArthurClimb                     ; 085B4/0860E
        bsr.w   ArthurReadLeftRight             ; 085B8/08612
        tst.b   g_ArthurDir(a6)                 ; 085BC/08616
        beq.b   l_085C6                         ; 085C0/0861A
        bsr.w   ArthurWalk                      ; 085C2/0861C
l_085C6:
        tst.b   g_OnPlatform(a6)                ; 085C6/08620
        beq.b   l_085D8                         ; 085CA/08624
        movea.l g_ArthurPlatform(a6),a0         ; 085CC/08626
        clr.b   $18(a0)                         ; 085D0/0862A
        clr.b   g_OnPlatform(a6)                ; 085D4/0862E
l_085D8:
        bsr.w   ArthurFloorCheck                ; 085D8/08632
        smi.b   g_Falling(a6)                   ; 085DC/08636
        move.w  g_ArthurX(a6),d3                ; 085E0/0863A
        move.w  g_ArthurY(a6),d4                ; 085E4/0863E
        subq.w  #$1,d4                          ; 085E8/08642
        bsr.w   ArthurOnPlatform                ; 085EA/08644
        beq.b   l_085F4                         ; 085EE/08648
        clr.b   g_Falling(a6)                   ; 085F0/0864A
l_085F4:
        tst.b   g_Falling(a6)                   ; 085F4/0864E
        bpl.b   l_085FE                         ; 085F8/08652
        clr.b   g_ArthurDir(a6)                 ; 085FA/08654
l_085FE:
        rts                                     ; 085FE/08658

;---------------------------------------------------------------------------
; Jump (and knockback) physics. Rising: X += vx (if moving), Y += vy, vx += $FA0,
; vy -= $3D90; below $3DFF it starts to fall: Y -= vy, vy += $3D90 up to 5 px/frame.
; Walls stop the horizontal part. Leaving a platform drops it.
;---------------------------------------------------------------------------
ArthurJump:
        tst.b   g_ArthurState(a6)               ; 08600/0865A
        bne.b   l_0860A                         ; 08604/0865E
        bsr.w   ArthurFire                      ; 08606/08660
l_0860A:
        bsr.w   ArthurAnimate                   ; 0860A/08664
        tst.b   g_ArthurDir(a6)                 ; 0860E/08668
        beq.b   l_08634                         ; 08612/0866C
        bpl.b   l_08626                         ; 08614/0866E
        bsr.w   WallCheckLeft                   ; 08616/08670  jumping left
        bne.b   l_08634                         ; 0861A/08674
        move.l  g_ArthurVelX(a6),d0             ; 0861C/08676
        sub.l   d0,g_ArthurX(a6)                ; 08620/0867A
        bra.b   l_08634                         ; 08624/0867E
l_08626:
        bsr.w   WallCheckRight                  ; 08626/08680
        bne.b   l_08634                         ; 0862A/08684
        move.l  g_ArthurVelX(a6),d0             ; 0862C/08686
        add.l   d0,g_ArthurX(a6)                ; 08630/0868A
l_08634:
        tst.b   g_Falling(a6)                   ; 08634/0868E
        bne.b   l_0867A                         ; 08638/08692
        move.l  g_ArthurVelY(a6),d0             ; 0863A/08694
        add.l   d0,g_ArthurY(a6)                ; 0863E/08698
        addi.l  #$fa0,g_ArthurVelX(a6)          ; 08642/0869C  vx grows while rising
        subi.l  #$3d90,g_ArthurVelY(a6)         ; 0864A/086A4  gravity
        cmpi.l  #$3dff,g_ArthurVelY(a6)         ; 08652/086AC
        bcc.b   l_08660                         ; 0865A/086B4
        st.b    g_Falling(a6)                   ; 0865C/086B6  top of the jump: falling from now on
l_08660:
        tst.b   g_OnPlatform(a6)                ; 08660/086BA
        beq.b   l_08678                         ; 08664/086BE
        move.l  g_ArthurPlatform(a6),d0         ; 08666/086C0
        beq.w   l_088B2                         ; 0866A/086C4
        movea.l d0,a0                           ; 0866E/086C8
        clr.b   $18(a0)                         ; 08670/086CA
        clr.b   g_OnPlatform(a6)                ; 08674/086CE
l_08678:
        rts                                     ; 08678/086D2
l_0867A:
        move.l  g_ArthurVelY(a6),d0             ; 0867A/086D4
        sub.l   d0,g_ArthurY(a6)                ; 0867E/086D8
        cmpi.w  #$5,g_ArthurVelY(a6)            ; 08682/086DC  fall speed limit 5 px/frame
        scs.b   g_Jumping(a6)                   ; 08688/086E2
        bcc.b   l_086E8                         ; 0868C/086E6
        addi.l  #$3d90,g_ArthurVelY(a6)         ; 0868E/086E8
        bra.b   l_086E8                         ; 08696/086F0

;---------------------------------------------------------------------------
; Falling (off an edge or after a jump's top): sideways at vx (growing), down at vy
; (up to 5 px/frame); lands on a platform or the floor (sound 5)
;---------------------------------------------------------------------------
ArthurFall:
        tst.b   g_ArthurState(a6)               ; 08698/086F2
        bne.b   l_086AC                         ; 0869C/086F6
        bsr.w   ArthurFire                      ; 0869E/086F8
        tst.b   g_FireCooldown(a6)              ; 086A2/086FC
        bne.b   l_086AC                         ; 086A6/08700
        bsr.w   ArthurAnimate                   ; 086A8/08702
l_086AC:
        move.l  g_ArthurVelX(a6),d0             ; 086AC/08706
        tst.b   g_ArthurDir(a6)                 ; 086B0/0870A
        beq.b   l_086BE                         ; 086B4/0870E
        bpl.b   l_086BA                         ; 086B6/08710
        neg.l   d0                              ; 086B8/08712
l_086BA:
        add.l   d0,g_ArthurX(a6)                ; 086BA/08714
l_086BE:
        move.l  g_ArthurVelY(a6),d0             ; 086BE/08718
        sub.l   d0,g_ArthurY(a6)                ; 086C2/0871C
        move.l  g_ArthurVelX(a6),d0             ; 086C6/08720
        addi.l  #$fa0,d0                        ; 086CA/08724
        tst.w   d0                              ; 086D0/0872A
        bmi.b   l_086D8                         ; 086D2/0872C
        move.l  d0,g_ArthurVelX(a6)             ; 086D4/0872E
l_086D8:
        cmpi.w  #$5,g_ArthurVelY(a6)            ; 086D8/08732
        bcc.b   l_086E8                         ; 086DE/08738
        addi.l  #$3d90,g_ArthurVelY(a6)         ; 086E0/0873A
l_086E8:
        move.w  g_ArthurX(a6),d3                ; 086E8/08742
        move.w  g_ArthurY(a6),d4                ; 086EC/08746
        subq.w  #$1,d4                          ; 086F0/0874A
        bsr.w   ArthurOnPlatform                ; 086F2/0874C
        bne.b   l_08726                         ; 086F6/08750
        bsr.w   ArthurFloorCheck                ; 086F8/08752
        smi.b   g_Falling(a6)                   ; 086FC/08756
        bmi.b   l_08724                         ; 08700/0875A
        clr.l   g_ArthurVelX(a6)                ; 08702/0875C  landed
        clr.b   g_Jumping(a6)                   ; 08706/08760
        tst.b   g_FrogTimer(a6)                 ; 0870A/08764
        beq.b   l_08716                         ; 0870E/08768
        lea.l   ArthurAnimFrog(pc),a1           ; 08710/0876A
        bra.b   l_0871A                         ; 08714/0876E
l_08716:
        lea.l   ArthurAnims(pc),a1              ; 08716/08770
l_0871A:
        bsr.w   ArthurSetAnim                   ; 0871A/08774
        moveq   #SFX_LAND,d0                    ; 0871E/08778
        bsr.w   PlaySfx                         ; 08720/0877A
l_08724:
        rts                                     ; 08724/0877E
l_08726:
        clr.b   g_Falling(a6)                   ; 08726/08780
        clr.b   g_Jumping(a6)                   ; 0872A/08784
        lea.l   ArthurAnims(pc),a1              ; 0872E/08788
        tst.b   g_Crouching(a6)                 ; 08732/0878C
        beq.b   l_0873C                         ; 08736/08790
        lea.l   ArthurAnimCrouch(pc),a1         ; 08738/08792
l_0873C:
        bsr.w   ArthurSetAnim                   ; 0873C/08796
        bra.w   ArthurAnimate                   ; 08740/0879A

;---------------------------------------------------------------------------
; Crouching: no walking; up / down and fire still read
;---------------------------------------------------------------------------
ArthurCrouch:
        clr.b   g_ArthurDir(a6)                 ; 08744/0879E
        bsr.w   ArthurReadUpDown                ; 08748/087A2
        bsr.w   ArthurFire                      ; 0874C/087A6
        bsr.w   ArthurAnimate                   ; 08750/087AA
        tst.b   g_OnPlatform(a6)                ; 08754/087AE
        beq.b   l_08770                         ; 08758/087B2
        bsr.w   ArthurOnPlatform                ; 0875A/087B4
        seq.b   g_Falling(a6)                   ; 0875E/087B8
        bne.b   l_08770                         ; 08762/087BC
        clr.b   g_OnPlatform(a6)                ; 08764/087BE
        movea.l g_ArthurPlatform(a6),a0         ; 08768/087C2
        clr.b   $18(a0)                         ; 0876C/087C6
l_08770:
        rts                                     ; 08770/087CA

;---------------------------------------------------------------------------
; Left / right held: face that way and walk; neither: stand (or keep crouching)
;---------------------------------------------------------------------------
ArthurReadLeftRight:
        move.w  g_Joy(a6),d0                    ; 08772/087CC
        and.w   g_JoyPrev(a6),d0                ; 08776/087D0
        btst    #$1,d0                          ; 0877A/087D4  right held (bit 1)
        bne.b   l_087B6                         ; 0877E/087D8
        btst    #$9,d0                          ; 08780/087DA  left held (bit 9)
        bne.b   l_087BC                         ; 08784/087DE
        tst.b   g_FrogTimer(a6)                 ; 08786/087E0
        beq.b   l_08792                         ; 0878A/087E4
        lea.l   ArthurAnimFrog(pc),a1           ; 0878C/087E6
        bra.b   l_087AC                         ; 08790/087EA
l_08792:
        tst.b   g_FireCooldown(a6)              ; 08792/087EC
        bne.b   l_087B0                         ; 08796/087F0
        tst.b   g_Crouching(a6)                 ; 08798/087F2
        beq.b   l_087A8                         ; 0879C/087F6
        lea.l   ArthurAnimCrouch(pc),a1         ; 0879E/087F8
        bsr.w   ArthurSetAnim                   ; 087A2/087FC
        bra.b   l_087B0                         ; 087A6/08800
l_087A8:
        lea.l   ArthurAnims(pc),a1              ; 087A8/08802
l_087AC:
        bsr.w   ArthurSetAnim                   ; 087AC/08806
l_087B0:
        clr.b   g_ArthurDir(a6)                 ; 087B0/0880A
        rts                                     ; 087B4/0880E
l_087B6:
        move.b  #$1,d1                          ; 087B6/08810
        bra.b   l_087BE                         ; 087BA/08814
l_087BC:
        st.b    d1                              ; 087BC/08816
l_087BE:
        move.b  d1,g_ArthurFacing(a6)           ; 087BE/08818
        cmp.b   g_ArthurDir(a6),d1              ; 087C2/0881C
        bne.b   l_087CC                         ; 087C6/08820
        clr.b   d1                              ; 087C8/08822
        rts                                     ; 087CA/08824
l_087CC:
        move.b  d1,g_ArthurDir(a6)              ; 087CC/08826
        tst.b   g_FrogTimer(a6)                 ; 087D0/0882A
        beq.b   l_087DC                         ; 087D4/0882E
        lea.l   ArthurAnimFrog(pc),a1           ; 087D6/08830
        bra.b   l_087E0                         ; 087DA/08834
l_087DC:
        lea.l   ArthurAnims(pc),a1              ; 087DC/08836
l_087E0:
        bsr.w   ArthurSetAnim                   ; 087E0/0883A
        rts                                     ; 087E4/0883E

;---------------------------------------------------------------------------
; Up: climb a ladder he stands at (or carry on climbing / step off at the top), else
; jump (sound 4). Down: step onto a ladder 18 px below his feet (moving 14 px down), carry
; on down, else crouch. Out: d0 nonzero = up or down was acted on.
;---------------------------------------------------------------------------
ArthurReadUpDown:
        clr.b   g_Crouching(a6)                 ; 087E6/08840  up / down only count when held for two VBL samples
        move.w  g_Joy(a6),d0                    ; 087EA/08844
        and.w   g_JoyPrev(a6),d0                ; 087EE/08848
        tst.b   (JumpButton).l                  ; jump on button 2: held for two samples, as up, and
        beq.b   l_udup                          ; not from a ladder (as up: a ladder is climbed)
        btst    #$e,d0
        beq.b   l_udup
        tst.b   g_OnLadder(a6)
        beq.w   l_08884
l_udup:
        btst    #$8,d0                          ; 087F2/0884C  up held (bit 8)
        bne.b   l_08808                         ; 087F6/08850
        btst    #$0,d0                          ; 087F8/08852  down held (bit 0)
        bne.w   l_088E6                         ; 087FC/08856
l_udnone:
        clr.b   g_LadderDir(a6)                 ; 08800/0885A  neither: not on a ladder move
        st.b    d0                              ; 08804/0885E
        rts                                     ; 08806/08860
l_08808:
        tst.b   g_FrogTimer(a6)                 ; 08808/08862  up: a frog cannot climb, he jumps
        bne.b   l_08884                         ; 0880C/08866
        move.w  g_ArthurX(a6),d6                ; 0880E/08868
        move.w  g_ArthurY(a6),d7                ; 08812/0886C
        bsr.w   LadderCheck                     ; 08816/08870  ladder here?
        beq.b   l_08840                         ; 0881A/08874
