        bhi.b   l_0883C                         ; 08888/088E2
        st.b    g_Jumping(a6)                   ; 0888A/088E4  jump
        tst.b   g_FrogTimer(a6)                 ; 0888E/088E8
        beq.b   l_0889A                         ; 08892/088EC
        lea.l   ArthurAnimFrogJump(pc),a1       ; 08894/088EE
        bra.b   l_088A8                         ; 08898/088F2
l_0889A:
        lea.l   ArthurAnimJump(pc),a1           ; 0889A/088F4
        tst.b   g_ArthurDir(a6)                 ; 0889E/088F8
        beq.b   l_088A8                         ; 088A2/088FC
        lea.l   ArthurAnimJumpFwd(pc),a1        ; 088A4/088FE
l_088A8:
