;---------------------------------------------------------------------------
; torch 2, lance 3, axe 2, cross 3, dagger 3
;---------------------------------------------------------------------------
MaxShotsPerWeapon:
	dc.b	$02,$03,$02,$03,$03,$00

;---------------------------------------------------------------------------
; On fire press: spawn a shot of type g_Weapon if a slot is free (sfx 6)
;---------------------------------------------------------------------------
ArthurFire:
        tst.b   g_PlayerDied(a6)                ; 08992/089EC
        bne.w   l_08A62                         ; 08996/089F0
        cmpi.b  #$5,g_FireCooldown(a6)          ; 0899A/089F4  can fire again once the cooldown is down to 5
        bhi.w   l_08A40                         ; 089A0/089FA
        move.w  g_JoyPrev(a6),d0                ; 089A4/089FE  fire newly pressed?
        not.w   d0                              ; 089A8/08A02
        and.w   g_Joy(a6),d0                    ; 089AA/08A04
        bpl.w   l_08A40                         ; 089AE/08A08
        lea.l   g_Shots(a6),a0                  ; 089B2/08A0C
        move.w  g_Weapon(a6),d0                 ; 089B6/08A10
        move.b  MaxShotsPerWeapon(pc,d0.w),d0   ; 089BA/08A14  slots this weapon may use
        moveq   #$26,d1                         ; 089BE/08A18
l_089C0:
        tst.b   (a0)                            ; 089C0/08A1A
        beq.b   l_089CC                         ; 089C2/08A1C
        adda.w  d1,a0                           ; 089C4/08A1E
        subq.b  #$1,d0                          ; 089C6/08A20
        bne.b   l_089C0                         ; 089C8/08A22
        bra.b   l_08A40                         ; 089CA/08A24
l_089CC:
        move.b  #$1,(a0)                        ; 089CC/08A26
        move.b  #$1,$1(a0)                      ; 089D0/08A2A
        clr.b   $13(a0)                         ; 089D6/08A30
        clr.b   $5(a0)                          ; 089DA/08A34
        clr.b   $4(a0)                          ; 089DE/08A38
        clr.b   $3(a0)                          ; 089E2/08A3C
        move.b  g_Weapon+1(a6),$1a(a0)          ; 089E6/08A40  shot type = g_Weapon (low byte)
        moveq   #$9,d0                          ; 089EC/08A46  from 9 px above his feet, or 3 below when crouching
        tst.b   g_Crouching(a6)                 ; 089EE/08A48
        beq.b   l_089F6                         ; 089F2/08A4C
        moveq   #-3,d0                          ; 089F4/08A4E
l_089F6:
        add.w   g_ArthurY(a6),d0                ; 089F6/08A50
        move.w  d0,$a(a0)                       ; 089FA/08A54
        tst.b   g_ArthurFacing(a6)              ; 089FE/08A58
        bpl.b   l_08A12                         ; 08A02/08A5C
        move.w  g_ArthurX(a6),$6(a0)            ; 08A04/08A5E
        move.b  #$2,$12(a0)                     ; 08A0A/08A64  facing left: from his X, direction 2
        bra.b   l_08A22                         ; 08A10/08A6A
l_08A12:
        moveq   #$f,d0                          ; 08A12/08A6C  facing right: 15 px ahead, direction 1
        add.w   g_ArthurX(a6),d0                ; 08A14/08A6E
        move.w  d0,$6(a0)                       ; 08A18/08A72
        move.b  #$1,$12(a0)                     ; 08A1C/08A76
l_08A22:
        move.b  #$f,g_FireCooldown(a6)          ; 08A22/08A7C  15-frame cooldown with the throw animation
        lea.l   ArthurAnimThrow(pc),a1          ; 08A28/08A82
        tst.b   g_Crouching(a6)                 ; 08A2C/08A86
        beq.b   l_08A36                         ; 08A30/08A8A
        lea.l   ArthurAnimThrowCrouch(pc),a1    ; 08A32/08A8C
l_08A36:
        bsr.w   ArthurSetAnim                   ; 08A36/08A90
        moveq   #SFX_THROW,d0                   ; 08A3A/08A94
        bsr.w   PlaySfx                         ; 08A3C/08A96
l_08A40:
        tst.b   g_FireCooldown(a6)              ; 08A40/08A9A
        beq.b   l_08A62                         ; 08A44/08A9E
        bsr.w   ArthurAnimate                   ; 08A46/08AA0
        subq.b  #$1,g_FireCooldown(a6)          ; 08A4A/08AA4
        bne.b   l_08A62                         ; 08A4E/08AA8
        lea.l   ArthurAnims(pc),a1              ; 08A50/08AAA
        tst.b   g_Crouching(a6)                 ; 08A54/08AAE
        beq.b   l_08A5E                         ; 08A58/08AB2
        lea.l   ArthurAnimCrouch(pc),a1         ; 08A5A/08AB4
l_08A5E:
        bsr.w   ArthurSetAnim                   ; 08A5E/08AB8
l_08A62:
        rts                                     ; 08A62/08ABC

;---------------------------------------------------------------------------
; Walk 1.125 px/frame unless firing; stopped by platforms and walls
;---------------------------------------------------------------------------
ArthurWalk:
        tst.b   g_FireCooldown(a6)              ; 08A64/08ABE
        bne.w   ArthurAnimate                   ; 08A68/08AC2
        tst.b   g_ArthurDir(a6)                 ; 08A6C/08AC6
        bmi.b   l_08A98                         ; 08A70/08ACA
        move.w  g_ArthurX(a6),d3                ; 08A72/08ACC
        move.w  g_ArthurY(a6),d4                ; 08A76/08AD0
        addq.w  #$1,d3                          ; 08A7A/08AD4
        addq.w  #$1,d4                          ; 08A7C/08AD6
        bsr.w   ArthurOnPlatform                ; 08A7E/08AD8
        bne.w   ArthurAnimate                   ; 08A82/08ADC
        bsr.b   WallCheckRight                  ; 08A86/08AE0
        bne.w   ArthurAnimate                   ; 08A88/08AE2
        addi.l  #$12000,g_ArthurX(a6)           ; 08A8C/08AE6  1.125 px/frame right
        bra.w   ArthurAnimate                   ; 08A94/08AEE
l_08A98:
        move.w  g_ArthurX(a6),d3                ; 08A98/08AF2
        move.w  g_ArthurY(a6),d4                ; 08A9C/08AF6
        subq.w  #$1,d3                          ; 08AA0/08AFA
        addq.w  #$1,d4                          ; 08AA2/08AFC
        bsr.w   ArthurOnPlatform                ; 08AA4/08AFE
        bne.w   ArthurAnimate                   ; 08AA8/08B02
        bsr.b   WallCheckLeft                   ; 08AAC/08B06
        bne.w   ArthurAnimate                   ; 08AAE/08B08
        subi.l  #$12000,g_ArthurX(a6)           ; 08AB2/08B0C  1.125 px/frame left
        bra.w   ArthurAnimate                   ; 08ABA/08B14

;---------------------------------------------------------------------------
; Wall 16 px to the right at knee height (Y - 7)? Push him out of it (WallProfileR);
; if that leaves him within 10 px of the right edge of the screen he stops walking.
; Out: Z clear = wall.
;---------------------------------------------------------------------------
WallCheckRight:
        moveq   #$10,d6                         ; 08ABE/08B18
        add.w   g_ArthurX(a6),d6                ; 08AC0/08B1A
        moveq   #-7,d7                          ; 08AC4/08B1E
        add.w   g_ArthurY(a6),d7                ; 08AC6/08B20
        bsr.w   MapTileAt                       ; 08ACA/08B24
        move.b  $4(a1),d0                       ; 08ACE/08B28
        andi.b  #$c0,d0                         ; 08AD2/08B2C
        bne.b   l_08AF0                         ; 08AD6/08B30
        move.b  (a1),d0                         ; 08AD8/08B32
        ext.w   d0                              ; 08ADA/08B34
        lea.l   WallProfileR(pc),a1             ; 08ADC/08B36
        adda.w  d0,a1                           ; 08AE0/08B3A
        move.b  (a1),d0                         ; 08AE2/08B3C
        beq.b   l_08AF0                         ; 08AE4/08B3E
        moveq   #$f,d1                          ; 08AE6/08B40
        and.w   g_ArthurX(a6),d1                ; 08AE8/08B42
        sub.b   d0,d1                           ; 08AEC/08B46
        bcc.b   l_08AF4                         ; 08AEE/08B48
l_08AF0:
        moveq   #$0,d0                          ; 08AF0/08B4A
        rts                                     ; 08AF2/08B4C
l_08AF4:
        sub.w   d1,g_ArthurX(a6)                ; 08AF4/08B4E
        clr.w   g_ArthurX+2(a6)                 ; 08AF8/08B52
        move.w  g_CameraX(a6),d0                ; 08AFC/08B56
        addi.w  #$100,d0                        ; 08B00/08B5A
        sub.w   g_ArthurX(a6),d0                ; 08B04/08B5E
l_08B08:
        cmp.w   #$a,d0                          ; 08B08/08B62
        bhi.b   l_08B12                         ; 08B0C/08B66
        clr.b   g_ArthurDir(a6)                 ; 08B0E/08B68
l_08B12:
        moveq   #-1,d0                          ; 08B12/08B6C
        rts                                     ; 08B14/08B6E

;---------------------------------------------------------------------------
; The same to the left (WallProfileL) and the left edge of the screen
;---------------------------------------------------------------------------
WallCheckLeft:
        moveq   #-16,d6                         ; 08B16/08B70
        add.w   g_ArthurX(a6),d6                ; 08B18/08B72
        moveq   #-7,d7                          ; 08B1C/08B76
        add.w   g_ArthurY(a6),d7                ; 08B1E/08B78
        bsr.w   MapTileAt                       ; 08B22/08B7C
        move.b  $4(a1),d0                       ; 08B26/08B80
        andi.b  #$c0,d0                         ; 08B2A/08B84
        bne.b   l_08B4A                         ; 08B2E/08B88
        move.b  (a1),d0                         ; 08B30/08B8A
        ext.w   d0                              ; 08B32/08B8C
        lea.l   WallProfileL(pc),a1             ; 08B34/08B8E
        adda.w  d0,a1                           ; 08B38/08B92
        move.b  (a1),d0                         ; 08B3A/08B94
        beq.b   l_08B4A                         ; 08B3C/08B96
        ext.w   d0                              ; 08B3E/08B98
        moveq   #$f,d1                          ; 08B40/08B9A
        and.w   g_ArthurX(a6),d1                ; 08B42/08B9C
        sub.w   d1,d0                           ; 08B46/08BA0
        bcc.b   l_08B4E                         ; 08B48/08BA2
l_08B4A:
        moveq   #$0,d0                          ; 08B4A/08BA4
        rts                                     ; 08B4C/08BA6
l_08B4E:
        add.w   d0,g_ArthurX(a6)                ; 08B4E/08BA8
        move.w  g_ArthurX(a6),d0                ; 08B52/08BAC
        sub.w   g_CameraX(a6),d0                ; 08B56/08BB0
        bra.b   l_08B08                         ; 08B5A/08BB4

;---------------------------------------------------------------------------
; 1.375 px/frame up (g_LadderDir > 0) or down
;---------------------------------------------------------------------------
ArthurClimb:
        bsr.w   ArthurAnimate                   ; 08B5C/08BB6
        move.l  #$16000,d0                      ; 08B60/08BBA  1.375 px/frame
        tst.b   g_LadderDir(a6)                 ; 08B66/08BC0
        bpl.b   l_08B6E                         ; 08B6A/08BC4
        neg.l   d0                              ; 08B6C/08BC6
l_08B6E:
        add.l   d0,g_ArthurY(a6)                ; 08B6E/08BC8
        rts                                     ; 08B72/08BCC

;---------------------------------------------------------------------------
; Ladder tile at d6, d7 (profile $40-$7D, not background)? Snap X to its 16-px column
; (the profile's bit 0 says which half).
;---------------------------------------------------------------------------
LadderCheck:
        bsr.w   MapTileAt                       ; 08B74/08BCE
        move.b  $4(a1),d0                       ; 08B78/08BD2
        andi.b  #$c0,d0                         ; 08B7C/08BD6
        bne.b   l_08BA8                         ; 08B80/08BDA
        move.b  (a1),d0                         ; 08B82/08BDC
        subi.b  #$40,d0                         ; 08B84/08BDE
        cmp.b   #$3d,d0                         ; 08B88/08BE2
        bhi.b   l_08BA8                         ; 08B8C/08BE6
        btst    #$0,d0                          ; 08B8E/08BE8
        bne.b   l_08B9A                         ; 08B92/08BEC
        addi.w  #$10,g_ArthurX(a6)              ; 08B94/08BEE
l_08B9A:
        moveq   #-15,d0                         ; 08B9A/08BF4
        and.w   g_ArthurX(a6),d0                ; 08B9C/08BF6
        move.w  d0,g_ArthurX(a6)                ; 08BA0/08BFA
        st.b    d0                              ; 08BA4/08BFE
        rts                                     ; 08BA6/08C00
l_08BA8:
        clr.b   d0                              ; 08BA8/08C02
        rts                                     ; 08BAA/08C04

;---------------------------------------------------------------------------
; Arthur's animations. Each table has offsets to the facing-right and facing-left scripts;
; ArthurSetAnim picks one by g_ArthurFacing. Frame numbers (sprite frames, tracks 33-36):
;   0-3 walk  4 stand  5 jump forward  6 jump up  7 crouch  8-9 throw  10-11 throw crouching
;   12 climb  13-14 top of a ladder  15 and 37-39 frog  31 knocked back (armour gone)
;   32-36 skeleton (dying)
; ~n is the mirrored copy of frame n (built at start-up). ArthurAnimate adds 16 to frames
; 0-15 when he has lost his armour (the frames in his underwear).
;---------------------------------------------------------------------------
ArthurAnims:
	dc.w	ArthurAnims_R-*,ArthurAnims_L-*	; facing right, facing left
ArthurAnims_R:
	AFRAME	4,4
ArthurAnims_R_2:
	AFRAME	0,4
	AFRAME	1,4
	AFRAME	2,4
	AFRAME	3,4
	AFRAME	2,4
	ALOOP	1,4,ArthurAnims_R_2
ArthurAnims_L:
	AFRAME	~4,4
ArthurAnims_L_2:
	AFRAME	~0,4
	AFRAME	~1,4
	AFRAME	~2,4
	AFRAME	~3,4
	AFRAME	~2,4
	ALOOP	~1,4,ArthurAnims_L_2
ArthurAnimFrog:
	dc.w	ArthurAnimFrog_R-*,ArthurAnimFrog_L-*	; facing right, facing left
ArthurAnimFrog_R:
	AFRAME	37,5
	AFRAME	38,4
	AFRAME	39,4
	ALOOP	15,5,ArthurAnimFrog_R
ArthurAnimFrog_L:
	AFRAME	~37,5
	AFRAME	~38,4
	AFRAME	~39,4
	ALOOP	~15,5,ArthurAnimFrog_L
ArthurAnimJump:
	dc.w	ArthurAnimJump_R-*,ArthurAnimJump_L-*	; facing right, facing left
ArthurAnimJump_R:
	ALOOP	6,127,ArthurAnimJump_R
ArthurAnimJump_L:
	ALOOP	~6,127,ArthurAnimJump_L
ArthurAnimJumpFwd:
	dc.w	ArthurAnimJumpFwd_R-*,ArthurAnimJumpFwd_L-*	; facing right, facing left
