;---------------------------------------------------------------------------
; Award a life at 20000, 70000, then every 70000 (BCD compare)
;---------------------------------------------------------------------------
ExtraLifeCheck:
        move.l  g_Score(a6),d0                  ; 08C8A/08CE4
        cmpi.b  #$1,g_ExtraLives(a6)            ; 08C8E/08CE8
        beq.b   l_08CB4                         ; 08C94/08CEE
        bcs.b   l_08CAA                         ; 08C96/08CF0
        cmp.l   g_NextExtraLife(a6),d0          ; 08C98/08CF2
        blt.b   l_08CA8                         ; 08C9C/08CF6
        addi.l  #$70000,g_NextExtraLife(a6)     ; 08C9E/08CF8
        bra.b   l_08CC8                         ; 08CA6/08D00
l_08CA8:
        rts                                     ; 08CA8/08D02
l_08CAA:
        cmp.l   #$20000,d0                      ; 08CAA/08D04
        bge.b   l_08CC8                         ; 08CB0/08D0A
        rts                                     ; 08CB2/08D0C
l_08CB4:
        cmp.l   #$70000,d0                      ; 08CB4/08D0E
        blt.b   l_08CC6                         ; 08CBA/08D14
        move.l  #$140000,g_NextExtraLife(a6)    ; 08CBC/08D16
        bra.b   l_08CC8                         ; 08CC4/08D1E
l_08CC6:
        rts                                     ; 08CC6/08D20
l_08CC8:
        addq.b  #$1,g_ExtraLives(a6)            ; 08CC8/08D22
        addq.b  #$1,g_Lives(a6)                 ; 08CCC/08D26
        bsr.w   DrawLives                       ; 08CD0/08D2A
snd108_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd108_512                      
        move    (a7)+,ccr                       
        moveq   #SFX_EXTRA_LIFE,d0              ;      /08D2E
        bsr.w   PlaySfx                         ;      /08D30  effect 14: extra life
        bra.w   snd108_end                      
snd108_512:
        move    (a7)+,ccr                       
        moveq   #$37,d0                         ; 08CD4/     
snd108_end:
        rts                                     ; 08CD6/08D34  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]

