        lea.l   EnemyContactBoxesCrouch(pc),a1  ; 08E1E/08E7C
l_08E22:
        lea.l   g_Enemies(a6),a5                ; 08E22/08E80
        moveq   #$27,d7                         ; 08E26/08E84
l_08E28:
        move.b  (a5),d0                         ; 08E28/08E86
        and.b   O_OnScreen(a5),d0               ; 08E2A/08E88
        beq.b   l_08E84                         ; 08E2E/08E8C
        clr.w   d0                              ; 08E30/08E8E
        move.b  O_Type(a5),d0                   ; 08E32/08E90
        cmp.b   #$e,d0                          ; 08E36/08E94
        bne.b   l_08E44                         ; 08E3A/08E98
        cmpi.b  #$a,O_Size(a5)                  ; 08E3C/08E9A  fire: only at full flare
        bne.b   l_08E84                         ; 08E42/08EA0
l_08E44:
        lsl.w   #$3,d0                          ; 08E44/08EA2
        lea.l   (a1,d0.w),a0                    ; 08E46/08EA4
        moveq   #-1,d1                          ; 08E4A/08EA8
        move.w  O_X(a5),d0                      ; 08E4C/08EAA
        sub.w   g_ArthurX(a6),d0                ; 08E50/08EAE
        bpl.b   l_08E58                         ; 08E54/08EB2
        moveq   #$1,d1                          ; 08E56/08EB4
l_08E58:
        add.w   (a0)+,d0                        ; 08E58/08EB6
        cmp.w   (a0)+,d0                        ; 08E5A/08EB8
        bhi.b   l_08E84                         ; 08E5C/08EBA
        move.w  O_Y(a5),d0                      ; 08E5E/08EBC
        sub.w   g_ArthurY(a6),d0                ; 08E62/08EC0
        add.w   (a0)+,d0                        ; 08E66/08EC4
        cmp.w   (a0)+,d0                        ; 08E68/08EC6
        bhi.b   l_08E84                         ; 08E6A/08EC8
        tst.b   g_CheatOn(a6)                   ; 08E6C/08ECA  cheat: no effect once the armour is gone
        beq.b   l_08E78                         ; 08E70/08ECE
        tst.b   g_NoArmour(a6)                  ; 08E72/08ED0
        bne.b   l_08E84                         ; 08E76/08ED4
l_08E78:
