        move.b  d1,g_ArthurDir(a6)              ; 08E7E/08EDC
        bra.b   l_08E8C                         ; 08E82/08EE0
l_08E84:
        lea.l   $3c(a5),a5                      ; 08E84/08EE2
        dbra    d7,l_08E28                      ; 08E88/08EE6
l_08E8C:
