;---------------------------------------------------------------------------
; Enemy shots against Arthur. Shot type 0 (the Magician's spell) turns him into a frog
; (g_FrogTimer = 8); any other hits him (g_ArthurState 1), except when the cheat is on
; and g_NoArmour is set. A shot that hits is removed. Skipped while Arthur flashes or is
; already hit; crouching uses the smaller box table.
;---------------------------------------------------------------------------
EnemyShotsVsArthur:
        tst.b   g_ArthurFlash(a6)               ; 08F4E/08FAC  not while flashing or already hit
        bne.w   l_09000                         ; 08F52/08FB0
        tst.b   g_ArthurState(a6)               ; 08F56/08FB4
        bne.w   l_09000                         ; 08F5A/08FB8
        lea.l   EnemyShotBoxes(pc),a1           ; 08F5E/08FBC  boxes by enemy-shot type (smaller set while crouching)
        tst.b   g_Crouching(a6)                 ; 08F62/08FC0
        beq.b   l_08F6C                         ; 08F66/08FC4
        lea.l   EnemyShotBoxesCrouch(pc),a1     ; 08F68/08FC6
l_08F6C:
        lea.l   g_EnemyShots(a6),a5             ; 08F6C/08FCA
        moveq   #$5,d7                          ; 08F70/08FCE
l_08F72:
        move.b  (a5),d0                         ; 08F72/08FD0  each active, on-screen enemy shot
        and.b   O_OnScreen(a5),d0               ; 08F74/08FD2
        beq.b   l_08FF8                         ; 08F78/08FD6
        move.b  O_Type(a5),d0                   ; 08F7A/08FD8
        ext.w   d0                              ; 08F7E/08FDC
        lsl.w   #$3,d0                          ; 08F80/08FDE
        lea.l   (a1,d0.w),a0                    ; 08F82/08FE0
        move.w  O_X(a5),d0                      ; 08F86/08FE4  X inside the box? d1 = side it came from (knock-back direction)
        sub.w   g_ArthurX(a6),d0                ; 08F8A/08FE8
        add.w   (a0)+,d0                        ; 08F8E/08FEC
        cmp.w   (a0)+,d0                        ; 08F90/08FEE
        bhi.b   l_08FF8                         ; 08F92/08FF0
        moveq   #-1,d1                          ; 08F94/08FF2
        sub.w   -$4(a0),d0                      ; 08F96/08FF4
        bmi.b   l_08F9E                         ; 08F9A/08FF8
        moveq   #$1,d1                          ; 08F9C/08FFA
l_08F9E:
        move.w  O_Y(a5),d0                      ; 08F9E/08FFC  Y inside the box?
        sub.w   g_ArthurY(a6),d0                ; 08FA2/09000
        add.w   (a0)+,d0                        ; 08FA6/09004
        cmp.w   (a0)+,d0                        ; 08FA8/09006
        bhi.b   l_08FF8                         ; 08FAA/09008
        tst.b   O_Type(a5)                      ; 08FAC/0900A  type 0: the frog spell
        bne.b   l_08FCE                         ; 08FB0/0900E
        move.b  #$8,g_FrogTimer(a6)             ; 08FB2/09010
        clr.b   g_OnLadder(a6)                  ; 08FB8/09016
        clr.b   g_FireCooldown(a6)              ; 08FBC/0901A
        clr.b   g_Crouching(a6)                 ; 08FC0/0901E
        lea.l   ArthurAnimFrog(pc),a1           ; 08FC4/09022
        bsr.w   ArthurSetAnim                   ; 08FC8/09026
        bra.b   l_08FE4                         ; 08FCC/0902A
l_08FCE:
        tst.b   g_CheatOn(a6)                   ; 08FCE/0902C  cheat on and no armour: no harm
        beq.b   l_08FDA                         ; 08FD2/09030
        tst.b   g_NoArmour(a6)                  ; 08FD4/09032
        bne.b   l_08FF8                         ; 08FD8/09036
l_08FDA:
        move.b  #AS_HIT,g_ArthurState(a6)       ; 08FDA/09038  hit: knocked back away from the shot
        move.b  d1,g_ArthurDir(a6)              ; 08FE0/0903E
l_08FE4:
        move.b  #$2,(a5)                        ; 08FE4/09042  the shot is used up
