        clr.b   O_Step(a5)                      ; 08FEE/0904C
        clr.b   O_Step2(a5)                     ; 08FF2/09050
        bra.b   l_09000                         ; 08FF6/09054
l_08FF8:
        lea.l   $1c(a5),a5                      ; 08FF8/09056
        dbra    d7,l_08F72                      ; 08FFC/0905A
l_09000:
        rts                                     ; 09000/0905E

