Torch_Start:
        clr.b   O_Size(a5)                      ; 092A6/09304
        lea.l   ShotSpeeds(pc),a1               ; 092AA/09308
        lea.l   Torch_Anim(pc),a0               ; 092AE/0930C
        bra.b   Shot_StartCommon                ; 092B2/09310

;---------------------------------------------------------------------------
; size class 2
;---------------------------------------------------------------------------
Lance_Start:
        move.b  #$2,O_Size(a5)                  ; 092B4/09312
        lea.l   ShotSpeeds(pc),a1               ; 092BA/09318
        lea.l   Lance_Anim(pc),a0               ; 092BE/0931C
        bra.b   Shot_StartCommon                ; 092C2/09320
Axe_Start:
        clr.b   O_Size(a5)                      ; 092C4/09322
        lea.l   ShotSpeeds(pc),a1               ; 092C8/09326
        lea.l   Axe_Anim(pc),a0                 ; 092CC/0932A
        bra.b   Shot_StartCommon                ; 092D0/0932E
Cross_Start:
        clr.b   O_Size(a5)                      ; 092D2/09330
        lea.l   ShotSpeeds(pc),a1               ; 092D6/09334
        lea.l   Cross_Anim(pc),a0               ; 092DA/09338
        bra.b   Shot_StartCommon                ; 092DE/0933C
Dagger_Start:
        clr.b   O_Size(a5)                      ; 092E0/0933E
        lea.l   DaggerSpeeds(pc),a1             ; 092E4/09342
        lea.l   Dagger_Anim(pc),a0              ; 092E8/09346
        bra.b   Shot_StartCommon                ; 092EC/0934A
ArmourDebris_Start:
        clr.b   O_Size(a5)                      ; 092EE/0934C
        lea.l   ArmourDebrisSpeeds(pc),a1       ; 092F2/09350
        lea.l   Debris_Anim(pc),a0              ; 092F6/09354

;---------------------------------------------------------------------------
; Animation for the direction, move table, remember the start X, fly
;---------------------------------------------------------------------------
Shot_StartCommon:
        subq.l  #$2,a0                          ; 092FA/09358
        bsr.w   SetAnimIndexed                  ; 092FC/0935A
        move.l  a1,O_MoveTable(a5)              ; 09300/0935E
        move.w  O_X(a5),Shot_StartX(a5)         ; 09304/09362
        move.b  #$1,O_State(a5)                 ; 0930A/09368
        clr.b   O_Step(a5)                      ; 09310/0936E
        rts                                     ; 09314/09372

;---------------------------------------------------------------------------
; O_Step: 0 straight, 1 start the fall, 2 fall, 3 big flame, 4 small flame, 5 end
;---------------------------------------------------------------------------
Torch_Fly:
        bsr.w   CheckFarAway                    ; 09316/09374
        clr.w   d0                              ; 0931A/09378
        move.b  O_Step(a5),d0                   ; 0931C/0937A
        add.w   d0,d0                           ; 09320/0937E
        add.w   d0,d0                           ; 09322/09380
        jmp     Torch_Fly_Jumps(pc,d0.w)        ; 09324/09382
Torch_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09328/09386
        bra.w   Shot_StartFall                  ; 0932C/0938A
        bra.w   Torch_Fall                      ; 09330/0938E
        bra.w   snd112_go                       ;      /09392
        bra.w   Torch_BurnSmall                 ; 09338/09396
        bra.w   Torch_BurnEnd                   ; 0933C/0939A

;---------------------------------------------------------------------------
; vx 2.93, vy 1.01 px/frame
;---------------------------------------------------------------------------
Shot_StartFall:
        move.l  #$2ef00,Shot_VX(a5)             ; 09340/0939E
        move.l  #$10300,Shot_VY(a5)             ; 09348/093A6
        addq.b  #$1,O_Step(a5)                  ; 09350/093AE
        rts                                     ; 09354/093B2
Torch_Fall:
        bsr.b   ShotArcMove                     ; 09356/093B4
        bne.b   l_0935E                         ; 09358/093B6
        addq.b  #$1,O_Step(a5)                  ; 0935A/093B8
l_0935E:
        rts                                     ; 0935E/093BC

;---------------------------------------------------------------------------
; Ballistic fall (torch, axe): X += vx (slowing by $BA1 a frame to 0), Y -= vy
; (vy growing by $FF0 a frame up to 5 px). Ends with ObjectMapCollide: Z set = landed.
;---------------------------------------------------------------------------
ShotArcMove:
        move.l  Shot_VX(a5),d0                  ; 09360/093BE
        cmpi.b  #$1,O_Dir(a5)                   ; 09364/093C2
        beq.b   l_0936E                         ; 0936A/093C8
        neg.l   d0                              ; 0936C/093CA
l_0936E:
        add.l   d0,O_X(a5)                      ; 0936E/093CC
        move.l  Shot_VY(a5),d0                  ; 09372/093D0
        sub.l   d0,O_Y(a5)                      ; 09376/093D4
        subi.l  #$ba1,Shot_VX(a5)               ; 0937A/093D8
        bpl.b   l_09388                         ; 09382/093E0
        clr.l   Shot_VX(a5)                     ; 09384/093E2
l_09388:
        cmpi.l  #$50000,Shot_VY(a5)             ; 09388/093E6
        bcc.b   l_0939A                         ; 09390/093EE
        addi.l  #$ff0,Shot_VY(a5)               ; 09392/093F0
l_0939A:
        bsr.w   Animate                         ; 0939A/093F8
        bra.w   ObjectMapCollide                ; 0939E/093FC
snd112_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd112_512                      
        move    (a7)+,ccr                       
l1m_09400:
        moveq   #SFX_TORCH_FLAME,d0             ;      /09400  effect 11: the torch bursts into flame on the ground
        bsr.w   PlaySfx                         ;      /09402
        bra.w   snd112_end                      
snd112_512:
        move    (a7)+,ccr                       
snd112_end:

;---------------------------------------------------------------------------
; Landed: size class 3 flame for 32 frames
;---------------------------------------------------------------------------
Torch_Burn:
        move.b  #$3,d0                          ; 093A2/09406  [1MB build: extra sound effect $B played here]
        bsr.w   SetBoxClass                     ; 093A6/0940A
        lea.l   Torch_AnimBurn(pc),a0           ; 093AA/0940E
        bsr.w   SetAnim                         ; 093AE/09412
        move.b  #$20,O_Param(a5)                ; 093B2/09416
        addq.b  #$1,O_Step(a5)                  ; 093B8/0941C
        rts                                     ; 093BC/09420

;---------------------------------------------------------------------------
; then size class 0 for 32 frames
;---------------------------------------------------------------------------
Torch_BurnSmall:
        subq.b  #$1,O_Param(a5)                 ; 093BE/09422
        bne.w   Animate                         ; 093C2/09426
        move.b  #$0,d0                          ; 093C6/0942A
        bsr.w   SetBoxClass                     ; 093CA/0942E
        lea.l   Torch_AnimBurnSmall(pc),a0      ; 093CE/09432
        bsr.w   SetAnim                         ; 093D2/09436
        move.b  #$20,O_Param(a5)                ; 093D6/0943A
        addq.b  #$1,O_Step(a5)                  ; 093DC/09440
        rts                                     ; 093E0/09444
Torch_BurnEnd:
        subq.b  #$1,O_Param(a5)                 ; 093E2/09446
        bne.w   Animate                         ; 093E6/0944A
l_093EA:
        move.b  #$3,O_State(a5)                 ; 093EA/0944E
        clr.b   O_Step(a5)                      ; 093F0/09454
        rts                                     ; 093F4/09458
Lance_Fly:
        bsr.w   CheckFarAway                    ; 093F6/0945A
        clr.w   d0                              ; 093FA/0945E
        move.b  O_Step(a5),d0                   ; 093FC/09460
        add.w   d0,d0                           ; 09400/09464
        add.w   d0,d0                           ; 09402/09466
        jmp     Lance_Fly_Jumps(pc,d0.w)        ; 09404/09468
Lance_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09408/0946C
        bra.w   Shot_End                        ; 0940C/09470
Shot_End:
        move.b  #$2,O_State(a5)                 ; 09410/09474
        clr.b   O_Step(a5)                      ; 09416/0947A
        rts                                     ; 0941A/0947E

;---------------------------------------------------------------------------
; O_Step: 0 straight, 1 start the fall, 2 fall, 3 end
;---------------------------------------------------------------------------
Axe_Fly:
        clr.w   d0                              ; 0941C/09480
        move.b  O_Step(a5),d0                   ; 0941E/09482
        add.w   d0,d0                           ; 09422/09486
        add.w   d0,d0                           ; 09424/09488
        jmp     Axe_Fly_Jumps(pc,d0.w)          ; 09426/0948A
Axe_Fly_Jumps:
        bra.w   Shot_Straight                   ; 0942A/0948E
        bra.w   Shot_StartFall                  ; 0942E/09492
        bra.w   Axe_Fall                        ; 09432/09496
        bra.w   l_093EA                         ; 09436/0949A
Axe_Fall:
        bsr.w   ShotArcMove                     ; 0943A/0949E
        bne.b   l_09444                         ; 0943E/094A2
        addq.b  #$1,O_Step(a5)                  ; 09440/094A4
l_09444:
        rts                                     ; 09444/094A8

;---------------------------------------------------------------------------
; Cross and dagger: straight to their range
;---------------------------------------------------------------------------
Cross_Fly:
        clr.w   d0                              ; 09446/094AA
        move.b  O_Step(a5),d0                   ; 09448/094AC
        add.w   d0,d0                           ; 0944C/094B0
        add.w   d0,d0                           ; 0944E/094B2
        jmp     Cross_Fly_Jumps(pc,d0.w)        ; 09450/094B4
Cross_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09454/094B8
        bra.w   l_09460                         ; 09458/094BC
        bra.w   l_09466                         ; 0945C/094C0
l_09460:
        addq.b  #$1,O_Step(a5)                  ; 09460/094C4
        rts                                     ; 09464/094C8
l_09466:
        move.b  #$2,O_State(a5)                 ; 09466/094CA
        clr.b   O_Step(a5)                      ; 0946C/094D0
        rts                                     ; 09470/094D4
ArmourDebris_Fly:
        tst.b   O_Step(a5)                      ; 09472/094D6
        beq.b   Shot_Straight                   ; 09476/094DA
        bra.b   Shot_End                        ; 09478/094DC

;---------------------------------------------------------------------------
; Move; next step once ShotRanges[type] px from the start X
;---------------------------------------------------------------------------
Shot_Straight:
        bsr.w   ApplyMoveTable                  ; 0947A/094DE
        move.w  O_X(a5),d1                      ; 0947E/094E2
        sub.w   Shot_StartX(a5),d1              ; 09482/094E6
        clr.w   d0                              ; 09486/094EA
        move.b  O_Type(a5),d0                   ; 09488/094EC
        move.b  ShotRanges(pc,d0.w),d0          ; 0948C/094F0
        add.w   d0,d1                           ; 09490/094F4
        add.w   d0,d0                           ; 09492/094F6
        cmp.w   d0,d1                           ; 09494/094F8
        bcs.w   Animate                         ; 09496/094FA
        addq.b  #$1,O_Step(a5)                  ; 0949A/094FE
        rts                                     ; 0949E/09502

;---------------------------------------------------------------------------
; px before the next step: torch 48, lance 192, axe 48, cross 48, dagger 197, armour 38
;---------------------------------------------------------------------------
ShotRanges:
	dc.b	$30,$C0,$30,$30,$C5,$26

;---------------------------------------------------------------------------
; State 2. O_Step: 0 gone, 1-2 deflected, 3-4 hit
;---------------------------------------------------------------------------
Shot_Hit:
        move.b  O_Step(a5),d0                   ; 094A6/0950A
        ext.w   d0                              ; 094AA/0950E
        add.w   d0,d0                           ; 094AC/09510
        add.w   d0,d0                           ; 094AE/09512
        jmp     Shot_Hit_Jumps(pc,d0.w)         ; 094B0/09514
Shot_Hit_Jumps:
        bra.w   Shot_Gone                       ; 094B4/09518
        bra.w   Shot_Deflected                  ; 094B8/0951C
        bra.w   Shot_HitWait                    ; 094BC/09520
        bra.w   Shot_HitEnemy                   ; 094C0/09524
        bra.w   Shot_HitWait                    ; 094C4/09528
Shot_Gone:
        move.b  #$3,O_State(a5)                 ; 094C8/0952C
        rts                                     ; 094CE/09532

;---------------------------------------------------------------------------
; sound 10, 15 frames
;---------------------------------------------------------------------------
Shot_Deflected:
        clr.b   O_Size(a5)                      ; 094D0/09534
        lea.l   Shot_AnimDeflect(pc),a0         ; 094D4/09538
        bsr.w   SetAnim                         ; 094D8/0953C
        move.b  #$f,O_Param(a5)                 ; 094DC/09540
        moveq   #SFX_DEFLECT,d0                 ; 094E2/09546
        bsr.w   PlaySfx                         ; 094E4/09548
        addq.b  #$1,O_Step(a5)                  ; 094E8/0954C
        rts                                     ; 094EC/09550
Shot_HitWait:
        subq.b  #$1,O_Param(a5)                 ; 094EE/09552
        bne.w   Animate                         ; 094F2/09556
        bra.b   Shot_Gone                       ; 094F6/0955A

;---------------------------------------------------------------------------
; sound 12, 8 frames
;---------------------------------------------------------------------------
Shot_HitEnemy:
        clr.b   O_Size(a5)                      ; 094F8/0955C
        lea.l   Shot_AnimHit(pc),a0             ; 094FC/09560
        bsr.w   SetAnim                         ; 09500/09564
        move.b  #$8,O_Param(a5)                 ; 09504/09568
snd113_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd113_512                      
        move    (a7)+,ccr                       
        moveq   #SFX_HURT,d0                    ;      /0956E
        bra.w   snd113_end                      
snd113_512:
        move    (a7)+,ccr                       
        moveq   #SFX_ENEMY_HIT,d0               ; 0950A/     
snd113_end:
        bsr.w   PlaySfx                         ; 0950C/09570
        addq.b  #$1,O_Step(a5)                  ; 09510/09574
        rts                                     ; 09514/09578
Shot_Free:
        clr.b   (a5)                            ; 09516/0957A
        rts                                     ; 09518/0957C
Shot_AnimHit:
	AF	$19,4
	AL	$1A,127,Shot_AnimHit
Shot_AnimDeflect:
	AF	$10,5
	AF	$11,5
	AL	$12,127,Shot_AnimHit

;---------------------------------------------------------------------------
; Per enemy type, 8 bytes: x offset.w, width.w, y offset.w, height.w
;---------------------------------------------------------------------------
EnemyHitboxes:
	dc.w	12,24,16,32	; E_WOODYPIG
	dc.w	12,24,16,24	; E_CROW
	dc.w	12,24,10,20	; E_PETITEDEVIL
	dc.w	12,24,16,32	; E_FLYINGKNIGHT
	dc.w	12,24,8,16	; E_BLUEKILLER
	dc.w	10,20,13,26	; E_REDARREMER
	dc.w	16,32,16,32	; E_SATAN
	dc.w	12,24,13,26	; E_MAGICIAN
	dc.w	16,32,21,42	; E_UNICORN
	dc.w	12,24,12,24	; E_SKELETON
	dc.w	14,28,14,28	; E_BIGMAN
	dc.w	12,24,18,28	; E_ZOMBIE
	dc.w	12,24,10,20	; E_DRAGON
	dc.w	10,20,9,18	; E_ASTAROTH
	dc.w	12,24,8,16	; E_FIRE
	dc.w	12,24,8,16	; E_PRINCESS
	dc.w	12,24,8,16	; E_TYPE16
	dc.w	12,24,16,32	; E_PLANT
	dc.w	12,24,24,48	; E_FIREPILLAR

;---------------------------------------------------------------------------
; Per enemy type: bitmask of weapon types that can hurt it (bit n = weapon n). Astaroth: cross only; Fire: nothing.
;---------------------------------------------------------------------------
EnemyVulnerability:
	dc.b	%00011111	; E_WOODYPIG: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_CROW: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PETITEDEVIL: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FLYINGKNIGHT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BLUEKILLER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_REDARREMER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SATAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_MAGICIAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_UNICORN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SKELETON: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BIGMAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_ZOMBIE: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_DRAGON: torch, lance, axe, cross, dagger
	dc.b	%00001000	; E_ASTAROTH: cross
	dc.b	%00000000	; E_FIRE: nothing
	dc.b	%00011111	; E_PRINCESS: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_TYPE16: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PLANT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FIREPILLAR: torch, lance, axe, cross, dagger
	dc.b	31	; pad

;---------------------------------------------------------------------------
; EnemyHitByShot - test Arthur's shots against enemy a5.
; Hitbox from EnemyHitboxes; Astaroth (type 13) can only be hit within +-9 px of his
; centre line. If the weapon's bit is clear in EnemyVulnerability the shot bounces off.
; Otherwise O_HP is decremented; at 0 the enemy dies (state 2) and EnemyPoints is
; awarded. The CROSS (weapon 3) is not used up when it kills an enemy - it carries on.
;---------------------------------------------------------------------------
EnemyHitByShot:
        lea.l   EnemyVulnerability(pc),a1       ; 095D4/09638  weapon bitmask and hit box of this enemy type
        clr.w   d0                              ; 095D8/0963C
        move.b  O_Type(a5),d0                   ; 095DA/0963E
        adda.w  d0,a1                           ; 095DE/09642
        lea.l   EnemyHitboxes(pc),a0            ; 095E0/09644
