;---------------------------------------------------------------------------
; ShotsVsEnemyShots - Arthur's shots against enemy shots.
;  Without the cross only fire-pillar shots (type 5) collide, and only Arthur's shot is
;  stopped. With the cross every enemy shot except the frog spell (0) and Astaroth's (10)
;  collides, and both shots are destroyed.
;  BUG: the box pointer a0 is set once per enemy shot and advanced by each test, so after
;  a miss the next of Arthur's shots is tested against the following words of the table
;  (another type's box). With one shot on screen it makes no difference.
;---------------------------------------------------------------------------
ShotsVsEnemyShots:
        lea.l   g_EnemyShots(a6),a1             ; 09704/09768
        moveq   #$5,d7                          ; 09708/0976C
l_0970A:
        move.b  (a1),d0                         ; 0970A/0976E
        and.b   $1(a1),d0                       ; 0970C/09770
        beq.w   l_097A0                         ; 09710/09774
        moveq   #$0,d1                          ; 09714/09778  d1 = 0 no collision, 1 Arthur's shot stops, 2 both destroyed
        move.b  $1a(a1),d0                      ; 09716/0977A
        cmpi.w  #$3,g_Weapon(a6)                ; 0971A/0977E
        beq.b   l_0972C                         ; 09720/09784
        cmp.b   #$5,d0                          ; 09722/09786  not the cross: only fire-pillar shots
        bne.b   l_09738                         ; 09726/0978A
        moveq   #$1,d1                          ; 09728/0978C
        bra.b   l_09738                         ; 0972A/0978E
l_0972C:
        tst.b   d0                              ; 0972C/09790  cross: all but the frog spell and Astaroth's shots
        beq.b   l_09738                         ; 0972E/09792
        cmp.b   #$a,d0                          ; 09730/09794
        beq.b   l_09738                         ; 09734/09798
        moveq   #$2,d1                          ; 09736/0979A
l_09738:
        tst.b   d1                              ; 09738/0979C
        beq.b   l_097A0                         ; 0973A/0979E
        ext.w   d0                              ; 0973C/097A0  box for this enemy-shot type (a0 advances through it below)
        lsl.w   #$3,d0                          ; 0973E/097A2
        lea.l   EnemyShotBlockBoxes(pc,d0.w),a0 ; 09740/097A4
        lea.l   g_Shots(a6),a2                  ; 09744/097A8
        moveq   #$3,d6                          ; 09748/097AC
l_0974A:
        move.b  (a2),d0                         ; 0974A/097AE
        and.b   $1(a2),d0                       ; 0974C/097B0
        beq.b   l_09798                         ; 09750/097B4
        move.w  $6(a1),d0                       ; 09752/097B6  X test
        sub.w   $6(a2),d0                       ; 09756/097BA
        add.w   (a0)+,d0                        ; 0975A/097BE
        cmp.w   (a0)+,d0                        ; 0975C/097C0
        bhi.b   l_09798                         ; 0975E/097C2
        move.w  $a(a1),d0                       ; 09760/097C4  Y test
        sub.w   $a(a2),d0                       ; 09764/097C8
        add.w   (a0)+,d0                        ; 09768/097CC
        cmp.w   (a0)+,d0                        ; 0976A/097CE
        bhi.b   l_09798                         ; 0976C/097D0
        subq.b  #$1,d1                          ; 0976E/097D2
        beq.b   l_09784                         ; 09770/097D4
        move.b  #$2,(a1)                        ; 09772/097D6  cross: the enemy shot is destroyed too
        move.b  #$2,$3(a1)                      ; 09776/097DA
        clr.b   $4(a1)                          ; 0977C/097E0
        clr.b   $5(a1)                          ; 09780/097E4
l_09784:
        move.b  #$2,(a2)                        ; 09784/097E8  Arthur's shot: state 2, step 1
        move.b  #$2,$3(a2)                      ; 09788/097EC
        move.b  #$1,$4(a2)                      ; 0978E/097F2
        clr.b   $5(a2)                          ; 09794/097F8
l_09798:
        lea.l   $26(a2),a2                      ; 09798/097FC
        dbra    d6,l_0974A                      ; 0979C/09800
l_097A0:
        lea.l   $1c(a1),a1                      ; 097A0/09804
        dbra    d7,l_0970A                      ; 097A4/09808
        rts                                     ; 097A8/0980C

