        sub.w   $a(a2),d0                       ; 09888/098EC
        addq.w  #$8,d0                          ; 0988C/098F0
        cmp.w   #$c,d0                          ; 0988E/098F2
        bhi.b   l_098E8                         ; 09892/098F6
