;---------------------------------------------------------------------------
; UpdateSpecialObjs - 2 slots x $20: bonus prizes.
; Slot 0 (O_Type 0) is the prize carried by every 6th spawned enemy (UpdateSpawners): it rides
; on the enemy (O_MoveTable = the enemy's slot) and drops when the enemy is killed; if the
; enemy leaves instead, the prize goes with it. Slot 1 (O_Type 1) is called by an invisible
; trigger item and falls from above.
; O_State: 0 attach, 1 prize (O_Step 0 ride, 1 fall, 2 reveal, 3 wait to be touched),
; 2 collected (30 frames), 3 free.
; O_Param = what it is: 0 armour, 1-5 weapon (g_Weapon = param - 1), 6-11 the level's
; treasure (200 points on level 0, 400 elsewhere), 12 rare treasure (4000), 13-19 points:
; 200, 500, 800, 1000, 2000, 5000, 10000. Sound 28 when collected (not for weapons).
;---------------------------------------------------------------------------
UpdateSpecialObjs:
        lea.l   g_SpecialObjs(a6),a5            ; 098FA/0995E
        moveq   #$2,d7                          ; 098FE/09962
l_09900:
        tst.b   (a5)                            ; 09900/09964
        beq.b   l_09932                         ; 09902/09966
        move.b  d7,d0                           ; 09904/09968
        add.w   g_GameFrame(a6),d0              ; 09906/0996A
        andi.b  #$f,d0                          ; 0990A/0996E
        bne.b   l_09914                         ; 0990E/09972
        bsr.w   CheckOnScreen                   ; 09910/09974
l_09914:
        clr.w   d0                              ; 09914/09978
        move.b  O_State(a5),d0                  ; 09916/0997A
        add.w   d0,d0                           ; 0991A/0997E
        add.w   d0,d0                           ; 0991C/09980
        jsr     SpecialStateTable(pc,d0.w)      ; 0991E/09982
        tst.b   O_OnScreen(a5)                  ; 09922/09986
        beq.b   l_09932                         ; 09926/0998A
        tst.l   O_Anim(a5)                      ; 09928/0998C
        beq.b   l_09932                         ; 0992C/09990
        bsr.w   QueueObjectDraw                 ; 0992E/09992
l_09932:
        lea.l   $20(a5),a5                      ; 09932/09996
        subq.w  #$1,d7                          ; 09936/0999A
        bne.b   l_09900                         ; 09938/0999C
        rts                                     ; 0993A/0999E
SpecialStateTable:
        bra.w   Special_Attach                  ; 0993C/099A0
        bra.w   Special_Prize                   ; 09940/099A4
        bra.w   Special_Collected               ; 09944/099A8
        bra.w   Special_Free                    ; 09948/099AC

