        add.b   d7,d0                           ; 09C66/09CCA
        andi.b  #$3,d0                          ; 09C68/09CCC
        bne.b   l_09C72                         ; 09C6C/09CD0
        bsr.w   CheckOnScreen                   ; 09C6E/09CD2
l_09C72:
