        tst.b   O_OnScreen(a5)                  ; 09C80/09CE4
        beq.b   l_09C92                         ; 09C84/09CE8
        cmpi.b  #$1,O_State(a5)                 ; 09C86/09CEA
        bhi.b   l_09C92                         ; 09C8C/09CF0
        bsr.w   QueueEnemyShotDraw              ; 09C8E/09CF2
l_09C92:
        lea.l   $1c(a5),a5                      ; 09C92/09CF6
        dbra    d7,l_09C5E                      ; 09C96/09CFA
        rts                                     ; 09C9A/09CFE
