;---------------------------------------------------------------------------
; QueueExplosionDraw - a dying enemy's explosion. While the frame is below $1B the frame
; from EffectFrames ($1B4CC graphics) is queued as a grid of 16 x 16 tiles around the
; enemy, by size class: below 4 a 2 x 2 square, 4 a 3 x 3, above 4 a 4 x 4 (walked as a
; snake, each step moving the last position by 16 px). From frame $1B on (the final puff,
; EnemyDie_Anim) it is drawn once, as a normal object.
;---------------------------------------------------------------------------
QueueExplosionDraw:
        cmpi.b  #$1b,O_Frame(a5)                ; 09FBC/0A020  the final puff: one BOB
        bcc.w   QueueObjectDraw                 ; 09FC2/0A026
        lea.l   BoxSizeTable(pc),a1             ; 09FC6/0A02A  (BoxSizeTable is looked up but not used)
        clr.w   d0                              ; 09FCA/0A02E
        move.b  O_Size(a5),d0                   ; 09FCC/0A030
        add.w   d0,d0                           ; 09FD0/0A034
        adda.w  d0,a1                           ; 09FD2/0A036
        move.w  O_X(a5),d1                      ; 09FD4/0A038
        move.w  O_Y(a5),d2                      ; 09FD8/0A03C
        move.w  #$10,d3                         ; 09FDC/0A040  one 16 x 16 tile, centred on the enemy
        moveq   #$10,d4                         ; 09FE0/0A044
        move.w  d3,d0                           ; 09FE2/0A046
        lsr.w   #$1,d0                          ; 09FE4/0A048
        sub.w   d0,d1                           ; 09FE6/0A04A
        move.w  d4,d0                           ; 09FE8/0A04C
        lsr.w   #$1,d0                          ; 09FEA/0A04E
        sub.w   d0,d2                           ; 09FEC/0A050
        movea.l (ItemGfxPtr).l,a1              ; 09FEE/0A052  explosion graphics + this frame
        lea.l   EffectFrames(pc),a2             ; 09FF4/0A058
        move.b  O_Frame(a5),d0                  ; 09FF8/0A05C
        ext.w   d0                              ; 09FFC/0A060
        add.w   d0,d0                           ; 09FFE/0A062
        add.w   d0,d0                           ; 0A000/0A064
        adda.w  d0,a2                           ; 0A002/0A066
        adda.w  (a2),a1                         ; 0A004/0A068
        moveq   #$10,d0                         ; 0A006/0A06A  grid step 16 px
        cmpi.b  #$4,O_Size(a5)                  ; 0A008/0A06C  size class 4: 3 x 3; above: 4 x 4
        beq.b   l_0A054                         ; 0A00E/0A072
        bhi.w   l_0A0E4                         ; 0A010/0A074
        movea.l g_BlitListPtr(a6),a0            ; 0A014/0A078  2 x 2
        move.l  a1,-(a0)                        ; 0A018/0A07C
        movem.w d1-d4,-(a0)                     ; 0A01A/0A07E
