;---------------------------------------------------------------------------
; QueueEnemyDraw - queue enemy a5 for DrawBobs.
; Dying enemies (state 2) are drawn as an explosion (QueueExplosionDraw) during the step
; that shows it; removed ones (state 3) not at all. Position = O_X/O_Y less half the
; BoxSizeTable size; graphics = g_BobSets[type] (the Crow / bat uses the bat or red-crow
; set by O_Param) + the frame's offset from BobFrameDescs, whose entries are
; (offset.w, y adjust.b, height.b). The Unicorn (type 8) is two BOBs: body
; (48 x 32, frame / 8 + 8) and legs (48 x 16, frame & 7).
;---------------------------------------------------------------------------
QueueEnemyDraw:
        cmpi.b  #ST_KILLED,O_State(a5)          ; 0A1E4/0A248  dying: explosion; removed: nothing
        bcs.b   l_0A21A                         ; 0A1EA/0A24E
        bhi.b   l_0A218                         ; 0A1EC/0A250
        cmpi.b  #E_DRAGON,O_Type(a5)            ; 0A1EE/0A252  Dragon: during its steps 2 and 5
        bne.b   l_0A208                         ; 0A1F4/0A258
        cmpi.b  #$2,O_Step(a5)                  ; 0A1F6/0A25A
        beq.b   l_0A210                         ; 0A1FC/0A260
        cmpi.b  #$5,O_Step(a5)                  ; 0A1FE/0A262
        beq.b   l_0A210                         ; 0A204/0A268
        bra.b   l_0A218                         ; 0A206/0A26A
l_0A208:
        cmpi.b  #$1,O_Step(a5)                  ; 0A208/0A26C
        bne.b   l_0A218                         ; 0A20E/0A272
l_0A210:
        tst.b   O_Step2(a5)                     ; 0A210/0A274
        bne.w   QueueExplosionDraw              ; 0A214/0A278
l_0A218:
        rts                                     ; 0A218/0A27C
l_0A21A:
        cmpi.b  #E_UNICORN,O_Type(a5)           ; 0A21A/0A27E  Unicorn: two BOBs
        beq.w   l_0A2B6                         ; 0A220/0A284
        lea.l   BoxSizeTable(pc),a1             ; 0A224/0A288  box size: the BOB is centred on O_X / O_Y
        moveq   #$0,d0                          ; 0A228/0A28C
        move.b  O_Size(a5),d0                   ; 0A22A/0A28E
        add.w   d0,d0                           ; 0A22E/0A292
        adda.w  d0,a1                           ; 0A230/0A294
        clr.w   d3                              ; 0A232/0A296
        clr.w   d4                              ; 0A234/0A298
        move.w  O_X(a5),d1                      ; 0A236/0A29A
        move.w  O_Y(a5),d2                      ; 0A23A/0A29E
        move.b  (a1)+,d3                        ; 0A23E/0A2A2
        move.b  (a1)+,d4                        ; 0A240/0A2A4
        move.w  d3,d0                           ; 0A242/0A2A6
        lsr.w   #$1,d0                          ; 0A244/0A2A8
        sub.w   d0,d1                           ; 0A246/0A2AA
        move.w  d4,d0                           ; 0A248/0A2AC
        lsr.w   #$1,d0                          ; 0A24A/0A2AE
        sub.w   d0,d2                           ; 0A24C/0A2B0
        move.b  O_Type(a5),d0                   ; 0A24E/0A2B2  Crow / bat: param < 3 bat graphics, 3 red crow
        cmp.b   #$1,d0                          ; 0A252/0A2B6
        bne.b   l_0A276                         ; 0A256/0A2BA
        cmpi.b  #$3,O_Param(a5)                 ; 0A258/0A2BC
        bcs.b   l_0A26C                         ; 0A25E/0A2C2
        bne.b   l_0A276                         ; 0A260/0A2C4
        movea.l g_BobSets+80(a6),a1             ; 0A262/0A2C6
        lea.l   BobFrameDescsRedCrow(pc),a2     ; 0A266/0A2CA
        bra.b   l_0A28A                         ; 0A26A/0A2CE
l_0A26C:
        movea.l g_BobSets+76(a6),a1             ; 0A26C/0A2D0
        lea.l   BobFrameDescsBat(pc),a2         ; 0A270/0A2D4
        bra.b   l_0A28A                         ; 0A274/0A2D8
l_0A276:
        add.w   d0,d0                           ; 0A276/0A2DA  graphics set of this enemy type, frame table of the type
        lea.l   g_BobSets(a6),a1                ; 0A278/0A2DC
        adda.w  d0,a1                           ; 0A27C/0A2E0
        adda.w  d0,a1                           ; 0A27E/0A2E2
        movea.l (a1),a1                         ; 0A280/0A2E4
        lea.l   BobFrameDescs(pc),a2            ; 0A282/0A2E6
        adda.w  d0,a2                           ; 0A286/0A2EA
        adda.w  (a2),a2                         ; 0A288/0A2EC
l_0A28A:
        move.b  O_Frame(a5),d0                  ; 0A28A/0A2EE  frame entry: offset.w, y adjust.b, height.b
        ext.w   d0                              ; 0A28E/0A2F2
