        rts                                     ; 0A612/0A676
Item_BlockPush:
        clr.b   O_HP(a5)                        ; 0A614/0A678
        move.w  O_Y(a5),d0                      ; 0A618/0A67C
        sub.w   g_ArthurY(a6),d0                ; 0A61C/0A680
        addi.w  #$10,d0                         ; 0A620/0A684
        cmp.w   #$20,d0                         ; 0A624/0A688
        bhi.b   l_0A5C0                         ; 0A628/0A68C
        move.w  O_X(a5),d0                      ; 0A62A/0A68E
        sub.w   g_ArthurX(a6),d0                ; 0A62E/0A692
        addi.w  #$20,d0                         ; 0A632/0A696
        cmp.w   #$40,d0                         ; 0A636/0A69A
        bhi.b   l_0A5C0                         ; 0A63A/0A69E
        move.w  d0,d1                           ; 0A63C/0A6A0
        cmp.w   #$20,d0                         ; 0A63E/0A6A2
        bcs.b   l_0A658                         ; 0A642/0A6A6
        neg.w   d1                              ; 0A644/0A6A8
        addi.w  #$40,d1                         ; 0A646/0A6AA
        cmp.w   #$5,d1                          ; 0A64A/0A6AE
        bhi.b   l_0A652                         ; 0A64E/0A6B2
        moveq   #$4,d1                          ; 0A650/0A6B4
l_0A652:
