        bhi.b   l_0A660                         ; 0A65C/0A6C0
        moveq   #$4,d1                          ; 0A65E/0A6C2
l_0A660:
        add.w   d1,g_ArthurX(a6)                ; 0A660/0A6C4
        rts                                     ; 0A664/0A6C8

;---------------------------------------------------------------------------
; O_Anim = step table, O_MoveTable = script for the type and param
;---------------------------------------------------------------------------
Item_PathStart:
        lea.l   ItemPaths(pc),a0                ; 0A666/0A6CA
        clr.w   d0                              ; 0A66A/0A6CE
        move.b  O_Type(a5),d0                   ; 0A66C/0A6D0
        add.w   d0,d0                           ; 0A670/0A6D4
        adda.w  d0,a0                           ; 0A672/0A6D6
        adda.w  (a0),a0                         ; 0A674/0A6D8
        move.b  O_Param(a5),d0                  ; 0A676/0A6DA
        add.w   d0,d0                           ; 0A67A/0A6DE
        adda.w  d0,a0                           ; 0A67C/0A6E0
        adda.w  (a0),a0                         ; 0A67E/0A6E2
        move.l  a0,O_Anim(a5)                   ; 0A680/0A6E4
        clr.b   O_AnimTimer(a5)                 ; 0A684/0A6E8
        clr.b   O_Step(a5)                      ; 0A688/0A6EC
        lea.l   ItemPathScripts(pc),a0          ; 0A68C/0A6F0
        move.b  O_Type(a5),d0                   ; 0A690/0A6F4
        add.w   d0,d0                           ; 0A694/0A6F8
        adda.w  d0,a0                           ; 0A696/0A6FA
        adda.w  (a0),a0                         ; 0A698/0A6FC
        move.b  O_Param(a5),d0                  ; 0A69A/0A6FE
        add.w   d0,d0                           ; 0A69E/0A702
        adda.w  d0,a0                           ; 0A6A0/0A704
        adda.w  (a0),a0                         ; 0A6A2/0A706
        move.l  a0,O_MoveTable(a5)              ; 0A6A4/0A708
        move.b  #$1,O_State(a5)                 ; 0A6A8/0A70C
        rts                                     ; 0A6AE/0A712

;---------------------------------------------------------------------------
; Next (step, frames) pair from the script; bit 7 = loop
;---------------------------------------------------------------------------
Item_PathScript:
        tst.b   O_AnimTimer(a5)                 ; 0A6B0/0A714
        bne.b   Item_PathMove                   ; 0A6B4/0A718
        movea.l O_MoveTable(a5),a0              ; 0A6B6/0A71A
        move.b  (a0)+,O_Step(a5)                ; 0A6BA/0A71E
        move.b  (a0)+,d0                        ; 0A6BE/0A722
        bpl.b   l_0A6C8                         ; 0A6C0/0A724
        andi.b  #$7f,d0                         ; 0A6C2/0A726
        adda.w  (a0),a0                         ; 0A6C6/0A72A
l_0A6C8:
