        move.l  a0,O_MoveTable(a5)              ; 0A6CC/0A730
        rts                                     ; 0A6D0/0A734

;---------------------------------------------------------------------------
; Move by the step's (dx, dy); carry Arthur if he is on it
;---------------------------------------------------------------------------
Item_PathMove:
