        clr.w   d0                              ; 0A6D6/0A73A
        move.b  O_Step(a5),d0                   ; 0A6D8/0A73C
        add.w   d0,d0                           ; 0A6DC/0A740
        add.w   d0,d0                           ; 0A6DE/0A742
        adda.w  d0,a0                           ; 0A6E0/0A744
        subq.b  #$1,O_AnimTimer(a5)             ; 0A6E2/0A746
        move.w  (a0)+,d0                        ; 0A6E6/0A74A
        ext.l   d0                              ; 0A6E8/0A74C
        asl.l   #$8,d0                          ; 0A6EA/0A74E
        add.l   d0,O_X(a5)                      ; 0A6EC/0A750
        move.w  (a0)+,d1                        ; 0A6F0/0A754
        ext.l   d1                              ; 0A6F2/0A756
        asl.l   #$8,d1                          ; 0A6F4/0A758
