        move.b  (a1,d0.w),d0                    ; 0A926/0A98A
        lea.l   BoxSizeTable(pc),a1             ; 0A92A/0A98E
        add.w   d0,d0                           ; 0A92E/0A992
        adda.w  d0,a1                           ; 0A930/0A994
        clr.w   d3                              ; 0A932/0A996
        clr.w   d4                              ; 0A934/0A998
        move.b  (a1)+,d3                        ; 0A936/0A99A
        move.b  (a1)+,d4                        ; 0A938/0A99C
        move.w  O_X(a5),d1                      ; 0A93A/0A99E
        move.w  d3,d0                           ; 0A93E/0A9A2
        lsr.w   #$1,d0                          ; 0A940/0A9A4
        sub.w   d0,d1                           ; 0A942/0A9A6
        move.w  O_Y(a5),d2                      ; 0A944/0A9A8
        move.w  d4,d0                           ; 0A948/0A9AC
        lsr.w   #$1,d0                          ; 0A94A/0A9AE
        sub.w   d0,d2                           ; 0A94C/0A9B0
        lea.l   ItemImageTable(pc),a1           ; 0A94E/0A9B2
        move.b  O_Type(a5),d0                   ; 0A952/0A9B6
        add.w   d0,d0                           ; 0A956/0A9BA
        adda.w  d0,a1                           ; 0A958/0A9BC
        adda.w  (a1),a1                         ; 0A95A/0A9BE
        move.b  O_Param(a5),d0                  ; 0A95C/0A9C0
        adda.w  d0,a1                           ; 0A960/0A9C4
        move.b  (a1),d0                         ; 0A962/0A9C6
        bmi.b   l_0A990                         ; 0A964/0A9C8
        lea.l   g_SmallBobSets(a6),a1           ; 0A966/0A9CA
        add.w   d0,d0                           ; 0A96A/0A9CE
        add.w   d0,d0                           ; 0A96C/0A9D0
        adda.w  d0,a1                           ; 0A96E/0A9D2
        movea.l (a1),a1                         ; 0A970/0A9D4
        lsr.w   #$1,d0                          ; 0A972/0A9D6
        lea.l   SmallBobSizes(pc,d0.w),a2       ; 0A974/0A9D8
        add.w   d4,d2                           ; 0A978/0A9DC
        move.b  (a2)+,d0                        ; 0A97A/0A9DE
        sub.w   d0,d2                           ; 0A97C/0A9E0
        move.b  (a2)+,d4                        ; 0A97E/0A9E2
        sub.w   d4,d2                           ; 0A980/0A9E4
        movea.l g_BlitListPtr(a6),a0            ; 0A982/0A9E6
        move.l  a1,-(a0)                        ; 0A986/0A9EA
        movem.w d1-d4,-(a0)                     ; 0A988/0A9EC
        move.l  a0,g_BlitListPtr(a6)            ; 0A98C/0A9F0
l_0A990:
