;---------------------------------------------------------------------------
; y-adjust.b, height.b for each of the 10 small BOB images
;---------------------------------------------------------------------------
SmallBobSizes:
	dc.b	$03,$0D,$01,$0F,$00,$10,$00,$10,$0C,$14,$0C,$14,$0C,$14,$0B,$15
	dc.b	$02,$0E,$00,$0A

;---------------------------------------------------------------------------
; Enemy spawners (16 slots x $C at g_Spawners, slot = enemy type).
; Slot: +0 active, +1 entries left, +2 script pointer, +6 script start, +$A frames to the
; next spawn, +$B flags (bit 0 world coords, bit 1 run once, bit 2 new zones only).
; Script (SpawnScripts): count.w, then per entry x.w, y.w (camera-relative unless flag
; bit 0), param.b, delay.b. A spawn needs a free enemy slot and g_SpawnQuota[type] > 0.
; Type 7 (the Magician) appears at the last shootable scenery hit instead; zombies 128 px further
; right. Every 6th spawned enemy carries a bonus (special object 0) - see BonusKinds.
;---------------------------------------------------------------------------
UpdateSpawners:
        lea.l   g_Spawners(a6),a2               ; 0A9A6/0AA0A  a2 = spawner slot ($C bytes), d7 = its enemy type
        clr.w   d7                              ; 0A9AA/0AA0E
l_0A9AC:
        tst.b   (a2)                            ; 0A9AC/0AA10
        beq.w   l_0AADC                         ; 0A9AE/0AA12
        tst.b   $1(a2)                          ; 0A9B2/0AA16  entries left?
        bhi.b   l_0A9E8                         ; 0A9B6/0AA1A
        btst    #$1,$b(a2)                      ; 0A9B8/0AA1C  script finished: a 'run once' spawner stops, the others start again
        seq.b   (a2)                            ; 0A9BE/0AA22
        bne.w   l_0AADC                         ; 0A9C0/0AA24
        bra.b   l_0A9DA                         ; 0A9C4/0AA28
        tst.b   G_SHIFT+$19(a2)                 ; 0A9C6/0AA2A  (never reached: nothing branches here)
        beq.b   l_0A9DA                         ; 0A9CA/0AA2E
        btst    #$2,$b(a2)                      ; 0A9CC/0AA30
        bne.b   l_0A9DA                         ; 0A9D2/0AA36
        clr.b   (a2)                            ; 0A9D4/0AA38
        bra.w   l_0AADC                         ; 0A9D6/0AA3A
l_0A9DA:
        movea.l $6(a2),a1                       ; 0A9DA/0AA3E  restart the script: count and first entry
        move.w  (a1)+,d0                        ; 0A9DE/0AA42
        move.b  d0,$1(a2)                       ; 0A9E0/0AA44
