;---------------------------------------------------------------------------
; Kind of bonus for the next carrier, cycling 0-6: treasure, treasure, weapon,
; treasure, kind 13, treasure, weapon. Treasure = 6 + level (kind 12 when g_BonusRoll
; carries); weapon = 1 + weapon number, picked by adding the level's weights (WeaponOddsTable) to
; the five g_WeaponOdds accumulators: the first that carries and is not Arthur's weapon.
;---------------------------------------------------------------------------
BonusKinds:
        bra.w   l_0AB08                         ; 0AAEC/0AB50
        bra.w   l_0AB08                         ; 0AAF0/0AB54
        bra.w   l_0AB1A                         ; 0AAF4/0AB58
        bra.w   l_0AB08                         ; 0AAF8/0AB5C
        bra.w   l_0AB54                         ; 0AAFC/0AB60
        bra.w   l_0AB08                         ; 0AB00/0AB64
        bra.w   l_0AB1A                         ; 0AB04/0AB68
l_0AB08:
        moveq   #$c,d0                          ; 0AB08/0AB6C  treasure: 6 + level, or kind 12 when g_BonusRoll carries (+21 a time)
        addi.b  #$15,g_BonusRoll(a6)            ; 0AB0A/0AB6E
        bcs.b   l_0AB18                         ; 0AB10/0AB74
        moveq   #$6,d0                          ; 0AB12/0AB76
        add.w   g_Level(a6),d0                  ; 0AB14/0AB78
l_0AB18:
        rts                                     ; 0AB18/0AB7C
l_0AB1A:
        move.w  g_Level(a6),d0                  ; 0AB1A/0AB7E  weapon: add the level's weights to the five g_WeaponOdds accumulators
        add.w   d0,d0                           ; 0AB1E/0AB82
        lea.l   WeaponOddsTable(pc,d0.w),a0     ; 0AB20/0AB84
        adda.w  (a0),a0                         ; 0AB24/0AB88
        addq.l  #$5,a0                          ; 0AB26/0AB8A
        lea.l   g_BossCountdown(a6),a3          ; 0AB28/0AB8C
        clr.b   d1                              ; 0AB2C/0AB90
        moveq   #$4,d6                          ; 0AB2E/0AB92
l_0AB30:
        move.b  -(a0),d0                        ; 0AB30/0AB94
        add.b   d0,-(a3)                        ; 0AB32/0AB96
        addx.b  d1,d1                           ; 0AB34/0AB98
        dbra    d6,l_0AB30                      ; 0AB36/0AB9A
        moveq   #$0,d0                          ; 0AB3A/0AB9E
l_0AB3C:
        btst    d0,d1                           ; 0AB3C/0ABA0  the first weapon whose accumulator carried ...
        bne.b   l_0AB4A                         ; 0AB3E/0ABA2
        addq.w  #$1,d0                          ; 0AB40/0ABA4
        cmp.w   #$5,d0                          ; 0AB42/0ABA6
        bne.b   l_0AB3C                         ; 0AB46/0ABAA
        bra.b   l_0AB1A                         ; 0AB48/0ABAC
l_0AB4A:
