        beq.b   l_0AB1A                         ; 0AB4E/0ABB2
        addq.b  #$1,d0                          ; 0AB50/0ABB4
        rts                                     ; 0AB52/0ABB6
l_0AB54:
        moveq   #$d,d0                          ; 0AB54/0ABB8
        add.w   g_Level(a6),d0                  ; 0AB56/0ABBA
        rts                                     ; 0AB5A/0ABBE

