        asl.l   #$8,d0                          ; 0AD9C/0AE00
        add.l   d0,O_Y(a5)                      ; 0AD9E/0AE02
        rts                                     ; 0ADA2/0AE06

;---------------------------------------------------------------------------
; Out: d0 = 16-way direction from object a5 to Arthur: 0 right, 4 down, 8 left,
; 12 up (clockwise on screen). Picks one of five 4-entry tables (one entry per quadrant)
; by the slope |dy|/|dx|. Data bug: the 45-degree table gives 5 instead of 6 for
; 'left and below'.
;---------------------------------------------------------------------------
DirectionToArthur:
        movem.l d1-d3/a0,-(a7)                  ; 0ADA4/0AE08
        clr.w   d0                              ; 0ADA8/0AE0C
        move.w  g_ArthurX(a6),d1                ; 0ADAA/0AE0E
        sub.w   O_X(a5),d1                      ; 0ADAE/0AE12
        bpl.b   l_0ADB8                         ; 0ADB2/0AE16
        neg.w   d1                              ; 0ADB4/0AE18
        addq.w  #$1,d0                          ; 0ADB6/0AE1A
l_0ADB8:
        move.w  g_ArthurY(a6),d2                ; 0ADB8/0AE1C
        sub.w   O_Y(a5),d2                      ; 0ADBC/0AE20
        bpl.b   l_0ADC6                         ; 0ADC0/0AE24
        neg.w   d2                              ; 0ADC2/0AE26
        addq.w  #$2,d0                          ; 0ADC4/0AE28
l_0ADC6:
        tst.w   d1                              ; 0ADC6/0AE2A
        bne.b   l_0ADD0                         ; 0ADC8/0AE2C
        move.w  #$ff,d2                         ; 0ADCA/0AE2E
        bra.b   l_0ADD4                         ; 0ADCE/0AE32
l_0ADD0:
        ext.l   d2                              ; 0ADD0/0AE34
        divu.w  d1,d2                           ; 0ADD2/0AE36
l_0ADD4:
        move.l  d2,d3                           ; 0ADD4/0AE38
        swap    d3                              ; 0ADD6/0AE3A
        mulu.w  #$64,d2                         ; 0ADD8/0AE3C
        lea.l   DirTabSteep(pc),a0              ; 0ADDC/0AE40
        cmp.w   #$258,d2                        ; 0ADE0/0AE44
        bcc.b   l_0AE08                         ; 0ADE4/0AE48
        lea.l   DirTab60(pc),a0                 ; 0ADE6/0AE4A
        cmp.w   #$96,d2                         ; 0ADEA/0AE4E
        bcc.b   l_0AE08                         ; 0ADEE/0AE52
        lea.l   DirTab45(pc),a0                 ; 0ADF0/0AE54
        cmp.w   #$4b,d2                         ; 0ADF4/0AE58
        bcc.b   l_0AE08                         ; 0ADF8/0AE5C
        lea.l   DirTabFlat(pc),a0               ; 0ADFA/0AE5E
        lsr.w   #$2,d1                          ; 0ADFE/0AE62
        cmp.w   d3,d1                           ; 0AE00/0AE64
        bhi.b   l_0AE08                         ; 0AE02/0AE66
        lea.l   DirTabLow(pc),a0                ; 0AE04/0AE68
l_0AE08:
        move.b  (a0,d0.w),d0                    ; 0AE08/0AE6C
        movem.l (a7)+,d1-d3/a0                  ; 0AE0C/0AE70
        rts                                     ; 0AE10/0AE74

;---------------------------------------------------------------------------
; DirectionToArthur results (0 right, 4 down, 8 left, 12 up) by quadrant: Arthur
; right-above, left-above, right-below, left-below. One table per slope band |dy|/|dx|:
; the slope is taken as the integer quotient q = |dy| div |dx|: Steep q >= 6, 60 2 <= q < 6,
; 45 q = 1, and for q = 0 Low when |dy| >= |dx| / 4, else Flat (checked in the emulator).
; The code's x100 thresholds (75, 150, 600) only see whole quotients, so the 1.5 step never
; happens.
;---------------------------------------------------------------------------
DirTabLow:
	dc.b	$0F,$09,$01,$07
DirTabFlat:
	dc.b	$00,$08,$00,$08
DirTab60:
	dc.b	$0D,$0B,$03,$05
DirTabSteep:
	dc.b	$0C,$0C,$04,$04

;---------------------------------------------------------------------------
; 45-degree band: the last entry is 5 where 6 is expected (the data bug)
;---------------------------------------------------------------------------
DirTab45:
	dc.b	$0E,$0A,$02,$05

;---------------------------------------------------------------------------
; Out: d0.b = pseudo-random byte (shift register in g_RandSeed)
;---------------------------------------------------------------------------
Random:
        move.w  d1,-(a7)                        ; 0AE26/0AE8A
        move.b  g_RandSeed+1(a6),d0             ; 0AE28/0AE8C
        move.b  g_RandSeed(a6),d1               ; 0AE2C/0AE90
        eor.b   d1,d0                           ; 0AE30/0AE94
        not.b   d0                              ; 0AE32/0AE96
        lsl.b   #$2,d0                          ; 0AE34/0AE98
        rol.w   g_RandSeed(a6)                  ; 0AE36/0AE9A
        move.w  (a7)+,d1                        ; 0AE3A/0AE9E
        move.b  g_RandSeed+1(a6),d0             ; 0AE3C/0AEA0
        rts                                     ; 0AE40/0AEA4

;---------------------------------------------------------------------------
; BCD score values indexed by AddScore
;---------------------------------------------------------------------------
ScoreValues:
	dc.l	$00000010	;  1: 10
	dc.l	$00000050	;  2: 50
	dc.l	$00000100	;  3: 100
	dc.l	$00000200	;  4: 200
	dc.l	$00000300	;  5: 300
	dc.l	$00000400	;  6: 400
	dc.l	$00000500	;  7: 500
	dc.l	$00000800	;  8: 800
	dc.l	$00001000	;  9: 1000
	dc.l	$00002000	; 10: 2000
	dc.l	$00003000	; 11: 3000
	dc.l	$00004000	; 12: 4000
	dc.l	$00005000	; 13: 5000
	dc.l	$00006000	; 14: 6000
	dc.l	$00007000	; 15: 7000
	dc.l	$FFFF8000	; 16: not valid BCD - no index uses it
	dc.l	$FFFF9000	; 17: not valid BCD - no index uses it
	dc.l	$00010000	; 18: 10000
	dc.l	$00020000	; 19: 20000
	dc.l	$00030000	; 20: 30000
	dc.l	$00050000	; 21: 50000
	dc.l	$00100000	; 22: 100000
	dc.l	$00015000	; 23: 15000

;---------------------------------------------------------------------------
; AddScore - d0 = index i: adds the BCD long at ScoreValues + 4*(i-1) to g_Score
; (the routine pre-decrements from the end of entry i). E.g. 13 = 5000, 18 = 10000.
;---------------------------------------------------------------------------
AddScore:
        add.w   d0,d0                           ; 0AE9E/0AF02
        add.w   d0,d0                           ; 0AEA0/0AF04
        lea.l   ScoreValues(pc,d0.w),a0         ; 0AEA2/0AF06
        lea.l   g_NextExtraLife(a6),a1          ; 0AEA6/0AF0A
        abcd.b  -(a0),-(a1)                     ; 0AEAA/0AF0E
        abcd.b  -(a0),-(a1)                     ; 0AEAC/0AF10
        abcd.b  -(a0),-(a1)                     ; 0AEAE/0AF12
        abcd.b  -(a0),-(a1)                     ; 0AEB0/0AF14
        rts                                     ; 0AEB2/0AF16

