        addq.l  #$2,a2                          ; 0AEE6/0AF4A
        move.b  (a0)+,d0                        ; 0AEE8/0AF4C
        clr.b   (a3)                            ; 0AEEA/0AF4E
        or.b    d0,(a3)                         ; 0AEEC/0AF50
        addq.l  #$2,a3                          ; 0AEEE/0AF52
        move.b  (a1)+,d0                        ; 0AEF0/0AF54
        clr.b   (a4)                            ; 0AEF2/0AF56
        or.b    d0,(a4)                         ; 0AEF4/0AF58
        addq.l  #$2,a4                          ; 0AEF6/0AF5A
        move.b  (a1)+,d0                        ; 0AEF8/0AF5C
        clr.b   (a5)                            ; 0AEFA/0AF5E
        or.b    d0,(a5)                         ; 0AEFC/0AF60
        addq.l  #$2,a5                          ; 0AEFE/0AF62
        move.b  (a0)+,d0                        ; 0AF00/0AF64
        clr.b   (a2)                            ; 0AF02/0AF66
        or.b    d0,(a2)                         ; 0AF04/0AF68
        addq.l  #$2,a2                          ; 0AF06/0AF6A
        move.b  (a0)+,d0                        ; 0AF08/0AF6C
        clr.b   (a3)                            ; 0AF0A/0AF6E
        or.b    d0,(a3)                         ; 0AF0C/0AF70
        addq.l  #$2,a3                          ; 0AF0E/0AF72
        move.b  (a1)+,d0                        ; 0AF10/0AF74
        clr.b   (a4)                            ; 0AF12/0AF76
        or.b    d0,(a4)                         ; 0AF14/0AF78
        addq.l  #$2,a4                          ; 0AF16/0AF7A
        move.b  (a1)+,d0                        ; 0AF18/0AF7C
        clr.b   (a5)                            ; 0AF1A/0AF7E
        or.b    d0,(a5)                         ; 0AF1C/0AF80
