        rts                                     ; 0AF72/0AFDA
;---------------------------------------------------------------------------
; DrawLives - the lives digit in the HUD (sprites 6 / 7): g_Lives - 1, at most 7; blank when 0
;---------------------------------------------------------------------------
DrawLives:
        move.b  g_Lives(a6),d0                  ; 0AF74/0AFDC
        subq.b  #$1,d0                          ; 0AF78/0AFE0
        bpl.b   l_0AF80                         ; 0AF7A/0AFE2
