        lea.l   (SPRITE6B_DATA+$25).l,a1        ; 0AFC6/0B02E
        lea.l   (SPRITE7B_DATA+$25).l,a2        ; 0AFCC/0B034
        bra.w   HudDigit                        ; 0AFD2/0B03A

;---------------------------------------------------------------------------
