        cmp.w   #$20,d2                         ; 0B0C6/0B132
        scc.b   d7                              ; 0B0CA/0B136
        bcc.b   l_0B0D6                         ; 0B0CC/0B138
        lea.l   (CLEAR_AREA).l,a1               ; 0B0CE/0B13A
        bra.b   l_0B0E2                         ; 0B0D4/0B140
l_0B0D6:
