; NameGridLetters - the 65 cells of the name-entry grid: A-Z, a-z, ! ? & , . ( ) / : * @,
; then the rub-out ($1E) and END ($1F) glyphs. Cell 62 ('@') enters a space.
;---------------------------------------------------------------------------
NameGridLetters:
	dc.b	'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!?&,.()/:*@'
	dc.b	$1E,$1F
TxtInitial:
	dc.b	'INITIAL'
	dc.b	$00,$00

;---------------------------------------------------------------------------
; RestoreBackground - undo last time's BOBs in this buffer: copy each saved rectangle
; back (A->D blits) from the restore list, then reset the list
;---------------------------------------------------------------------------
RestoreBackground:
        jmp     EnhRestoreBackground            ; the scroller
; (RestoreBackground: the rest of the original routine removed - the scroller does it)


;---------------------------------------------------------------------------
; DrawBobs - draw this frame's BOB list. The Queue*Draw routines push 12-byte entries
; (x.w, y.w, width.w, height.w, graphics.l) downwards from g_SaveBufA's address in the
; globals; this walks them from g_BlitListPtr back up, so the last queued is drawn first
; and the first queued ends up on top. g_SavePtr restarts at g_SaveBufA.
;---------------------------------------------------------------------------
DrawBobs:
        jmp     EnhDrawBobs                     ; the scroller
; (DrawBobs: the rest of the original routine removed - the scroller does it)


; (DrawBob: the original's, unused with the scroller - removed)


; (WaitBlitIRQ: the original's, unused with the scroller - removed)


;---------------------------------------------------------------------------
;---------------------------------------------------------------------------
; PlayMusic - d0 = tune number (see sound/SOUND.md): calls the sound driver through
; vector $60 with command 1 (d0.l = tune<<16 | 1). Only with the music package (PF_MUSIC);
; the callers choose by profile, this is a safety net.
;---------------------------------------------------------------------------
PlayMusic:
        btst    #PF_MUSIC,(Profile).l           
        beq.b   pmu_none                        
        move.l  a1,-(a7)                        
        swap    d0                              
        addq.w  #$1,d0                          
        movea.l (VEC_SPURIOUS).w,a1             
        jsr     (a1)                            
        movea.l (a7)+,a1                        
pmu_none:
        rts                                     

; (DrawBobMasked: the original's, unused with the scroller - removed)


;---------------------------------------------------------------------------
; Unreferenced
;---------------------------------------------------------------------------
; PlaySfx - d0 = effect number (0-29). Calls the sound driver through vector $60
; with command 2 (d0.l = number<<16 | 2). Driver source: sound/gng_sfx_512k.s.
; Effects used here: 1 hit, 4 jump, 5 land, 6 throw, 10/12 weapon hits,
; 17/20 enemy events, 28 key or item collected.
; [1MB] with command 2 (d0.l = number<<16 | 2). Driver source: sound/gng_music_1mb.s.
;---------------------------------------------------------------------------
PlaySfx:
        move.l  a1,-(a7)                        ; 0BCC8/0BC58
        swap    d0                              ; 0BCCA/0BC5A
        addq.w  #$2,d0                          ; 0BCCC/0BC5C
        movea.l (VEC_SPURIOUS).w,a1             ; 0BCCE/0BC5E
        jsr     (a1)                            ; 0BCD2/0BC62
        movea.l (a7)+,a1                        ; 0BCD4/0BC64
        rts                                     ; 0BCD6/0BC66

;---------------------------------------------------------------------------
; Level 2 (PORTS) - CIA-A serial keyboard.
; Reads SDR, handshakes via CRA SPMODE for ~85us, decodes the raw
; keycode (NOT + ROR 1); key-down codes go to g_RawKey and the ASCII
; equivalent from KeyAsciiTable to g_AsciiKey.
;---------------------------------------------------------------------------
KeyboardIRQ:
        movem.l d0-d1/a0,-(a7)                  ; 0BCD8/0BC68
        lea.l   CUSTOM,a0                       ; 0BCDC/0BC6C
        move.w  INTREQR(a0),d0                  ; 0BCE2/0BC72
        and.w   INTENAR(a0),d0                  ; 0BCE6/0BC76
        andi.w  #$8,d0                          ; 0BCEA/0BC7A
        move.w  d0,INTREQ(a0)                   ; 0BCEE/0BC7E
        lea.l   $bfe001.l,a0                    ; 0BCF2/0BC82
        move.b  $d00(a0),d0                     ; 0BCF8/0BC88
        btst    #$3,d0                          ; 0BCFC/0BC8C
        beq.b   l_0BD54                         ; 0BD00/0BC90
        clr.w   d0                              ; 0BD02/0BC92
        move.b  $c00(a0),d0                     ; 0BD04/0BC94
        ori.b   #$40,$e00(a0)                   ; 0BD08/0BC98
        andi.b  #$f6,$e00(a0)                   ; 0BD0E/0BC9E
        move.b  #$2,$400(a0)                    ; 0BD14/0BCA4
        move.b  #$0,$500(a0)                    ; 0BD1A/0BCAA
        ori.b   #$1,$e00(a0)                    ; 0BD20/0BCB0
        move.b  #$0,$c00(a0)                    ; 0BD26/0BCB6
l_0BD2C:
        move.b  $d00(a0),d1                     ; 0BD2C/0BCBC
        btst    #$3,d1                          ; 0BD30/0BCC0
        beq.b   l_0BD2C                         ; 0BD34/0BCC4
        move.w  #INTF_PORTS,CUSTOM+INTREQ       ; 0BD36/0BCC6
        andi.b  #$bf,$e00(a0)                   ; 0BD3E/0BCCE
        not.b   d0                              ; 0BD44/0BCD4
        ror.b   #$1,d0                          ; 0BD46/0BCD6
        bmi.b   l_0BD54                         ; 0BD48/0BCD8
        move.b  d0,g_RawKey(a6)                 ; 0BD4A/0BCDA
        move.b  KeyAsciiTable(pc,d0.w),g_AsciiKey(a6); 0BD4E/0BCDE
l_0BD54:
        movem.l (a7)+,d0-d1/a0                  ; 0BD54/0BCE4
        rte                                     ; 0BD58/0BCE8

;---------------------------------------------------------------------------
; KeyAsciiTable - ASCII for raw key codes $00-$67 (0 = no character): the main block in
; US order, keypad digits at $0F, $1D-$1F, $2D-$2F and '.' at $3C (keypad 7-9 give nothing); $40 space, $41 backspace,
; $42 tab, $43 / $44 enter / return, $45 Esc, $46 Del.
;---------------------------------------------------------------------------
KeyAsciiTable:
	dc.b	'~1234567890-=\'
	dc.b	$00
	dc.b	'0QWERTYUIOP[]'
	dc.b	$00
	dc.b	'123ASDFGHJKL;'
	dc.b	$27,$00,$00,$34,$35,$36,$00
	dc.b	'ZXCVBNM,./'
	dc.b	$00,$2E,$00,$00,$00,$20,$08,$09,$0D,$0D,$1B,$7F,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00

;---------------------------------------------------------------------------
; ==================================================================
; VblIRQ - Level 3 vertical blank
;  - removes the interrupted SR from the stack into g_SavedSR
;  - sets HUD sprite (4-7) and Arthur sprite (0-3) control words,
;    copies Arthur's new frame into sprite RAM when it changes
;    (negative frame number = mirrored set at +$2A)
;  - g_VblCount++, reads the joystick into g_Joy (fire = bit 15)
;  - ticks the music player (vector $60, d0 = 0)
;  - if the logic interrupt is not already running and g_SkipLogic is
;    clear, raises SOFTINT -> Level1Logic runs next
;  - if returning to user mode with g_RedrawPending set, rewrites the
;    return address to RedrawEntry so the redraw runs outside IRQs
; ==================================================================
;---------------------------------------------------------------------------
VblIRQ:
        move.w  (a7)+,g_SavedSR(a6)             ; 0BDC2/0BD52  pop the exception SR into the globals (pushed back before RTE)
        movem.l d0-d7/a0-a5,-(a7)               ; 0BDC6/0BD56
        lea.l   CUSTOM,a0                       ; 0BDCA/0BD5A
        move.w  #INTF_VERTB,INTREQ(a0)          ; 0BDD0/0BD60  acknowledge VERTB
        tst.b   g_Spr47Visible(a6)              ; 0BDD6/0BD66  HUD sprites 4-7: the control words, or nothing
        bne.b   l_0BE0E                         ; 0BDDA/0BD6A
        clr.l   (SPRITE4_DATA).l                ; 0BDDC/0BD6C
        clr.l   (SPRITE5_DATA).l                ; 0BDE2/0BD72
        clr.l   (SPRITE6_DATA).l                ; 0BDE8/0BD78
        clr.l   (SPRITE7_DATA).l                ; 0BDEE/0BD7E
        clr.l   (SPRITE4B_DATA).l               ; 0BDF4/0BD84
        clr.l   (SPRITE5B_DATA).l               ; 0BDFA/0BD8A
        clr.l   (SPRITE6B_DATA).l               ; 0BE00/0BD90
        clr.l   (SPRITE7B_DATA).l               ; 0BE06/0BD96
        bra.b   l_0BE42                         ; 0BE0C/0BD9C
l_0BE0E:
        lea.l   (HudSpriteCtl).l,a1             ; 0BE0E/0BD9E
        move.l  (a1),(SPRITE4_DATA).l           ; 0BE12/0BDA2
        move.l  (a1)+,(SPRITE5_DATA).l          ; 0BE18/0BDA8
        move.l  (a1),(SPRITE6_DATA).l           ; 0BE1E/0BDAE
        move.l  (a1)+,(SPRITE7_DATA).l          ; 0BE24/0BDB4
        move.l  (a1),(SPRITE4B_DATA).l          ; 0BE2A/0BDBA
        move.l  (a1)+,(SPRITE5B_DATA).l         ; 0BE30/0BDC0
        move.l  (a1),(SPRITE6B_DATA).l          ; 0BE36/0BDC6
        move.l  (a1)+,(SPRITE7B_DATA).l         ; 0BE3C/0BDCC
l_0BE42:
        lea.l   (SPRITE0_DATA).l,a1             ; 0BE42/0BDD2  Arthur's sprites 0-3: control words from ArthurSpritePos, or nothing
        lea.l   (SPRITE1_DATA).l,a2             ; 0BE48/0BDD8
        lea.l   (SPRITE2_DATA).l,a3             ; 0BE4E/0BDDE
        lea.l   (SPRITE3_DATA).l,a4             ; 0BE54/0BDE4
        tst.b   g_ArthurVisible(a6)             ; 0BE5A/0BDEA
        bne.b   l_0BE6C                         ; 0BE5E/0BDEE
        clr.l   (a1)                            ; 0BE60/0BDF0
        clr.l   (a2)                            ; 0BE62/0BDF2
        clr.l   (a3)                            ; 0BE64/0BDF4
        clr.l   (a4)                            ; 0BE66/0BDF6
        bra.w   l_0BF5A                         ; 0BE68/0BDF8
l_0BE6C:
        lea.l   g_ArthurSprCtl(a6),a5           ; 0BE6C/0BDFC
        move.l  (a5)+,(a1)+                     ; 0BE70/0BE00
        move.l  (a5)+,(a2)+                     ; 0BE72/0BE02
        move.l  (a5)+,(a3)+                     ; 0BE74/0BE04
        move.l  (a5)+,(a4)+                     ; 0BE76/0BE06
        move.b  g_ArthurFrame(a6),d0            ; 0BE78/0BE08  Arthur frame changed? copy 4 x $80 bytes of sprite data
        cmp.b   g_ArthurShownFrame(a6),d0       ; 0BE7C/0BE0C
        beq.w   l_0BF5A                         ; 0BE80/0BE10
        move.b  d0,g_ArthurShownFrame(a6)       ; 0BE84/0BE14
        lea.l   (ARTHUR_SPR_GFX).l,a5           ; 0BE88/0BE18
        ext.w   d0                              ; 0BE8E/0BE22
        bpl.b   l_0BE98                         ; 0BE90/0BE24
        not.w   d0                              ; 0BE92/0BE26  negative frame ~n: the mirrored copy, stored after the 42 normal frames
        addi.w  #$2a,d0                         ; 0BE94/0BE28
l_0BE98:
        mulu.w  #$80,d0                         ; 0BE98/0BE2C  $80 bytes a frame in each of the four sprite banks ($2900 apart)
        adda.l  d0,a5                           ; 0BE9C/0BE30
        movem.l (a5)+,d0-d7                     ; 0BE9E/0BE32
        movem.l d0-d7,(a1)                      ; 0BEA2/0BE36
        lea.l   $20(a1),a1                      ; 0BEA6/0BE3A
        movem.l (a5)+,d0-d7                     ; 0BEAA/0BE3E
        movem.l d0-d7,(a1)                      ; 0BEAE/0BE42
        lea.l   $20(a1),a1                      ; 0BEB2/0BE46
        movem.l (a5)+,d0-d7                     ; 0BEB6/0BE4A
        movem.l d0-d7,(a1)                      ; 0BEBA/0BE4E
        lea.l   $20(a1),a1                      ; 0BEBE/0BE52
        movem.l (a5)+,d0-d7                     ; 0BEC2/0BE56
        movem.l d0-d7,(a1)                      ; 0BEC6/0BE5A
        lea.l   $2880(a5),a5                    ; 0BECA/0BE5E
        movem.l (a5)+,d0-d7                     ; 0BECE/0BE62
        movem.l d0-d7,(a2)                      ; 0BED2/0BE66
        lea.l   $20(a2),a2                      ; 0BED6/0BE6A
        movem.l (a5)+,d0-d7                     ; 0BEDA/0BE6E
        movem.l d0-d7,(a2)                      ; 0BEDE/0BE72
        lea.l   $20(a2),a2                      ; 0BEE2/0BE76
        movem.l (a5)+,d0-d7                     ; 0BEE6/0BE7A
        movem.l d0-d7,(a2)                      ; 0BEEA/0BE7E
        lea.l   $20(a2),a2                      ; 0BEEE/0BE82
        movem.l (a5)+,d0-d7                     ; 0BEF2/0BE86
        movem.l d0-d7,(a2)                      ; 0BEF6/0BE8A
        lea.l   $2880(a5),a5                    ; 0BEFA/0BE8E
        movem.l (a5)+,d0-d7                     ; 0BEFE/0BE92
        movem.l d0-d7,(a3)                      ; 0BF02/0BE96
        lea.l   $20(a3),a3                      ; 0BF06/0BE9A
        movem.l (a5)+,d0-d7                     ; 0BF0A/0BE9E
        movem.l d0-d7,(a3)                      ; 0BF0E/0BEA2
        lea.l   $20(a3),a3                      ; 0BF12/0BEA6
        movem.l (a5)+,d0-d7                     ; 0BF16/0BEAA
        movem.l d0-d7,(a3)                      ; 0BF1A/0BEAE
        lea.l   $20(a3),a3                      ; 0BF1E/0BEB2
        movem.l (a5)+,d0-d7                     ; 0BF22/0BEB6
        movem.l d0-d7,(a3)                      ; 0BF26/0BEBA
        lea.l   $2880(a5),a5                    ; 0BF2A/0BEBE
        movem.l (a5)+,d0-d7                     ; 0BF2E/0BEC2
        movem.l d0-d7,(a4)                      ; 0BF32/0BEC6
        lea.l   $20(a4),a4                      ; 0BF36/0BECA
        movem.l (a5)+,d0-d7                     ; 0BF3A/0BECE
        movem.l d0-d7,(a4)                      ; 0BF3E/0BED2
        lea.l   $20(a4),a4                      ; 0BF42/0BED6
        movem.l (a5)+,d0-d7                     ; 0BF46/0BEDA
        movem.l d0-d7,(a4)                      ; 0BF4A/0BEDE
        lea.l   $20(a4),a4                      ; 0BF4E/0BEE2
        movem.l (a5)+,d0-d7                     ; 0BF52/0BEE6
        movem.l d0-d7,(a4)                      ; 0BF56/0BEEA
l_0BF5A:
        addq.w  #$1,g_VblCount(a6)              ; 0BF5A/0BEEE  g_VblCount++
        move.w  g_Joy(a6),g_JoyPrev(a6)         ; 0BF5E/0BEF2  keep previous joystick state for edge detection
        move.w  $c(a0),d0                       ; 0BF64/0BEF8  JOY1DAT -> decode to b0 down, b1 right, b8 up, b9 left
        andi.w  #$303,d0                        ; 0BF68/0BEFC
        move.w  d0,d1                           ; 0BF6C/0BF00
        andi.w  #$202,d1                        ; 0BF6E/0BF02
        lsr.w   #$1,d1                          ; 0BF72/0BF06
        eor.w   d1,d0                           ; 0BF74/0BF08
        btst    #$7,$bfe001.l                   ; 0BF76/0BF0A  fire button -> bit 15
        bne.b   l_0BF84                         ; 0BF7E/0BF12
        bset    #$f,d0                          ; 0BF80/0BF14
l_0BF84:
        btst    #POTGOR_B2,POTGOR(a0)           ; second button (port 2, pin 9) -> bit 14: low = pressed
        bne.b   l_joyb2
        bset    #$e,d0
l_joyb2:
        move.w  #POTGO_B2,POTGO(a0)             ; (pin 9 an output, driven high: the button pulls it low)
        move.w  d0,g_Joy(a6)                    ; 0BF84/0BF18
        moveq   #$0,d0                          ; 0BF88/0BF1C  command 0 = tick
        movea.l (VEC_SPURIOUS).w,a1             ; 0BF8A/0BF1E
        jsr     (a1)                            ; 0BF8E/0BF22  music player tick
        move.w  g_SavedSR(a6),d0                ; 0BF90/0BF24  interrupted code at IPL 1 = logic still running: skip this frame
        andi.w  #$700,d0                        ; 0BF94/0BF28
        cmp.w   #$100,d0                        ; 0BF98/0BF2C
        bne.b   l_0BFA8                         ; 0BF9C/0BF30
        movem.l (a7)+,d0-d7/a0-a5               ; 0BF9E/0BF32
        move.w  g_SavedSR(a6),-(a7)             ; 0BFA2/0BF36
        jmp     IrqExit3                        ; 0BFA6/0BF3A  (rte, with the interrupted a6)
l_0BFA8:
        tst.b   g_SkipLogic(a6)                 ; 0BFA8/0BF3C
        bne.b   l_0BFB4                         ; 0BFAC/0BF40
        move.w  #INTF_SETCLR|INTF_SOFTINT,$9c(a0); 0BFAE/0BF42  INTREQ = SET|SOFTINT -> run Level1Logic
l_0BFB4:
        movem.l (a7)+,d0-d7/a0-a5               ; 0BFB4/0BF48  interrupted user mode with a redraw pending?
        btst    #$5,g_SavedSR(a6)               ; 0BFB8/0BF4C
        bne.b   l_0BFD8                         ; 0BFBE/0BF52
        tst.b   g_RedrawPending(a6)             ; 0BFC0/0BF54
        beq.b   l_0BFD8                         ; 0BFC4/0BF58
        clr.b   g_RedrawPending(a6)             ; 0BFC6/0BF5A
        addq.l  #$4,a7                          ; 0BFCA/0BF5E  replace the return address; reset the user stack
        pea.l   (RedrawEntry).l                 ; 0BFCC/0BF60  redirect user-mode return to RedrawEntry
        andi.w  #$dfff,g_SavedSR(a6)            ; 0BFD0/0BF64
        move    a6,usp                          ; 0BFD6/0BF6A
l_0BFD8:
        move.w  g_SavedSR(a6),-(a7)             ; 0BFD8/0BF6C
        jmp     IrqExit3                        ; 0BFDC/0BF70  (rte, with the interrupted a6)

;---------------------------------------------------------------------------
; RedrawScreen - full redraw of the playfield at the new origin g_NewTileX/Y, into
; g_ScreenSpare1, then copied to g_ScreenSpare2 (CameraJump / SwapScreens show them).
; 18 x 16 tiles of 16 x 16, from the bottom row up: cell = map byte (the map is in
; 16 x 16-tile cells), tile = CellTiles[cell][row][col], blitted from the level file
; (160 bytes a tile: 16 lines x 5 planes, BLTSIZE $1401, D modulo 34). Interrupts are
; held off (INTENA) around each blit. Cell $67 always gives tile 0.
; On level 1, map cells $1F and $1D (its tiles 0-9) take their tiles from a second bank
; (tile + 256). Levels 0 (before tile column $70) and 2 (before $40) then draw the
; shootable scenery into the background (DrawSceneryOnRedraw).
; Finally sets g_RedrawDone. Runs outside the interrupts, from RedrawEntry, or directly
; during set-up.
;---------------------------------------------------------------------------
RedrawScreen:
        jmp     EnhRedrawScreen                 ; the scroller: draw the pristine buffer
; (RedrawScreen: the rest of the original routine removed - the scroller does it)

CollisionBoxes:
	dc.b	16,16	; size class 0: width, height
	dc.b	16,32	; size class 1: width, height
	dc.b	32,16	; size class 2: width, height
	dc.b	16,32	; size class 3: width, height
	dc.b	48,48	; size class 4: width, height
	dc.b	48,16	; size class 5: width, height
	dc.b	64,64	; size class 6: width, height
	dc.b	64,16	; size class 7: width, height
	dc.b	16,48	; size class 8: width, height
	dc.b	48,32	; size class 9: width, height
	dc.b	16,64	; size class 10: width, height

;---------------------------------------------------------------------------
; Floor test for object a5: looks for floor under the bottom-left, then the bottom-right
; corner of its collision box. Floor found: Y is moved up onto it, d0 = 0 (Z set).
; No floor under either corner: d0 = -1 (Z clear).
;---------------------------------------------------------------------------
ObjectMapCollide:
        move.w  d7,-(a7)                        ; 0C15E/0C0F2
        move.w  O_X(a5),d6                      ; 0C160/0C0F4
        move.w  O_Y(a5),d7                      ; 0C164/0C0F8
        clr.w   d0                              ; 0C168/0C0FC
        move.b  O_Size(a5),d0                   ; 0C16A/0C0FE
        add.w   d0,d0                           ; 0C16E/0C102
        lea.l   CollisionBoxes(pc,d0.w),a1      ; 0C170/0C104
        move.b  (a1)+,d0                        ; 0C174/0C108
        lsr.w   #$1,d0                          ; 0C176/0C10A
        sub.w   d0,d6                           ; 0C178/0C10C
        move.b  (a1)+,d0                        ; 0C17A/0C10E
        lsr.w   #$1,d0                          ; 0C17C/0C110
        sub.w   d0,d7                           ; 0C17E/0C112
        jsr     (MapTileAt).l                       ; 0C180/0C114
        move.b  $4(a1),d0                       ; 0C184/0C118
        andi.b  #$c0,d0                         ; 0C188/0C11C
        bne.b   l_0C1A4                         ; 0C18C/0C120
        move.b  (a1),d0                         ; 0C18E/0C122
        ext.w   d0                              ; 0C190/0C124
        lea.l   (FloorProfile).l,a1           ; 0C192/0C126
        adda.w  d0,a1                           ; 0C196/0C12A
        move.b  (a1),d1                         ; 0C198/0C12C
        beq.b   l_0C1A4                         ; 0C19A/0C12E
        moveq   #$f,d0                          ; 0C19C/0C130
        and.w   d7,d0                           ; 0C19E/0C132
        sub.b   d0,d1                           ; 0C1A0/0C134
        bcc.b   l_0C1F0                         ; 0C1A2/0C136
l_0C1A4:
        move.w  O_X(a5),d6                      ; 0C1A4/0C138
        move.w  O_Y(a5),d7                      ; 0C1A8/0C13C
        lea.l   (BoxSizeTable).l,a1             ; 0C1AC/0C140
        clr.w   d0                              ; 0C1B0/0C144
        move.b  O_Size(a5),d0                   ; 0C1B2/0C146
        add.w   d0,d0                           ; 0C1B6/0C14A
        adda.w  d0,a1                           ; 0C1B8/0C14C
        move.b  (a1)+,d0                        ; 0C1BA/0C14E
        lsr.w   #$1,d0                          ; 0C1BC/0C150
        add.w   d0,d6                           ; 0C1BE/0C152
        move.b  (a1)+,d0                        ; 0C1C0/0C154
        lsr.w   #$1,d0                          ; 0C1C2/0C156
        sub.w   d0,d7                           ; 0C1C4/0C158
        jsr     (MapTileAt).l                       ; 0C1C6/0C15A
        move.b  $4(a1),d0                       ; 0C1CA/0C15E
