        movea.l a1,a4                           ;      /0C31A
        move.w  (a4),d1                         ;      /0C31C
        adda.w  d6,a4                           ;      /0C31E
        move.w  (a4),d2                         ;      /0C320
        adda.w  d6,a4                           ;      /0C322
        move.w  (a4),d3                         ;      /0C324
        adda.w  d6,a4                           ;      /0C326
        move.w  (a4),d4                         ;      /0C328
        adda.w  d6,a4                           ;      /0C32A
        move.w  (a4),d5                         ;      /0C32C
        move.w  d1,d0                           ;      /0C32E
        or.w    d2,d0                           ;      /0C330
        or.w    d3,d0                           ;      /0C332
        or.w    d4,d0                           ;      /0C334
        or.w    d5,d0                           ;      /0C336
        movea.l a2,a4                           ;      /0C338
        move.w  d1,(a4)                         ;      /0C33A
        adda.w  d6,a4                           ;      /0C33C
        move.w  d0,(a4)                         ;      /0C33E
        adda.w  d6,a4                           ;      /0C340
        move.w  d2,(a4)                         ;      /0C342
        adda.w  d6,a4                           ;      /0C344
        move.w  d0,(a4)                         ;      /0C346
        adda.w  d6,a4                           ;      /0C348
        move.w  d3,(a4)                         ;      /0C34A
        adda.w  d6,a4                           ;      /0C34C
        move.w  d0,(a4)                         ;      /0C34E
        adda.w  d6,a4                           ;      /0C350
        move.w  d4,(a4)                         ;      /0C352
        adda.w  d6,a4                           ;      /0C354
