        adda.w  d6,a4                           ;      /0C358
        move.w  d5,(a4)                         ;      /0C35A
        adda.w  d6,a4                           ;      /0C35C
        move.w  d0,(a4)                         ;      /0C35E
        addq.l  #$2,a1                          ;      /0C360
        addq.l  #$2,a2                          ;      /0C362
        movem.w (a7)+,d3-d5                     ;      /0C364
        dbra    d3,l1m_0C316                    ;      /0C368
