;---------------------------------------------------------------------------
; Build frame pointer table from offsets; d0 = bitmask of frames present
;---------------------------------------------------------------------------
BuildFrameTable:
        moveq   #$0,d2                          ; 0C450/0C384
l_0C452:
        move.w  (a3)+,d6                        ; 0C452/0C386
        move.l  (a4)+,d1                        ; 0C454/0C388
        clr.l   (a0)+                           ; 0C456/0C38A
        btst    d2,d0                           ; 0C458/0C38C
        beq.b   l_0C46E                         ; 0C45A/0C38E
        move.l  a2,-$4(a0)                      ; 0C45C/0C390
        lea.l   (a5,d1.l),a1                    ; 0C460/0C394
        lsr.w   #$1,d6                          ; 0C464/0C398
        subq.w  #$1,d6                          ; 0C466/0C39A
        btst    #PF_CACHE,(Profile).l           ; the cache is chip RAM and stays: the frame
        bne.b   bft_cached                      ; table points into it (the 1MB program copies)
l_0C468:
        move.w  (a1)+,(a2)+                     ; 0C468/     
        dbra    d6,l_0C468                      ; 0C46A/     
        bra.b   l_0C46E                         
bft_cached:
        move.l  a1,-$4(a0)                      
l_0C46E:
        addq.w  #$1,d2                          ; 0C46E/0C3A2
        dbra    d7,l_0C452                      ; 0C470/0C3A4
        rts                                     ; 0C474/0C3A8

