;---------------------------------------------------------------------------
FindFreeEnemyShot:
        lea.l   g_EnemyShots(a6),a4             ; 0C646/0C57A
        moveq   #$5,d6                          ; 0C64A/0C57E
l_0C64C:
        tst.b   (a4)                            ; 0C64C/0C580
        beq.b   l_0C658                         ; 0C64E/0C582
        lea.l   $1c(a4),a4                      ; 0C650/0C584
        dbra    d6,l_0C64C                      ; 0C654/0C588
l_0C658:
        rts                                     ; 0C658/0C58C

;---------------------------------------------------------------------------
; === Woody Pig (type 0, 100 pts) ===
; Flying pig of the level-0 forest; created by the spawners, flies in along a movement table and can drop/fire a projectile (FindFreeEnemyShot).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies in 16 directions at 1.55 px/frame (1 in 4 use the faster
; WoodyPigMoveFast table). O_Param 0: flies in from the edge of the screen at double speed;
; 1-2: emerges in place (size class 0 growing to 2). While Arthur is within 128 px it may loop
; the loop (8 turns of 1/16, up to 0-7 loops per pig, more likely the closer he is). When it
; is above Arthur but not over him and no enemy shot is in flight, it picks one up (enemy shot
; type 4, carried in Pig_Bomb) and drops it after a short animation (26 + 10 frames). If it is
; killed while carrying, the shot is let go (state 3).
;---------------------------------------------------------------------------
Enemy_WoodyPig:
        move.b  O_State(a5),d0                  ; 0C65A/0C58E
        add.w   d0,d0                           ; 0C65E/0C592
        add.w   d0,d0                           ; 0C660/0C594
        jmp     Enemy_WoodyPig_Jumps(pc,d0.w)   ; 0C662/0C596
Enemy_WoodyPig_Jumps:
        bra.w   WoodyPig_Init                   ; 0C666/0C59A
        bra.w   WoodyPig_Active                 ; 0C66A/0C59E
        bra.w   WoodyPig_Dying                  ; 0C66E/0C5A2
        bra.w   WoodyPig_Free                   ; 0C672/0C5A6

;---------------------------------------------------------------------------
; State 0. O_Step 0 set up, 1 fly in, 2-3 emerge
;---------------------------------------------------------------------------
WoodyPig_Init:
        clr.w   d0                              ; 0C676/0C5AA
        move.b  O_Step(a5),d0                   ; 0C678/0C5AC
        add.w   d0,d0                           ; 0C67C/0C5B0
        add.w   d0,d0                           ; 0C67E/0C5B2
        jmp     WoodyPig_Init_Jumps(pc,d0.w)    ; 0C680/0C5B4
WoodyPig_Init_Jumps:
        bra.w   WoodyPig_Setup                  ; 0C684/0C5B8
        bra.w   WoodyPig_FlyIn                  ; 0C688/0C5BC
        bra.w   WoodyPig_Emerge                 ; 0C68C/0C5C0
        bra.w   WoodyPig_Emerge                 ; 0C690/0C5C4

;---------------------------------------------------------------------------
; Shots pass through until it is on screen; O_Dir 1 (right) or 9 (left); O_Step = param + 1
;---------------------------------------------------------------------------
WoodyPig_Setup:
        move.b  #$2,(a5)                        ; 0C694/0C5C8
        clr.b   Pig_Drop(a5)                    ; 0C698/0C5CC
        clr.b   Pig_Unused31(a5)                ; 0C69C/0C5D0
        clr.b   Pig_Unused32(a5)                ; 0C6A0/0C5D4
        clr.b   Pig_Unused33(a5)                ; 0C6A4/0C5D8
        clr.l   Pig_Bomb(a5)                    ; 0C6A8/0C5DC
        clr.b   Pig_LoopAcc(a5)                 ; 0C6AC/0C5E0
        clr.b   Pig_TurnAcc(a5)                 ; 0C6B0/0C5E4
        move.w  g_GameFrame(a6),d0              ; 0C6B4/0C5E8
        add.w   d7,d0                           ; 0C6B8/0C5EC
        andi.w  #$7,d0                          ; 0C6BA/0C5EE
        move.b  d0,Pig_Loops(a5)                ; 0C6BE/0C5F2
        move.b  #$2,O_Size(a5)                  ; 0C6C2/0C5F6
        move.b  #$1,O_Dir(a5)                   ; 0C6C8/0C5FC
        move.w  O_X(a5),d0                      ; 0C6CE/0C602
        cmp.w   g_ArthurX(a6),d0                ; 0C6D2/0C606
        blt.b   l_0C6DE                         ; 0C6D6/0C60A
        move.b  #$9,O_Dir(a5)                   ; 0C6D8/0C60C
l_0C6DE:
        clr.l   O_Anim(a5)                      ; 0C6DE/0C612
        lea.l   WoodyPigMoveTable(pc),a0        ; 0C6E2/0C616
        move.w  g_GameFrame(a6),d0              ; 0C6E6/0C61A
        add.w   d7,d0                           ; 0C6EA/0C61E
        andi.w  #$3,d0                          ; 0C6EC/0C620
        bne.b   l_0C6F6                         ; 0C6F0/0C624
        lea.l   WoodyPigMoveFast(pc),a0         ; 0C6F2/0C626
l_0C6F6:
        move.l  a0,O_MoveTable(a5)              ; 0C6F6/0C62A
        move.b  O_Param(a5),d0                  ; 0C6FA/0C62E
        addq.b  #$1,d0                          ; 0C6FE/0C632
        move.b  d0,O_Step(a5)                   ; 0C700/0C634
        rts                                     ; 0C704/0C638

;---------------------------------------------------------------------------
; Double speed until inside the screen (16-240 px from its left edge)
;---------------------------------------------------------------------------
WoodyPig_FlyIn:
        tst.b   O_Step2(a5)                     ; 0C706/0C63A
        bne.b   l_0C726                         ; 0C70A/0C63E
        lea.l   WoodyPig_AnimFlyB(pc),a0        ; 0C70C/0C640
        cmpi.b  #$9,O_Dir(a5)                   ; 0C710/0C644
        bne.b   l_0C71C                         ; 0C716/0C64A
        lea.l   WoodyPig_AnimFlyA(pc),a0        ; 0C718/0C64C
l_0C71C:
