        addi.w  #$10,d0                         ; 0C72E/0C662
        cmp.w   #$e0,d0                         ; 0C732/0C666
        bls.b   l_0C744                         ; 0C736/0C66A
        bsr.w   Animate                         ; 0C738/0C66C  animate
        bsr.w   ApplyMoveTable                  ; 0C73C/0C670  move by the movement table
        bra.w   ApplyMoveTable                  ; 0C740/0C674
l_0C744:
        move.b  #ST_ACTIVE,O_State(a5)          ; 0C744/0C678
        clr.b   O_Step(a5)                      ; 0C74A/0C67E
        clr.b   O_Step2(a5)                     ; 0C74E/0C682
        rts                                     ; 0C752/0C686

;---------------------------------------------------------------------------
; Emerging animation (12-frame delay first); hittable at frame 4
;---------------------------------------------------------------------------
WoodyPig_Emerge:
        tst.b   O_Step2(a5)                     ; 0C754/0C688
        bne.b   l_0C780                         ; 0C758/0C68C
        move.b  #$0,O_Size(a5)                  ; 0C75A/0C68E
        lea.l   WoodyPig_AnimEmergeB(pc),a0     ; 0C760/0C694
        cmpi.b  #$9,O_Dir(a5)                   ; 0C764/0C698
        bne.b   l_0C770                         ; 0C76A/0C69E
