        bsr.w   SetAnim                         ; 0C776/0C6AA  start animation
        addq.b  #$1,O_Step2(a5)                 ; 0C77A/0C6AE
        rts                                     ; 0C77E/0C6B2
l_0C780:
        subq.b  #$1,Pig_Turns(a5)               ; 0C780/0C6B4
        bne.b   l_0C7B4                         ; 0C784/0C6B8
        bsr.w   Animate                         ; 0C786/0C6BA  animate
        move.b  #$1,Pig_Turns(a5)               ; 0C78A/0C6BE
        move.b  O_Frame(a5),d0                  ; 0C790/0C6C4
        cmp.b   #$4,d0                          ; 0C794/0C6C8
        bcs.b   l_0C7B4                         ; 0C798/0C6CC
        move.b  #$2,O_Size(a5)                  ; 0C79A/0C6CE
        tst.b   O_AnimTimer(a5)                 ; 0C7A0/0C6D4
        bne.b   l_0C7B4                         ; 0C7A4/0C6D8
        move.b  #ST_ACTIVE,O_State(a5)          ; 0C7A6/0C6DA
