WoodyPigMoveTable:
	dc.b	$00,$00,$00,$00,$01,$8D,$00,$00,$01,$6E,$FF,$69,$01,$18,$FE,$E8
	dc.b	$00,$97,$FE,$92,$00,$00,$FE,$73,$FF,$69,$FE,$92,$FE,$E8,$FE,$E8
