        moveq   #$19,d0                         ; 0C8AC/       d0 is not used by what follows. [1MB build: PlaySfx here, effect 18; the call was removed in 512K]
snd134_end:
l_0C8AE:
        tst.b   O_Step2(a5)                     ; 0C8AE/0C7E6
        bne.b   l_0C8D2                         ; 0C8B2/0C7EA
        move.b  #$1,(a5)                        ; 0C8B4/0C7EC
