        add.w   d7,d0                           ; 0C8E4/0C81C
        andi.w  #$f,d0                          ; 0C8E6/0C81E
        bne.b   l_0C918                         ; 0C8EA/0C822
        move.w  O_X(a5),d0                      ; 0C8EC/0C824
        sub.w   g_ArthurX(a6),d0                ; 0C8F0/0C828
        bpl.b   l_0C8F8                         ; 0C8F4/0C82C
