        cmp.w   g_ArthurX(a6),d0                ; 0CC18/0CB50
        slt.b   O_Dir(a5)                       ; 0CC1C/0CB54
        neg.b   O_Dir(a5)                       ; 0CC20/0CB58
        move.b  #$2,O_Size(a5)                  ; 0CC24/0CB5C
        lea.l   Bat_AnimFly(pc),a0              ; 0CC2A/0CB62
        cmpi.b  #$3,O_Param(a5)                 ; 0CC2E/0CB66  param 3+: crow
        bcs.b   l_0CC56                         ; 0CC34/0CB6C
        clr.b   O_Size(a5)                      ; 0CC36/0CB6E
        move.b  #$1,Crw_Crow(a5)                ; 0CC3A/0CB72
