; State 3: give the spawn quota back, free the slot
;---------------------------------------------------------------------------
PetiteDevil_Free:
        addq.b  #$1,g_SpawnQuota+2(a6)          ; 0D8CC/0D812
        clr.b   (a5)                            ; 0D8D0/0D816  free this enemy slot
        rts                                     ; 0D8D2/0D818

