l_0DD9A:
        rts                                     ; 0DD9A/0DCE0

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
BlueKiller_FaceArthur:
        move.w  O_X(a5),d0                      ; 0DD9C/0DCE2
        cmp.w   g_ArthurX(a6),d0                ; 0DDA0/0DCE6
