        rts                                     ; 0DDAC/0DCF2

;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 walk 2, 2 hop up, 3 hop down, 4 drop, 5 swoop
;---------------------------------------------------------------------------
BlueKiller_Active:
        clr.w   d0                              ; 0DDAE/0DCF4
        move.b  O_Step(a5),d0                   ; 0DDB0/0DCF6
        add.w   d0,d0                           ; 0DDB4/0DCFA
        add.w   d0,d0                           ; 0DDB6/0DCFC
        jsr     BlueKiller_MorphTimer_Jumps(pc,d0.w); 0DDB8/0DCFE
        bsr.w   PetiteDevil_RemoveOffScreen     ; 0DDBC/0DD02
        bsr.b   BlueKiller_MorphTimer           ; 0DDC0/0DD06
        bra.w   CheckFarAway                    ; 0DDC2/0DD08

;---------------------------------------------------------------------------
