        move.b  #$2,O_Param(a5)                 ; 0DDD2/0DD18  start mode 2 (blink in)
        clr.b   O_State(a5)                     ; 0DDD8/0DD1E  -> state 0 (spawn)
        clr.b   O_Step(a5)                      ; 0DDDC/0DD22
        clr.b   O_Step2(a5)                     ; 0DDE0/0DD26
l_0DDE4:
        rts                                     ; 0DDE4/0DD2A
BlueKiller_MorphTimer_Jumps:
        bra.w   BlueKiller_Walk                 ; 0DDE6/0DD2C
        bra.w   BlueKiller_Walk2                ; 0DDEA/0DD30
        bra.w   BlueKiller_HopUp                ; 0DDEE/0DD34
        bra.w   BlueKiller_HopDown              ; 0DDF2/0DD38
        bra.w   BlueKiller_Drop                 ; 0DDF6/0DD3C
        bra.w   BlueKiller_Swoop2               ; 0DDFA/0DD40

