        bsr.w   Random                          ; 0DE3C/0DD82  random number
        andi.w  #$3,d0                          ; 0DE40/0DD86
        move.b  BlueKillerWalkTimes(pc,d0.w),BK_WalkTime(a5); 0DE44/0DD8A
        addq.b  #$1,O_Step2(a5)                 ; 0DE4A/0DD90

