	AL	$06,3,BlueKiller_AnimWalk_0
BlueKiller_AnimWalk_1:
	AF	$00,3
	AF	$01,3
	AF	$02,3
	AL	$01,3,BlueKiller_AnimWalk_1
BlueKiller_AnimDrop:
	AF	$04,8
BlueKiller_AnimDrop_2:
	AL	$03,3,BlueKiller_AnimDrop_2
BlueKiller_AnimAppear:
	AF	$0C,2
	AL	$0D,2,BlueKiller_AnimAppear
BlueKiller_AnimWalk2:
	dc.w	BlueKiller_AnimWalk2_0-*	; 0
	dc.w	BlueKiller_AnimWalk2_1-*	; 1
BlueKiller_AnimWalk2_0:
	AF	$0F,3
	AF	$10,3
	AF	$11,3
	AL	$10,3,BlueKiller_AnimWalk2_0
BlueKiller_AnimWalk2_1:
	AF	$09,3
	AF	$0A,3
	AF	$0B,3
	AL	$0A,3,BlueKiller_AnimWalk2_1

;---------------------------------------------------------------------------
; Blue Killer swoops: two sets (BK_SwoopSet), each a direction table of two 6-step
; movement tables - falling at 1.71 px/frame while the sideways speed builds up
;---------------------------------------------------------------------------
BlueKillerSwoopA:
	dc.w	BlueKillerSwoopA_0-*	; 0
	dc.w	BlueKillerSwoopA_1-*	; 1
BlueKillerSwoopB:
	dc.w	BlueKillerSwoopB_0-*	; 0
	dc.w	BlueKillerSwoopB_1-*	; 1
BlueKillerSwoopA_0:
	dc.w	48,-439	;  0: dx +0.19, dy -1.71
	dc.w	79,-439	;  1: dx +0.31, dy -1.71
	dc.w	120,-439	;  2: dx +0.47, dy -1.71
	dc.w	192,-439	;  3: dx +0.75, dy -1.71
	dc.w	408,-439	;  4: dx +1.59, dy -1.71
	dc.w	480,-439	;  5: dx +1.88, dy -1.71
BlueKillerSwoopB_0:
	dc.w	-48,-439	;  0: dx -0.19, dy -1.71
	dc.w	-79,-439	;  1: dx -0.31, dy -1.71
	dc.w	-120,-439	;  2: dx -0.47, dy -1.71
	dc.w	-192,-439	;  3: dx -0.75, dy -1.71
	dc.w	-408,-439	;  4: dx -1.59, dy -1.71
	dc.w	-480,-439	;  5: dx -1.88, dy -1.71
BlueKillerSwoopA_1:
	dc.w	72,-439	;  0: dx +0.28, dy -1.71
	dc.w	96,-439	;  1: dx +0.38, dy -1.71
	dc.w	192,-439	;  2: dx +0.75, dy -1.71
	dc.w	432,-439	;  3: dx +1.69, dy -1.71
	dc.w	480,-439	;  4: dx +1.88, dy -1.71
	dc.w	504,-439	;  5: dx +1.97, dy -1.71
BlueKillerSwoopB_1:
	dc.w	-72,-439	;  0: dx -0.28, dy -1.71
	dc.w	-96,-439	;  1: dx -0.38, dy -1.71
	dc.w	-192,-439	;  2: dx -0.75, dy -1.71
	dc.w	-432,-439	;  3: dx -1.69, dy -1.71
	dc.w	-480,-439	;  4: dx -1.88, dy -1.71
	dc.w	-504,-439	;  5: dx -1.97, dy -1.71

;---------------------------------------------------------------------------
; straight down at 1.71 px/frame
;---------------------------------------------------------------------------
BlueKillerFallTable:
	dc.b	$00,$00,$FE,$49

;---------------------------------------------------------------------------
; === Red Arremer (type 5, 1000 pts, 3 hits) ===
; The red gargoyle: walks, takes off and dives at Arthur, hovers and shoots; changes size class between standing and flying. Sound effect 12 when hit.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded. O_Param: bits 0-1 = start mode (1 perched, 2 blink in, 0/3 at
; once), bits 2+ = starting aggression.
;   * Perched (mode 1): crouches until Arthur comes within 96 px across and 48 px up or
;     down, or it is shot at, then wakes after 16 frames.
;   * On the ground (O_Step 0) it walks to RedArremerWalkScript, and four timers decide
;     what it does next: shoot (enemy shot type 7) on RedArremerShotTimes, swoop at
;     Arthur on RedArremerSwoopTimes, take off and hover on RedArremerTakeOffTimes (x 8
;     frames), and - once only - rage after 50 x 32 frames: it flashes for 76 frames,
;     then uses the faster tables (RA_Rage 1).
;   * It glides away when Arthur is within 48 px, and towards him when he is 112+ px away.
;   * Dodging: when one of Arthur's shots is flying at it at its height (and Arthur is
;     84+ px away) it jumps up out of the way and hovers.
;   * Swoop: from above, an elliptical dive onto the spot where Arthur stood, then up and
;     away; from level or below, a fast flight past him.
;   * Flying states use size class 9, standing 3. Removed when far above or below the
;     camera.
; Mode 2 (used when a Blue Killer turns into a Red Arremer) counts $F0 down by $61 a frame
; and waits for exactly 0, twice, which takes 2 x 26,352 frames (about 17 minutes) during
; which it blinks and shots pass through it - presumably a bug. The placed Red Arremers use
; mode 1.
;---------------------------------------------------------------------------
Enemy_RedArremer:
        move.b  O_State(a5),d0                  ; 0E1FA/0E140
        add.w   d0,d0                           ; 0E1FE/0E144
        add.w   d0,d0                           ; 0E200/0E146
        jmp     Enemy_RedArremer_Jumps(pc,d0.w) ; 0E202/0E148
Enemy_RedArremer_Jumps:
        bra.w   RedArremer_Init                 ; 0E206/0E14C
        bra.w   RedArremer_Active               ; 0E20A/0E150
        bra.w   RedArremer_Dying                ; 0E20E/0E154
        bra.w   RedArremer_Free                 ; 0E212/0E158

;---------------------------------------------------------------------------
; State 0. O_Step 0 decode O_Param, 1 perched, 2 blink in, 3 set up
;---------------------------------------------------------------------------
RedArremer_Init:
        move.b  O_Step(a5),d0                   ; 0E216/0E15C
        add.w   d0,d0                           ; 0E21A/0E160
        add.w   d0,d0                           ; 0E21C/0E162
        jmp     RedArremer_Init_Jumps(pc,d0.w)  ; 0E21E/0E164
RedArremer_Init_Jumps:
        bra.w   RedArremer_Decode               ; 0E222/0E168
        bra.w   RedArremer_Perched              ; 0E226/0E16C
        bra.w   RedArremer_BlinkIn              ; 0E22A/0E170
        bra.w   RedArremer_Setup                ; 0E22E/0E174
RedArremer_Decode:
        move.b  O_Param(a5),d0                  ; 0E232/0E178  starting aggression = O_Param >> 2
        lsr.b   #$2,d0                          ; 0E236/0E17C
        move.b  d0,RA_Rage(a5)                  ; 0E238/0E17E
        moveq   #$3,d0                          ; 0E23C/0E182
        and.b   O_Param(a5),d0                  ; 0E23E/0E184  start mode = O_Param & 3 (0 -> 3)
        bne.b   l_0E246                         ; 0E242/0E188
        moveq   #$3,d0                          ; 0E244/0E18A
l_0E246:
        move.b  d0,O_Step(a5)                   ; 0E246/0E18C
        move.b  #$ff,O_HP(a5)                   ; 0E24A/0E190
        clr.b   O_Param(a5)                     ; 0E250/0E196
        rts                                     ; 0E254/0E19A
RedArremer_Perched:
        move.b  O_Step2(a5),d0                  ; 0E256/0E19C
        add.w   d0,d0                           ; 0E25A/0E1A0
        add.w   d0,d0                           ; 0E25C/0E1A2
        jmp     RedArremer_Perched_Jumps(pc,d0.w); 0E25E/0E1A4
RedArremer_Perched_Jumps:
        bra.w   RedArremer_PerchStart           ; 0E262/0E1A8
        bra.w   RedArremer_PerchWait            ; 0E266/0E1AC
        bra.w   RedArremer_PerchWake            ; 0E26A/0E1B0
RedArremer_PerchStart:
        move.b  #$3,O_Size(a5)                  ; 0E26E/0E1B4
        move.b  #$1,O_Dir(a5)                   ; 0E274/0E1BA
        lea.l   RedArremer_AnimPerch(pc),a0     ; 0E27A/0E1C0
        bsr.w   SetAnim                         ; 0E27E/0E1C4  start animation
        move.b  #$10,RA_BaseY(a5)               ; 0E282/0E1C8
        addq.b  #$1,O_Step2(a5)                 ; 0E288/0E1CE
        rts                                     ; 0E28C/0E1D2

;---------------------------------------------------------------------------
; Wake when Arthur is within +-96 px across and +-48 px vertically, or when hit
; (EnemyHitByShot sets O_Param)
;---------------------------------------------------------------------------
RedArremer_PerchWait:
        move.w  O_Y(a5),d0                      ; 0E28E/0E1D4
        sub.w   g_ArthurY(a6),d0                ; 0E292/0E1D8
        addi.w  #$30,d0                         ; 0E296/0E1DC
        cmp.w   #$60,d0                         ; 0E29A/0E1E0
        bhi.b   l_0E2B2                         ; 0E29E/0E1E4
        move.w  O_X(a5),d0                      ; 0E2A0/0E1E6
        sub.w   g_ArthurX(a6),d0                ; 0E2A4/0E1EA
        addi.w  #$60,d0                         ; 0E2A8/0E1EE
        cmp.w   #$c0,d0                         ; 0E2AC/0E1F2
        bls.b   l_0E2B8                         ; 0E2B0/0E1F6
l_0E2B2:
        tst.b   O_Param(a5)                     ; 0E2B2/0E1F8
        beq.b   l_0E2BC                         ; 0E2B6/0E1FC
l_0E2B8:
        addq.b  #$1,O_Step2(a5)                 ; 0E2B8/0E1FE
l_0E2BC:
        rts                                     ; 0E2BC/0E202

;---------------------------------------------------------------------------
; 16 frames, then set up
;---------------------------------------------------------------------------
RedArremer_PerchWake:
        subq.b  #$1,RA_BaseY(a5)                ; 0E2BE/0E204
        bne.b   l_0E2CE                         ; 0E2C2/0E208
        move.b  #$3,O_Step(a5)                  ; 0E2C4/0E20A
        clr.b   O_Step2(a5)                     ; 0E2CA/0E210
l_0E2CE:
        rts                                     ; 0E2CE/0E214

;---------------------------------------------------------------------------
; Mode 2 (a Blue Killer that has turned): shots pass through (O_Active 2) and it
; blinks until RA_CentreX reaches 0, twice
;---------------------------------------------------------------------------
RedArremer_BlinkIn:
        move.b  O_Step2(a5),d0                  ; 0E2D0/0E216
        add.w   d0,d0                           ; 0E2D4/0E21A
        add.w   d0,d0                           ; 0E2D6/0E21C
        jmp     RedArremer_BlinkIn_Jumps(pc,d0.w); 0E2D8/0E21E
RedArremer_BlinkIn_Jumps:
        bra.w   RedArremer_BlinkStart           ; 0E2DC/0E222
        bra.w   RedArremer_Blink                ; 0E2E0/0E226
        bra.w   RedArremer_BlinkSize            ; 0E2E4/0E22A
        bra.w   RedArremer_Blink                ; 0E2E8/0E22E
        bra.w   RedArremer_BlinkDone            ; 0E2EC/0E232
RedArremer_BlinkStart:
        move.b  #$2,(a5)                        ; 0E2F0/0E236  O_Active 2: not hit by shots
        move.w  #$f0,RA_CentreX(a5)             ; 0E2F4/0E23A
        addq.b  #$1,O_Step2(a5)                 ; 0E2FA/0E240

;---------------------------------------------------------------------------
; Blink every 16 frames; RA_CentreX -= $61 until it is exactly 0 (26,352 frames)
;---------------------------------------------------------------------------
RedArremer_Blink:
        moveq   #$f,d0                          ; 0E2FE/0E244
        and.w   g_GameFrame(a6),d0              ; 0E300/0E246
        bne.b   l_0E31A                         ; 0E304/0E24A
        moveq   #$10,d0                         ; 0E306/0E24C
        and.w   g_GameFrame(a6),d0              ; 0E308/0E24E
        bne.b   l_0E316                         ; 0E30C/0E252
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E30E/0E254
        bsr.w   SetAnimIndexed                  ; 0E312/0E258  start animation for current direction
l_0E316:
        clr.l   O_Anim(a5)                      ; 0E316/0E25C
l_0E31A:
        subi.w  #$61,RA_CentreX(a5)             ; 0E31A/0E260
        bne.b   l_0E326                         ; 0E320/0E266
        addq.b  #$1,O_Step2(a5)                 ; 0E322/0E268
l_0E326:
        rts                                     ; 0E326/0E26C
RedArremer_BlinkSize:
        move.w  #$f0,RA_CentreX(a5)             ; 0E328/0E26E
        moveq   #$3,d0                          ; 0E32E/0E274
        bsr.w   SetBoxClass                     ; 0E330/0E276  change size class
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E334/0E27A
        bsr.w   SetAnimIndexed                  ; 0E338/0E27E  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E33C/0E282
        rts                                     ; 0E340/0E286
RedArremer_BlinkDone:
        move.b  #ST_ACTIVE,O_State(a5)          ; 0E342/0E288
        clr.b   O_Step(a5)                      ; 0E348/0E28E
        clr.b   O_Step2(a5)                     ; 0E34C/0E292
        rts                                     ; 0E350/0E296

;---------------------------------------------------------------------------
; (direction word, frames) pairs; direction -1 = stand; 0 = loop (offset follows)
;---------------------------------------------------------------------------
RedArremerWalkScript:
	dc.b	$00,$14,$00,$1C,$01,$0A,$00,$0C,$FF,$0A,$00,$14,$01,$1E,$00,$05
	dc.b	$FF,$14,$01,$1A,$01,$0A,$00,$0C,$FF,$14,$00,$02,$01,$05,$00,$0F
	dc.b	$00,$00,$FF,$DE,$00

;---------------------------------------------------------------------------
; frames between shots: 90, 100, 220, 130, 160, 180, 200, 120 (0 = loop)
;---------------------------------------------------------------------------
RedArremerShotTimes:
	dc.b	$5A,$64,$DC,$82,$A0,$B4,$C8,$78,$00,$FF,$F7,$00

;---------------------------------------------------------------------------
; frames between swoops: 72, 136, 85, 92, 108, 144, 70, 49
;---------------------------------------------------------------------------
RedArremerSwoopTimes:
	dc.b	$48,$88,$55,$5C,$6C,$90,$46,$31,$00,$FF,$F7,$00

;---------------------------------------------------------------------------
; x 8 frames between take-offs: 10, 20, 30, 40, 50, 60
;---------------------------------------------------------------------------
RedArremerTakeOffTimes:
	dc.b	$0A,$14,$1E,$28,$32,$3C,$00,$FF,$F9

;---------------------------------------------------------------------------
; 3 HP, size 3, face Arthur, start the four scripts, rage in 50 x 32 frames
;---------------------------------------------------------------------------
RedArremer_Setup:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0E398/0E2DE  one more big enemy engaged
        move.b  #$3,O_HP(a5)                    ; 0E39C/0E2E2
        move.b  #$3,O_Size(a5)                  ; 0E3A2/0E2E8
        move.w  O_X(a5),d0                      ; 0E3A8/0E2EE
        cmp.w   g_ArthurX(a6),d0                ; 0E3AC/0E2F2
        slt.b   O_Dir(a5)                       ; 0E3B0/0E2F6
        addq.b  #$1,O_Dir(a5)                   ; 0E3B4/0E2FA
        lea.l   RedArremerWalkScript(pc),a0     ; 0E3B8/0E2FE
        move.w  (a0)+,RA_WalkDir(a5)            ; 0E3BC/0E302
        move.l  a0,RA_WalkPtr(a5)               ; 0E3C0/0E306
        lea.l   RedArremerShotTimes(pc),a0      ; 0E3C4/0E30A
        move.b  (a0)+,RA_ShotTime(a5)           ; 0E3C8/0E30E
        move.l  a0,RA_ShotPtr(a5)               ; 0E3CC/0E312
        lea.l   RedArremerSwoopTimes(pc),a0     ; 0E3D0/0E316
        move.b  (a0)+,RA_SwoopTime(a5)          ; 0E3D4/0E31A
        move.l  a0,RA_SwoopPtr(a5)              ; 0E3D8/0E31E
        lea.l   RedArremerTakeOffTimes(pc),a0   ; 0E3DC/0E322
        move.b  (a0)+,RA_Phase(a5)              ; 0E3E0/0E326
        move.l  a0,RA_FlyPtr(a5)                ; 0E3E4/0E32A
        move.b  #$32,RA_RageTime(a5)            ; 0E3E8/0E32E
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E3EE/0E334
        bsr.w   SetAnimIndexed                  ; 0E3F2/0E338  start animation for current direction
        move.b  #ST_ACTIVE,O_State(a5)          ; 0E3F6/0E33C
        clr.b   O_Step(a5)                      ; 0E3FC/0E342
        clr.b   O_Step2(a5)                     ; 0E400/0E346
        rts                                     ; 0E404/0E34A

;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 fly, 2 shoot, 3 glide, 4 rage, 5 dodge / hover, 6 swoop.
; Then the hit flinch, and removal when it is far above or below the camera.
;---------------------------------------------------------------------------
RedArremer_Active:
        move.b  O_Step(a5),d0                   ; 0E406/0E34C
        add.w   d0,d0                           ; 0E40A/0E350
        add.w   d0,d0                           ; 0E40C/0E352
        jsr     RedArremer_Active_Jumps(pc,d0.w); 0E40E/0E354
        bsr.w   RedArremer_Flinch               ; 0E412/0E358
        move.w  O_Y(a5),d0                      ; 0E416/0E35C  more than 64 px below or 320 above the camera: remove
        sub.w   g_CameraY(a6),d0                ; 0E41A/0E360
        addi.w  #$40,d0                         ; 0E41E/0E364
        cmp.w   #$180,d0                        ; 0E422/0E368
        bls.b   l_0E42E                         ; 0E426/0E36C
        move.b  #ST_REMOVE,O_State(a5)          ; 0E428/0E36E
l_0E42E:
        rts                                     ; 0E42E/0E374
RedArremer_Active_Jumps:
        bra.w   RedArremer_Walk                 ; 0E430/0E376
        bra.w   RedArremer_Fly                  ; 0E434/0E37A
        bra.w   RedArremer_Shoot                ; 0E438/0E37E
        bra.w   RedArremer_Glide                ; 0E43C/0E382
        bra.w   RedArremer_Rage                 ; 0E440/0E386
        bra.w   RedArremer_Dodge                ; 0E444/0E38A
        bra.w   RedArremer_Swoop                ; 0E448/0E38E

;---------------------------------------------------------------------------
; walking: +-0.8 px/frame
;---------------------------------------------------------------------------
RedArremerWalkMove:
	dc.b	$00,$CD,$FF,$33

;---------------------------------------------------------------------------
; Step 0: walk, and check the shot, swoop, take-off, distance, dodge and rage timers
;---------------------------------------------------------------------------
RedArremer_Walk:
        tst.b   O_Step2(a5)                     ; 0E450/0E396
        bne.b   l_0E45A                         ; 0E454/0E39A
        bsr.b   RedArremer_WalkStart            ; 0E456/0E39C
        bra.b   l_0E45C                         ; 0E458/0E39E
l_0E45A:
        bsr.b   RedArremer_Walking              ; 0E45A/0E3A0
l_0E45C:
        bsr.w   RedArremer_ShotTimer            ; 0E45C/0E3A2
        bsr.w   RedArremer_SwoopTimer           ; 0E460/0E3A6
        bsr.w   RedArremer_TakeOffTimer         ; 0E464/0E3AA
        bsr.w   RedArremer_CheckGlide           ; 0E468/0E3AE
        bsr.w   RedArremer_CheckDodge           ; 0E46C/0E3B2
        bra.w   RedArremer_RageTimer            ; 0E470/0E3B6
RedArremer_WalkStart:
        lea.l   RedArremerWalkMove(pc),a0       ; 0E474/0E3BA
        move.l  a0,O_MoveTable(a5)              ; 0E478/0E3BE
        move.b  #$3,O_Size(a5)                  ; 0E47C/0E3C2
        move.w  g_ArthurX(a6),d0                ; 0E482/0E3C8
        cmp.w   O_X(a5),d0                      ; 0E486/0E3CC
        shi.b   O_Dir(a5)                       ; 0E48A/0E3D0
        addq.b  #$1,O_Dir(a5)                   ; 0E48E/0E3D4
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E492/0E3D8
        bsr.w   SetAnimIndexed                  ; 0E496/0E3DC  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E49A/0E3E0
        rts                                     ; 0E49E/0E3E4

;---------------------------------------------------------------------------
; Walk; if there is no floor under it any more, fly
;---------------------------------------------------------------------------
RedArremer_Walking:
        bsr.w   RedArremer_WalkScriptStep       ; 0E4A0/0E3E6
        bsr.w   RedArremer_MoveX                ; 0E4A4/0E3EA
        subq.w  #$2,O_Y(a5)                     ; 0E4A8/0E3EE
        bsr.w   ObjectMapCollide                ; 0E4AC/0E3F2  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_0E4BC                         ; 0E4B0/0E3F6
        move.b  #$1,O_Step(a5)                  ; 0E4B2/0E3F8
        clr.b   O_Step2(a5)                     ; 0E4B8/0E3FE
l_0E4BC:
        rts                                     ; 0E4BC/0E402

;---------------------------------------------------------------------------
; Step 1: O_Step2 0 take off, 1 rise, 2 fly to Arthur, 3 fly past him, 4 hover,
; 5 come down, 6 drop. Shoots and swoops while flying.
;---------------------------------------------------------------------------
RedArremer_Fly:
        move.b  O_Step2(a5),d0                  ; 0E4BE/0E404
        add.w   d0,d0                           ; 0E4C2/0E408
        add.w   d0,d0                           ; 0E4C4/0E40A
        jsr     RedArremer_Fly_Jumps(pc,d0.w)   ; 0E4C6/0E40C
        move.b  O_Step2(a5),d0                  ; 0E4CA/0E410
        subq.b  #$2,d0                          ; 0E4CE/0E414
        cmp.b   #$1,d0                          ; 0E4D0/0E416
        bhi.b   l_0E4DE                         ; 0E4D4/0E41A
        bsr.w   RedArremer_ShotTimer            ; 0E4D6/0E41C
        bra.w   RedArremer_SwoopTimer           ; 0E4DA/0E420
l_0E4DE:
        rts                                     ; 0E4DE/0E424
RedArremer_Fly_Jumps:
        bra.w   RedArremer_TakeOff              ; 0E4E0/0E426
        bra.w   RedArremer_Rise                 ; 0E4E4/0E42A
        bra.w   RedArremer_FlyToArthur          ; 0E4E8/0E42E
        bra.w   RedArremer_FlyPast              ; 0E4EC/0E432
        bra.w   RedArremer_Hover                ; 0E4F0/0E436
        bra.w   RedArremer_Descend              ; 0E4F4/0E43A
        bra.w   RedArremer_Drop                 ; 0E4F8/0E43E

;---------------------------------------------------------------------------
; +-1.75 px/frame (calm), +-2.0 (after its rage)
;---------------------------------------------------------------------------
RedArremerFlySpeed:
	dc.b	$01,$C0,$FE,$40,$02,$00,$FE,$00

;---------------------------------------------------------------------------
; Random heights of the flight curve: 64, 72, 84, 68, 76, 56, 80, 88
;---------------------------------------------------------------------------
RedArremerFlyHeights:
