        clr.b   O_Step2(a5)                     ; 0EC5E/0EBAC
l_0EC62:
        rts                                     ; 0EC62/0EBB0
RedArremer_RageTimer:
        tst.b   RA_Rage(a5)                     ; 0EC64/0EBB2
        bne.b   l_0EC86                         ; 0EC68/0EBB6
        move.w  g_GameFrame(a6),d0              ; 0EC6A/0EBB8
        addq.w  #$1,d0                          ; 0EC6E/0EBBC
        andi.w  #$1f,d0                         ; 0EC70/0EBBE
        bne.b   l_0EC86                         ; 0EC74/0EBC2
        subq.b  #$1,RA_RageTime(a5)             ; 0EC76/0EBC4  every 32 frames, only before its rage
