        bne.b   l_0ECB4                         ; 0ECA0/0EBEE
        movea.l RA_FlyPtr(a5),a0                ; 0ECA2/0EBF0
        move.b  (a0),RA_Phase(a5)               ; 0ECA6/0EBF4
        clr.b   O_Step(a5)                      ; 0ECAA/0EBF8
        clr.b   O_Step2(a5)                     ; 0ECAE/0EBFC
l_0ECB2:
        rts                                     ; 0ECB2/0EC00
l_0ECB4:
