        bsr.w   ObjectMapCollide                ; 0ECBE/0EC0C  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_0ECD4                         ; 0ECC2/0EC10
        movea.l RA_FlyPtr(a5),a0                ; 0ECC4/0EC12
