RedArremer_TooLow:
        move.w  O_Y(a5),d0                      ; 0ECD6/0EC24
        sub.w   g_CameraY(a6),d0                ; 0ECDA/0EC28
        bmi.b   l_0ECE6                         ; 0ECDE/0EC2C
        cmp.w   #$30,d0                         ; 0ECE0/0EC2E
        bhi.b   l_0ECF6                         ; 0ECE4/0EC32
l_0ECE6:
        move.b  #$1,O_Step(a5)                  ; 0ECE6/0EC34
        clr.b   O_Step2(a5)                     ; 0ECEC/0EC3A
        move.w  RA_BaseY(a5),O_Y(a5)            ; 0ECF0/0EC3E
l_0ECF6:
        rts                                     ; 0ECF6/0EC44
RedArremer_FaceArthur:
        move.w  g_ArthurX(a6),d0                ; 0ECF8/0EC46
        cmp.w   O_X(a5),d0                      ; 0ECFC/0EC4A
        shi.b   O_Dir(a5)                       ; 0ED00/0EC4E
        addq.b  #$1,O_Dir(a5)                   ; 0ED04/0EC52
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0ED08/0EC56
        bra.w   SetAnimIndexed                  ; 0ED0C/0EC5A
RedArremer_CurveUp:
        bsr.w   Animate                         ; 0ED10/0EC5E  animate
        bsr.b   RedArremer_CurveY               ; 0ED14/0EC62
        addq.b  #$8,RA_Phase(a5)                ; 0ED16/0EC64
        cmpi.b  #$a0,RA_Phase(a5)               ; 0ED1A/0EC68
        bls.b   l_0ED2C                         ; 0ED20/0EC6E
        move.b  #$80,RA_Phase(a5)               ; 0ED22/0EC70
        addq.b  #$1,O_Step2(a5)                 ; 0ED28/0EC76
l_0ED2C:
        rts                                     ; 0ED2C/0EC7A

;---------------------------------------------------------------------------
; Y = RA_BaseY + RA_RadiusY x 2 x sin(RA_Phase) / 256
;---------------------------------------------------------------------------
RedArremer_CurveY:
        clr.w   d0                              ; 0ED2E/0EC7C
        move.b  RA_Phase(a5),d0                 ; 0ED30/0EC7E
        lea.l   SineTable(pc),a0                ; 0ED34/0EC82
        move.b  (a0,d0.w),d0                    ; 0ED38/0EC86
        add.b   d0,d0                           ; 0ED3C/0EC8A
        clr.w   d1                              ; 0ED3E/0EC8C
        move.b  RA_RadiusY(a5),d1               ; 0ED40/0EC8E
        mulu.w  d0,d1                           ; 0ED44/0EC92
        lsr.w   #$8,d1                          ; 0ED46/0EC94
        add.w   RA_BaseY(a5),d1                 ; 0ED48/0EC96
        move.w  d1,O_Y(a5)                      ; 0ED4C/0EC9A
        rts                                     ; 0ED50/0EC9E
RedArremer_TooFarToDive:
        move.b  #$5,O_Step(a5)                  ; 0ED52/0ECA0
        move.b  #$3,O_Step2(a5)                 ; 0ED58/0ECA6
        move.b  #$80,RA_Phase(a5)               ; 0ED5E/0ECAC
        rts                                     ; 0ED64/0ECB2

;---------------------------------------------------------------------------
; State 2: sound 12, EnemyBurst, 63 frames
;---------------------------------------------------------------------------
RedArremer_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0ED66/0ECB4
        beq.b   l_0ED80                         ; 0ED6C/0ECBA
        bcc.b   l_0ED84                         ; 0ED6E/0ECBC
        moveq   #SFX_ENEMY_HIT,d0               ; 0ED70/0ECBE
        bsr.w   PlaySfx                         ; 0ED72/0ECC0  sound effect 12 (weapon/boss hit)
        move.b  #$3f,RA_RadiusX(a5)             ; 0ED76/0ECC4
        addq.b  #$1,O_Step(a5)                  ; 0ED7C/0ECCA  next step
l_0ED80:
        bra.w   EnemyBurst                      ; 0ED80/0ECCE
l_0ED84:
        move.b  #$2,O_Size(a5)                  ; 0ED84/0ECD2
        subq.b  #$1,RA_RadiusX(a5)              ; 0ED8A/0ECD8
        bne.b   l_0ED96                         ; 0ED8E/0ECDC
        move.b  #ST_REMOVE,O_State(a5)          ; 0ED90/0ECDE
l_0ED96:
        rts                                     ; 0ED96/0ECE4

;---------------------------------------------------------------------------
; State 3: free, give the spawn quota back
;---------------------------------------------------------------------------
RedArremer_Free:
        clr.b   (a5)                            ; 0ED98/0ECE6  free this enemy slot
        addq.b  #$1,g_SpawnQuota+5(a6)          ; 0ED9A/0ECE8
        tst.b   g_BigEnemyCount(a6)             ; 0ED9E/0ECEC
        beq.b   l_0EDA8                         ; 0EDA2/0ECF0
        subq.b  #$1,g_BigEnemyCount(a6)         ; 0EDA4/0ECF2
l_0EDA8:
        rts                                     ; 0EDA8/0ECF6
RedArremer_AnimPerch:
	AF	$03,5
	AL	$04,5,RedArremer_AnimPerch
RedArremer_AnimWalk:
	dc.w	RedArremer_AnimWalk_0-*	; 0
	dc.w	RedArremer_AnimWalk_1-*	; 1
RedArremer_AnimWalk_0:
	AF	$08,3
	AF	$09,3
	AF	$0A,3
	AL	$09,3,RedArremer_AnimWalk_0
RedArremer_AnimWalk_1:
	AF	$00,3
	AF	$01,3
	AF	$02,3
	AL	$01,3,RedArremer_AnimWalk_1
RedArremer_AnimFly:
	dc.w	RedArremer_AnimFly_0-*	; 0
	dc.w	RedArremer_AnimFly_1-*	; 1
RedArremer_AnimFly_0:
	AF	$14,3
	AF	$15,3
	AF	$16,3
