;---------------------------------------------------------------------------
; === Satan (type 6, 3000 pts, 4 hits (boss)) ===
; Big winged demon boss of levels 4-5: flies at Arthur, fires, and on its last hit calls BossKilled (key drop / weapon check).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Sleeps until it is in view (parameter 1: for a further 6 x 64 frames, during which
;     it can be hit; 3 hits wake it, but its HP is then reset to 4).
;   * Hovers for 180 frames, drifting slowly (one of 4 directions, re-chosen every
;     128 frames; always down when Arthur is 64+ pixels below), turning to face Arthur.
;     While hovering it fires (enemy shot type 11, aimed in 16 directions) every 45-65
;     frames, and every 47-90 frames folds its wings for 30 frames, when shots pass
;     through it (O_Active bit 7).
;   * Then attacks: from above, a U-shaped dive (sine curve) down to around Arthur's
;     height and up again while flying across at 2-2.25 px/frame; level with Arthur, it
;     flies across and climbs out of the second half of the dive; from below, it flies
;     straight at him at 3.5 px/frame. Then it hovers again.
;   * If it leaves the screen it flies back in for 16-31 frames, then attacks again.
; Bug: the dying state waits for its timer to reach 0 the wrong way round (beq instead
; of bne), so the 63-frame pause after the explosion is skipped.
;---------------------------------------------------------------------------
Enemy_Satan:
        move.b  O_State(a5),d0                  ; 0EE1C/0ED6A
        add.w   d0,d0                           ; 0EE20/0ED6E
        add.w   d0,d0                           ; 0EE22/0ED70
        jmp     Enemy_Satan_Jumps(pc,d0.w)      ; 0EE24/0ED72
Enemy_Satan_Jumps:
        bra.w   Satan_Init                      ; 0EE28/0ED76
        bra.w   Satan_Active                    ; 0EE2C/0ED7A
        bra.w   Satan_Dying                     ; 0EE30/0ED7E
        bra.w   Satan_Free                      ; 0EE34/0ED82

;---------------------------------------------------------------------------
; State 0: 4 HP, size class 4, face Arthur, then sleep until in view
;---------------------------------------------------------------------------
Satan_Init:
        tst.b   O_Step(a5)                      ; 0EE38/0ED86
        bne.b   Satan_Sleep                     ; 0EE3C/0ED8A
        move.b  #$4,O_HP(a5)                    ; 0EE3E/0ED8C
        move.b  #$4,O_Size(a5)                  ; 0EE44/0ED92
        move.w  O_X(a5),d0                      ; 0EE4A/0ED98
        cmp.w   g_ArthurX(a6),d0                ; 0EE4E/0ED9C
        slt.b   O_Dir(a5)                       ; 0EE52/0EDA0  O_Dir 0 if Arthur is to the right, 1 if to the left
        addq.b  #$1,O_Dir(a5)                   ; 0EE56/0EDA4
        lea.l   Satan_AnimGuard(pc),a0          ; 0EE5A/0EDA8
        bsr.w   SetAnimIndexed                  ; 0EE5E/0EDAC  start animation for current direction
        clr.b   Sat_Returning(a5)               ; 0EE62/0EDB0
        clr.b   Sat_Hold(a5)                    ; 0EE66/0EDB4
        move.b  #$6,Sat_WakeDelay(a5)           ; 0EE6A/0EDB8
        addq.b  #$1,O_Step(a5)                  ; 0EE70/0EDBE  next step
        rts                                     ; 0EE74/0EDC2

;---------------------------------------------------------------------------
; Shots pass through while it sleeps ($81). Wake when inside the camera window
; (0-256, 0-240); parameter 1 waits a further Sat_WakeDelay x 64 frames.
;---------------------------------------------------------------------------
Satan_Sleep:
        move.b  #$81,(a5)                       ; 0EE76/0EDC4  active, shots pass through
        move.w  O_X(a5),d0                      ; 0EE7A/0EDC8
        sub.w   g_CameraX(a6),d0                ; 0EE7E/0EDCC
        cmp.w   #$100,d0                        ; 0EE82/0EDD0
        bhi.b   l_0EED2                         ; 0EE86/0EDD4
        move.w  O_Y(a5),d0                      ; 0EE88/0EDD6
        sub.w   g_CameraY(a6),d0                ; 0EE8C/0EDDA
        cmp.w   #$f0,d0                         ; 0EE90/0EDDE
        bhi.b   l_0EED2                         ; 0EE94/0EDE2
        tst.b   O_Param(a5)                     ; 0EE96/0EDE4
        beq.b   l_0EEBA                         ; 0EE9A/0EDE8
        move.b  #$1,(a5)                        ; 0EE9C/0EDEA
        cmpi.b  #$1,O_HP(a5)                    ; 0EEA0/0EDEE  parameter 1 is hittable while it waits: down to 1 HP wakes it at once
        beq.b   l_0EEBA                         ; 0EEA6/0EDF4
        moveq   #$3f,d0                         ; 0EEA8/0EDF6  every 64 frames
        and.w   g_GameFrame(a6),d0              ; 0EEAA/0EDF8
        cmp.w   #$3f,d0                         ; 0EEAE/0EDFC
        bne.b   l_0EED2                         ; 0EEB2/0EE00
        subq.b  #$1,Sat_WakeDelay(a5)           ; 0EEB4/0EE02
        bne.b   l_0EED2                         ; 0EEB8/0EE06
l_0EEBA:
        move.b  #$4,O_HP(a5)                    ; 0EEBA/0EE08  4 hits (damage taken while waiting is forgotten)
        move.b  #ST_ACTIVE,O_State(a5)          ; 0EEC0/0EE0E
        clr.b   O_Step(a5)                      ; 0EEC6/0EE14
        clr.b   O_Step2(a5)                     ; 0EECA/0EE18
        move.b  #$1,(a5)                        ; 0EECE/0EE1C
l_0EED2:
        rts                                     ; 0EED2/0EE20

;---------------------------------------------------------------------------
; State 1. O_Step 0 = hover (O_Step2 0 count, 1 set up, 2 face, 3 hover),
; O_Step 1 = attack (O_Step2 0 aim, 1 dive, 2 fly to the dive point, 3 fly straight).
;---------------------------------------------------------------------------
Satan_Active:
        tst.b   O_Step(a5)                      ; 0EED4/0EE22
        bne.w   Satan_Attack                    ; 0EED8/0EE26
        clr.w   d0                              ; 0EEDC/0EE2A
        move.b  O_Step2(a5),d0                  ; 0EEDE/0EE2C
        add.w   d0,d0                           ; 0EEE2/0EE30
        add.w   d0,d0                           ; 0EEE4/0EE32
        jmp     Satan_Active_Jumps(pc,d0.w)     ; 0EEE6/0EE34
Satan_Active_Jumps:
        bra.w   Satan_Engage                    ; 0EEEA/0EE38
        bra.w   Satan_HoverStart                ; 0EEEE/0EE3C
        bra.w   Satan_Face                      ; 0EEF2/0EE40
        bra.w   Satan_Hover                     ; 0EEF6/0EE44
Satan_Engage:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0EEFA/0EE48
        addq.b  #$1,O_Step2(a5)                 ; 0EEFE/0EE4C
        rts                                     ; 0EF02/0EE50

;---------------------------------------------------------------------------
; 180 frames of hovering
;---------------------------------------------------------------------------
Satan_HoverStart:
        move.b  #$b4,Sat_Timer(a5)              ; 0EF04/0EE52
        clr.b   Sat_FirePhase(a5)               ; 0EF0A/0EE58
        move.b  #$1e,Sat_GuardTime(a5)          ; 0EF0E/0EE5C  guard 30 frames
        bsr.w   Satan_RandomFireTime            ; 0EF14/0EE62
        move.b  d0,Sat_FireTime(a5)             ; 0EF18/0EE66
        clr.b   Sat_Swoop(a5)                   ; 0EF1C/0EE6A
        clr.b   Sat_Drift(a5)                   ; 0EF20/0EE6E
        move.w  g_ArthurX(a6),d0                ; 0EF24/0EE72
        cmp.w   O_X(a5),d0                      ; 0EF28/0EE76
        scs.b   O_Dir(a5)                       ; 0EF2C/0EE7A
        addq.b  #$1,O_Dir(a5)                   ; 0EF30/0EE7E
        addq.b  #$1,O_Step2(a5)                 ; 0EF34/0EE82
        rts                                     ; 0EF38/0EE86
Satan_Face:
        lea.l   Satan_AnimHover(pc),a0          ; 0EF3A/0EE88
        bsr.w   SetAnimIndexed                  ; 0EF3E/0EE8C  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0EF42/0EE90
Satan_Hover:
        bsr.w   Animate                         ; 0EF46/0EE94  animate
        bsr.w   Satan_KeepOnScreen              ; 0EF4A/0EE98
        tst.b   Sat_Returning(a5)               ; 0EF4E/0EE9C
        bne.b   l_0EF94                         ; 0EF52/0EEA0
        tst.b   Sat_Hold(a5)                    ; 0EF54/0EEA2
        bne.b   l_0EF8E                         ; 0EF58/0EEA6
        move.w  O_X(a5),d0                      ; 0EF5A/0EEA8  turn round when Arthur passes it
        cmp.w   g_ArthurX(a6),d0                ; 0EF5E/0EEAC
        scs.b   d0                              ; 0EF62/0EEB0
        addq.b  #$1,d0                          ; 0EF64/0EEB2
        cmp.b   O_Dir(a5),d0                    ; 0EF66/0EEB4
        beq.b   l_0EF76                         ; 0EF6A/0EEB8
        move.b  d0,O_Dir(a5)                    ; 0EF6C/0EEBA
        move.b  #$2,O_Step2(a5)                 ; 0EF70/0EEBE
l_0EF76:
        bsr.b   Satan_FireCycle                 ; 0EF76/0EEC4
        subq.b  #$1,Sat_Timer(a5)               ; 0EF78/0EEC6
        bne.b   l_0EF9A                         ; 0EF7C/0EECA
l_0EF7E:
        move.b  #$1,O_Step(a5)                  ; 0EF7E/0EECC
        clr.b   O_Step2(a5)                     ; 0EF84/0EED2
        move.b  #$1,(a5)                        ; 0EF88/0EED6
        rts                                     ; 0EF8C/0EEDA
l_0EF8E:
        subq.b  #$1,Sat_Timer(a5)               ; 0EF8E/0EEDC
        beq.b   l_0EF7E                         ; 0EF92/0EEE0
l_0EF94:
        move.b  #$1,(a5)                        ; 0EF94/0EEE2
        rts                                     ; 0EF98/0EEE6
l_0EF9A:
        moveq   #$7f,d0                         ; 0EF9A/0EEE8  every 128 frames pick a new drift
        and.w   g_GameFrame(a6),d0              ; 0EF9C/0EEEA
        cmp.w   #$7f,d0                         ; 0EFA0/0EEEE
        bne.b   l_0EFC8                         ; 0EFA4/0EEF2
        move.w  g_ArthurY(a6),d0                ; 0EFA6/0EEF4  Arthur 64+ px below: drift down
        addi.w  #$40,d0                         ; 0EFAA/0EEF8
        sub.w   O_Y(a5),d0                      ; 0EFAE/0EEFC
        bpl.b   l_0EFBC                         ; 0EFB2/0EF00
        moveq   #$3,d0                          ; 0EFB4/0EF02
        move.b  d0,Sat_Drift(a5)                ; 0EFB6/0EF04
        bra.b   l_0EFC8                         ; 0EFBA/0EF08
l_0EFBC:
        bsr.w   Random                          ; 0EFBC/0EF0A  random number
        andi.b  #$3,d0                          ; 0EFC0/0EF0E
        move.b  d0,Sat_Drift(a5)                ; 0EFC4/0EF12
l_0EFC8:
        lea.l   Satan_DriftSpeed(pc),a0         ; 0EFC8/0EF16
        move.b  Sat_Drift(a5),d0                ; 0EFCC/0EF1A
        bsr.w   Satan_MoveDir                   ; 0EFD0/0EF1E
        bra.w   Satan_KeepAboveGround           ; 0EFD4/0EF22

;---------------------------------------------------------------------------
; Hover drift (8.8): +-0.44 px/frame horizontally (0, 1), vertically (2, 3)
;---------------------------------------------------------------------------
Satan_DriftSpeed:
	dc.b	$00,$70,$FF,$90,$00,$70,$FF,$90

;---------------------------------------------------------------------------
; Shoot every Sat_ShotWait frames for Sat_FireTime frames, then guard for 30 frames
; (shots pass through), then start again
;---------------------------------------------------------------------------
Satan_FireCycle:
        tst.b   Sat_FirePhase(a5)               ; 0EFE0/0EF2E
        bne.b   l_0F008                         ; 0EFE4/0EF32
        tst.b   O_OnScreen(a5)                  ; 0EFE6/0EF34
        beq.b   l_0EFFC                         ; 0EFEA/0EF38
        subq.b  #$1,Sat_ShotWait(a5)            ; 0EFEC/0EF3A  shot gap
        bne.b   l_0EFFC                         ; 0EFF0/0EF3E
        bsr.w   Satan_Shoot                     ; 0EFF2/0EF40
        bsr.b   Satan_RandomShotGap             ; 0EFF6/0EF44
        move.b  d0,Sat_ShotWait(a5)             ; 0EFF8/0EF46
l_0EFFC:
        subq.b  #$1,Sat_FireTime(a5)            ; 0EFFC/0EF4A
        bne.b   l_0F052                         ; 0F000/0EF4E
        addq.b  #$1,Sat_FirePhase(a5)           ; 0F002/0EF50
        rts                                     ; 0F006/0EF54
l_0F008:
        cmpi.b  #$1,Sat_FirePhase(a5)           ; 0F008/0EF56
