        rts                                     ; 0F3F0/0F33E
Satan_AnimHover:
	dc.w	Satan_AnimHover_0-*	; 0
	dc.w	Satan_AnimFlap-*	; 1
Satan_AnimHover_0:
	AF	$05,10
	AF	$06,10
	AF	$07,10
	AL	$06,10,Satan_AnimHover_0

;---------------------------------------------------------------------------
; Satan flapping: frames 0, 1, 2, 1 (also the opening scene's demon)
;---------------------------------------------------------------------------
Satan_AnimFlap:
	AF	$00,10
	AF	$01,10
	AF	$02,10
	AL	$01,10,Satan_AnimFlap
Satan_AnimDive:
	dc.w	Satan_AnimReturnR-*	; 0
	dc.w	Satan_AnimReturnL-*	; 1
Satan_AnimReturnL:
	AL	$08,5,Satan_AnimReturnL
Satan_AnimReturnR:
	AL	$03,5,Satan_AnimReturnR
Satan_AnimGuard:
	dc.w	Satan_AnimGuard_0-*	; 0
	dc.w	Satan_AnimWings-*	; 1
Satan_AnimGuard_0:
	AL	$04,5,Satan_AnimGuard_0

;---------------------------------------------------------------------------
; Satan, wings spread (frame 4, held)
;---------------------------------------------------------------------------
Satan_AnimWings:
	AL	$04,5,Satan_AnimWings

;---------------------------------------------------------------------------
; === Magician (type 7, 2000 pts) ===
; Rises from a gravestone Arthur has shot (spawned at g_SceneryHitX/Y), throws off its cloak, casts one spell (enemy shot type 0: turns Arthur into a frog) and fades away. Sound effect 17 when killed.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: the spawner puts it where Arthur last shot a gravestone. It rises
; cloaked for 60 + 20 frames (shots pass through: O_Active 2), throws off the cloak and
; becomes hittable (size class 9), casts one spell at Arthur - enemy shot type 0, which turns
; him into a frog (EnemyShotsVsArthur) - waits 20 frames, then cloaks again and blinks out
; over 60 frames. The graphics are the hooded figure (frames 0-1) and the winged figure
; (frames 2-3).
;---------------------------------------------------------------------------
Enemy_Magician:
        move.b  O_State(a5),d0                  ; 0F422/0F370
        add.w   d0,d0                           ; 0F426/0F374
        add.w   d0,d0                           ; 0F428/0F376
        jmp     Enemy_Magician_Jumps(pc,d0.w)   ; 0F42A/0F378
Enemy_Magician_Jumps:
        bra.w   Magician_Init                   ; 0F42E/0F37C
        bra.w   Magician_Active                 ; 0F432/0F380
        bra.w   Magician_Dying                  ; 0F436/0F384
        bra.w   Magician_Free                   ; 0F43A/0F388

;---------------------------------------------------------------------------
; State 0: shots pass through (O_Active 2), size 3, face Arthur, cloaked
;---------------------------------------------------------------------------
Magician_Init:
        move.b  #$2,(a5)                        ; 0F43E/0F38C
        move.b  #$3,O_Size(a5)                  ; 0F442/0F390
        bsr.w   Magician_FaceArthur             ; 0F448/0F396
        lea.l   Magician_AnimCloak(pc),a0       ; 0F44A/0F398
        bsr.w   SetAnimIndexed                  ; 0F44E/0F39C  start animation for current direction
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0F452/0F3A0
        clr.b   O_Step(a5)                      ; 0F456/0F3A4
        clr.b   O_Step2(a5)                     ; 0F45A/0F3A8
        rts                                     ; 0F45E/0F3AC

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
Magician_FaceArthur:
        move.w  g_ArthurX(a6),d0                ; 0F460/0F3AE
        cmp.w   O_X(a5),d0                      ; 0F464/0F3B2
        scs.b   O_Dir(a5)                       ; 0F468/0F3B6
        neg.b   O_Dir(a5)                       ; 0F46C/0F3BA
        rts                                     ; 0F470/0F3BE

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 cast, 2 fade
;---------------------------------------------------------------------------
Magician_Active:
        move.b  O_Step(a5),d0                   ; 0F472/0F3C0
        add.w   d0,d0                           ; 0F476/0F3C4
        add.w   d0,d0                           ; 0F478/0F3C6
        jmp     Magician_Active_Jumps(pc,d0.w)  ; 0F47A/0F3C8
Magician_Active_Jumps:
        bra.w   Magician_Rise                   ; 0F47E/0F3CC
        bra.w   Magician_Cast                   ; 0F482/0F3D0
        bra.w   Magician_Fade                   ; 0F486/0F3D4

;---------------------------------------------------------------------------
; 60 frames, turning to face Arthur
;---------------------------------------------------------------------------
Magician_Rise:
        tst.b   O_Step2(a5)                     ; 0F48A/0F3D8
        bne.b   l_0F49A                         ; 0F48E/0F3DC
        move.b  #$3c,Mag_Timer(a5)              ; 0F490/0F3DE
snd139_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd139_512                      
        move    (a7)+,ccr                       
        moveq   #$3,d0                          ;      /0F3E4
        bra.w   snd139_end                      
snd139_512:
        move    (a7)+,ccr                       
snd139_end:
        addq.b  #$1,O_Step2(a5)                 ; 0F496/0F3E6
l_0F49A:
        subq.b  #$1,Mag_Timer(a5)               ; 0F49A/0F3EA
        beq.b   l_0F4A2                         ; 0F49E/0F3EE
        bra.b   Magician_FaceArthur             ; 0F4A0/0F3F0
l_0F4A2:
        addq.b  #$1,O_Step(a5)                  ; 0F4A2/0F3F2  next step
        clr.b   O_Step2(a5)                     ; 0F4A6/0F3F6
        rts                                     ; 0F4AA/0F3FA
Magician_Cast:
        move.b  O_Step2(a5),d0                  ; 0F4AC/0F3FC
        add.w   d0,d0                           ; 0F4B0/0F400
        add.w   d0,d0                           ; 0F4B2/0F402
        jmp     Magician_Cast_Jumps(pc,d0.w)    ; 0F4B4/0F404
Magician_Cast_Jumps:
        bra.w   Magician_CastStart              ; 0F4B8/0F408
        bra.w   Magician_Reveal                 ; 0F4BC/0F40C
        bra.w   Magician_AfterCast              ; 0F4C0/0F410
Magician_CastStart:
        move.b  #$14,Mag_Cast(a5)               ; 0F4C4/0F414
        addq.b  #$1,O_Step2(a5)                 ; 0F4CA/0F41A

;---------------------------------------------------------------------------
; After 20 frames: hittable, size 9, the winged figure, and cast the spell
;---------------------------------------------------------------------------
Magician_Reveal:
        subq.b  #$1,Mag_Cast(a5)                ; 0F4CE/0F41E
        bne.b   l_0F4F4                         ; 0F4D2/0F422
        move.b  #$1,(a5)                        ; 0F4D4/0F424  hittable from now on
        move.b  #$9,O_Size(a5)                  ; 0F4D8/0F428
        bsr.w   Magician_FaceArthur             ; 0F4DE/     
        lea.l   Magician_AnimReveal(pc),a0      ; 0F4E0/0F432
        bsr.w   SetAnimIndexed                  ; 0F4E4/0F436  start animation for current direction
        bsr.b   Magician_Spell                  ; 0F4E8/0F43A
        move.b  #$14,Mag_Cast(a5)               ; 0F4EA/0F43C
        addq.b  #$1,O_Step2(a5)                 ; 0F4F0/0F442
l_0F4F4:
        bra.w   Animate                         ; 0F4F4/0F446

;---------------------------------------------------------------------------
; 20 frames, then fade
;---------------------------------------------------------------------------
Magician_AfterCast:
        subq.b  #$1,Mag_Cast(a5)                ; 0F4F8/0F44A
        bne.b   l_0F508                         ; 0F4FC/0F44E
        move.b  #$2,O_Step(a5)                  ; 0F4FE/0F450
        clr.b   O_Step2(a5)                     ; 0F504/0F456
l_0F508:
        rts                                     ; 0F508/0F45A

;---------------------------------------------------------------------------
; Enemy shot type 0 (the frog spell) from 10 px below its centre, the way it faces
;---------------------------------------------------------------------------
Magician_Spell:
        bsr.w   FindFreeEnemyShot               ; 0F50A/0F45C  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0F53A                         ; 0F50E/0F460
        move.b  O_Dir(a5),$12(a4)               ; 0F510/0F462
        move.w  O_X(a5),$6(a4)                  ; 0F516/0F468
        moveq   #-10,d0                         ; 0F51C/0F46E
        add.w   O_Y(a5),d0                      ; 0F51E/0F470
        move.w  d0,$a(a4)                       ; 0F522/0F474
        clr.b   $3(a4)                          ; 0F526/0F478
        clr.b   $4(a4)                          ; 0F52A/0F47C
        clr.b   $5(a4)                          ; 0F52E/0F480
        move.b  #$1,(a4)                        ; 0F532/0F484
        clr.b   $1a(a4)                         ; 0F536/0F488  enemy shot type 0: the frog spell
l_0F53A:
        rts                                     ; 0F53A/0F48C

;---------------------------------------------------------------------------
; Cloak again, shots pass through, blink for 60 frames, then remove
;---------------------------------------------------------------------------
Magician_Fade:
        tst.b   O_Step2(a5)                     ; 0F53C/0F48E
        bne.b   l_0F562                         ; 0F540/0F492
        move.b  #$3c,Mag_Timer(a5)              ; 0F542/0F494
        move.b  #$2,(a5)                        ; 0F548/0F49A  shots pass through again
        move.b  #$3,O_Size(a5)                  ; 0F54C/0F49E
        bsr.w   Magician_FaceArthur             ; 0F552/0F4A4
        lea.l   Magician_AnimCloak(pc),a0       ; 0F556/0F4A8
        bsr.w   SetAnimIndexed                  ; 0F55A/0F4AC  start animation for current direction
snd141_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd141_512                      
        move    (a7)+,ccr                       
        moveq   #$3,d0                          ;      /0F4B0
        bra.w   snd141_end                      
snd141_512:
        move    (a7)+,ccr                       
snd141_end:
        addq.b  #$1,O_Step2(a5)                 ; 0F55E/0F4B2
l_0F562:
        subq.b  #$1,Mag_Timer(a5)               ; 0F562/0F4B6
        bne.b   l_0F570                         ; 0F566/0F4BA
        move.b  #ST_REMOVE,O_State(a5)          ; 0F568/0F4BC
        rts                                     ; 0F56E/0F4C2
l_0F570:
        moveq   #$2,d0                          ; 0F570/0F4C4  invisible every other 2 frames
        and.w   g_GameFrame(a6),d0              ; 0F572/0F4C6
        beq.b   l_0F57C                         ; 0F576/0F4CA
        clr.l   O_Anim(a5)                      ; 0F578/0F4CC
l_0F57C:
        lea.l   Magician_AnimCloak(pc),a0       ; 0F57C/0F4D0
        bsr.w   SetAnimIndexed                  ; 0F580/0F4D4  start animation for current direction
        bra.w   CheckFarAway                    ; 0F584/0F4D8

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing, 63 frames
;---------------------------------------------------------------------------
Magician_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0F588/0F4DC
        beq.b   l_0F5A4                         ; 0F58E/0F4E2
        bcc.b   l_0F5A8                         ; 0F590/0F4E4
        moveq   #SFX_ENEMY_DIE,d0               ; 0F592/0F4E6
        bsr.w   PlaySfx                         ; 0F594/0F4E8  sound effect 17 (enemy event)
        move.b  #$3f,Mag_Timer(a5)              ; 0F598/0F4EC
        addq.b  #$1,O_Step(a5)                  ; 0F59E/0F4F2  next step
        rts                                     ; 0F5A2/0F4F6
l_0F5A4:
        bra.w   EnemyDieFacing                  ; 0F5A4/0F4F8
l_0F5A8:
        move.b  #$2,O_Size(a5)                  ; 0F5A8/0F4FC
        subq.b  #$1,Mag_Timer(a5)               ; 0F5AE/0F502
        bne.b   l_0F5BA                         ; 0F5B2/0F506
        move.b  #ST_REMOVE,O_State(a5)          ; 0F5B4/0F508
l_0F5BA:
        rts                                     ; 0F5BA/0F50E

;---------------------------------------------------------------------------
; State 3: give the spawn quota back, free the slot
;---------------------------------------------------------------------------
Magician_Free:
        addq.b  #$1,g_SpawnQuota+7(a6)          ; 0F5BC/0F510
        clr.b   (a5)                            ; 0F5C0/0F514  free this enemy slot
        rts                                     ; 0F5C2/0F516
Magician_AnimCloak:
	dc.w	Magician_AnimCloak_0-*	; 0
	dc.w	Magician_AnimCloak_1-*	; 1
Magician_AnimReveal:
	dc.w	Magician_AnimReveal_0-*	; 0
	dc.w	Magician_AnimReveal_1-*	; 1
Magician_AnimCloak_0:
	AL	$00,1,Magician_AnimCloak_0
Magician_AnimCloak_1:
	AL	$01,1,Magician_AnimCloak_1
Magician_AnimReveal_0:
	AL	$03,1,Magician_AnimReveal_0
Magician_AnimReveal_1:
	AL	$02,1,Magician_AnimReveal_1

;---------------------------------------------------------------------------
; === Unicorn (Cyclops) (type 8, 2000 pts, 10 hits (boss)) ===
; Boss of level 0 (one, at the gate) and level 1 (two); also on level 5. Drawn as two BOBs (legs + body).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits (Uni_Delay x 16 frames) once Arthur is near its level, then walks to a walk
;     script, turning back at the edges of its arena (Unicorn_ChooseWalkDir).
;   * Fires a shot (enemy shot type 1, straight ahead) whenever Unicorn_ShotScript says so:
;     fire pose for 40 frames, shot, 25 frames recovery.
;   * Jumps over Arthur's weapons: any of Arthur's shots flying towards it within 56 pixels
;     starts a jump (Unicorn_CheckThreats).
;   * Keeps its distance: Uni_Approach asks to walk towards Arthur when he is 120+ pixels away
;     and away from him when closer than 32 (unicorn on the left) / 56 (on the right).
;   * After a random 51-130 frames it gets angry: next it either charges at Arthur
;     (Unicorn_Charge) or jumps at him (Unicorn_JumpAt), 50/50 (always the charge for variant 2).
;---------------------------------------------------------------------------
Enemy_Unicorn:
        move.b  O_State(a5),d0                  ; 0F5DC/0F530
        add.w   d0,d0                           ; 0F5E0/0F534
        add.w   d0,d0                           ; 0F5E2/0F536
        jmp     Enemy_Unicorn_Jumps(pc,d0.w)    ; 0F5E4/0F538
Enemy_Unicorn_Jumps:
        bra.w   Unicorn_Init                    ; 0F5E8/0F53C
        bra.w   Unicorn_Active                  ; 0F5EC/0F540
        bra.w   Unicorn_Dying                   ; 0F5F0/0F544
        bra.w   Unicorn_Free                    ; 0F5F4/0F548

;---------------------------------------------------------------------------
; State 0: set up the slot (10 HP, size class 4, scripts, start delay) then wait
; until it is on screen.
;---------------------------------------------------------------------------
Unicorn_Init:
        tst.b   O_Step(a5)                      ; 0F5F8/0F54C
        bne.w   Unicorn_WaitVisible             ; 0F5FC/0F550
        clr.b   Uni_Timer(a5)                   ; 0F600/0F554
        clr.b   Uni_Aiming(a5)                  ; 0F604/0F558
        clr.b   Uni_Angry(a5)                   ; 0F608/0F55C
        clr.b   Uni_Approach(a5)                ; 0F60C/0F560
        clr.b   Uni_Gravity(a5)                 ; 0F610/0F564
        clr.b   Uni_Delay(a5)                   ; 0F614/0F568
        clr.w   Uni_ChargeX(a5)                 ; 0F618/0F56C
        clr.b   Uni_JumpNext(a5)                ; 0F61C/0F570
        move.b  O_Param(a5),Uni_Variant(a5)     ; 0F620/0F574  variant from the spawn parameter
        move.b  #$4,O_Size(a5)                  ; 0F626/0F57A
        move.w  O_X(a5),d0                      ; 0F62C/0F580
        cmp.w   g_ArthurX(a6),d0                ; 0F630/0F584
        slt.b   O_Dir(a5)                       ; 0F634/0F588  face Arthur: O_Dir = 1 (right) if he is to the right, else 2 (left)
        addq.b  #$2,O_Dir(a5)                   ; 0F638/0F58C
        lea.l   Unicorn_AnimStand(pc),a0        ; 0F63C/0F590
        move.l  a0,Uni_AnimSet(a5)              ; 0F640/0F594
        bsr.w   SetAnimIndexed                  ; 0F644/0F598  start animation for current direction
        clr.b   O_AnimTimer(a5)                 ; 0F648/0F59C
        bsr.w   Animate                         ; 0F64C/0F5A0  animate
        lea.l   Unicorn_ShotScript(pc),a0       ; 0F650/0F5A4
        move.b  (a0)+,Uni_ShotWait(a5)          ; 0F654/0F5A8
        move.l  a0,Uni_ShotPtr(a5)              ; 0F658/0F5AC
        move.b  #$a,O_HP(a5)                    ; 0F65C/0F5B0  10 hits
        move.b  Uni_Variant(a5),d0              ; 0F662/0F5B6
        cmp.b   #$4,d0                          ; 0F666/0F5BA  variant 4: becomes variant 0, delay 10
        beq.b   l_0F67C                         ; 0F66A/0F5BE
        cmp.b   #$3,d0                          ; 0F66C/0F5C0  variant 3: becomes variant 2, delay 10
        bne.b   l_0F680                         ; 0F670/0F5C4
        subq.b  #$1,d0                          ; 0F672/0F5C6
l_0F674:
        move.b  d0,Uni_Variant(a5)              ; 0F674/0F5C8
        moveq   #$a,d0                          ; 0F678/0F5CC
        bra.b   l_0F692                         ; 0F67A/0F5CE
l_0F67C:
        clr.b   d0                              ; 0F67C/0F5D0
        bra.b   l_0F674                         ; 0F67E/0F5D2
l_0F680:
        lea.l   Unicorn_StartDelays(pc),a0      ; 0F680/0F5D4  otherwise a delay of 2-4 x 16 frames
        move.w  g_GameFrame(a6),d0              ; 0F684/0F5D8
        add.w   d7,d0                           ; 0F688/0F5DC
        andi.w  #$3,d0                          ; 0F68A/0F5DE
        move.b  (a0,d0.w),d0                    ; 0F68E/0F5E2
l_0F692:
        move.b  d0,Uni_Delay(a5)                ; 0F692/0F5E6
        addq.b  #$1,O_Step(a5)                  ; 0F696/0F5EA  next step
        rts                                     ; 0F69A/0F5EE
Unicorn_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 0F69C/0F5F0
        beq.b   l_0F6B0                         ; 0F6A0/0F5F4
        move.b  #ST_ACTIVE,O_State(a5)          ; 0F6A2/0F5F6
        clr.b   O_Step(a5)                      ; 0F6A8/0F5FC
        clr.b   O_Step2(a5)                     ; 0F6AC/0F600
l_0F6B0:
        rts                                     ; 0F6B0/0F604
	dc.b	$00

;---------------------------------------------------------------------------
; Shot timing script: one byte per shot = frames to wait; bit 7 set = last entry,
; followed by a word offset back to the loop point.
;---------------------------------------------------------------------------
Unicorn_ShotScript:
	dc.b	',> GV6H#@'
	dc.b	$16
	dc.b	'/D8TCW'
	dc.b	$CA,$FF,$EF

;---------------------------------------------------------------------------
; Start delay per spawn (x 16 frames), picked with the frame counter
;---------------------------------------------------------------------------
Unicorn_StartDelays:
	dc.b	$02,$03,$04,$03

;---------------------------------------------------------------------------
; State 1. Does nothing while Arthur is 128+ pixels above it (variant != 0).
; O_Step: 0 wait, 1 walk, 2 jump, 3 charge, 4 reposition, 5 fire.
;---------------------------------------------------------------------------
Unicorn_Active:
        move.w  O_Y(a5),d0                      ; 0F6CA/0F61E
        sub.w   g_ArthurY(a6),d0                ; 0F6CE/0F622
        bpl.b   l_0F6E2                         ; 0F6D2/0F626
        cmp.w   #$ff80,d0                       ; 0F6D4/0F628  Arthur 128+ pixels above it?
        bgt.b   l_0F6E2                         ; 0F6D8/0F62C
        tst.b   Uni_Variant(a5)                 ; 0F6DA/0F62E
        beq.b   l_0F6E2                         ; 0F6DE/0F632
        rts                                     ; 0F6E0/0F634
l_0F6E2:
        clr.w   d0                              ; 0F6E2/0F636
        move.b  O_Step(a5),d0                   ; 0F6E4/0F638
        add.w   d0,d0                           ; 0F6E8/0F63C
        add.w   d0,d0                           ; 0F6EA/0F63E
        jmp     Unicorn_Active_Jumps(pc,d0.w)   ; 0F6EC/0F640
Unicorn_Active_Jumps:
        bra.w   Unicorn_Wait                    ; 0F6F0/0F644
        bra.w   Unicorn_WalkStep                ; 0F6F4/0F648
        bra.w   Unicorn_JumpStep                ; 0F6F8/0F64C
        bra.w   Unicorn_Charge                  ; 0F6FC/0F650
        bra.w   Unicorn_Reposition              ; 0F700/0F654
        bra.w   Unicorn_Fire                    ; 0F704/0F658

;---------------------------------------------------------------------------
; Step 0: snap onto the floor, then count down Uni_Delay (every 16 frames).
; Level 5: does not start until Arthur is on its level. Starts at once after a hit (HP 6).
;---------------------------------------------------------------------------
Unicorn_Wait:
        tst.b   O_Step2(a5)                     ; 0F708/0F65C
        bne.b   l_0F718                         ; 0F70C/0F660
        bsr.w   ObjectMapCollide                ; 0F70E/0F662  first frame: snap onto the floor
        addq.b  #$1,O_Step2(a5)                 ; 0F712/0F666
        rts                                     ; 0F716/0F66A
l_0F718:
        cmpi.w  #$5,g_Level(a6)                 ; 0F718/0F66C  level 5: wait until Arthur is no more than 16 pixels below it
        bne.b   l_0F72E                         ; 0F71E/0F672
        move.w  g_ArthurY(a6),d0                ; 0F720/0F674
        addi.w  #$10,d0                         ; 0F724/0F678
        sub.w   O_Y(a5),d0                      ; 0F728/0F67C
        bmi.b   l_0F756                         ; 0F72C/0F680
l_0F72E:
        cmpi.b  #$6,O_HP(a5)                    ; 0F72E/0F682  already hit (6 HP left)? start at once
        beq.b   l_0F748                         ; 0F734/0F688
        move.w  g_GameFrame(a6),d0              ; 0F736/0F68A
        addq.w  #$1,d0                          ; 0F73A/0F68E
        andi.w  #$f,d0                          ; 0F73C/0F690
        bne.b   l_0F756                         ; 0F740/0F694
        subq.b  #$1,Uni_Delay(a5)               ; 0F742/0F696  every 16 frames
        bne.b   l_0F756                         ; 0F746/0F69A
l_0F748:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0F748/0F69C  one more big enemy engaged
        move.b  #$1,O_Step(a5)                  ; 0F74C/0F6A0
