        addi.w  #$100,d0                        ; 0F760/0F6B4
        cmp.w   #$400,d0                        ; 0F764/0F6B8
        bhi.b   l_0F77C                         ; 0F768/0F6BC
        move.w  O_Y(a5),d0                      ; 0F76A/0F6BE
        sub.w   g_CameraY(a6),d0                ; 0F76E/0F6C2
        addi.w  #$a0,d0                         ; 0F772/0F6C6
        cmp.w   #$240,d0                        ; 0F776/0F6CA
        bls.b   l_0F78A                         ; 0F77A/0F6CE
l_0F77C:
