        bpl.b   l_0F7B8                         ; 0F7B0/0F704  bit 7: last entry, loop
        adda.w  (a0),a0                         ; 0F7B2/0F706
        andi.b  #$7f,d0                         ; 0F7B4/0F708
l_0F7B8:
