        move.b  d0,Uni_ShotWait(a5)             ; 0F7BC/0F710
        move.b  #$1,Uni_Aiming(a5)              ; 0F7C0/0F714
        lea.l   Unicorn_AnimAim(pc),a0          ; 0F7C6/0F71A
        move.l  a0,Uni_AnimSet(a5)              ; 0F7CA/0F71E
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F7CE/0F722
        bcs.b   l_0F7D8                         ; 0F7D4/0F728
        addq.l  #$4,a0                          ; 0F7D6/0F72A
l_0F7D8:
