        bne.b   l_0F812                         ; 0F7E8/0F73C
        lea.l   Unicorn_AnimFire(pc),a0         ; 0F7EA/0F73E
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F7EE/0F742
        bcs.b   l_0F7F8                         ; 0F7F4/0F748
        addq.l  #$4,a0                          ; 0F7F6/0F74A
l_0F7F8:
