        bsr.w   Unicorn_ChooseWalkDir           ; 0F87E/0F7D2
        lea.l   Unicorn_WalkMove(pc),a0         ; 0F882/0F7D6
        move.l  a0,O_MoveTable(a5)              ; 0F886/0F7DA
        move.b  #$1,Uni_JumpType(a5)            ; 0F88A/0F7DE
        move.w  O_X(a5),d0                      ; 0F890/0F7E4
        cmp.w   g_ArthurX(a6),d0                ; 0F894/0F7E8
        blt.b   l_0F8A0                         ; 0F898/0F7EC
        move.b  #$2,Uni_JumpType(a5)            ; 0F89A/0F7EE
l_0F8A0:
