        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F8A4/0F7F8
        bcs.b   l_0F8AE                         ; 0F8AA/0F7FE
        addq.l  #$4,a0                          ; 0F8AC/0F800
l_0F8AE:
