        move.b  Uni_Variant(a5),d0              ; 0F8CA/0F81E  variants 1 and 3 start with a jump
        beq.b   l_0F8E2                         ; 0F8CE/0F822
        cmp.b   #$2,d0                          ; 0F8D0/0F824
