        cmp.w   #$78,d0                         ; 0F966/0F8BE
        bcc.b   l_0F960                         ; 0F96A/0F8C2
        subq.b  #$1,Uni_Approach(a5)            ; 0F96C/0F8C4
        cmp.w   #$38,d0                         ; 0F970/0F8C8
        bls.b   l_0F960                         ; 0F974/0F8CC
        subq.b  #$1,Uni_Approach(a5)            ; 0F976/0F8CE
        rts                                     ; 0F97A/0F8D2

