        cmpi.b  #$1,Uni_JumpType(a5)            ; 0FA88/0F9E0
        bne.b   l_0FA92                         ; 0FA8E/0F9E6
        moveq   #$f,d0                          ; 0FA90/0F9E8
l_0FA92:
