        bhi.b   l_0FB1E                         ; 0FB12/0FA6A
        btst    #$0,Uni_JumpType(a5)            ; 0FB14/0FA6C
        bne.b   l_0FB34                         ; 0FB1A/0FA72
        bra.b   l_0FAF8                         ; 0FB1C/0FA74
l_0FB1E:
