        tst.b   Uni_JumpType(a5)                ; 0FB24/0FA7C
        beq.b   l_0FAF8                         ; 0FB28/0FA80
        btst    #$0,Uni_JumpType(a5)            ; 0FB2A/0FA82
        beq.b   l_0FB34                         ; 0FB30/0FA88
