;---------------------------------------------------------------------------
Unicorn_Gravity:
	dc.b	$50,$00,$00,$06,$19,$00,$00,$01

;---------------------------------------------------------------------------
; Y += Uni_VelY, then slow it by the gravity for this phase
;---------------------------------------------------------------------------
Unicorn_RiseStep:
        move.l  Uni_VelY(a5),d0                 ; 0FB66/0FABE
        add.l   d0,O_Y(a5)                      ; 0FB6A/0FAC2
        lea.l   Unicorn_Gravity(pc),a0          ; 0FB6E/0FAC6
        tst.b   Uni_Gravity(a5)                 ; 0FB72/0FACA
        beq.b   l_0FB7A                         ; 0FB76/0FACE
        addq.l  #$4,a0                          ; 0FB78/0FAD0
l_0FB7A:
        move.w  (a0),d0                         ; 0FB7A/0FAD2
        ext.l   d0                              ; 0FB7C/0FAD4
        sub.l   d0,Uni_VelY(a5)                 ; 0FB7E/0FAD6
        rts                                     ; 0FB82/0FADA
Unicorn_JumpApproachApex:
        bsr.b   Unicorn_MoveX                   ; 0FB84/0FADC
        move.b  #$1,Uni_Gravity(a5)             ; 0FB86/0FADE
        bsr.b   Unicorn_RiseStep                ; 0FB8C/0FAE4
        cmpi.l  #$1900,Uni_VelY(a5)             ; 0FB8E/0FAE6  until it is below 0.1 px/frame
        bhi.w   Animate                         ; 0FB96/0FAEE
        addq.b  #$1,O_Step2(a5)                 ; 0FB9A/0FAF2
        rts                                     ; 0FB9E/0FAF6
Unicorn_JumpApex:
        bsr.b   Unicorn_MoveX                   ; 0FBA0/0FAF8
        move.b  #$1,Uni_Gravity(a5)             ; 0FBA2/0FAFA
        bsr.b   Unicorn_FallStep                ; 0FBA8/0FB00
        bra.w   Animate                         ; 0FBAA/0FB02

;---------------------------------------------------------------------------
; Y -= Uni_VelY, speeding up to the limit for this phase
;---------------------------------------------------------------------------
Unicorn_FallStep:
        move.l  Uni_VelY(a5),d0                 ; 0FBAE/0FB06
        sub.l   d0,O_Y(a5)                      ; 0FBB2/0FB0A
        lea.l   Unicorn_Gravity(pc),a0          ; 0FBB6/0FB0E
        tst.b   Uni_Gravity(a5)                 ; 0FBBA/0FB12
        beq.b   l_0FBC2                         ; 0FBBE/0FB16
        addq.l  #$4,a0                          ; 0FBC0/0FB18
l_0FBC2:
        move.w  Uni_VelY(a5),d0                 ; 0FBC2/0FB1A
        cmp.w   $2(a0),d0                       ; 0FBC6/0FB1E
        bhi.b   l_0FBD4                         ; 0FBCA/0FB22
        move.w  (a0),d0                         ; 0FBCC/0FB24
        ext.l   d0                              ; 0FBCE/0FB26
        add.l   d0,Uni_VelY(a5)                 ; 0FBD0/0FB28
l_0FBD4:
        tst.b   Uni_Gravity(a5)                 ; 0FBD4/0FB2C
        beq.b   l_0FBDE                         ; 0FBD8/0FB30
        addq.b  #$1,O_Step2(a5)                 ; 0FBDA/0FB32
l_0FBDE:
        rts                                     ; 0FBDE/0FB36

;---------------------------------------------------------------------------
; X += Unicorn_JumpSpeedX[Uni_JumpType] (8.8)
;---------------------------------------------------------------------------
Unicorn_MoveX:
        lea.l   Unicorn_JumpSpeedX(pc),a0       ; 0FBE0/0FB38
        move.b  Uni_JumpType(a5),d0             ; 0FBE4/0FB3C
        ext.w   d0                              ; 0FBE8/0FB40
        add.w   d0,d0                           ; 0FBEA/0FB42
        adda.w  d0,a0                           ; 0FBEC/0FB44
        move.w  (a0),d0                         ; 0FBEE/0FB46
        ext.l   d0                              ; 0FBF0/0FB48
        asl.l   #$8,d0                          ; 0FBF2/0FB4A
        add.l   d0,O_X(a5)                      ; 0FBF4/0FB4C
        rts                                     ; 0FBF8/0FB50

;---------------------------------------------------------------------------
; Horizontal speed per jump type, 8.8: odd = right, even = left, growing with the type
;---------------------------------------------------------------------------
Unicorn_JumpSpeedX:
	dc.b	$00,$00,$00,$6F,$FF,$91,$00,$F4,$FF,$0C,$01,$3E,$FE,$C2,$01,$6E
	dc.b	$FE,$92,$02,$0E,$FD,$F2,$02,$24,$FD,$DC,$02,$42,$FD,$BE,$04,$A0
	dc.b	$FB,$60

