        rts                                     ; 0FEBC/0FE22

;---------------------------------------------------------------------------
; Angry -> charge (step 3) or jump at Arthur (step 2/7), 50/50; variant 2 always charges.
; Otherwise, unless aiming: jump over any of Arthur's 4 shots that is close;
; then reposition if Uni_Approach asks for it.
;---------------------------------------------------------------------------
Unicorn_CheckThreats:
        tst.b   Uni_Angry(a5)                   ; 0FEBE/0FE24
        bne.b   l_0FF06                         ; 0FEC2/0FE28
        tst.b   Uni_Aiming(a5)                  ; 0FEC4/0FE2A
        bne.b   l_0FEF4                         ; 0FEC8/0FE2E
        clr.b   d1                              ; 0FECA/0FE30
        lea.l   g_Shots(a6),a0                  ; 0FECC/0FE32
        bsr.b   Unicorn_ShotNear                ; 0FED0/0FE36
        tst.b   d1                              ; 0FED2/0FE38
        bne.b   l_0FF04                         ; 0FED4/0FE3A
        lea.l   $26(a0),a0                      ; 0FED6/0FE3C
        bsr.b   Unicorn_ShotNear                ; 0FEDA/0FE40
        tst.b   d1                              ; 0FEDC/0FE42
        bne.b   l_0FF04                         ; 0FEDE/0FE44
        lea.l   $26(a0),a0                      ; 0FEE0/0FE46
        bsr.b   Unicorn_ShotNear                ; 0FEE4/0FE4A
        tst.b   d1                              ; 0FEE6/0FE4C
        bne.b   l_0FF04                         ; 0FEE8/0FE4E
        lea.l   $26(a0),a0                      ; 0FEEA/0FE50
        bsr.b   Unicorn_ShotNear                ; 0FEEE/0FE54
        tst.b   d1                              ; 0FEF0/0FE56
        bne.b   l_0FF04                         ; 0FEF2/0FE58
l_0FEF4:
        tst.b   Uni_Approach(a5)                ; 0FEF4/0FE5A
        beq.b   l_0FF04                         ; 0FEF8/0FE5E
        move.b  #$4,O_Step(a5)                  ; 0FEFA/0FE60
        clr.b   O_Step2(a5)                     ; 0FF00/0FE66
l_0FF04:
        rts                                     ; 0FF04/0FE6A
l_0FF06:
        cmpi.b  #$2,Uni_Variant(a5)             ; 0FF06/0FE6C  variant 2 always charges
        beq.b   l_0FF18                         ; 0FF0C/0FE72
        bsr.w   Random                          ; 0FF0E/0FE74  random number
        andi.b  #$1,d0                          ; 0FF12/0FE78
        bne.b   l_0FF24                         ; 0FF16/0FE7C
l_0FF18:
        move.b  #$3,O_Step(a5)                  ; 0FF18/0FE7E
        clr.b   O_Step2(a5)                     ; 0FF1E/0FE84
        rts                                     ; 0FF22/0FE88
l_0FF24:
        move.b  #$2,O_Step(a5)                  ; 0FF24/0FE8A  jump at Arthur
        move.b  #$7,O_Step2(a5)                 ; 0FF2A/0FE90
        rts                                     ; 0FF30/0FE96

;---------------------------------------------------------------------------
; Shot slot a0 active, on screen, not flying the way the unicorn faces and within
; +-56 pixels horizontally -> d1+1 and start a jump
;---------------------------------------------------------------------------
Unicorn_ShotNear:
        move.b  (a0),d0                         ; 0FF32/0FE98
        and.b   $1(a0),d0                       ; 0FF34/0FE9A
        beq.b   l_0FF62                         ; 0FF38/0FE9E
        move.b  Uni_JumpType(a5),d0             ; 0FF3A/0FEA0
        cmp.b   $12(a0),d0                      ; 0FF3E/0FEA4  shot flying the way the unicorn faces (away from it)? ignore
        beq.b   l_0FF62                         ; 0FF42/0FEA8
        move.w  O_X(a5),d0                      ; 0FF44/0FEAA
        sub.w   $6(a0),d0                       ; 0FF48/0FEAE
        addi.w  #$38,d0                         ; 0FF4C/0FEB2
        cmp.w   #$70,d0                         ; 0FF50/0FEB6
        bhi.b   l_0FF62                         ; 0FF54/0FEBA
        addq.b  #$1,d1                          ; 0FF56/0FEBC
        move.b  #$2,O_Step(a5)                  ; 0FF58/0FEBE
        clr.b   O_Step2(a5)                     ; 0FF5E/0FEC4
l_0FF62:
        rts                                     ; 0FF62/0FEC8

;---------------------------------------------------------------------------
; Step 5: after the wind-up, spawn enemy shot type 1 at the unicorn moving the way it
; faces, then walk on (or charge if angry)
;---------------------------------------------------------------------------
Unicorn_Fire:
        subq.b  #$1,Uni_Timer(a5)               ; 0FF64/0FECA
        bne.w   Animate                         ; 0FF68/0FECE
        bsr.w   FindFreeEnemyShot               ; 0FF6C/0FED2  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0FFC8                         ; 0FF70/0FED6
        move.w  O_X(a5),$6(a4)                  ; 0FF72/0FED8  shot starts at the unicorn
        move.w  O_Y(a5),$a(a4)                  ; 0FF78/0FEDE
        move.b  Uni_JumpType(a5),d0             ; 0FF7E/0FEE4
        subq.b  #$1,d0                          ; 0FF82/0FEE8
        move.b  d0,$12(a4)                      ; 0FF84/0FEEA
        clr.b   $3(a4)                          ; 0FF88/0FEEE
        clr.b   $4(a4)                          ; 0FF8C/0FEF2
        clr.b   $5(a4)                          ; 0FF90/0FEF6
        move.b  #$1,(a4)                        ; 0FF94/0FEFA
        move.b  #$1,$1a(a4)                     ; 0FF98/0FEFE  enemy shot type 1 (unicorn fireball)
        lea.l   Unicorn_AnimStand(pc),a0        ; 0FF9E/0FF04
        move.l  a0,Uni_AnimSet(a5)              ; 0FFA2/0FF08
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0FFA6/0FF0C
        bcs.b   l_0FFB0                         ; 0FFAC/0FF12
        addq.l  #$4,a0                          ; 0FFAE/0FF14
l_0FFB0:
        adda.w  (a0),a0                         ; 0FFB0/0FF16
        move.l  a0,O_Anim(a5)                   ; 0FFB2/0FF18
        tst.b   Uni_Angry(a5)                   ; 0FFB6/0FF1C
        bne.b   l_0FFCA                         ; 0FFBA/0FF20
        move.b  #$1,O_Step(a5)                  ; 0FFBC/0FF22
        move.b  #$1,O_Step2(a5)                 ; 0FFC2/0FF28
l_0FFC8:
        rts                                     ; 0FFC8/0FF2E
l_0FFCA:
        move.b  #$3,O_Step(a5)                  ; 0FFCA/0FF30
        clr.b   O_Step2(a5)                     ; 0FFD0/0FF36
        rts                                     ; 0FFD4/0FF3A

;---------------------------------------------------------------------------
; State 2: sound effect 12, the shared explosion (EnemyExplode), then 63 frames
;---------------------------------------------------------------------------
Unicorn_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0FFD6/0FF3C
        beq.b   l_0FFF0                         ; 0FFDC/0FF42
        bcc.b   l_0FFF4                         ; 0FFDE/0FF44
        move.b  #$3f,Uni_Timer(a5)              ; 0FFE0/0FF46
        addq.b  #$1,O_Step(a5)                  ; 0FFE6/0FF4C  next step
        moveq   #SFX_ENEMY_HIT,d0               ; 0FFEA/0FF50  sound effect 12
        bra.w   PlaySfx                         ; 0FFEC/0FF52
l_0FFF0:
        bra.w   EnemyExplode                    ; 0FFF0/0FF56
l_0FFF4:
        move.b  #$2,O_Size(a5)                  ; 0FFF4/0FF5A
        subq.b  #$1,Uni_Timer(a5)               ; 0FFFA/0FF60
        bne.b   l_10006                         ; 0FFFE/0FF64
        move.b  #ST_REMOVE,O_State(a5)          ; 10000/0FF66
l_10006:
        rts                                     ; 10006/0FF6C

;---------------------------------------------------------------------------
; State 3: free the slot. Level 1: the boss is beaten (BossKilled).
;---------------------------------------------------------------------------
Unicorn_Free:
        addq.b  #$1,g_SpawnQuota+8(a6)          ; 10008/0FF6E  give the unicorn spawn quota back
        tst.b   g_BigEnemyCount(a6)             ; 1000C/0FF72
        beq.b   l_10016                         ; 10010/0FF76
        subq.b  #$1,g_BigEnemyCount(a6)         ; 10012/0FF78  one big enemy fewer
l_10016:
        clr.b   (a5)                            ; 10016/0FF7C  free this enemy slot
        cmpi.w  #$5,g_Level(a6)                 ; 10018/0FF7E  on level 5 it is not the boss
        bne.w   BossKilled                      ; 1001E/0FF84
        rts                                     ; 10022/0FF88
Unicorn_AnimStand:
	dc.w	Unicorn_AnimStand_0-*	; 0
	dc.w	Unicorn_AnimStand_0-*	; 1
	dc.w	Unicorn_AnimStand_2-*	; 2
Unicorn_AnimStand_0:
	AF	$4F,10
	AF	$35,10
	AF	$5E,10
	AL	$35,10,Unicorn_AnimStand_0
Unicorn_AnimStand_2:
	AF	$1B,10
	AF	$01,10
	AF	$2A,10
	AL	$01,10,Unicorn_AnimStand_2
Unicorn_AnimJump:
	dc.w	Unicorn_AnimJump_0-*	; 0
	dc.w	Unicorn_AnimJump_0-*	; 1
	dc.w	Unicorn_AnimJump_2-*	; 2
Unicorn_AnimJump_0:
	AL	$54,10,Unicorn_AnimJump_0
Unicorn_AnimJump_2:
	AL	$20,10,Unicorn_AnimJump_2
Unicorn_AnimAim:
	dc.w	Unicorn_AnimAim_0-*	; 0
	dc.w	Unicorn_AnimAim_0-*	; 1
	dc.w	Unicorn_AnimAim_2-*	; 2
Unicorn_AnimAim_0:
	AF	$47,10
	AF	$45,10
	AF	$46,10
	AL	$45,10,Unicorn_AnimAim_0
Unicorn_AnimAim_2:
	AF	$13,10
	AF	$11,10
	AF	$12,10
	AL	$11,10,Unicorn_AnimAim_2
Unicorn_AnimJumpAim:
	dc.w	Unicorn_AnimJumpAim_0-*	; 0
	dc.w	Unicorn_AnimJumpAim_0-*	; 1
	dc.w	Unicorn_AnimJumpAim_2-*	; 2
Unicorn_AnimJumpAim_0:
	AL	$44,10,Unicorn_AnimJumpAim_0
Unicorn_AnimJumpAim_2:
	AL	$10,10,Unicorn_AnimJumpAim_2
Unicorn_AnimFire:
	dc.w	Unicorn_AnimFire_0-*	; 0
	dc.w	Unicorn_AnimFire_0-*	; 1
	dc.w	Unicorn_AnimFire_2-*	; 2
Unicorn_AnimFire_0:
	AL	$3D,10,Unicorn_AnimFire_0
Unicorn_AnimFire_2:
	AL	$09,10,Unicorn_AnimFire_2

;---------------------------------------------------------------------------
; === Skeleton (type 9, 100 pts) ===
; Rises out of the floor (map collision) on the castle levels. Sound effect 17.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: lies as a pile of bones (size class 0) until Arthur comes within
; 32 px of it, then rises out of the floor and hops: two small hops (3 px/frame up, 0.8
; px/frame across), turning towards Arthur when he is 64+ px away, then a big leap that
; lands where Arthur was (dx / 42 per frame, a sine arc about 80 px high), then hops again.
; It does not give its spawn quota back when it is removed (the others do).
;---------------------------------------------------------------------------
Enemy_Skeleton:
        move.b  O_State(a5),d0                  ; 10082/0FFE8
        add.w   d0,d0                           ; 10086/0FFEC
        add.w   d0,d0                           ; 10088/0FFEE
        jmp     Enemy_Skeleton_Jumps(pc,d0.w)   ; 1008A/0FFF0
Enemy_Skeleton_Jumps:
        bra.w   Skeleton_Init                   ; 1008E/0FFF4
        bra.w   Skeleton_Active                 ; 10092/0FFF8
        bra.w   Skeleton_Dying                  ; 10096/0FFFC
        bra.w   Skeleton_Free                   ; 1009A/10000

;---------------------------------------------------------------------------
; State 0: lie dormant until Arthur is within 32 px both ways
;---------------------------------------------------------------------------
Skeleton_Init:
        tst.b   O_Step(a5)                      ; 1009E/10004
        bne.b   Skeleton_Dormant                ; 100A2/10008
        clr.b   O_Size(a5)                      ; 100A4/1000A
        lea.l   Skeleton_AnimBones(pc),a0       ; 100A8/1000E
        bsr.w   SetAnim                         ; 100AC/10012  start animation
        addq.b  #$1,O_Step(a5)                  ; 100B0/10016  next step
        rts                                     ; 100B4/1001A
Skeleton_Dormant:
        tst.b   O_OnScreen(a5)                  ; 100B6/1001C
        beq.b   l_100EE                         ; 100BA/10020
        move.w  O_X(a5),d0                      ; 100BC/10022
        sub.w   g_ArthurX(a6),d0                ; 100C0/10026
        addi.w  #$20,d0                         ; 100C4/1002A
        cmp.w   #$40,d0                         ; 100C8/1002E
        bhi.b   l_100EE                         ; 100CC/10032
        move.w  O_Y(a5),d0                      ; 100CE/10034
        sub.w   g_ArthurY(a6),d0                ; 100D2/10038
        addi.w  #$20,d0                         ; 100D6/1003C
        cmp.w   #$40,d0                         ; 100DA/10040
        bhi.b   l_100EE                         ; 100DE/10044
        move.b  #ST_ACTIVE,O_State(a5)          ; 100E0/10046
        clr.b   O_Step(a5)                      ; 100E6/1004C
        clr.b   O_Step2(a5)                     ; 100EA/10050
l_100EE:
        rts                                     ; 100EE/10054

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 hop, 2 leap
;---------------------------------------------------------------------------
Skeleton_Active:
        move.b  O_Step(a5),d0                   ; 100F0/10056
        add.w   d0,d0                           ; 100F4/1005A
        add.w   d0,d0                           ; 100F6/1005C
        jsr     Skeleton_Active_Jumps(pc,d0.w)  ; 100F8/1005E
        bra.w   CheckFarAway                    ; 100FC/10062
Skeleton_Active_Jumps:
        bra.w   Skeleton_Rise                   ; 10100/10066
        bra.w   Skeleton_Hop                    ; 10104/1006A
        bra.w   Skeleton_Leap                   ; 10108/1006E
Skeleton_Rise:
        move.b  O_Step2(a5),d0                  ; 1010C/10072
        add.w   d0,d0                           ; 10110/10076
        add.w   d0,d0                           ; 10112/10078
        jmp     Skeleton_Rise_Jumps(pc,d0.w)    ; 10114/1007A
Skeleton_Rise_Jumps:
        bra.w   Skeleton_RiseStart              ; 10118/1007E
        bra.w   Skeleton_Rising1                ; 1011C/10082
        bra.w   Skeleton_Rising2                ; 10120/10086

;---------------------------------------------------------------------------
; Start rising at 3.5 px/frame
;---------------------------------------------------------------------------
Skeleton_RiseStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 10124/1008A
        move.l  a0,O_MoveTable(a5)              ; 10128/1008E
        move.b  #$4,O_Dir(a5)                   ; 1012C/10092
        move.b  #$2,O_Size(a5)                  ; 10132/10098
        lea.l   Skeleton_AnimRise(pc),a0        ; 10138/1009E
        bsr.w   SetAnim                         ; 1013C/100A2  start animation
        move.l  #$38000,Skl_VelY(a5)            ; 10140/100A6
        addq.b  #$1,O_Step2(a5)                 ; 10148/100AE
        rts                                     ; 1014C/100B2
Skeleton_Rising1:
        bsr.b   Skeleton_RiseStep               ; 1014E/100B4
        tst.b   O_AnimTimer(a5)                 ; 10150/100B6
        bne.b   l_1015A                         ; 10154/100BA
        addq.b  #$1,O_Step2(a5)                 ; 10156/100BC
l_1015A:
        rts                                     ; 1015A/100C0

;---------------------------------------------------------------------------
; when the animation ends: size 3, start hopping
;---------------------------------------------------------------------------
Skeleton_Rising2:
        bsr.b   Skeleton_RiseStep               ; 1015C/100C2
        tst.b   O_AnimTimer(a5)                 ; 1015E/100C4
        bne.b   l_10174                         ; 10162/100C8
        move.b  #$3,O_Size(a5)                  ; 10164/100CA
        move.b  #$1,O_Step(a5)                  ; 1016A/100D0
        clr.b   O_Step2(a5)                     ; 10170/100D6
l_10174:
        rts                                     ; 10174/100DA

;---------------------------------------------------------------------------
; Y += speed, speed -= 0.16
;---------------------------------------------------------------------------
Skeleton_RiseStep:
        move.w  Skl_VelY(a5),d0                 ; 10176/100DC
        add.w   d0,O_Y(a5)                      ; 1017A/100E0
        subi.l  #$2985,Skl_VelY(a5)             ; 1017E/100E4
        bra.w   Animate                         ; 10186/100EC

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 take off, 2 rise, 3 fall, 4-5 pause and aim
;---------------------------------------------------------------------------
Skeleton_Hop:
        move.b  O_Step2(a5),d0                  ; 1018A/100F0
        add.w   d0,d0                           ; 1018E/100F4
        add.w   d0,d0                           ; 10190/100F6
        jmp     Skeleton_Hop_Jumps(pc,d0.w)     ; 10192/100F8
Skeleton_Hop_Jumps:
        bra.w   snd148_go                       ;      /100FC
        bra.w   Skeleton_TakeOff                ; 1019A/10100
        bra.w   Skeleton_HopRise                ; 1019E/10104
        bra.w   Skeleton_HopFall                ; 101A2/10108
        bra.w   Skeleton_Land                   ; 101A6/1010C
        bra.w   Skeleton_LandPause              ; 101AA/10110
snd148_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd148_512                      
        move    (a7)+,ccr                       
l1m_10114:
        moveq   #SFX_SKELETON_HOP,d0            ;      /10114  effect 22: skeleton hop
        bsr.w   PlaySfx                         ;      /10116
        bra.w   snd148_end                      
snd148_512:
        move    (a7)+,ccr                       
snd148_end:

;---------------------------------------------------------------------------
; 2 hops before the leap
;---------------------------------------------------------------------------
Skeleton_HopStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 101AE/1011A
        move.l  a0,O_MoveTable(a5)              ; 101B2/1011E
        move.b  #$2,Skl_Hops(a5)                ; 101B6/10122
        addq.b  #$1,O_Step2(a5)                 ; 101BC/10128
        rts                                     ; 101C0/1012C

;---------------------------------------------------------------------------
; 3 px/frame upwards
;---------------------------------------------------------------------------
Skeleton_TakeOff:
        lea.l   Skeleton_AnimHop(pc),a0         ; 101C2/1012E
        bsr.w   SetAnim                         ; 101C6/10132  start animation
        move.l  #$30000,Skl_VelY(a5)            ; 101CA/10136
        addq.b  #$1,O_Step2(a5)                 ; 101D2/1013E

;---------------------------------------------------------------------------
; gravity 0.165 px/frame^2 until the top
;---------------------------------------------------------------------------
Skeleton_HopRise:
        bsr.w   Skeleton_HopMove                ; 101D6/10142
        subi.l  #$2a16,Skl_VelY(a5)             ; 101DA/10146
        tst.w   Skl_VelY(a5)                    ; 101E2/1014E
        bne.b   l_101EC                         ; 101E6/10152
        addq.b  #$1,O_Step2(a5)                 ; 101E8/10154
l_101EC:
        rts                                     ; 101EC/10158

;---------------------------------------------------------------------------
; down to -3 px/frame until it lands
;---------------------------------------------------------------------------
Skeleton_HopFall:
        bsr.b   Skeleton_HopMove                ; 101EE/1015A
        cmpi.w  #$fffd,Skl_VelY(a5)             ; 101F0/1015C
        blt.b   l_10200                         ; 101F6/10162
        subi.l  #$2a16,Skl_VelY(a5)             ; 101F8/10164
l_10200:
        bsr.w   ObjectMapCollide                ; 10200/1016C  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_1020A                         ; 10204/10170
        addq.b  #$1,O_Step2(a5)                 ; 10206/10172
l_1020A:
        rts                                     ; 1020A/10176
Skeleton_Land:
        move.b  #$6,Skl_Pause(a5)               ; 1020C/10178
        addq.b  #$1,O_Step2(a5)                 ; 10212/1017E

;---------------------------------------------------------------------------
; 6 frames, aim, then hop again or leap
;---------------------------------------------------------------------------
Skeleton_LandPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10216/10182
        bne.w   Animate                         ; 1021A/10186
        bsr.b   Skeleton_Aim                    ; 1021E/1018A
        move.b  #$1,O_Step2(a5)                 ; 10220/1018C
        subq.b  #$1,Skl_Hops(a5)                ; 10226/10192
        bne.b   l_10236                         ; 1022A/10196
        move.b  #$2,O_Step(a5)                  ; 1022C/10198
        clr.b   O_Step2(a5)                     ; 10232/1019E
l_10236:
        rts                                     ; 10236/101A2

;---------------------------------------------------------------------------
; Arthur 64+ px away: face him (O_Dir 1 right, 3 left); closer: keep going
;---------------------------------------------------------------------------
Skeleton_Aim:
        move.w  O_X(a5),d0                      ; 10238/101A4
        sub.w   g_ArthurX(a6),d0                ; 1023C/101A8
        addi.w  #$40,d0                         ; 10240/101AC
        cmp.w   #$80,d0                         ; 10244/101B0
        bcs.b   l_10260                         ; 10248/101B4
        move.b  #$3,O_Dir(a5)                   ; 1024A/101B6
        move.w  O_X(a5),d0                      ; 10250/101BC
        cmp.w   g_ArthurX(a6),d0                ; 10254/101C0
        bhi.b   l_10260                         ; 10258/101C4
        move.b  #$1,O_Dir(a5)                   ; 1025A/101C6
l_10260:
        rts                                     ; 10260/101CC

;---------------------------------------------------------------------------
; X += move table dx for O_Dir, Y += Skl_VelY
;---------------------------------------------------------------------------
Skeleton_HopMove:
        movea.l O_MoveTable(a5),a0              ; 10262/101CE
        clr.w   d0                              ; 10266/101D2
        move.b  O_Dir(a5),d0                    ; 10268/101D4
        add.w   d0,d0                           ; 1026C/101D8
        add.w   d0,d0                           ; 1026E/101DA
        adda.w  d0,a0                           ; 10270/101DC
        move.w  (a0),d0                         ; 10272/101DE
        ext.l   d0                              ; 10274/101E0
        asl.l   #$8,d0                          ; 10276/101E2
        add.l   d0,O_X(a5)                      ; 10278/101E4
        move.l  Skl_VelY(a5),d0                 ; 1027C/101E8
        add.l   d0,O_Y(a5)                      ; 10280/101EC
        bra.w   Animate                         ; 10284/101F0

;---------------------------------------------------------------------------
; O_Step2: 0 aim, 1 up, 2 down, 3-4 pause
;---------------------------------------------------------------------------
Skeleton_Leap:
        move.b  O_Step2(a5),d0                  ; 10288/101F4
        add.w   d0,d0                           ; 1028C/101F8
        add.w   d0,d0                           ; 1028E/101FA
        jmp     Skeleton_Leap_Jumps(pc,d0.w)    ; 10290/101FC
Skeleton_Leap_Jumps:
        bra.w   Skeleton_LeapStart              ; 10294/10200
        bra.w   Skeleton_LeapUp                 ; 10298/10204
        bra.w   Skeleton_LeapDown               ; 1029C/10208
        bra.w   Skeleton_LeapLand               ; 102A0/1020C
        bra.w   Skeleton_LeapPause              ; 102A4/10210

;---------------------------------------------------------------------------
; Skl_LeapDX = (Arthur X - X) / 42: lands on his spot after 42 frames
;---------------------------------------------------------------------------
Skeleton_LeapStart:
        lea.l   Skeleton_AnimLeap(pc),a0        ; 102A8/10214
        bsr.w   SetAnim                         ; 102AC/10218  start animation
        move.w  O_Y(a5),Skl_BaseY(a5)           ; 102B0/1021C
        clr.b   Skl_Phase(a5)                   ; 102B6/10222
        move.w  g_ArthurX(a6),d0                ; 102BA/10226
        sub.w   O_X(a5),d0                      ; 102BE/1022A
        ext.l   d0                              ; 102C2/1022E
        asl.l   #$8,d0                          ; 102C4/10230
        divs.w  #$2a,d0                         ; 102C6/10232
        ext.l   d0                              ; 102CA/10236
        asl.l   #$8,d0                          ; 102CC/10238
        move.l  d0,Skl_LeapDX(a5)               ; 102CE/1023A
        addq.b  #$1,O_Step2(a5)                 ; 102D2/1023E
        rts                                     ; 102D6/10242

;---------------------------------------------------------------------------
; phase += 6 until the top
;---------------------------------------------------------------------------
Skeleton_LeapUp:
        addq.b  #$6,Skl_Phase(a5)               ; 102D8/10244
        bmi.b   l_102EA                         ; 102DC/10248
        bsr.b   Skeleton_LeapY                  ; 102DE/1024A
        move.l  Skl_LeapDX(a5),d0               ; 102E0/1024C
        add.l   d0,O_X(a5)                      ; 102E4/10250
        rts                                     ; 102E8/10254
l_102EA:
        addq.b  #$1,O_Step2(a5)                 ; 102EA/10256
        rts                                     ; 102EE/1025A

;---------------------------------------------------------------------------
; until the phase wraps, or it lands (checked near the end)
;---------------------------------------------------------------------------
Skeleton_LeapDown:
        addq.b  #$6,Skl_Phase(a5)               ; 102F0/1025C
        bcs.b   l_10316                         ; 102F4/10260
        cmpi.b  #$e0,Skl_Phase(a5)              ; 102F6/10262
        bcs.b   l_10304                         ; 102FC/10268
        bsr.w   ObjectMapCollide                ; 102FE/1026A  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_10316                         ; 10302/1026E
l_10304:
        bsr.b   Skeleton_LeapY                  ; 10304/10270
        move.l  Skl_LeapDX(a5),d0               ; 10306/10272
        add.l   d0,O_X(a5)                      ; 1030A/10276
        rts                                     ; 1030E/1027A
	dc.b	$3B,$6D,$00,$20,$00,$0A
l_10316:
        addq.b  #$1,O_Step2(a5)                 ; 10316/10282
        rts                                     ; 1031A/10286
Skeleton_LeapLand:
        move.b  #$6,Skl_Pause(a5)               ; 1031C/10288
        addq.b  #$1,O_Step2(a5)                 ; 10322/1028E
Skeleton_LeapPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10326/10292
        bne.w   Animate                         ; 1032A/10296
        bsr.w   Skeleton_Aim                    ; 1032E/1029A
        move.b  #$1,O_Step(a5)                  ; 10332/1029E
        clr.b   O_Step2(a5)                     ; 10338/102A4
        rts                                     ; 1033C/102A8

;---------------------------------------------------------------------------
; Y = Skl_BaseY + sin(phase) x 2 x 80 / 256
;---------------------------------------------------------------------------
Skeleton_LeapY:
        lea.l   SineTable(pc),a0                ; 1033E/102AA
        clr.w   d0                              ; 10342/102AE
        move.b  Skl_Phase(a5),d0                ; 10344/102B0
        move.b  (a0,d0.w),d0                    ; 10348/102B4
        add.w   d0,d0                           ; 1034C/102B8
        mulu.w  #$50,d0                         ; 1034E/102BA
        lsr.w   #$8,d0                          ; 10352/102BE
        add.w   Skl_BaseY(a5),d0                ; 10354/102C0
        move.w  d0,O_Y(a5)                      ; 10358/102C4
        rts                                     ; 1035C/102C8

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing
;---------------------------------------------------------------------------
Skeleton_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 1035E/102CA
        beq.b   l_10374                         ; 10364/102D0
        bcc.b   l_10378                         ; 10366/102D2
        moveq   #SFX_ENEMY_DIE,d0               ; 10368/102D4
        bsr.w   PlaySfx                         ; 1036A/102D6  sound effect 17 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 1036E/102DA  next step
        rts                                     ; 10372/102DE
l_10374:
        bra.w   EnemyDieFacing                  ; 10374/102E0
l_10378:
        move.b  #ST_REMOVE,O_State(a5)          ; 10378/102E4
        rts                                     ; 1037E/102EA

;---------------------------------------------------------------------------
; State 3: free the slot (no spawn quota given back)
;---------------------------------------------------------------------------
Skeleton_Free:
        clr.b   (a5)                            ; 10380/102EC  free this enemy slot
        rts                                     ; 10382/102EE

;---------------------------------------------------------------------------
; (dx, dy) 8.8: 0 still, 1 right 0.8, 2 down, 3 left 0.8, 4 up (only dx is used)
;---------------------------------------------------------------------------
SkeletonMoveTable:
	dc.b	$00,$00,$00,$00,$00,$CC,$00,$00,$00,$00,$FF,$34,$FF,$34,$00,$00
	dc.b	$00,$00,$00,$CC
Skeleton_AnimBones:
	AL	$00,3,Skeleton_AnimBones
Skeleton_AnimRise:
	AF	$01,1
	AL	$02,1,Skeleton_AnimRise
Skeleton_AnimHop:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,4,Skeleton_AnimHop
Skeleton_AnimLeap:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,3,Skeleton_AnimLeap

;---------------------------------------------------------------------------
; === Big Man (type 10, 500 pts, 10 hits) ===
; Ogre that walks and charges along the floor, pauses at random and throws projectiles.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Walks at 0.53 px/frame, turning back at the edge of a floor, and pauses (70 or 100
;     frames, random) after each walk time in BigManWalkTimes, then picks a random direction.
;   * When Arthur is on its level (10 px below to 45 px above), it fights: paces to and
;     fro across him (turning 40 px past him), charges at 2 px/frame, and throws enemy
;     shot type 3 on BigManShotTimes (10-frame wind-up).
;   * When Arthur is directly below (within 10 px across) it crouches and throws down
;     every 30 frames.
;   * Each hit makes it flinch for 6 frames. Only acts while on screen.
;---------------------------------------------------------------------------
Enemy_BigMan:
        move.b  O_State(a5),d0                  ; 103BA/10326
        add.w   d0,d0                           ; 103BE/1032A
        add.w   d0,d0                           ; 103C0/1032C
        jmp     Enemy_BigMan_Jumps(pc,d0.w)     ; 103C2/1032E
Enemy_BigMan_Jumps:
        bra.w   BigMan_Init                     ; 103C6/10332
        bra.w   BigMan_Active                   ; 103CA/10336
        bra.w   BigMan_Dying                    ; 103CE/1033A
        bra.w   BigMan_Free                     ; 103D2/1033E

;---------------------------------------------------------------------------
; State 0: 10 HP, size 3, face Arthur, start the scripts; wait until on screen
;---------------------------------------------------------------------------
BigMan_Init:
        tst.b   O_Step(a5)                      ; 103D6/10342
        bne.b   BigMan_WaitVisible              ; 103DA/10346
        move.b  O_Param(a5),BM_Crouched(a5)     ; 103DC/10348
        clr.b   O_Param(a5)                     ; 103E2/1034E
        move.w  O_X(a5),d0                      ; 103E6/10352
        cmp.w   g_ArthurX(a6),d0                ; 103EA/10356
        slt.b   O_Dir(a5)                       ; 103EE/1035A
        addq.b  #$1,O_Dir(a5)                   ; 103F2/1035E
        move.b  #$3,O_Size(a5)                  ; 103F6/10362
        lea.l   BigMan_AnimWalk(pc),a0          ; 103FC/10368
        bsr.w   SetAnimIndexed                  ; 10400/1036C  start animation for current direction
        move.b  #$a,O_HP(a5)                    ; 10404/10370
        clr.b   BM_Timer(a5)                    ; 1040A/10376
        clr.b   BM_EdgeDir(a5)                  ; 1040E/1037A
        clr.b   BM_AtEdge(a5)                   ; 10412/1037E
        clr.b   BM_EdgeTurn(a5)                 ; 10416/10382
        lea.l   BigManShotTimes(pc),a0          ; 1041A/10386
        move.b  (a0)+,BM_ShotTime(a5)           ; 1041E/1038A
        move.l  a0,BM_ShotPtr(a5)               ; 10422/1038E
        lea.l   BigManWalkTimes(pc),a0          ; 10426/10392
        move.b  (a0)+,BM_WalkTime(a5)           ; 1042A/10396
        move.l  a0,BM_WalkPtr(a5)               ; 1042E/1039A
        lea.l   BigManMoveTable(pc),a0          ; 10432/1039E
        move.l  a0,O_MoveTable(a5)              ; 10436/103A2
        addq.b  #$1,O_Step(a5)                  ; 1043A/103A6  next step
        rts                                     ; 1043E/103AA
BigMan_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 10440/103AC
        beq.b   l_10452                         ; 10444/103B0
        addq.b  #ST_ACTIVE,O_State(a5)          ; 10446/103B2
        clr.b   O_Step(a5)                      ; 1044A/103B6
        clr.b   O_Step2(a5)                     ; 1044E/103BA
l_10452:
        rts                                     ; 10452/103BE
	dc.b	$00

;---------------------------------------------------------------------------
; frames between shots: 45, 35, 20, 20, 42, 60, 35, 50, 28 (bit 7 = loop)
;---------------------------------------------------------------------------
BigManShotTimes:
	dc.b	$2D,$23,$14,$14,$2A,$3C,$23,$32,$9C,$FF,$F7

;---------------------------------------------------------------------------
; frames of walking between pauses: 190, 100, 163, 230, 98, 156, 120, 160, 120
;---------------------------------------------------------------------------
BigManWalkTimes:
	dc.b	$BE,$64,$A3,$E6,$62,$9C,$78,$A0,$78,$00,$FF,$F6

;---------------------------------------------------------------------------
; O_Dir 0/1: +-0.53 walking; 2/3: +-2.0 charging
;---------------------------------------------------------------------------
BigManMoveTable:
	dc.b	$00,$88,$00,$00,$FF,$78,$00,$00,$02,$00,$00,$00,$FE,$00,$00,$00

;---------------------------------------------------------------------------
; State 1 (on screen only). O_Step: 0 walk, 1 fight, 2 shoot down, 3 flinch
;---------------------------------------------------------------------------
BigMan_Active:
        tst.b   O_OnScreen(a5)                  ; 1047C/103E8
        beq.b   l_104AA                         ; 10480/103EC
        move.b  O_Step(a5),d0                   ; 10482/103EE
        add.w   d0,d0                           ; 10486/103F2
        add.w   d0,d0                           ; 10488/103F4
        jsr     BigMan_Active_Jumps(pc,d0.w)    ; 1048A/103F6
        tst.b   O_Param(a5)                     ; 1048E/103FA
        beq.b   l_104AA                         ; 10492/103FE
        clr.b   O_Param(a5)                     ; 10494/10400  hit (EnemyHitByShot set O_Param): flinch
        move.b  #$3,O_Step(a5)                  ; 10498/10404
        clr.b   O_Step2(a5)                     ; 1049E/1040A
        lea.l   BigMan_AnimFlinch(pc),a0        ; 104A2/1040E
        bra.w   SetAnimIndexed                  ; 104A6/10412
l_104AA:
        rts                                     ; 104AA/10416
BigMan_Active_Jumps:
        bra.w   BigMan_Walk                     ; 104AC/10418
        bra.w   BigMan_Fight                    ; 104B0/1041C
        bra.w   BigMan_ShootDown                ; 104B4/10420
        bra.w   BigMan_Flinch                   ; 104B8/10424

;---------------------------------------------------------------------------
; 6 frames after a hit, then walk
;---------------------------------------------------------------------------
BigMan_Flinch:
        tst.b   O_Step2(a5)                     ; 104BC/10428
        bne.b   l_104CC                         ; 104C0/1042C
        move.b  #$6,BM_FlinchTime(a5)           ; 104C2/1042E
snd149_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd149_512                      
        move    (a7)+,ccr                       
        moveq   #SFX_HURT,d0                    ;      /10434  effect 19: hit
        bsr.w   PlaySfx                         ;      /10436
        bra.w   snd149_end                      
snd149_512:
        move    (a7)+,ccr                       
snd149_end:
        addq.b  #$1,O_Step2(a5)                 ; 104C8/1043A
l_104CC:
        subq.b  #$1,BM_FlinchTime(a5)           ; 104CC/1043E
        bne.w   Animate                         ; 104D0/10442
        clr.b   O_Step(a5)                      ; 104D4/10446
        clr.b   O_Step2(a5)                     ; 104D8/1044A
        clr.b   O_Param(a5)                     ; 104DC/1044E
        rts                                     ; 104E0/10452

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 walk, 2 pause, 3-4 crouch
;---------------------------------------------------------------------------
BigMan_Walk:
        clr.w   d0                              ; 104E2/10454
        move.b  O_Step2(a5),d0                  ; 104E4/10456
        add.w   d0,d0                           ; 104E8/1045A
        add.w   d0,d0                           ; 104EA/1045C
        jmp     BigMan_Walk_Jumps(pc,d0.w)      ; 104EC/1045E
BigMan_Walk_Jumps:
        bra.w   BigMan_WalkStart                ; 104F0/10462
        bra.w   BigMan_Walking                  ; 104F4/10466
        bra.w   BigMan_Pause                    ; 104F8/1046A
        bra.w   BigMan_CrouchWait               ; 104FC/1046E
        bra.w   BigMan_Crouching                ; 10500/10472
BigMan_WalkStart:
        lea.l   BigMan_AnimWalk(pc),a0          ; 10504/10476
        bsr.w   SetAnimIndexed                  ; 10508/1047A  start animation for current direction
        tst.b   BM_Crouched(a5)                 ; 1050C/1047E
        beq.b   l_10534                         ; 10510/10482
        lea.l   BigMan_AnimCrouch(pc),a0        ; 10512/10484
        bsr.w   SetAnimIndexed                  ; 10516/10488  start animation for current direction
        bsr.w   Random                          ; 1051A/1048C  random number
        andi.w  #$3,d0                          ; 1051E/10490
        move.b  BigManCrouchTimes(pc,d0.w),BM_CrouchTime(a5); 10522/10494
        move.b  #$3,O_Step2(a5)                 ; 10528/1049A
        clr.b   BM_Crouched(a5)                 ; 1052E/104A0
        rts                                     ; 10532/104A4
l_10534:
        addq.b  #$1,O_Step2(a5)                 ; 10534/104A6
        rts                                     ; 10538/104AA

;---------------------------------------------------------------------------
; x 64 frames: 2, 3, 3, 2
;---------------------------------------------------------------------------
BigManCrouchTimes:
	dc.b	$02,$03,$03,$02

;---------------------------------------------------------------------------
; Arthur on its level: fight. Directly below it: shoot down. Otherwise walk,
; turn at floor edges, and pause when the walk time runs out.
;---------------------------------------------------------------------------
BigMan_Walking:
        move.w  g_ArthurY(a6),d0                ; 1053E/104B0
        sub.w   O_Y(a5),d0                      ; 10542/104B4  Arthur from 10 below to 45 above it: fight
        addi.w  #$a,d0                          ; 10546/104B8
        bmi.b   l_1055E                         ; 1054A/104BC
        cmp.w   #$37,d0                         ; 1054C/104BE
        bhi.b   l_1055E                         ; 10550/104C2
        move.b  #$1,O_Step(a5)                  ; 10552/104C4
        clr.b   O_Step2(a5)                     ; 10558/104CA
        rts                                     ; 1055C/104CE
l_1055E:
        move.w  O_X(a5),d0                      ; 1055E/104D0
        sub.w   g_ArthurX(a6),d0                ; 10562/104D4  Arthur within 10 px across and below: shoot down
        addi.w  #$a,d0                          ; 10566/104D8
        cmp.w   #$14,d0                         ; 1056A/104DC
        bhi.b   l_10586                         ; 1056E/104E0
        move.w  O_Y(a5),d0                      ; 10570/104E2
        cmp.w   g_ArthurY(a6),d0                ; 10574/104E6
        blt.b   l_10586                         ; 10578/104EA
        move.b  #$2,O_Step(a5)                  ; 1057A/104EC
        clr.b   O_Step2(a5)                     ; 10580/104F2
        rts                                     ; 10584/104F6
l_10586:
        move.w  g_GameFrame(a6),d0              ; 10586/104F8
        addq.w  #$1,d0                          ; 1058A/104FC
        andi.w  #$1f,d0                         ; 1058C/104FE
        bne.b   l_10594                         ; 10590/10502
snd150_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd150_512                      
        move    (a7)+,ccr                       
        moveq   #SFX_THUD,d0                    ;      /10504
        bsr.w   PlaySfx                         ;      /10506  effect 9: footstep
        bra.w   snd150_end                      
snd150_512:
        move    (a7)+,ccr                       
        moveq   #$c,d0                          ; 10592/       d0 is not used by what follows. [1MB build: PlaySfx here, effect 9 (footstep); the call was removed in 512K]
snd150_end:
l_10594:
        move.w  g_GameFrame(a6),d0              ; 10594/1050A
        addq.w  #$1,d0                          ; 10598/1050E
        andi.w  #$f,d0                          ; 1059A/10510
        bne.b   l_105C4                         ; 1059E/10514
        bsr.w   BigMan_CheckEdge                ; 105A0/10516  every 16 frames: floor ahead?
        tst.b   BM_AtEdge(a5)                   ; 105A4/1051A
        beq.b   l_105C4                         ; 105A8/1051E
        move.b  O_Dir(a5),d0                    ; 105AA/10520
        cmp.b   BM_EdgeDir(a5),d0               ; 105AE/10524
        bne.b   l_105C4                         ; 105B2/10528
        bchg    #$0,d0                          ; 105B4/1052A  at the edge and still facing it: turn round
        move.b  d0,O_Dir(a5)                    ; 105B8/1052E
        lea.l   BigMan_AnimWalk(pc),a0          ; 105BC/10532
        bsr.w   SetAnimIndexed                  ; 105C0/10536  start animation for current direction
l_105C4:
        bsr.w   ApplyMoveTable                  ; 105C4/1053A  move by the movement table
        bsr.w   Animate                         ; 105C8/1053E  animate
        subq.b  #$1,BM_WalkTime(a5)             ; 105CC/10542
        bne.b   l_10612                         ; 105D0/10546
        movea.l BM_WalkPtr(a5),a0               ; 105D2/10548
        move.b  (a0)+,d0                        ; 105D6/1054C
        bne.b   l_105DE                         ; 105D8/1054E
        adda.w  (a0),a0                         ; 105DA/10550
        move.b  (a0)+,d0                        ; 105DC/10552
l_105DE:
        move.l  a0,BM_WalkPtr(a5)               ; 105DE/10554
        move.b  d0,BM_WalkTime(a5)              ; 105E2/10558
        bsr.w   Random                          ; 105E6/1055C  random number
        andi.w  #$1,d0                          ; 105EA/10560
        bne.b   l_10600                         ; 105EE/10564
        lea.l   BigMan_AnimPauseB(pc),a0        ; 105F0/10566
        bsr.w   SetAnimIndexed                  ; 105F4/1056A  start animation for current direction
        move.b  #$64,BM_PauseTime(a5)           ; 105F8/1056E  pause 100 frames
        bra.b   l_1060E                         ; 105FE/10574
l_10600:
        lea.l   BigMan_AnimPauseA(pc),a0        ; 10600/10576
        bsr.w   SetAnimIndexed                  ; 10604/1057A  start animation for current direction
        move.b  #$46,BM_PauseTime(a5)           ; 10608/1057E  or 70
l_1060E:
        addq.b  #$1,O_Step2(a5)                 ; 1060E/10584
l_10612:
        rts                                     ; 10612/10588

;---------------------------------------------------------------------------
; then a random direction
;---------------------------------------------------------------------------
BigMan_Pause:
        subq.b  #$1,BM_PauseTime(a5)            ; 10614/1058A
        bne.w   Animate                         ; 10618/1058E
        bsr.w   Random                          ; 1061C/10592  random number
        andi.b  #$1,d0                          ; 10620/10596
        move.b  d0,O_Dir(a5)                    ; 10624/1059A
        clr.b   O_Step2(a5)                     ; 10628/1059E
        rts                                     ; 1062C/105A2

;---------------------------------------------------------------------------
; Waits until Arthur is within 16 px of it vertically (one unsigned compare:
; O_Y - Arthur Y + 16 <= 32), then counts BM_CrouchTime
;---------------------------------------------------------------------------
BigMan_CrouchWait:
        move.w  O_Y(a5),d0                      ; 1062E/105A4
        sub.w   g_ArthurY(a6),d0                ; 10632/105A8
        addi.w  #$10,d0                         ; 10636/105AC
        subi.w  #$20,d0                         ; 1063A/105B0
        bhi.b   l_10644                         ; 1063E/105B4
        addq.b  #$1,O_Step2(a5)                 ; 10640/105B6
l_10644:
        rts                                     ; 10644/105BA
BigMan_Crouching:
        moveq   #$3f,d0                         ; 10646/105BC
        and.w   g_GameFrame(a6),d0              ; 10648/105BE
        bne.b   l_1065A                         ; 1064C/105C2
        subq.b  #$1,BM_CrouchTime(a5)           ; 1064E/105C4
        bne.b   l_1065A                         ; 10652/105C8
        move.b  #$1,O_Step2(a5)                 ; 10654/105CA
l_1065A:
        rts                                     ; 1065A/105D0

;---------------------------------------------------------------------------
; Is there floor 2 px below? No: BM_AtEdge = 1 and remember the direction
;---------------------------------------------------------------------------
BigMan_CheckEdge:
        subq.w  #$2,O_Y(a5)                     ; 1065C/105D2
        bsr.w   ObjectMapCollide                ; 10660/105D6  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_1067E                         ; 10664/105DA
        tst.b   BM_AtEdge(a5)                   ; 10666/105DC
        bne.b   l_10678                         ; 1066A/105E0
        move.b  O_Dir(a5),BM_EdgeDir(a5)        ; 1066C/105E2
        move.b  #$1,BM_AtEdge(a5)               ; 10672/105E8
l_10678:
        addq.w  #$2,O_Y(a5)                     ; 10678/105EE
        rts                                     ; 1067C/105F2
l_1067E:
        clr.b   BM_AtEdge(a5)                   ; 1067E/105F4
        clr.b   BM_EdgeTurn(a5)                 ; 10682/105F8
        rts                                     ; 10686/105FC

;---------------------------------------------------------------------------
; O_Step2: 0 face Arthur, 1 pace, 2 charge, 3 wind up, 4 throw
;---------------------------------------------------------------------------
BigMan_Fight:
        clr.w   d0                              ; 10688/105FE
        move.b  O_Step2(a5),d0                  ; 1068A/10600
        add.w   d0,d0                           ; 1068E/10604
        add.w   d0,d0                           ; 10690/10606
        jmp     BigMan_Fight_Jumps(pc,d0.w)     ; 10692/10608
BigMan_Fight_Jumps:
        bra.w   BigMan_FightStart               ; 10696/1060C
        bra.w   BigMan_Pace                     ; 1069A/10610
        bra.w   BigMan_Charge                   ; 1069E/10614
        bra.w   BigMan_WindUp                   ; 106A2/10618
        bra.w   BigMan_Throw                    ; 106A6/1061C
BigMan_FightStart:
