;---------------------------------------------------------------------------
; === Zombie (type 11, 200 pts) ===
; Spawned at run time near Arthur: rises out of the ground (size class changes as it emerges), shambles along the floor and sinks back. Sound effect 20.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: created hidden (shots pass through), drops onto the floor, waits a
; random 12-187 frames (parameter 1: no wait), then rises out of the ground, its size class
; growing with the animation. It shambles towards Arthur at 0.81 px/frame; once past him it
; walks on for 40-110 frames, then sinks back into the ground (also after 360 frames, or
; when the floor ends). Shots pass through it while it rises and sinks.
;---------------------------------------------------------------------------
Enemy_Zombie:
        move.b  O_State(a5),d0                  ; 109C4/1093E
        add.w   d0,d0                           ; 109C8/10942
        add.w   d0,d0                           ; 109CA/10944
        jmp     Enemy_Zombie_Jumps(pc,d0.w)     ; 109CC/10946
Enemy_Zombie_Jumps:
        bra.w   Zombie_Init                     ; 109D0/1094A
        bra.w   Zombie_Active                   ; 109D4/1094E
        bra.w   Zombie_Dying                    ; 109D8/10952
        bra.w   Zombie_Free                     ; 109DC/10956
ZombieInitSteps:
        bra.w   Zombie_Hide                     ; 109E0/1095A
        bra.w   Zombie_Drop                     ; 109E4/1095E
        bra.w   Zombie_WaitRise                 ; 109E8/10962
        bra.w   Zombie_StartRise                ; 109EC/10966

;---------------------------------------------------------------------------
; State 0. O_Step 0: O_Step2 0 hide, 1 drop to the floor, 2 wait, 3 start rising;
; O_Step 1: rise
;---------------------------------------------------------------------------
Zombie_Init:
        tst.b   O_Step(a5)                      ; 109F0/1096A
        bne.w   Zombie_Rise                     ; 109F4/1096E
        clr.w   d0                              ; 109F8/10972
        move.b  O_Step2(a5),d0                  ; 109FA/10974
        add.w   d0,d0                           ; 109FE/10978
        add.w   d0,d0                           ; 10A00/1097A
        jmp     ZombieInitSteps(pc,d0.w)        ; 10A02/1097C

;---------------------------------------------------------------------------
; shots pass through, size 0, invisible
;---------------------------------------------------------------------------
Zombie_Hide:
        move.b  #$2,(a5)                        ; 10A06/10980
        clr.b   O_Size(a5)                      ; 10A0A/10984
        clr.l   O_Anim(a5)                      ; 10A0E/10988
        addq.b  #$1,O_Step2(a5)                 ; 10A12/1098C
l_10A16:
        rts                                     ; 10A16/10990

;---------------------------------------------------------------------------
; Move down 2 px a frame until there is floor; parameter 1 starts at once
;---------------------------------------------------------------------------
Zombie_Drop:
        subq.w  #$2,O_Y(a5)                     ; 10A18/10992
        bsr.w   ObjectMapCollide                ; 10A1C/10996  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_10A16                         ; 10A20/1099A
        tst.b   O_Param(a5)                     ; 10A22/1099C
        beq.b   l_10A38                         ; 10A26/109A0
        move.b  #ST_ACTIVE,O_State(a5)          ; 10A28/109A2
        clr.b   O_Step(a5)                      ; 10A2E/109A8
        clr.b   O_Step2(a5)                     ; 10A32/109AC
        rts                                     ; 10A36/109B0
l_10A38:
        lea.l   ZombieRiseDelays(pc),a0         ; 10A38/109B2
        move.w  d7,d0                           ; 10A3C/109B6
        add.w   g_GameFrame(a6),d0              ; 10A3E/109B8
        andi.w  #$f,d0                          ; 10A42/109BC
        adda.w  d0,a0                           ; 10A46/109C0
        move.b  (a0),Zmb_Timer(a5)              ; 10A48/109C2
        move.b  #$b4,Zmb_WalkTime(a5)           ; 10A4C/109C6  walk for 180 x 2 frames at most
        addq.b  #$1,O_Step2(a5)                 ; 10A52/109CC
        rts                                     ; 10A56/109D0
Zombie_WaitRise:
        subq.b  #$1,Zmb_Timer(a5)               ; 10A58/109D2
        bne.b   l_10A16                         ; 10A5C/109D6
        addq.b  #$1,O_Step2(a5)                 ; 10A5E/109D8
        rts                                     ; 10A62/109DC

;---------------------------------------------------------------------------
; face Arthur, rising animation
;---------------------------------------------------------------------------
Zombie_StartRise:
        clr.b   O_Dir(a5)                       ; 10A64/109DE
        move.w  O_X(a5),d0                      ; 10A68/109E2
        cmp.w   g_ArthurX(a6),d0                ; 10A6C/109E6
        blt.b   l_10A76                         ; 10A70/109EA
        addq.b  #$1,O_Dir(a5)                   ; 10A72/109EC
l_10A76:
