        rts                                     ; 10A92/10A0C

;---------------------------------------------------------------------------
; Size class follows ZombieRiseSizes as the animation runs; then active and hittable
;---------------------------------------------------------------------------
Zombie_Rise:
        tst.b   O_Step2(a5)                     ; 10A94/10A0E
        bne.b   l_10AC0                         ; 10A98/10A12
        move.b  #$2,(a5)                        ; 10A9A/10A14
        subq.w  #$2,O_Y(a5)                     ; 10A9E/10A18
        bsr.w   ObjectMapCollide                ; 10AA2/10A1C  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   Zombie_NoFloor                  ; 10AA6/10A20
        lea.l   ZombieRiseSizes(pc),a0          ; 10AA8/10A22
        move.b  (a0)+,O_Size(a5)                ; 10AAC/10A26
        move.l  a0,Zmb_SizePtr(a5)              ; 10AB0/10A2A
        move.b  #$7,Zmb_Steps(a5)               ; 10AB4/10A2E
