;---------------------------------------------------------------------------
; === Dragon (type 12, 200 pts per segment) ===
; Flying dragon boss of levels 2-3: a chain of segments led by the head (6 hits); the head aims and breathes fire at Arthur. Sound effects 12/20; awards 1000 extra on defeat.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * The placed head (parameter 0) builds the body: 7 segments (parameter 1) and a tail
;     (parameter 2) in free enemy slots, linked through Drg_Next / Drg_Prev.
;   * The head steers along path scripts of (frames, direction) pairs in 16 directions
;     at 2 px/frame. Each direction change is handed down the chain with a 6-frame
;     delay per segment (7 for the tail), which makes the body follow the head's path.
;   * Entrance: a short S-curve, then it waits frozen until it is on screen and Arthur
;     is no more than 32 px below it, for a further 2-5 x 16 frames, then attacks.
;   * Attack: when a path step ends it may (3 in 16) dive at Arthur if he is 24+ px in
;     front of it; otherwise it turns round once it is 94+ px past him (turn paths for the
;     upper and lower half of the screen), and climbs or descends towards his height.
;   * Every 32 frames, if Arthur is within 72 px vertically, it breathes fire (enemy shot
;     type 9) and opens its mouth for 10 frames.
;   * Hits: each hit on any segment scores 200. Hitting the tail kills it; hitting a body
;     segment kills the tail instead, so the dragon shortens from the tail. The head takes
;     6 hits; killing it kills every segment, scores a further 1000 and ends the boss.
;   * Off levels 2-3 it is removed when it gets far off screen.
;---------------------------------------------------------------------------
Enemy_Dragon:
        move.b  O_State(a5),d0                  ; 10CCE/10C48
        add.w   d0,d0                           ; 10CD2/10C4C
        add.w   d0,d0                           ; 10CD4/10C4E
        jmp     Enemy_Dragon_Jumps(pc,d0.w)     ; 10CD6/10C50
Enemy_Dragon_Jumps:
        bra.w   Dragon_Init                     ; 10CDA/10C54
        bra.w   Dragon_Active                   ; 10CDE/10C58
        bra.w   Dragon_Dying                    ; 10CE2/10C5C
        bra.w   Dragon_Free                     ; 10CE6/10C60

;---------------------------------------------------------------------------
; State 0: by part (O_Param): head / body segment / tail
;---------------------------------------------------------------------------
Dragon_Init:
        move.b  O_Param(a5),d0                  ; 10CEA/10C64
        add.w   d0,d0                           ; 10CEE/10C68
        add.w   d0,d0                           ; 10CF0/10C6A
        jmp     Dragon_Init_Jumps(pc,d0.w)      ; 10CF2/10C6C
Dragon_Init_Jumps:
        bra.w   Dragon_InitHead                 ; 10CF6/10C70
        bra.w   Dragon_InitBody                 ; 10CFA/10C74
        bra.w   Dragon_InitTail                 ; 10CFE/10C78
Dragon_InitHead:
        move.b  O_Step(a5),d0                   ; 10D02/10C7C
        add.w   d0,d0                           ; 10D06/10C80
        add.w   d0,d0                           ; 10D08/10C82
        jmp     Dragon_InitHead_Jumps(pc,d0.w)  ; 10D0A/10C84
Dragon_InitHead_Jumps:
        bra.w   Dragon_HeadSetup                ; 10D0E/10C88
        bra.w   Dragon_BuildBody                ; 10D12/10C8C
        bra.w   Dragon_NumberChain              ; 10D16/10C90

;---------------------------------------------------------------------------
; Face Arthur, size 3, 6 HP, 16-way move table, start the entrance path
;---------------------------------------------------------------------------
Dragon_HeadSetup:
        clr.b   O_Dir(a5)                       ; 10D1A/10C94
        clr.b   Drg_Facing(a5)                  ; 10D1E/10C98
        clr.b   Drg_Part(a5)                    ; 10D22/10C9C
        move.w  O_X(a5),d0                      ; 10D26/10CA0
        cmp.w   g_ArthurX(a6),d0                ; 10D2A/10CA4
        blt.b   l_10D3C                         ; 10D2E/10CA8
        move.b  #$8,O_Dir(a5)                   ; 10D30/10CAA  Arthur to the left: direction 8, facing left
        move.b  #$1,Drg_Facing(a5)              ; 10D36/10CB0
l_10D3C:
        move.b  #$3,O_Size(a5)                  ; 10D3C/10CB6
        lea.l   Dragon_AnimFly(pc),a0           ; 10D42/10CBC
        clr.w   d0                              ; 10D46/10CC0
        move.b  Drg_Facing(a5),d0               ; 10D48/10CC2
        add.w   d0,d0                           ; 10D4C/10CC6
        adda.w  d0,a0                           ; 10D4E/10CC8
        adda.w  (a0),a0                         ; 10D50/10CCA
        bsr.w   SetAnim                         ; 10D52/10CCC  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10D56/10CD0
        move.l  a0,O_MoveTable(a5)              ; 10D5A/10CD4
        lea.l   DragonEntrancePath(pc),a0       ; 10D5E/10CD8
        move.b  (a0)+,Drg_PathTime(a5)          ; 10D62/10CDC
        move.b  (a0)+,O_Dir(a5)                 ; 10D66/10CE0
        move.l  a0,Drg_PathPtr(a5)              ; 10D6A/10CE4
        move.b  #$2,Drg_Aggro(a5)               ; 10D6E/10CE8  attack chance 3 in 16
        clr.b   Drg_Firing(a5)                  ; 10D74/10CEE
        clr.b   Drg_Pending(a5)                 ; 10D78/10CF2
        clr.b   Drg_Frozen(a5)                  ; 10D7C/10CF6
        move.b  #$6,O_HP(a5)                    ; 10D80/10CFA
        move.w  O_Y(a5),Drg_HomeY(a5)           ; 10D86/10D00
        addq.b  #$1,O_Step(a5)                  ; 10D8C/10D06  next step
        clr.b   O_Step2(a5)                     ; 10D90/10D0A
        rts                                     ; 10D94/10D0E

;---------------------------------------------------------------------------
