        beq.b   l_10DB4                         ; 10DA6/10D20
        lea.l   $3c(a4),a4                      ; 10DA8/10D22
        dbra    d5,l_10DA4                      ; 10DAC/10D26
        bra.w   Dragon_BuildExit                ; 10DB0/10D2A
l_10DB4:
        move.l  a4,$24(a3)                      ; 10DB4/10D2E
        cmp.b   #$7,d6                          ; 10DB8/10D32  first segment: 20 px behind the head, 3 px lower
        beq.b   l_10DD2                         ; 10DBC/10D36
        move.w  $6(a3),d0                       ; 10DBE/10D38
        addi.w  #$e,d0                          ; 10DC2/10D3C
        move.w  d0,$6(a4)                       ; 10DC6/10D40
        move.w  $a(a3),$a(a4)                   ; 10DCA/10D44
        bra.b   l_10DE8                         ; 10DD0/10D4A
l_10DD2:
        move.w  $6(a3),d0                       ; 10DD2/10D4C
        addi.w  #$14,d0                         ; 10DD6/10D50
        move.w  d0,$6(a4)                       ; 10DDA/10D54
        move.w  $a(a3),d0                       ; 10DDE/10D58
        subq.w  #$3,d0                          ; 10DE2/10D5C
        move.w  d0,$a(a4)                       ; 10DE4/10D5E
l_10DE8:
        clr.b   $3(a4)                          ; 10DE8/10D62
        clr.b   $4(a4)                          ; 10DEC/10D66
        clr.b   $5(a4)                          ; 10DF0/10D6A
        move.b  #$1,(a4)                        ; 10DF4/10D6E
        clr.b   $1(a4)                          ; 10DF8/10D72
        move.b  O_Type(a5),$1a(a4)              ; 10DFC/10D76
        move.b  #$1,$2(a4)                      ; 10E02/10D7C
        move.l  a3,$28(a4)                      ; 10E08/10D82  link back to the previous segment
        movea.l a4,a3                           ; 10E0C/10D86
        subq.w  #$1,d6                          ; 10E0E/10D88
        bne.b   l_10D9E                         ; 10E10/10D8A
        lea.l   g_Enemies(a6),a4                ; 10E12/10D8C
        moveq   #$27,d5                         ; 10E16/10D90
l_10E18:
        tst.b   (a4)                            ; 10E18/10D92
        beq.b   l_10E26                         ; 10E1A/10D94
        lea.l   $3c(a4),a4                      ; 10E1C/10D96
        dbra    d5,l_10E18                      ; 10E20/10D9A
        bra.b   Dragon_BuildExit                ; 10E24/10D9E
l_10E26:
        move.l  a4,$24(a3)                      ; 10E26/10DA0
        move.l  a3,$28(a4)                      ; 10E2A/10DA4
        clr.l   $24(a4)                         ; 10E2E/10DA8
        move.b  O_Type(a5),$1a(a4)              ; 10E32/10DAC
        move.b  #$2,$2(a4)                      ; 10E38/10DB2
        clr.b   $3(a4)                          ; 10E3E/10DB8
        clr.b   $4(a4)                          ; 10E42/10DBC
        clr.b   $5(a4)                          ; 10E46/10DC0
        move.b  #$1,(a4)                        ; 10E4A/10DC4
        clr.b   $1(a4)                          ; 10E4E/10DC8
        move.w  $6(a3),d0                       ; 10E52/10DCC
        addi.w  #$c,d0                          ; 10E56/10DD0
        move.w  d0,$6(a4)                       ; 10E5A/10DD4
        move.w  $a(a3),d0                       ; 10E5E/10DD8
        addq.w  #$2,d0                          ; 10E62/10DDC
        move.w  d0,$a(a4)                       ; 10E64/10DDE
