        lea.l   DragonMoveTable(pc),a0          ; 10EB4/10E2E
        move.l  a0,O_MoveTable(a5)              ; 10EB8/10E32
        clr.b   Drg_NewDir(a5)                  ; 10EBC/10E36
        clr.b   Drg_Delay(a5)                   ; 10EC0/10E3A
        clr.b   Drg_Pending(a5)                 ; 10EC4/10E3E
        clr.b   Drg_Frozen(a5)                  ; 10EC8/10E42
        clr.b   Drg_Firing(a5)                  ; 10ECC/10E46
        move.b  #$1,O_HP(a5)                    ; 10ED0/10E4A
        move.b  #$1,Drg_Part(a5)                ; 10ED6/10E50
        move.b  #ST_ACTIVE,O_State(a5)          ; 10EDC/10E56
        clr.b   O_Step(a5)                      ; 10EE2/10E5C
        clr.b   O_Step2(a5)                     ; 10EE6/10E60
        rts                                     ; 10EEA/10E64

;---------------------------------------------------------------------------
; Tail: size 0, 1 HP, Drg_Part 2
;---------------------------------------------------------------------------
Dragon_InitTail:
        clr.b   O_Dir(a5)                       ; 10EEC/10E66
        move.w  O_X(a5),d0                      ; 10EF0/10E6A
        sub.w   g_ArthurX(a6),d0                ; 10EF4/10E6E
        blt.b   l_10F00                         ; 10EF8/10E72
        move.b  #$8,O_Dir(a5)                   ; 10EFA/10E74
l_10F00:
        move.b  #$0,O_Size(a5)                  ; 10F00/10E7A
        lea.l   Dragon_AnimTail(pc),a0          ; 10F06/10E80
        bsr.w   SetAnim                         ; 10F0A/10E84  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10F0E/10E88
        move.l  a0,O_MoveTable(a5)              ; 10F12/10E8C
        clr.b   Drg_NewDir(a5)                  ; 10F16/10E90
        clr.b   Drg_Delay(a5)                   ; 10F1A/10E94
        clr.b   Drg_Pending(a5)                 ; 10F1E/10E98
        clr.b   Drg_Frozen(a5)                  ; 10F22/10E9C
        clr.b   Drg_Firing(a5)                  ; 10F26/10EA0
        move.b  #$1,O_HP(a5)                    ; 10F2A/10EA4
        move.b  #$2,Drg_Part(a5)                ; 10F30/10EAA
        move.b  #ST_ACTIVE,O_State(a5)          ; 10F36/10EB0
        clr.b   O_Step(a5)                      ; 10F3C/10EB6
        clr.b   O_Step2(a5)                     ; 10F40/10EBA
        rts                                     ; 10F44/10EBE

;---------------------------------------------------------------------------
; DragonEntrancePath - (frames, direction) steps flown on arrival (DSTEP; directions as
; DragonMoveTable: 0 right, 4 down, 8 left, 12 up), ended by a zero word. Then DragonPatrolPath.
;---------------------------------------------------------------------------
DragonEntrancePath:
	DSTEP	10,9	; WNW
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,7	; WSW
	DSTEP	10,8	; W
	dc.w	0		; end

;---------------------------------------------------------------------------
; 16-way (dx, dy) at 2 px/frame (8.8), 0 = right, 4 = down
;---------------------------------------------------------------------------
DragonMoveTable:
	dc.b	$02,$00,$00,$00,$01,$D9,$FF,$3D,$01,$6A,$FE,$96,$00,$C3,$FE,$27
	dc.b	$00,$00,$FE,$00,$FF,$3D,$FE,$27,$FE,$96,$FE,$96,$FE,$27,$FF,$3D
	dc.b	$FE,$00,$00,$00,$FE,$27,$00,$C3,$FE,$96,$01,$6A,$FF,$3D,$01,$D9
	dc.b	$00,$00,$02,$00,$00,$C3,$01,$D9,$01,$6A,$01,$6A,$01,$D9,$00,$C3

;---------------------------------------------------------------------------
; State 1: head or segment; then remove it when far off screen (not on levels 2-3)
;---------------------------------------------------------------------------
Dragon_Active:
        tst.b   Drg_Part(a5)                    ; 10F94/10F0E
        bne.b   l_10F9E                         ; 10F98/10F12
        bsr.b   Dragon_Head                     ; 10F9A/10F14
        bra.b   l_10FA2                         ; 10F9C/10F16
l_10F9E:
        bsr.w   Dragon_Segment                  ; 10F9E/10F18
l_10FA2:
        cmpi.w  #$2,g_Level(a6)                 ; 10FA2/10F1C  levels 2 and 3: never removed
        beq.b   l_10FE4                         ; 10FA8/10F22
        cmpi.w  #$3,g_Level(a6)                 ; 10FAA/10F24
        beq.b   l_10FE4                         ; 10FB0/10F2A
        move.w  O_X(a5),d0                      ; 10FB2/10F2C
        sub.w   g_CameraX(a6),d0                ; 10FB6/10F30
        addi.w  #$180,d0                        ; 10FBA/10F34
        cmp.w   #$400,d0                        ; 10FBE/10F38
        bhi.b   l_10FD6                         ; 10FC2/10F3C
        move.w  O_Y(a5),d0                      ; 10FC4/10F3E
        sub.w   g_CameraY(a6),d0                ; 10FC8/10F42
        addi.w  #$180,d0                        ; 10FCC/10F46
        cmp.w   #$400,d0                        ; 10FD0/10F4A
        bls.b   l_10FE4                         ; 10FD4/10F4E
l_10FD6:
        move.b  #ST_REMOVE,O_State(a5)          ; 10FD6/10F50
        clr.b   O_Step(a5)                      ; 10FDC/10F56
        clr.b   O_Step2(a5)                     ; 10FE0/10F5A
l_10FE4:
        rts                                     ; 10FE4/10F5E

;---------------------------------------------------------------------------
; O_Step 0 = entrance (O_Step2 0 start, 1 path, 2 pick wait, 3 wait to be seen,
; 4 wait for Arthur), O_Step 1 = attack.
;---------------------------------------------------------------------------
Dragon_Head:
        tst.b   O_Step(a5)                      ; 10FE6/10F60
        bne.w   Dragon_Attack                   ; 10FEA/10F64
        move.b  O_Step2(a5),d0                  ; 10FEE/10F68
        add.w   d0,d0                           ; 10FF2/10F6C
        add.w   d0,d0                           ; 10FF4/10F6E
        jmp     Dragon_Head_Jumps(pc,d0.w)      ; 10FF6/10F70
Dragon_Head_Jumps:
        bra.w   Dragon_EntranceStart            ; 10FFA/10F74
        bra.w   Dragon_EntrancePath             ; 10FFE/10F78
        bra.w   Dragon_PickWait                 ; 11002/10F7C
        bra.w   Dragon_WaitSeen                 ; 11006/10F80
        bra.w   Dragon_WaitArthur               ; 1100A/10F84
Dragon_EntranceStart:
        movea.l Drg_Next(a5),a4                 ; 1100E/10F88
        move.b  Drg_PathTime(a5),$39(a4)        ; 11012/10F8C
        move.b  O_Dir(a5),$38(a4)               ; 11018/10F92
        move.b  #$1,$34(a4)                     ; 1101E/10F98
        addq.b  #$1,O_Step2(a5)                 ; 11024/10F9E
        rts                                     ; 11028/10FA2

;---------------------------------------------------------------------------
; Follow the entrance path, handing each new direction to the next segment.
; At its end: freeze every segment and load the patrol path.
;---------------------------------------------------------------------------
Dragon_EntrancePath:
        subq.b  #$1,Drg_PathTime(a5)            ; 1102A/10FA4
        bne.b   l_11060                         ; 1102E/10FA8
        movea.l Drg_PathPtr(a5),a0              ; 11030/10FAA
        move.b  (a0)+,d0                        ; 11034/10FAE
        move.b  (a0)+,d1                        ; 11036/10FB0
        tst.w   -$2(a0)                         ; 11038/10FB2
        beq.b   l_11062                         ; 1103C/10FB6
        move.b  d0,Drg_PathTime(a5)             ; 1103E/10FB8
        move.b  d1,O_Dir(a5)                    ; 11042/10FBC
        move.l  a0,Drg_PathPtr(a5)              ; 11046/10FC0
        movea.l Drg_Next(a5),a4                 ; 1104A/10FC4
        move.b  d0,$39(a4)                      ; 1104E/10FC8
        move.b  d1,$38(a4)                      ; 11052/10FCC
        move.b  #$1,$34(a4)                     ; 11056/10FD0
        bra.w   ApplyMoveTable                  ; 1105C/10FD6
l_11060:
        rts                                     ; 11060/10FDA
l_11062:
        moveq   #$8,d6                          ; 11062/10FDC
        movea.l a5,a4                           ; 11064/10FDE
l_11066:
        move.b  #$1,$35(a4)                     ; 11066/10FE0
        movea.l $24(a4),a4                      ; 1106C/10FE6
        dbra    d6,l_11066                      ; 11070/10FEA
        lea.l   DragonPatrolPath(pc),a0         ; 11074/10FEE  patrol path
        adda.w  (a0),a0                         ; 11078/10FF2
        move.b  (a0)+,Drg_PathTime(a5)          ; 1107A/10FF4
        move.b  (a0)+,O_Dir(a5)                 ; 1107E/10FF8
        move.l  a0,Drg_PathPtr(a5)              ; 11082/10FFC
        movea.l Drg_Next(a5),a4                 ; 11086/11000
        move.b  Drg_PathTime(a5),$39(a4)        ; 1108A/11004
        move.b  O_Dir(a5),$38(a4)               ; 11090/1100A
        move.b  #$1,$34(a4)                     ; 11096/11010
        addq.b  #$1,O_Step2(a5)                 ; 1109C/11016
        rts                                     ; 110A0/1101A

;---------------------------------------------------------------------------
; x 16 frames: 3, 2, 3, 2 (level 5: 5, 2, 5, 4)
;---------------------------------------------------------------------------
DragonWaitTimes:
	dc.b	$03,$02,$03,$02

;---------------------------------------------------------------------------
; Dragon wait times on level 5 (DragonWaitTimes elsewhere)
;---------------------------------------------------------------------------
DragonWaitTimesL5:
	dc.b	$05,$02,$05,$04
Dragon_PickWait:
        lea.l   DragonWaitTimesL5(pc),a0        ; 110AA/11024
        cmpi.w  #$5,g_Level(a6)                 ; 110AE/11028
        beq.b   l_110BA                         ; 110B4/1102E
        lea.l   DragonWaitTimes(pc),a0          ; 110B6/11030
l_110BA:
        move.w  g_GameFrame(a6),d0              ; 110BA/11034
        add.w   d7,d0                           ; 110BE/11038
        andi.w  #$3,d0                          ; 110C0/1103A
        adda.w  d0,a0                           ; 110C4/1103E
        move.b  (a0),Drg_Wait(a5)               ; 110C6/11040
        addq.b  #$1,O_Step2(a5)                 ; 110CA/11044
        rts                                     ; 110CE/11048
Dragon_WaitSeen:
        tst.b   O_OnScreen(a5)                  ; 110D0/1104A
        beq.b   l_110DA                         ; 110D4/1104E
        addq.b  #$1,O_Step2(a5)                 ; 110D6/11050
l_110DA:
        rts                                     ; 110DA/11054

;---------------------------------------------------------------------------
; Count down Drg_Wait (every 16 frames) while Arthur is no more than 32 px below;
; then unfreeze the chain and attack
;---------------------------------------------------------------------------
Dragon_WaitArthur:
        move.w  g_ArthurY(a6),d0                ; 110DC/11056
        addi.w  #$20,d0                         ; 110E0/1105A
        sub.w   O_Y(a5),d0                      ; 110E4/1105E  Arthur more than 32 px below it: wait
        bmi.b   l_1111E                         ; 110E8/11062
        move.w  g_GameFrame(a6),d0              ; 110EA/11064
        addq.w  #$1,d0                          ; 110EE/11068
        andi.w  #$f,d0                          ; 110F0/1106A
        bne.b   l_1111E                         ; 110F4/1106E
        subq.b  #$1,Drg_Wait(a5)                ; 110F6/11070
        bne.b   l_1111E                         ; 110FA/11074
        move.b  #$1,O_Step(a5)                  ; 110FC/11076
        clr.b   O_Step2(a5)                     ; 11102/1107C
        addq.b  #$1,g_BigEnemyCount(a6)         ; 11106/11080  one more big enemy engaged
        moveq   #$8,d6                          ; 1110A/11084
        movea.l a5,a4                           ; 1110C/11086
l_1110E:
        clr.b   $35(a4)                         ; 1110E/11088
        move.l  $24(a4),d0                      ; 11112/1108C
        beq.b   l_1111E                         ; 11116/11090
        movea.l d0,a4                           ; 11118/11092
        dbra    d6,l_1110E                      ; 1111A/11094
l_1111E:
        rts                                     ; 1111E/11098

;---------------------------------------------------------------------------
; Flap every 128 frames, steer, breathe fire, move
;---------------------------------------------------------------------------
Dragon_Attack:
        move.w  g_GameFrame(a6),d0              ; 11120/1109A
        addq.w  #$1,d0                          ; 11124/1109E
        andi.w  #$7f,d0                         ; 11126/110A0
        bne.b   l_11144                         ; 1112A/110A4
        lea.l   Dragon_AnimFlap(pc),a0          ; 1112C/110A6
        tst.b   Drg_Facing(a5)                  ; 11130/110AA
        beq.b   l_11138                         ; 11134/110AE
        addq.l  #$2,a0                          ; 11136/110B0
l_11138:
        adda.w  (a0),a0                         ; 11138/110B2
        move.l  a0,O_Anim(a5)                   ; 1113A/110B4
        move.b  #$a,O_AnimTimer(a5)             ; 1113E/110B8
snd152_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd152_512                      
        move    (a7)+,ccr                       
        moveq   #SFX_STOMP,d0                   ;      /110BE  effect 24: the dragon attacks
        bsr.w   PlaySfx                         ;      /110C0
        bra.w   snd152_end                      
snd152_512:
        move    (a7)+,ccr                       
snd152_end:
l_11144:
        bsr.w   Animate                         ; 11144/110C4  animate
        bsr.w   Random                          ; 11148/110C8  random number
        move.b  d0,d5                           ; 1114C/110CC
        bsr.b   Dragon_Steer                    ; 1114E/110CE
        bsr.w   Dragon_Breathe                  ; 11150/110D0
        bra.w   ApplyMoveTable                  ; 11154/110D4

;---------------------------------------------------------------------------
; When the path step ends: maybe dive at Arthur, turn round, or climb / descend
; towards his height (level 5: stay near Drg_HomeY)
;---------------------------------------------------------------------------
Dragon_Steer:
        subq.b  #$1,Drg_PathTime(a5)            ; 11158/110D8
        beq.b   l_11160                         ; 1115C/110DC
        rts                                     ; 1115E/110DE
l_11160:
        cmpi.w  #$5,g_Level(a6)                 ; 11160/110E0  level 5: never dives
        beq.b   Dragon_TurnCheck                ; 11166/110E6
        moveq   #$f,d0                          ; 11168/110E8  3 in 16 chance to dive
        and.b   d5,d0                           ; 1116A/110EA
        cmp.b   Drg_Aggro(a5),d0                ; 1116C/110EC
        bhi.b   Dragon_TurnCheck                ; 11170/110F0
        tst.b   Drg_Facing(a5)                  ; 11172/110F2
        beq.b   l_111B0                         ; 11176/110F6
        move.w  O_X(a5),d0                      ; 11178/110F8  facing left: Arthur must be 24+ px to the left
        sub.w   g_ArthurX(a6),d0                ; 1117C/110FC
        subi.w  #$18,d0                         ; 11180/11100
        bmi.b   Dragon_TurnCheck                ; 11184/11104

;---------------------------------------------------------------------------
; Head for Arthur (not straight down) for 40 frames, 18 if it is in the bottom 96 px of the screen
;---------------------------------------------------------------------------
Dragon_DiveAtArthur:
        bsr.w   DirectionToArthur               ; 11186/11106  direction towards Arthur
        cmp.b   #$4,d0                          ; 1118A/1110A  not straight down
        beq.b   Dragon_TurnCheck                ; 1118E/1110E
        move.b  d0,d4                           ; 11190/11110
        move.w  g_CameraY(a6),d3                ; 11192/11112
        addi.w  #$60,d3                         ; 11196/11116
        moveq   #$28,d0                         ; 1119A/1111A
        move.w  O_Y(a5),d1                      ; 1119C/1111C
        cmp.w   d3,d1                           ; 111A0/11120
        bhi.b   l_111A6                         ; 111A2/11122
        moveq   #$12,d0                         ; 111A4/11124
l_111A6:
        move.b  d4,d1                           ; 111A6/11126
        movea.l Drg_PathPtr(a5),a0              ; 111A8/11128
        bra.w   Dragon_SetPathStep              ; 111AC/1112C
l_111B0:
        move.w  g_ArthurX(a6),d0                ; 111B0/11130
        sub.w   O_X(a5),d0                      ; 111B4/11134
        subi.w  #$18,d0                         ; 111B8/11138
        bpl.b   Dragon_DiveAtArthur             ; 111BC/1113C
Dragon_TurnCheck:
        move.w  O_X(a5),d0                      ; 111BE/1113E
        cmp.w   g_ArthurX(a6),d0                ; 111C2/11142
        bhi.b   l_111D2                         ; 111C6/11146
        tst.b   Drg_Facing(a5)                  ; 111C8/11148
        bne.b   l_111DA                         ; 111CC/1114C
        bra.w   Dragon_SeekHeight               ; 111CE/1114E
l_111D2:
        tst.b   Drg_Facing(a5)                  ; 111D2/11152
        bne.w   Dragon_SeekHeight               ; 111D6/11156
l_111DA:
        move.w  g_LevelWidth(a6),d0             ; 111DA/1115A  past the right end of the level, or 94+ px past Arthur: turn
        addi.w  #$100,d0                        ; 111DE/1115E
        cmp.w   O_X(a5),d0                      ; 111E2/11162
        bls.b   Dragon_Turn                     ; 111E6/11166
        move.w  O_X(a5),d0                      ; 111E8/11168
        sub.w   g_ArthurX(a6),d0                ; 111EC/1116C
        addi.w  #$5e,d0                         ; 111F0/11170
        cmp.w   #$bc,d0                         ; 111F4/11174
        bcs.w   Dragon_SeekHeight               ; 111F8/11178

;---------------------------------------------------------------------------
; Turn round: path for the upper or lower half of the screen, flip Drg_Facing
;---------------------------------------------------------------------------
Dragon_Turn:
        move.w  g_CameraY(a6),d3                ; 111FC/1117C
        addi.w  #$80,d3                         ; 11200/11180
        moveq   #$0,d0                          ; 11204/11184
        move.w  O_Y(a5),d1                      ; 11206/11186
        cmp.w   d3,d1                           ; 1120A/1118A
        bcs.b   l_11210                         ; 1120C/1118C
        moveq   #$2,d0                          ; 1120E/1118E
l_11210:
        lea.l   DragonTurnRight(pc),a0          ; 11210/11190
        clr.w   d1                              ; 11214/11194
        move.b  Drg_Facing(a5),d1               ; 11216/11196
        beq.b   l_11220                         ; 1121A/1119A
        lea.l   DragonTurnLeft(pc),a0           ; 1121C/1119C
l_11220:
        adda.w  d0,a0                           ; 11220/111A0
        adda.w  (a0),a0                         ; 11222/111A2
        move.l  a0,Drg_PathPtr(a5)              ; 11224/111A4
        eori.b  #$1,d1                          ; 11228/111A8
        move.b  d1,Drg_Facing(a5)               ; 1122C/111AC
        add.w   d1,d1                           ; 11230/111B0
        lea.l   Dragon_AnimFly(pc),a0           ; 11232/111B2
        adda.w  d1,a0                           ; 11236/111B6
        adda.w  (a0),a0                         ; 11238/111B8
        bsr.w   SetAnim                         ; 1123A/111BA  start animation

;---------------------------------------------------------------------------
; Next (frames, direction) pair; bit 7 = loop (offset follows)
;---------------------------------------------------------------------------
Dragon_NextPathStep:
        movea.l Drg_PathPtr(a5),a0              ; 1123E/111BE
        move.b  (a0)+,d0                        ; 11242/111C2
        move.b  (a0)+,d1                        ; 11244/111C4
        tst.b   d0                              ; 11246/111C6
        bpl.b   Dragon_SetPathStep              ; 11248/111C8
        andi.b  #$7f,d0                         ; 1124A/111CA
        adda.w  (a0),a0                         ; 1124E/111CE

;---------------------------------------------------------------------------
; Take a (frames, direction) step and hand the direction to the next segment
; (10-frame delay)
;---------------------------------------------------------------------------
Dragon_SetPathStep:
        move.b  d0,Drg_PathTime(a5)             ; 11250/111D0
        move.b  d1,O_Dir(a5)                    ; 11254/111D4
        move.l  a0,Drg_PathPtr(a5)              ; 11258/111D8
        move.l  Drg_Next(a5),d0                 ; 1125C/111DC
        beq.b   l_1127E                         ; 11260/111E0
        movea.l d0,a4                           ; 11262/111E2
        move.b  O_Dir(a5),d0                    ; 11264/111E4
        cmp.b   $12(a4),d0                      ; 11268/111E8
        beq.b   l_1127E                         ; 1126C/111EC
        move.b  d0,$38(a4)                      ; 1126E/111EE
        move.b  #$a,$39(a4)                     ; 11272/111F2
        move.b  #$1,$34(a4)                     ; 11278/111F8
l_1127E:
        rts                                     ; 1127E/111FE

;---------------------------------------------------------------------------
; 160+ px above Arthur: descend; below him: climb; else carry on (36-frame steps)
;---------------------------------------------------------------------------
Dragon_SeekHeight:
        cmpi.w  #$5,g_Level(a6)                 ; 11280/11200
        beq.b   l_112B4                         ; 11286/11206
        lea.l   DragonClimb(pc),a0              ; 11288/11208
        move.w  O_Y(a5),d0                      ; 1128C/1120C
        sub.w   g_ArthurY(a6),d0                ; 11290/11210
        bmi.b   l_112A0                         ; 11294/11214
        cmp.w   #$a0,d0                         ; 11296/11216  more than 160 px above him?
        bcs.b   Dragon_NextPathStep             ; 1129A/1121A
        lea.l   DragonDescend(pc),a0            ; 1129C/1121C
l_112A0:
        move.b  Drg_Facing(a5),d0               ; 112A0/11220
        ext.w   d0                              ; 112A4/11224
        add.w   d0,d0                           ; 112A6/11226
        adda.w  d0,a0                           ; 112A8/11228
        move.b  (a0)+,d0                        ; 112AA/1122A
        move.b  (a0)+,d1                        ; 112AC/1122C
        movea.l Drg_PathPtr(a5),a0              ; 112AE/1122E
        bra.b   Dragon_SetPathStep              ; 112B2/11232
l_112B4:
        move.w  Drg_HomeY(a5),d0                ; 112B4/11234  level 5: more than 256 px from its start height, or 94+ px from Arthur: head back
        sub.w   g_ArthurY(a6),d0                ; 112B8/11238
        addi.w  #$100,d0                        ; 112BC/1123C
        cmp.w   #$200,d0                        ; 112C0/11240
        bhi.b   l_112EE                         ; 112C4/11244
        move.w  O_Y(a5),d0                      ; 112C6/11246
        sub.w   g_ArthurY(a6),d0                ; 112CA/1124A
        addi.w  #$5e,d0                         ; 112CE/1124E
        cmp.w   #$bc,d0                         ; 112D2/11252
        bcs.w   Dragon_NextPathStep             ; 112D6/11256
        lea.l   DragonClimb(pc),a0              ; 112DA/1125A
        move.w  O_Y(a5),d0                      ; 112DE/1125E
        cmp.w   g_ArthurY(a6),d0                ; 112E2/11262
        bcs.b   l_112EC                         ; 112E6/11266
        lea.l   DragonDescend(pc),a0            ; 112E8/11268
l_112EC:
        bra.b   l_112A0                         ; 112EC/1126C
