	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,9	; WNW
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,5	; SSW
	DSTEP	10,5	; SSW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,8	; W
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,10	; NW
	DSTEP	10,7	; WSW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,7	; WSW
	DSTEP	10,11	; NNW
	DSTEP	10,8	; W
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DLOOP	10,6,DragonPatrolLeftward	; SW, then loop
DragonPatrolRightward:
	DSTEP	10,0	; E
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,15	; ENE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,0	; E
