	DSTEP	10,15	; ENE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
