;---------------------------------------------------------------------------
; DragonTurnRight - turn paths when facing right: upper / lower half of the screen.
;---------------------------------------------------------------------------
DragonTurnRight:
	dc.w	DragonTurnRightUpper-*	; in the upper half of the screen
	dc.w	DragonTurnRightLower-*	; in the lower half of the screen
DragonTurnRightUpper:
	DSTEP	10,13	; NNE
	DSTEP	10,12	; N
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
