DragonTurnLeftLower:
	DSTEP	10,5	; SSW
	DSTEP	10,4	; S
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DLOOP	10,1,DragonPatrolRightward	; ESE, then loop

;---------------------------------------------------------------------------
; State 2. O_Step: 0 decide, 1 head: sound 12, 2 explode, 3 wait then +1000,
; 4 segment: sound 20, 5 explode, 6 wait
;---------------------------------------------------------------------------
Dragon_Dying:
        move.b  O_Step(a5),d0                   ; 114EE/1146E
        add.w   d0,d0                           ; 114F2/11472
        add.w   d0,d0                           ; 114F4/11474
        jmp     Dragon_Dying_Jumps(pc,d0.w)     ; 114F6/11476
Dragon_Dying_Jumps:
        bra.w   Dragon_HitSegment               ; 114FA/1147A
        bra.w   Dragon_HeadDies                 ; 114FE/1147E
        bra.w   EnemyExplode                    ; 11502/11482
        bra.w   Dragon_HeadWait                 ; 11506/11486
        bra.w   Dragon_SegmentDies              ; 1150A/1148A
        bra.w   EnemyBurst                      ; 1150E/1148E
        bra.w   Dragon_SegmentWait              ; 11512/11492

;---------------------------------------------------------------------------
; Head: every segment dies with it. Tail: unlink it. Body segment: it lives on and
; the tail dies instead.
;---------------------------------------------------------------------------
Dragon_HitSegment:
        movea.l a5,a4                           ; 11516/11496
        move.b  $37(a4),d0                      ; 11518/11498
        beq.b   l_1154A                         ; 1151C/1149C
        cmp.b   #$8,d0                          ; 1151E/1149E  the head?
        beq.b   l_1156C                         ; 11522/114A2
l_11524:
        movea.l $24(a4),a4                      ; 11524/114A4  a body segment: find the tail
        tst.b   $37(a4)                         ; 11528/114A8
        bne.b   l_11524                         ; 1152C/114AC
        addq.b  #$1,(a4)                        ; 1152E/114AE  kill the tail instead (O_Active 2)
        move.b  #ST_ACTIVE,O_State(a5)          ; 11530/114B0  and this segment carries on
        clr.b   O_Step(a5)                      ; 11536/114B6
        move.b  #$1,(a5)                        ; 1153A/114BA
        clr.b   O_HP(a5)                        ; 1153E/114BE
        move.l  a4,-(a7)                        ; 11542/114C2
        bsr.w   Dragon_Segment                  ; 11544/114C4
        movea.l (a7)+,a4                        ; 11548/114C8
l_1154A:
        movea.l $28(a4),a3                      ; 1154A/114CA  unlink the dying segment: the one before it becomes the tail
        cmpi.b  #$8,$37(a3)                     ; 1154E/114CE
        beq.b   l_1155A                         ; 11554/114D4
        clr.b   $37(a3)                         ; 11556/114D6
l_1155A:
        clr.l   $24(a3)                         ; 1155A/114DA
        move.b  #$2,$3(a4)                      ; 1155E/114DE  state 2, step 4: segment death
        move.b  #$4,$4(a4)                      ; 11564/114E4
        rts                                     ; 1156A/114EA
l_1156C:
        move.l  $24(a4),d0                      ; 1156C/114EC
        beq.b   l_11588                         ; 11570/114F0
l_11572:
        movea.l d0,a3                           ; 11572/114F2
        move.b  #$2,$3(a3)                      ; 11574/114F4  every segment: state 2 step 4
        move.b  #$4,$4(a3)                      ; 1157A/114FA
        addq.b  #$1,(a3)                        ; 11580/11500
        move.l  $24(a3),d0                      ; 11582/11502
        bne.b   l_11572                         ; 11586/11506
l_11588:
        move.b  #$2,$3(a4)                      ; 11588/11508
        move.b  #$1,$4(a4)                      ; 1158E/1150E
        rts                                     ; 11594/11514
Dragon_HeadDies:
        moveq   #SFX_ENEMY_HIT,d0               ; 11596/11516
