        move.b  #$1,Drg_HeadDead(a5)            ; 1159C/1151C
        move.b  #$3f,Drg_PathTime(a5)           ; 115A2/11522
        addq.b  #$1,O_Step(a5)                  ; 115A8/11528  next step
        clr.b   O_Step2(a5)                     ; 115AC/1152C
        rts                                     ; 115B0/11530
Dragon_HeadWait:
        subq.b  #$1,Drg_PathTime(a5)            ; 115B2/11532
        bne.b   l_115C4                         ; 115B6/11536
        moveq   #PTS_1000,d0                    ; 115B8/11538
        bsr.w   AddScore                        ; 115BA/1153A  +1000 for the head
        move.b  #ST_REMOVE,O_State(a5)          ; 115BE/1153E
l_115C4:
        rts                                     ; 115C4/11544
Dragon_SegmentDies:
        moveq   #SFX_ENEMY_DIE2,d0              ; 115C6/11546
        bsr.w   PlaySfx                         ; 115C8/11548  sound effect 20 (enemy event)
        clr.b   Drg_HeadDead(a5)                ; 115CC/1154C
        move.b  #$3f,Drg_PathTime(a5)           ; 115D0/11550
        addq.b  #$1,O_Step(a5)                  ; 115D6/11556  next step
        clr.b   O_Step2(a5)                     ; 115DA/1155A
        rts                                     ; 115DE/1155E
Dragon_SegmentWait:
        subq.b  #$1,Drg_PathTime(a5)            ; 115E0/11560
        bne.b   l_115EC                         ; 115E4/11564
        move.b  #ST_REMOVE,O_State(a5)          ; 115E6/11566
l_115EC:
        rts                                     ; 115EC/1156C

