;---------------------------------------------------------------------------
; === Astaroth (type 13, 10000 pts, 10 hits, cross only (final boss)) ===
; Seated final boss in the throne room: fires projectiles; can only be hurt by the cross, in a narrow band (see EnemyHitByShot); its last hit calls BossKilled -> Ending.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits until on screen, then walks to and fro in a 128-pixel arena (camera X + 96
;     to + 224), at a random 0.18 or 0.41 px/frame, turning at the ends and after a
;     random 0-1023 frames, always facing Arthur.
;   * Fires enemy shot type 10 the way it faces, from a lower (Y-5) or upper (Y+12)
;     point, every 70-180 frames (AstarothShotGaps). While Arthur is within 80 px the shot
;     timer runs at a quarter of the speed and shots come from the lower point; further
;     away they come from whichever point was chosen last.
;   * A stand-and-fire phase (every 256-767 frames, faster shots from AstarothFastGaps)
;     is coded, but the branch that should keep it going is the wrong way round: the
;     phase ends in the same frame it starts.
;   * 10 hits, by the cross only (EnemyVulnerability).
;---------------------------------------------------------------------------
Enemy_Astaroth:
        move.b  O_State(a5),d0                  ; 11640/115C0
        add.w   d0,d0                           ; 11644/115C4
        add.w   d0,d0                           ; 11646/115C6
        jmp     Enemy_Astaroth_Jumps(pc,d0.w)   ; 11648/115C8
Enemy_Astaroth_Jumps:
        bra.w   Astaroth_Init                   ; 1164C/115CC
        bra.w   Astaroth_Active                 ; 11650/115D0
        bra.w   Astaroth_Dying                  ; 11654/115D4
        bra.w   Astaroth_Free                   ; 11658/115D8

;---------------------------------------------------------------------------
; State 0: size 6, 10 HP, then wait to be on screen and fix the arena
;---------------------------------------------------------------------------
Astaroth_Init:
        tst.b   O_Step(a5)                      ; 1165C/115DC
        bne.b   Astaroth_Wake                   ; 11660/115E0
        move.b  #$6,O_Size(a5)                  ; 11662/115E2
        move.b  #$1,O_Dir(a5)                   ; 11668/115E8
        move.b  #$1,Ast_Facing(a5)              ; 1166E/115EE
        clr.b   Ast_Turning(a5)                 ; 11674/115F4
        clr.b   Ast_Standing(a5)                ; 11678/115F8
        clr.b   Ast_HighShot(a5)                ; 1167C/115FC
        lea.l   AstarothMoveTables(pc),a0       ; 11680/11600
        move.l  a0,O_MoveTable(a5)              ; 11684/11604
        move.b  #$a,O_HP(a5)                    ; 11688/11608
        bsr.w   Astaroth_NextStand              ; 1168E/1160E
        bsr.w   Astaroth_NextShotTime           ; 11692/11612
        addq.b  #$1,O_Step(a5)                  ; 11696/11616  next step
        rts                                     ; 1169A/1161A
Astaroth_Wake:
        tst.b   O_OnScreen(a5)                  ; 1169C/1161C
        beq.b   l_116C2                         ; 116A0/11620
        move.w  g_CameraX(a6),d0                ; 116A2/11622  arena: camera X + 96 ... + 224
        addi.w  #$60,d0                         ; 116A6/11626
        move.w  d0,Ast_ArenaL(a5)               ; 116AA/1162A
        addi.w  #$80,d0                         ; 116AE/1162E
        move.w  d0,Ast_ArenaR(a5)               ; 116B2/11632
        addq.b  #ST_ACTIVE,O_State(a5)          ; 116B6/11636
        clr.b   O_Step(a5)                      ; 116BA/1163A
        clr.b   O_Step2(a5)                     ; 116BE/1163E
l_116C2:
        rts                                     ; 116C2/11642

;---------------------------------------------------------------------------
; Walk with its move table; stop and turn at the arena ends
;---------------------------------------------------------------------------
Astaroth_Walk:
        move.w  d7,d0                           ; 116C4/11644
        add.w   g_GameFrame(a6),d0              ; 116C6/11646
        andi.w  #$1f,d0                         ; 116CA/1164A
snd153_go:
        move    sr,-(a7)                        ; sound: the 1MB code with its music package, else the 512K code
        btst    #PF_MUSIC,(Profile).l           
        beq.b   snd153_512                      
        move    (a7)+,ccr                       
        bne.b   l1m_11656                       ;      /1164E
        moveq   #SFX_THUD,d0                    ;      /11650
        bsr.w   PlaySfx                         ;      /11652
l1m_11656:
        bra.w   snd153_end                      
snd153_512:
        move    (a7)+,ccr                       
        bne.b   l_116D2                         ; 116CE/     
        moveq   #$c,d0                          ; 116D0/       d0 is not used by what follows. [1MB build: PlaySfx here, effect 9 (footstep); the call was removed in 512K]
