;---------------------------------------------------------------------------
; === Princess / (unused 16) / Man-eater plant (types 15, 16, 17) ===
; Shared stationary handler: animates in place and, for the plant, spits projectiles (eyeballs) at Arthur when on screen. The princess uses it in the cut-scenes.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: faces Arthur; while on screen it waits PlantWaits frames, opens its
; mouth for 24 frames and spits enemy shot type 6, then waits again.
;---------------------------------------------------------------------------
Enemy_Princess_Unused16_Plant:
        move.w  g_GameFrame(a6),d0              ; 11B1A/11AA2
        add.b   d7,d0                           ; 11B1E/11AA6
        andi.b  #$f,d0                          ; 11B20/11AA8
        bne.b   l_11B2A                         ; 11B24/11AAC
        bsr.w   CheckOnScreen                   ; 11B26/11AAE  visible?
l_11B2A:
        clr.w   d0                              ; 11B2A/11AB2
        move.b  O_State(a5),d0                  ; 11B2C/11AB4
        add.w   d0,d0                           ; 11B30/11AB8
        add.w   d0,d0                           ; 11B32/11ABA
        jmp     Enemy_Princess_Unused16_Plant_Jumps(pc,d0.w); 11B34/11ABC
Enemy_Princess_Unused16_Plant_Jumps:
        bra.w   Plant_Init                      ; 11B38/11AC0
        bra.w   Plant_Active                    ; 11B3C/11AC4
        bra.w   Plant_Dying                     ; 11B40/11AC8
        bra.w   Plant_Free                      ; 11B44/11ACC
Plant_Init:
        move.b  #$1,O_Size(a5)                  ; 11B48/11AD0
        move.w  O_X(a5),d0                      ; 11B4E/11AD6
        cmp.w   g_ArthurX(a6),d0                ; 11B52/11ADA
        slt.b   O_Dir(a5)                       ; 11B56/11ADE
        addq.b  #$1,O_Dir(a5)                   ; 11B5A/11AE2
        lea.l   Plant_AnimIdle(pc),a0           ; 11B5E/11AE6
        bsr.w   SetAnimIndexed                  ; 11B62/11AEA  start animation for current direction
        lea.l   PlantWaits(pc),a0               ; 11B66/11AEE
        move.b  (a0)+,Plt_Wait(a5)              ; 11B6A/11AF2
        move.l  a0,Plt_WaitPtr(a5)              ; 11B6E/11AF6
        addq.b  #ST_ACTIVE,O_State(a5)          ; 11B72/11AFA
        clr.b   O_Step(a5)                      ; 11B76/11AFE
        clr.b   O_Step2(a5)                     ; 11B7A/11B02
        rts                                     ; 11B7E/11B06
	dc.b	$00

;---------------------------------------------------------------------------
; frames between spits (bit 7 = loop)
;---------------------------------------------------------------------------
PlantWaits:
	dc.b	$41,$46,$08,$50,$08
	dc.b	'7<UPZ!IKZ-'
	dc.b	$09,$4F,$1D,$50,$2D,$B5,$FF,$EB

;---------------------------------------------------------------------------
; State 1. O_Step: 0 wait to be on screen, 1 wait, 2 spit
;---------------------------------------------------------------------------
Plant_Active:
        move.b  O_Step(a5),d0                   ; 11B98/11B20
        add.w   d0,d0                           ; 11B9C/11B24
        add.w   d0,d0                           ; 11B9E/11B26
        jmp     Plant_Active_Jumps(pc,d0.w)     ; 11BA0/11B28
Plant_Active_Jumps:
        bra.w   Plant_WaitSeen                  ; 11BA4/11B2C
        bra.w   Plant_Wait                      ; 11BA8/11B30
        bra.w   Plant_Spit                      ; 11BAC/11B34
Plant_WaitSeen:
        tst.b   O_OnScreen(a5)                  ; 11BB0/11B38
        beq.b   l_11BBA                         ; 11BB4/11B3C
        addq.b  #$1,O_Step(a5)                  ; 11BB6/11B3E  next step
l_11BBA:
        rts                                     ; 11BBA/11B42
Plant_Wait:
        tst.b   O_Step2(a5)                     ; 11BBC/11B44
        bne.b   l_11BE0                         ; 11BC0/11B48
        move.w  O_X(a5),d0                      ; 11BC2/11B4A
        cmp.w   g_ArthurX(a6),d0                ; 11BC6/11B4E
        slt.b   O_Dir(a5)                       ; 11BCA/11B52
        addq.b  #$1,O_Dir(a5)                   ; 11BCE/11B56
        lea.l   Plant_AnimIdle(pc),a0           ; 11BD2/11B5A
        bsr.w   SetAnimIndexed                  ; 11BD6/11B5E  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 11BDA/11B62
        rts                                     ; 11BDE/11B66
l_11BE0:
        bsr.w   Animate                         ; 11BE0/11B68  animate
        subq.b  #$1,Plt_Wait(a5)                ; 11BE4/11B6C
        bne.b   l_11C0A                         ; 11BE8/11B70
        movea.l Plt_WaitPtr(a5),a0              ; 11BEA/11B72
        move.b  (a0)+,d0                        ; 11BEE/11B76
        bpl.b   l_11BF8                         ; 11BF0/11B78
        adda.w  (a0),a0                         ; 11BF2/11B7A
        andi.b  #$7f,d0                         ; 11BF4/11B7C
l_11BF8:
        move.b  d0,Plt_Wait(a5)                 ; 11BF8/11B80
        move.l  a0,Plt_WaitPtr(a5)              ; 11BFC/11B84
        move.b  #$2,O_Step(a5)                  ; 11C00/11B88
        clr.b   O_Step2(a5)                     ; 11C06/11B8E
l_11C0A:
        tst.b   O_OnScreen(a5)                  ; 11C0A/11B92
        bne.b   l_11C18                         ; 11C0E/11B96
        clr.b   O_Step(a5)                      ; 11C10/11B98
        clr.b   O_Step2(a5)                     ; 11C14/11B9C
l_11C18:
        rts                                     ; 11C18/11BA0

;---------------------------------------------------------------------------
