;---------------------------------------------------------------------------
Plant_Spit:
        tst.b   O_Step2(a5)                     ; 11C1A/11BA2
        bne.b   l_11C32                         ; 11C1E/11BA6
        move.b  #$18,Plt_Mouth(a5)              ; 11C20/11BA8
        lea.l   Plant_AnimSpit(pc),a0           ; 11C26/11BAE
