        bne.w   Animate                         ; 11C36/11BBE
        bsr.w   FindFreeEnemyShot               ; 11C3A/11BC2  find a free enemy-projectile slot (fires a shot)
        bne.b   l_11C74                         ; 11C3E/11BC6
        move.w  O_X(a5),$6(a4)                  ; 11C40/11BC8
        subq.w  #$1,$6(a4)                      ; 11C46/11BCE
        move.w  O_Y(a5),$a(a4)                  ; 11C4A/11BD2
        addq.w  #$5,$6(a4)                      ; 11C50/11BD8
        clr.b   $3(a4)                          ; 11C54/11BDC
        clr.b   $4(a4)                          ; 11C58/11BE0
        clr.b   $5(a4)                          ; 11C5C/11BE4
        move.b  #$1,(a4)                        ; 11C60/11BE8
        move.b  #$6,$1a(a4)                     ; 11C64/11BEC  enemy shot type 6
        move.b  #$1,O_Step(a5)                  ; 11C6A/11BF2
        clr.b   O_Step2(a5)                     ; 11C70/11BF8
l_11C74:
        rts                                     ; 11C74/11BFC

;---------------------------------------------------------------------------
; State 2: sound 20, EnemyBurst
;---------------------------------------------------------------------------
Plant_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 11C76/11BFE
        beq.b   l_11C8C                         ; 11C7C/11C04
        bcc.b   l_11C90                         ; 11C7E/11C06
        addq.b  #$1,O_Step(a5)                  ; 11C80/11C08  next step
