Princess_11C8A:	; (no references found - unused/debug code)
        rts                                     ; 11C8A/11C12
l_11C8C:
        bra.w   EnemyBurst                      ; 11C8C/11C14
l_11C90:
        move.b  #ST_REMOVE,O_State(a5)          ; 11C90/11C18
        rts                                     ; 11C96/11C1E

