        add.w   g_GameFrame(a6),d0              ; 11D20/11CA8
        andi.w  #$3,d0                          ; 11D24/11CAC
        move.b  (a0,d0.w),Pil_LowWait(a5)       ; 11D28/11CB0
        move.l  a0,Pil_LowPtr(a5)               ; 11D2E/11CB6
        move.b  $1(a0,d0.w),Pil_HighWait(a5)    ; 11D32/11CBA
        move.l  a0,Pil_HighPtr(a5)              ; 11D38/11CC0
        move.b  #$4,O_HP(a5)                    ; 11D3C/11CC4
        addq.b  #ST_ACTIVE,O_State(a5)          ; 11D42/11CCA
        clr.b   O_Step(a5)                      ; 11D46/11CCE
        clr.b   O_Step2(a5)                     ; 11D4A/11CD2
        rts                                     ; 11D4E/11CD6

;---------------------------------------------------------------------------
; State 1. O_Step: 0 wait to be on screen, 1 idle, 2 lower shot, 3 upper shot, 4 both
;---------------------------------------------------------------------------
FirePillar_Active:
        move.b  O_Step(a5),d0                   ; 11D50/11CD8
        add.w   d0,d0                           ; 11D54/11CDC
        add.w   d0,d0                           ; 11D56/11CDE
