        blt.b   l_11DB4                         ; 11DAC/11D34
        move.b  #$3,O_Dir(a5)                   ; 11DAE/11D36
l_11DB4:
        lea.l   FirePillar_AnimIdle(pc),a0      ; 11DB4/11D3C
        bsr.w   SetAnimIndexed                  ; 11DB8/11D40  start animation for current direction
