        movea.l Pil_HighPtr(a5),a0              ; 11E06/11D8E
        move.b  (a0)+,Pil_HighWait(a5)          ; 11E0A/11D92
        bpl.b   l_11E18                         ; 11E0E/11D96
        andi.b  #$7f,Pil_HighWait(a5)           ; 11E10/11D98
        adda.w  (a0),a0                         ; 11E16/11D9E
l_11E18:
        move.l  a0,Pil_HighPtr(a5)              ; 11E18/11DA0
        ori.b   #$1,Pil_Fire(a5)                ; 11E1C/11DA4
l_11E22:
